import { useState, useRef } from 'react';
import {
  FileText,
  Image as ImageIcon,
  File,
  Upload,
  Trash2,
  Download,
  Loader2,
  AlertCircle,
  X,
} from 'lucide-react';
import { useProcurementDocuments } from '../hooks/useProcurementDocuments';
import {
  DOCUMENT_TYPE_LABELS,
  type ProcurementDocumentType,
  type ProcurementEntityType,
} from '@/types/procurement/document.types';
import { formatDisplayDate } from '@/utils/dateFormat';

interface DocumentTypeOption {
  value: ProcurementDocumentType;
  label: string;
}

interface ProcurementDocumentPanelProps {
  entityType: ProcurementEntityType;
  entityId: string;
  allowedTypes?: DocumentTypeOption[];
  readOnly?: boolean;
}

const DEFAULT_ALLOWED_TYPES: DocumentTypeOption[] = Object.entries(DOCUMENT_TYPE_LABELS).map(
  ([value, label]) => ({ value: value as ProcurementDocumentType, label })
);

function getFileIcon(mimeType?: string) {
  if (!mimeType) return File;
  if (mimeType === 'application/pdf') return FileText;
  if (mimeType.startsWith('image/')) return ImageIcon;
  return File;
}

function formatFileSize(bytes?: number): string {
  if (!bytes) return '';
  if (bytes < 1024) return `${bytes} B`;
  if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`;
  return `${(bytes / (1024 * 1024)).toFixed(1)} MB`;
}


export function ProcurementDocumentPanel({
  entityType,
  entityId,
  allowedTypes = DEFAULT_ALLOWED_TYPES,
  readOnly = false,
}: ProcurementDocumentPanelProps) {
  const { documents, loading, error, uploadDocument, deleteDocument, uploading } =
    useProcurementDocuments(entityType, entityId);

  const [showUpload, setShowUpload] = useState(false);
  const [selectedType, setSelectedType] = useState<ProcurementDocumentType>(
    allowedTypes[0]?.value || 'other'
  );
  const [notes, setNotes] = useState('');
  const [selectedFile, setSelectedFile] = useState<File | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) setSelectedFile(file);
  };

  const handleUpload = async () => {
    if (!selectedFile) return;

    try {
      await uploadDocument(selectedFile, selectedType, notes || undefined);
      setShowUpload(false);
      setSelectedFile(null);
      setNotes('');
      if (fileInputRef.current) fileInputRef.current.value = '';
    } catch {
      // Error is handled by the hook
    }
  };

  const handleDelete = async (docId: string, docName: string) => {
    if (!confirm(`Delete "${docName}"? This cannot be undone.`)) return;
    await deleteDocument(docId);
  };

  return (
    <div className="bg-[var(--ff-bg-secondary)] border border-[var(--ff-border-light)] rounded-lg">
      {/* Header */}
      <div className="flex items-center justify-between px-5 py-4 border-b border-[var(--ff-border-light)]">
        <div className="flex items-center gap-2">
          <FileText className="h-5 w-5 text-blue-400" />
          <h3 className="font-semibold text-[var(--ff-text-primary)]">
            Documents {documents.length > 0 && `(${documents.length})`}
          </h3>
        </div>
        {!readOnly && (
          <button
            onClick={() => setShowUpload(!showUpload)}
            className="inline-flex items-center gap-1.5 px-3 py-1.5 text-sm bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors"
          >
            <Upload className="h-4 w-4" />
            Upload
          </button>
        )}
      </div>

      {/* Upload Form */}
      {showUpload && (
        <div className="px-5 py-4 border-b border-[var(--ff-border-light)] bg-[var(--ff-bg-tertiary)]">
          <div className="space-y-3">
            {/* File Input */}
            <div>
              <label className="block text-sm text-[var(--ff-text-secondary)] mb-1">File</label>
              <input
                ref={fileInputRef}
                type="file"
                accept=".pdf,.jpg,.jpeg,.png,.docx,.xlsx"
                onChange={handleFileSelect}
                className="block w-full text-sm text-[var(--ff-text-secondary)] file:mr-3 file:py-1.5 file:px-3 file:rounded-lg file:border-0 file:text-sm file:bg-blue-600 file:text-white hover:file:bg-blue-700 file:cursor-pointer"
              />
              <p className="text-xs text-[var(--ff-text-tertiary)] mt-1">
                PDF, JPEG, PNG, DOCX, XLSX — max 20MB
              </p>
            </div>

            {/* Document Type */}
            <div>
              <label className="block text-sm text-[var(--ff-text-secondary)] mb-1">Document Type</label>
              <select
                value={selectedType}
                onChange={(e) => setSelectedType(e.target.value as ProcurementDocumentType)}
                className="w-full px-3 py-2 rounded-lg bg-[var(--ff-bg-primary)] border border-[var(--ff-border-light)] text-[var(--ff-text-primary)] text-sm"
              >
                {allowedTypes.map((opt) => (
                  <option key={opt.value} value={opt.value}>
                    {opt.label}
                  </option>
                ))}
              </select>
            </div>

            {/* Notes */}
            <div>
              <label className="block text-sm text-[var(--ff-text-secondary)] mb-1">
                Notes <span className="text-[var(--ff-text-tertiary)]">(optional)</span>
              </label>
              <input
                type="text"
                value={notes}
                onChange={(e) => setNotes(e.target.value)}
                placeholder="e.g. Original supplier quote"
                className="w-full px-3 py-2 rounded-lg bg-[var(--ff-bg-primary)] border border-[var(--ff-border-light)] text-[var(--ff-text-primary)] text-sm placeholder:text-[var(--ff-text-tertiary)]"
              />
            </div>

            {/* Actions */}
            <div className="flex items-center gap-2 pt-1">
              <button
                onClick={handleUpload}
                disabled={!selectedFile || uploading}
                className="inline-flex items-center gap-1.5 px-4 py-2 text-sm bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
              >
                {uploading ? (
                  <>
                    <Loader2 className="h-4 w-4 animate-spin" />
                    Uploading...
                  </>
                ) : (
                  <>
                    <Upload className="h-4 w-4" />
                    Upload Document
                  </>
                )}
              </button>
              <button
                onClick={() => {
                  setShowUpload(false);
                  setSelectedFile(null);
                  setNotes('');
                }}
                className="inline-flex items-center gap-1.5 px-4 py-2 text-sm text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)] transition-colors"
              >
                <X className="h-4 w-4" />
                Cancel
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Error */}
      {error && (
        <div className="px-5 py-3 bg-red-500/10 border-b border-red-500/30 flex items-center gap-2">
          <AlertCircle className="h-4 w-4 text-red-400 shrink-0" />
          <p className="text-sm text-red-400">{error}</p>
        </div>
      )}

      {/* Document List */}
      <div className="divide-y divide-[var(--ff-border-light)]">
        {loading ? (
          <div className="flex items-center justify-center py-8">
            <Loader2 className="h-5 w-5 animate-spin text-blue-400" />
          </div>
        ) : documents.length === 0 ? (
          <div className="text-center py-8">
            <FileText className="h-10 w-10 text-[var(--ff-text-tertiary)] mx-auto mb-2" />
            <p className="text-sm text-[var(--ff-text-secondary)]">No documents uploaded yet</p>
          </div>
        ) : (
          documents.map((doc) => {
            const Icon = getFileIcon(doc.mimeType);
            const typeLabel = DOCUMENT_TYPE_LABELS[doc.documentType] || doc.documentType;

            return (
              <div
                key={doc.id}
                className="flex items-center gap-3 px-5 py-3 hover:bg-[var(--ff-bg-hover)] transition-colors"
              >
                <div className="p-2 rounded-lg bg-blue-500/10 shrink-0">
                  <Icon className="h-5 w-5 text-blue-400" />
                </div>

                <div className="flex-1 min-w-0">
                  <p className="text-sm font-medium text-[var(--ff-text-primary)] truncate">
                    {doc.documentName}
                  </p>
                  <div className="flex items-center gap-2 text-xs text-[var(--ff-text-tertiary)]">
                    <span className="px-1.5 py-0.5 rounded bg-[var(--ff-bg-tertiary)] text-[var(--ff-text-secondary)]">
                      {typeLabel}
                    </span>
                    {doc.fileSize && <span>{formatFileSize(doc.fileSize)}</span>}
                    <span>{formatDisplayDate(doc.uploadedAt)}</span>
                    {doc.uploadedByName && <span>by {doc.uploadedByName}</span>}
                  </div>
                  {doc.notes && (
                    <p className="text-xs text-[var(--ff-text-tertiary)] mt-0.5 truncate">
                      {doc.notes}
                    </p>
                  )}
                </div>

                <div className="flex items-center gap-1 shrink-0">
                  <a
                    href={doc.fileUrl}
                    target="_blank"
                    rel="noopener noreferrer"
                    className="p-1.5 hover:bg-[var(--ff-bg-tertiary)] rounded-lg transition-colors"
                    title="Download"
                  >
                    <Download className="h-4 w-4 text-[var(--ff-text-secondary)]" />
                  </a>
                  {!readOnly && (
                    <button
                      onClick={() => handleDelete(doc.id, doc.documentName)}
                      className="p-1.5 hover:bg-red-500/10 rounded-lg transition-colors"
                      title="Delete"
                    >
                      <Trash2 className="h-4 w-4 text-red-400" />
                    </button>
                  )}
                </div>
              </div>
            );
          })
        )}
      </div>
    </div>
  );
}

// WORKING: Purchase Order Detail API - GET detail, PATCH status, DELETE
import type { NextApiRequest, NextApiResponse } from 'next';
import { neon } from '@neondatabase/serverless';
import { apiResponse } from '@/lib/apiResponse';
import { log } from '@/lib/logger';
import { withAuth, AuthenticatedRequest } from '@/lib/auth';
import { poApprovalService } from '@/services/procurement/approval';
import { createAuditLog } from '@/services/procurement/auditService';

const sql = neon(process.env.DATABASE_URL!);

// UUID validation regex
const UUID_REGEX = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

async function handler(req: NextApiRequest, res: NextApiResponse) {
  const { id } = req.query;

  if (!id || typeof id !== 'string') {
    return apiResponse.badRequest(res, 'Purchase order ID is required');
  }

  // Validate UUID format
  if (!UUID_REGEX.test(id)) {
    return apiResponse.notFound(res, 'Purchase order', id);
  }

  if (req.method === 'GET') {
    return handleGet(req, res, id);
  } else if (req.method === 'PATCH') {
    return handlePatch(req, res, id);
  } else if (req.method === 'DELETE') {
    return handleDelete(req, res, id);
  } else {
    return apiResponse.methodNotAllowed(res, req.method!, ['GET', 'PATCH', 'DELETE']);
  }
}

async function handleGet(req: NextApiRequest, res: NextApiResponse, id: string) {
  try {
    // Fetch PO with supplier and project info
    const poResult = await sql`
      SELECT
        po.id,
        po.po_number,
        po.status,
        po.supplier_id,
        COALESCE(s.company_name, s.name) as supplier_name,
        s.contact_email as supplier_email,
        s.contact_phone as supplier_phone,
        po.project_id,
        p.project_name,
        po.delivery_address,
        po.order_date,
        po.expected_delivery_date,
        po.payment_terms,
        po.currency,
        po.tax_rate,
        po.subtotal,
        po.tax_amount,
        po.total_amount,
        po.internal_notes,
        po.supplier_notes,
        po.created_by,
        po.created_at,
        po.updated_at,
        po.version,
        po.current_approval_request_id,
        po.approved_by,
        po.approved_at,
        po.odoo_po_id,
        po.supplier_reference,
        po.quote_number,
        po.quote_attachment_url,
        po.quote_attachment_name,
        po.department
      FROM purchase_orders po
      LEFT JOIN suppliers s ON po.supplier_id = s.id
      LEFT JOIN projects p ON po.project_id = p.id
      WHERE po.id = ${id}
    `;

    if (poResult.length === 0) {
      return apiResponse.notFound(res, 'Purchase order', id);
    }

    const po = poResult[0]!;

    // Fetch line items
    const itemsResult = await sql`
      SELECT
        id,
        item_code,
        item_description,
        quantity_ordered,
        quantity_received,
        uom,
        unit_price,
        total_price,
        notes
      FROM purchase_order_items
      WHERE purchase_order_id = ${id}
      ORDER BY created_at
    `;

    // Map items with calculated pending quantity
    const items = itemsResult.map((item, index) => {
      const qtyOrdered = parseFloat(item.quantity_ordered) || 0;
      const qtyReceived = parseFloat(item.quantity_received) || 0;
      return {
        id: item.id,
        lineNumber: index + 1,
        description: item.item_description,
        itemCode: item.item_code,
        quantityOrdered: qtyOrdered,
        quantityReceived: qtyReceived,
        quantityPending: Math.max(0, qtyOrdered - qtyReceived),
        unitOfMeasure: item.uom,
        unitPrice: parseFloat(item.unit_price) || 0,
        lineTotal: parseFloat(item.total_price) || 0,
        notes: item.notes,
      };
    });

    // Fetch history from purchase_order_history
    const historyResult = await sql`
      SELECT id, action, notes, created_by, created_at
      FROM purchase_order_history
      WHERE purchase_order_id = ${id}
      ORDER BY created_at DESC
    `;

    // Fetch version history if version > 1
    const versionHistory = po.version > 1
      ? await poApprovalService.getVersionHistory(id)
      : [];

    // Fetch GRN receipts linked to this PO
    const receiptsResult = await sql`
      SELECT id, grn_number, delivery_date, received_by_name, total_items, status
      FROM goods_receipt_notes
      WHERE purchase_order_id = ${id}
      ORDER BY delivery_date DESC
    `;

    // Fetch documents: procurement_documents + odoo_documents linked to this PO or its GRNs
    const grnIds = receiptsResult.map(r => r.id);
    const odooDocsResult = grnIds.length > 0
      ? await sql`
          SELECT id, document_name, document_type, file_url, file_name, mime_type, file_size, created_at
          FROM odoo_documents
          WHERE (ff_entity_type = 'purchase_order' AND ff_entity_id = ${id}::uuid)
             OR (ff_entity_type = 'goods_receipt_note' AND ff_entity_id = ANY(${grnIds}::uuid[]))
          ORDER BY created_at DESC
        `
      : await sql`
          SELECT id, document_name, document_type, file_url, file_name, mime_type, file_size, created_at
          FROM odoo_documents
          WHERE ff_entity_type = 'purchase_order' AND ff_entity_id = ${id}::uuid
          ORDER BY created_at DESC
        `;

    // Get quote comparison if RFQ linked
    let quoteComparison = null;
    try {
      quoteComparison = await poApprovalService.getQuoteComparisonForApproval(id);
    } catch {
      // Quote comparison is optional
    }

    const purchaseOrder = {
      id: po.id,
      poNumber: po.po_number,
      status: po.status,
      supplierId: po.supplier_id,
      supplierName: po.supplier_name || 'Unknown Supplier',
      supplierEmail: po.supplier_email,
      supplierPhone: po.supplier_phone,
      projectId: po.project_id,
      projectName: po.project_name,
      deliveryAddress: po.delivery_address,
      orderDate: po.order_date,
      expectedDeliveryDate: po.expected_delivery_date,
      paymentTerms: po.payment_terms,
      currency: po.currency || 'ZAR',
      taxRate: parseFloat(po.tax_rate) || 15,
      subtotal: parseFloat(po.subtotal) || 0,
      taxAmount: parseFloat(po.tax_amount) || 0,
      totalAmount: parseFloat(po.total_amount) || 0,
      notes: po.internal_notes,
      supplierNotes: po.supplier_notes,
      createdBy: po.created_by,
      createdAt: po.created_at,
      updatedAt: po.updated_at,
      // Versioning
      version: po.version || 1,
      versionHistory,
      // Approval info
      currentApprovalRequestId: po.current_approval_request_id,
      approvedBy: po.approved_by,
      approvedAt: po.approved_at,
      // Odoo integration
      odooPoId: po.odoo_po_id || null,
      // Quote / supplier reference
      supplierReference: po.supplier_reference || null,
      quoteNumber: po.quote_number || null,
      quoteAttachmentUrl: po.quote_attachment_url || null,
      quoteAttachmentName: po.quote_attachment_name || null,
      department: po.department || null,
      // Quote comparison for approvers
      quoteComparison,
      items,
      history: historyResult.map(h => ({
        id: h.id,
        action: h.action,
        notes: h.notes,
        createdBy: h.created_by,
        createdAt: h.created_at,
      })),
      receipts: receiptsResult.map(r => ({
        id: r.id,
        grnNumber: r.grn_number,
        receivedDate: r.delivery_date,
        receivedBy: r.received_by_name || 'Unknown',
        totalItems: parseInt(r.total_items) || 0,
      })),
      odooDocuments: odooDocsResult.map(d => ({
        id: d.id,
        name: d.document_name,
        type: d.document_type,
        fileUrl: d.file_url,
        fileName: d.file_name,
        mimeType: d.mime_type,
        fileSize: parseInt(d.file_size) || 0,
        createdAt: d.created_at,
      })),
    };

    return apiResponse.success(res, purchaseOrder);
  } catch (error) {
    log.error('Failed to fetch purchase order detail', error);
    return apiResponse.internalError(res, error);
  }
}

async function handlePatch(req: NextApiRequest, res: NextApiResponse, id: string) {
  try {
    const { action, notes, reason } = req.body;
    const authReq = req as AuthenticatedRequest;
    const userId = authReq.user?.id || 'system';
    const userName = authReq.user?.name || 'System';

    if (!action) {
      return apiResponse.badRequest(res, 'Action is required');
    }

    // Get current PO status
    const currentPO = await sql`
      SELECT status, version FROM purchase_orders WHERE id = ${id}
    `;

    if (currentPO.length === 0) {
      return apiResponse.notFound(res, 'Purchase order', id);
    }

    const currentStatus = currentPO[0]!.status;
    const currentVersion = currentPO[0]!.version || 1;

    // Handle approval workflow actions with the approval service
    switch (action) {
      case 'submit': {
        if (currentStatus !== 'draft') {
          return apiResponse.badRequest(res, 'Only draft POs can be submitted');
        }

        const result = await poApprovalService.submitForApproval(id, userId, userName);

        log.info('PO submitted for approval', { id, autoApproved: result.autoApproved });

        createAuditLog({
          entityType: 'purchase_order',
          entityId: id,
          action: 'update',
          performedBy: userId,
          performedByName: userName,
          oldValues: { status: currentStatus },
          newValues: { status: result.autoApproved ? 'approved' : 'pending_approval' },
        });

        return apiResponse.success(res, {
          id,
          status: result.autoApproved ? 'approved' : 'pending_approval',
          action: 'submitted',
          autoApproved: result.autoApproved,
          approvalRequest: result.approvalRequest,
        });
      }

      case 'approve': {
        if (currentStatus !== 'pending_approval') {
          return apiResponse.badRequest(res, 'Only pending POs can be approved');
        }

        await poApprovalService.approvePO(id, userId, userName, notes);

        log.info('PO approved', { id, approver: userName });

        createAuditLog({
          entityType: 'purchase_order',
          entityId: id,
          action: 'approve',
          performedBy: userId,
          performedByName: userName,
          oldValues: { status: currentStatus },
          newValues: { status: 'approved' },
        });

        return apiResponse.success(res, {
          id,
          status: 'approved',
          action: 'approved',
        });
      }

      case 'reject': {
        if (currentStatus !== 'pending_approval') {
          return apiResponse.badRequest(res, 'Only pending POs can be rejected');
        }

        if (!reason && !notes) {
          return apiResponse.badRequest(res, 'Rejection reason is required');
        }

        const result = await poApprovalService.rejectPO(id, userId, userName, reason || notes);

        log.info('PO rejected', { id, rejecter: userName, newVersion: result.newVersion });

        createAuditLog({
          entityType: 'purchase_order',
          entityId: id,
          action: 'reject',
          performedBy: userId,
          performedByName: userName,
          oldValues: { status: currentStatus },
          newValues: { status: 'draft' },
          reason: reason || notes,
        });

        return apiResponse.success(res, {
          id,
          status: 'draft',
          action: 'rejected',
          previousVersion: currentVersion,
          newVersion: result.newVersion,
        });
      }

      case 'send': {
        if (currentStatus !== 'approved') {
          return apiResponse.badRequest(res, 'Only approved POs can be sent');
        }
        await updatePOStatusSimple(id, 'sent', userId, notes);
        createAuditLog({
          entityType: 'purchase_order',
          entityId: id,
          action: 'update',
          performedBy: userId,
          performedByName: userName,
          oldValues: { status: currentStatus },
          newValues: { status: 'sent' },
        });
        return apiResponse.success(res, { id, status: 'sent', action: 'sent' });
      }

      case 'acknowledge': {
        if (currentStatus !== 'sent') {
          return apiResponse.badRequest(res, 'Only sent POs can be acknowledged');
        }
        await updatePOStatusSimple(id, 'acknowledged', userId, notes);
        createAuditLog({
          entityType: 'purchase_order',
          entityId: id,
          action: 'update',
          performedBy: userId,
          performedByName: userName,
          oldValues: { status: currentStatus },
          newValues: { status: 'acknowledged' },
        });
        return apiResponse.success(res, { id, status: 'acknowledged', action: 'acknowledged' });
      }

      case 'complete': {
        if (!['acknowledged', 'partial_receipt'].includes(currentStatus)) {
          return apiResponse.badRequest(res, 'Cannot complete PO in current status');
        }
        await updatePOStatusSimple(id, 'completed', userId, notes);
        createAuditLog({
          entityType: 'purchase_order',
          entityId: id,
          action: 'update',
          performedBy: userId,
          performedByName: userName,
          oldValues: { status: currentStatus },
          newValues: { status: 'completed' },
        });
        return apiResponse.success(res, { id, status: 'completed', action: 'completed' });
      }

      case 'cancel': {
        if (['completed', 'cancelled', 'draft'].includes(currentStatus)) {
          return apiResponse.badRequest(res, 'Cannot cancel PO in current status');
        }
        await updatePOStatusSimple(id, 'cancelled', userId, notes);
        createAuditLog({
          entityType: 'purchase_order',
          entityId: id,
          action: 'update',
          performedBy: userId,
          performedByName: userName,
          oldValues: { status: currentStatus },
          newValues: { status: 'cancelled' },
        });
        return apiResponse.success(res, { id, status: 'cancelled', action: 'cancelled' });
      }

      case 'update_fields': {
        // Allow field edits on Odoo-imported POs only
        const checkOdoo = await sql`SELECT odoo_po_id FROM purchase_orders WHERE id = ${id}`;
        if (!checkOdoo[0]?.odoo_po_id) {
          return apiResponse.badRequest(res, 'Field editing is only allowed for Odoo-imported POs');
        }

        const { fields } = req.body;
        if (!fields || typeof fields !== 'object') {
          return apiResponse.badRequest(res, 'Fields object is required');
        }

        const allowedFields: Record<string, string> = {
          expectedDeliveryDate: 'expected_delivery_date',
          orderDate: 'order_date',
          deliveryAddress: 'delivery_address',
          paymentTerms: 'payment_terms',
          internalNotes: 'internal_notes',
          supplierNotes: 'supplier_notes',
        };

        const updates: string[] = [];
        const values: (string | null)[] = [];
        let vi = 1;

        for (const [key, val] of Object.entries(fields)) {
          const col = allowedFields[key];
          if (!col) continue;
          updates.push(`${col} = $${vi}`);
          values.push(val as string | null);
          vi++;
        }

        if (updates.length === 0) {
          return apiResponse.badRequest(res, 'No valid fields to update');
        }

        updates.push(`updated_at = NOW()`);
        const updateQuery = `UPDATE purchase_orders SET ${updates.join(', ')} WHERE id = $${vi}`;
        values.push(id);

        await sql.query(updateQuery, values);

        await sql`
          INSERT INTO purchase_order_history (
            purchase_order_id, action, notes, created_by, created_at
          ) VALUES (
            ${id}, ${'edited'}, ${`Fields updated: ${Object.keys(fields).join(', ')}`}, ${userId}, NOW()
          )
        `;

        log.info('PO fields updated (Odoo)', { id, fields: Object.keys(fields) });

        createAuditLog({
          entityType: 'purchase_order',
          entityId: id,
          action: 'update',
          performedBy: userId,
          performedByName: userName,
          newValues: fields,
        });

        return apiResponse.success(res, { id, action: 'updated', fields: Object.keys(fields) });
      }

      default:
        return apiResponse.badRequest(res, `Invalid action: ${action}`);
    }
  } catch (error) {
    log.error('Failed to update purchase order status', error);
    return apiResponse.internalError(res, error);
  }
}

// Helper for non-approval status updates
async function updatePOStatusSimple(poId: string, status: string, userId: string, notes?: string) {
  await sql`
    UPDATE purchase_orders
    SET status = ${status}, updated_at = NOW()
    WHERE id = ${poId}
  `;

  await sql`
    INSERT INTO purchase_order_history (
      purchase_order_id, action, notes, created_by, created_at
    ) VALUES (
      ${poId}, ${status}, ${notes || null}, ${userId}, NOW()
    )
  `;
}

async function handleDelete(req: NextApiRequest, res: NextApiResponse, id: string) {
  try {
    // Check if PO exists and is draft
    const currentPO = await sql`
      SELECT status FROM purchase_orders WHERE id = ${id}
    `;

    if (currentPO.length === 0) {
      return apiResponse.notFound(res, 'Purchase order', id);
    }

    if (currentPO[0]!.status !== 'draft') {
      return apiResponse.badRequest(res, 'Only draft purchase orders can be deleted');
    }

    // Delete history first (foreign key)
    await sql`DELETE FROM purchase_order_history WHERE purchase_order_id = ${id}`;

    // Delete items (foreign key)
    await sql`DELETE FROM purchase_order_items WHERE purchase_order_id = ${id}`;

    // Delete PO
    await sql`DELETE FROM purchase_orders WHERE id = ${id}`;

    log.info('Purchase order deleted', { id });

    return apiResponse.success(res, { deleted: true, id });
  } catch (error) {
    log.error('Failed to delete purchase order', error);
    return apiResponse.internalError(res, error);
  }
}

export default withAuth(handler);

import { useState, useEffect, useCallback } from 'react';
import type { ProcurementDocument, ProcurementDocumentType } from '@/types/procurement/document.types';
import { log } from '@/lib/logger';

interface UseProcurementDocumentsReturn {
  documents: ProcurementDocument[];
  loading: boolean;
  error: string | null;
  uploadDocument: (file: File, documentType: ProcurementDocumentType, notes?: string) => Promise<void>;
  deleteDocument: (documentId: string) => Promise<void>;
  refreshDocuments: () => Promise<void>;
  uploading: boolean;
}

export function useProcurementDocuments(
  entityType: string,
  entityId: string | undefined
): UseProcurementDocumentsReturn {
  const [documents, setDocuments] = useState<ProcurementDocument[]>([]);
  const [loading, setLoading] = useState(false);
  const [uploading, setUploading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const fetchDocuments = useCallback(async () => {
    if (!entityId) return;

    setLoading(true);
    setError(null);
    try {
      const res = await fetch(
        `/api/procurement/documents?entity_type=${entityType}&entity_id=${entityId}`
      );
      const data = await res.json();
      if (data.success) {
        setDocuments(data.data);
      } else {
        setError(data.error?.message || 'Failed to fetch documents');
      }
    } catch (err) {
      log.error('Failed to fetch procurement documents', { error: err });
      setError('Failed to load documents');
    } finally {
      setLoading(false);
    }
  }, [entityType, entityId]);

  useEffect(() => {
    fetchDocuments();
  }, [fetchDocuments]);

  const uploadDocument = useCallback(
    async (file: File, documentType: ProcurementDocumentType, notes?: string) => {
      if (!entityId) return;

      setUploading(true);
      setError(null);
      try {
        const formData = new FormData();
        formData.append('file', file);
        formData.append('entity_type', entityType);
        formData.append('entity_id', entityId);
        formData.append('document_type', documentType);
        if (notes) formData.append('notes', notes);

        const res = await fetch('/api/procurement/documents', {
          method: 'POST',
          body: formData,
        });
        const data = await res.json();

        if (data.success) {
          setDocuments((prev) => [data.data, ...prev]);
        } else {
          setError(data.error?.message || 'Failed to upload document');
          throw new Error(data.error?.message || 'Upload failed');
        }
      } catch (err) {
        const msg = err instanceof Error ? err.message : 'Upload failed';
        log.error('Failed to upload procurement document', { error: err });
        setError(msg);
        throw err;
      } finally {
        setUploading(false);
      }
    },
    [entityType, entityId]
  );

  const deleteDocument = useCallback(async (documentId: string) => {
    setError(null);
    try {
      const res = await fetch(`/api/procurement/documents?id=${documentId}`, {
        method: 'DELETE',
      });
      const data = await res.json();

      if (data.success) {
        setDocuments((prev) => prev.filter((d) => d.id !== documentId));
      } else {
        setError(data.error?.message || 'Failed to delete document');
      }
    } catch (err) {
      log.error('Failed to delete procurement document', { error: err });
      setError('Failed to delete document');
    }
  }, []);

  return {
    documents,
    loading,
    error,
    uploadDocument,
    deleteDocument,
    refreshDocuments: fetchDocuments,
    uploading,
  };
}

