                    <dt className="text-[var(--ff-text-secondary)]">VAT ({purchaseOrder.taxRate}%)</dt>
                    <dd className="text-[var(--ff-text-primary)]">{formatCurrency(purchaseOrder.taxAmount)}</dd>
