tool_input.new_string:
{activeTab === 'documents' && (() => {
  // Document Checklist detection logic
  const odooDocs = purchaseOrder.odooDocuments || [];

  // Quote: procurement_documents quote_pdf OR odoo quote OR legacy quoteAttachmentUrl
  const quoteDoc = procDocs.find(d => d.documentType === 'quote_pdf')
    || odooDocs.find(d => d.type === 'quote');
  const quoteUrl = quoteDoc
    ? ('fileUrl' in quoteDoc ? quoteDoc.fileUrl : quoteDoc.fileUrl)
    : purchaseOrder.quoteAttachmentUrl;
  const quoteName = quoteDoc
    ? ('documentName' in quoteDoc ? quoteDoc.documentName : quoteDoc.name)
    : purchaseOrder.quoteAttachmentName || 'Quote';
  const hasQuote = !!quoteDoc || !!purchaseOrder.quoteAttachmentUrl;

  // PO Document: procurement_documents contract OR odoo purchase.order model
  const poDoc = procDocs.find(d => d.documentType === 'contract')
    || odooDocs.find(d => d.odooModel === 'purchase.order');
  const poDocUrl = poDoc ? ('fileUrl' in poDoc ? poDoc.fileUrl : poDoc.fileUrl) : null;
  const poDocName = poDoc
    ? ('documentName' in poDoc ? poDoc.documentName : poDoc.name)
    : null;
  const hasPO = !!poDoc;

  // GRV: procurement_documents grv/delivery_note OR odoo stock.picking
  const grvDoc = procDocs.find(d => d.documentType === 'grv' || d.documentType === 'delivery_note')
    || odooDocs.find(d => d.odooModel === 'stock.picking');
  const grvUrl = grvDoc ? ('fileUrl' in grvDoc ? grvDoc.fileUrl : grvDoc.fileUrl) : null;
  const grvName = grvDoc
    ? ('documentName' in grvDoc ? grvDoc.documentName : grvDoc.name)
    : null;
  const hasGRV = !!grvDoc;

  // Invoice: procurement_documents invoice OR odoo invoice type OR odoo account.move
  const invoiceDoc = procDocs.find(d => d.documentType === 'invoice')
    || odooDocs.find(d => d.type === 'invoice' || d.odooModel === 'account.move');
  const invoiceUrl = invoiceDoc ? ('fileUrl' in invoiceDoc ? invoiceDoc.fileUrl : invoiceDoc.fileUrl) : null;
  const invoiceName = invoiceDoc
    ? ('documentName' in invoiceDoc ? invoiceDoc.documentName : invoiceDoc.name)
    : null;
  const hasInvoice = !!invoiceDoc;

  const checklistItems = [
    { label: 'Quote', present: hasQuote, name: quoteName, url: quoteUrl },
    { label: 'Purchase Order', present: hasPO, name: poDocName, url: poDocUrl },
    { label: 'GRV', present: hasGRV, name: grvName, url: grvUrl },
    { label: 'Supplier Invoice', present: hasInvoice, name: invoiceName, url: invoiceUrl },
  ];
  const completedCount = checklistItems.filter(i => i.present).length;
  const allComplete = completedCount === 4;

  return (
  <div className="space-y-6">
    {/* Document Checklist */}
    <div className={`bg-[var(--ff-bg-secondary)] border rounded-lg p-5 ${allComplete ? 'border-green-500/50' : 'border-[var(--ff-border-light)]'}`}>
      <div className="flex items-center justify-between mb-4">
        <div className="flex items-center gap-2">
          <FileText className="h-5 w-5 text-blue-400" />
          <h3 className="font-semibold text-[var(--ff-text-primary)]">Document Checklist</h3>
        </div>
        <span className={`text-sm font-medium px-2.5 py-1 rounded-full ${allComplete ? 'bg-green-500/20 text-green-400' : 'bg-orange-500/20 text-orange-400'}`}>
          {allComplete ? '4/4 Complete' : `${completedCount}/4`}
        </span>
      </div>
      <div className="space-y-2">
        {checklistItems.map((item) => (
          <div key={item.label} className="flex items-center gap-3 py-2 px-3 rounded-lg hover:bg-[var(--ff-bg-hover)] transition-colors">
            {item.present ? (
              <CheckCircle className="h-5 w-5 text-green-400 shrink-0" />
            ) : (
              <XCircle className="h-5 w-5 text-red-400 shrink-0" />
            )}
            <span className="text-sm font-medium text-[var(--ff-text-primary)] w-32 shrink-0">
              {item.label}
            </span>
            {item.present && item.url ? (
              <a
                href={item.url}
                target="_blank"
                rel="noopener noreferrer"
                className="text-sm text-blue-400 hover:text-blue-300 truncate transition-colors"
              >
                {item.name}
              </a>
            ) : !item.present ? (
              <span className="text-sm text-red-400/70">Missing — upload required</span>
            ) : (
              <span className="text-sm text-[var(--ff-text-secondary)] truncate">{item.name}</span>
            )}
          </div>
        ))}
      </div>
    </div>

    {/* Synced Documents from Odoo */}

