    // Update reconciled balance if part of a reconciliation
    if (reconciliationId) {
      await updateReconciledBalance(reconciliationId);
    }

    log.info('Matched bank transaction', { bankTxId, journalLineId }, 'accounting');
    return mapTxRow(rows[0]!);
  } catch (err) {
