/**
 * Chart of Accounts API
 * GET  /api/accounting/chart-of-accounts - List all accounts (flat or tree)
 * POST /api/accounting/chart-of-accounts - Create new account
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth } from '@/lib/auth';
import { log } from '@/lib/logger';
import {
  getChartOfAccounts,
  getAccountTree,
  createAccount,
  updateAccount,
} from '@/modules/accounting/services/chartOfAccountsService';

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method === 'GET') {
    try {
      const { view, subtype } = req.query;
      let data;
      if (view === 'tree') {
        data = await getAccountTree();
      } else {
        const accounts = await getChartOfAccounts();
        data = subtype
          ? accounts.filter(a => a.accountSubtype === String(subtype))
          : accounts;
      }
      return apiResponse.success(res, data);
    } catch (err) {
      log.error('Failed to get chart of accounts', { error: err }, 'accounting-api');
      return apiResponse.badRequest(res, 'Failed to get chart of accounts');
    }
  }

  if (req.method === 'POST') {
    try {
      const { accountCode, accountName, accountType, accountSubtype, parentAccountId, description, normalBalance } = req.body;

      if (!accountCode || !accountName || !accountType || !normalBalance) {
        return apiResponse.badRequest(res, 'accountCode, accountName, accountType, and normalBalance are required');
      }

      const account = await createAccount({
        accountCode,
        accountName,
        accountType,
        accountSubtype,
        parentAccountId,
        description,
        normalBalance,
      });

      return apiResponse.success(res, account);
    } catch (err) {
      const message = err instanceof Error ? err.message : 'Failed to create account';
      log.error('Failed to create account', { error: err }, 'accounting-api');
      return apiResponse.badRequest(res, message);
    }
  }

  if (req.method === 'PUT') {
    try {
      const { id, accountName, description, isActive, displayOrder } = req.body;
      if (!id) return apiResponse.badRequest(res, 'id is required');
      const updated = await updateAccount(id, { accountName, description, isActive, displayOrder });
      return apiResponse.success(res, updated);
    } catch (err) {
      const message = err instanceof Error ? err.message : 'Failed to update account';
      log.error('Failed to update account', { error: err }, 'accounting-api');
      return apiResponse.badRequest(res, message);
    }
  }

  res.setHeader('Allow', ['GET', 'POST', 'PUT']);
  return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET', 'POST', 'PUT']);
}

export default withAuth(withErrorHandler(handler));

/**
 * Chart of Accounts Detail API
 * GET    /api/accounting/chart-of-accounts-detail?id=... - Get single account
 * PUT    /api/accounting/chart-of-accounts-detail - Update account
 * DELETE /api/accounting/chart-of-accounts-detail - Delete (deactivate) account
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth } from '@/lib/auth';
import { log } from '@/lib/logger';
import {
  getAccountById,
  updateAccount,
  deleteAccount,
} from '@/modules/accounting/services/chartOfAccountsService';

async function handler(req: NextApiRequest, res: NextApiResponse) {
  const id = (req.query.id || req.body?.id) as string;

  if (req.method === 'GET') {
    if (!id) return apiResponse.badRequest(res, 'id is required');
    try {
      const account = await getAccountById(id);
      if (!account) return apiResponse.notFound(res, 'Account', id);
      return apiResponse.success(res, account);
    } catch (err) {
      log.error('Failed to get account', { id, error: err }, 'accounting-api');
      return apiResponse.badRequest(res, 'Failed to get account');
    }
  }

  if (req.method === 'PUT') {
    if (!id) return apiResponse.badRequest(res, 'id is required');
    try {
      const { accountName, description, isActive, displayOrder } = req.body;
      const account = await updateAccount(id, { accountName, description, isActive, displayOrder });
      return apiResponse.success(res, account);
    } catch (err) {
      const message = err instanceof Error ? err.message : 'Failed to update account';
      log.error('Failed to update account', { id, error: err }, 'accounting-api');
      return apiResponse.badRequest(res, message);
    }
  }

  if (req.method === 'DELETE') {
    if (!id) return apiResponse.badRequest(res, 'id is required');
    try {
      await deleteAccount(id);
      return apiResponse.success(res, { deleted: true });
    } catch (err) {
      const message = err instanceof Error ? err.message : 'Failed to delete account';
      log.error('Failed to delete account', { id, error: err }, 'accounting-api');
      return apiResponse.badRequest(res, message);
    }
  }

  res.setHeader('Allow', ['GET', 'PUT', 'DELETE']);
  return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET', 'PUT', 'DELETE']);
}

export default withAuth(withErrorHandler(handler));

/**
 * Default Accounts Configuration API
 * GET /api/accounting/default-accounts - Get default account mappings
 * POST /api/accounting/default-accounts - Save default account mappings
 * Sage equivalent: Accounts > Default Accounts
 *
 * Stores mappings in gl_accounts metadata (JSON column) or a simple key-value approach.
 * Uses a settings row in a lightweight pattern: one JSON object stored per company.
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { createLoggedSql } from '@/lib/db-logger';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth } from '@/lib/auth';
import { log } from '@/lib/logger';

const sql = createLoggedSql(process.env.DATABASE_URL!);

const SETTINGS_KEY = 'accounting_default_accounts';

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method === 'GET') {
    try {
      // Try to read from app_settings table, fall back to empty
      let mappings: Record<string, string> = {};
      try {
        const [row] = await sql`
          SELECT value FROM app_settings WHERE key = ${SETTINGS_KEY}
        `;
        if (row?.value) {
          mappings = typeof row.value === 'string' ? JSON.parse(row.value) : row.value;
        }
      } catch {
        // app_settings table may not exist yet — return empty mappings
      }

      return apiResponse.success(res, { mappings });
    } catch (err) {
      log.error('Failed to fetch default accounts', { error: err, module: 'accounting' });
      return apiResponse.databaseError(res, err, 'Failed to fetch default accounts');
    }
  }

  if (req.method === 'POST') {
    const { mappings } = req.body;

    if (!mappings || typeof mappings !== 'object') {
      return apiResponse.validationError(res, { mappings: 'Object of key-value mappings required' });
    }

    try {
      // Upsert into app_settings
      await sql`
        INSERT INTO app_settings (key, value, updated_at)
        VALUES (${SETTINGS_KEY}, ${JSON.stringify(mappings)}::jsonb, NOW())
        ON CONFLICT (key) DO UPDATE
        SET value = ${JSON.stringify(mappings)}::jsonb, updated_at = NOW()
      `;

      log.info('Default accounts saved', { keys: Object.keys(mappings), module: 'accounting' });
      return apiResponse.success(res, { saved: true });
    } catch (err) {
      // If app_settings doesn't exist, create it
      if (String(err).includes('app_settings')) {
        try {
          await sql`
            CREATE TABLE IF NOT EXISTS app_settings (
              key TEXT PRIMARY KEY,
              value JSONB NOT NULL DEFAULT '{}',
              updated_at TIMESTAMPTZ DEFAULT NOW()
            )
          `;
          await sql`
            INSERT INTO app_settings (key, value, updated_at)
            VALUES (${SETTINGS_KEY}, ${JSON.stringify(mappings)}::jsonb, NOW())
          `;
          log.info('Created app_settings table and saved default accounts', { module: 'accounting' });
          return apiResponse.success(res, { saved: true });
        } catch (createErr) {
          log.error('Failed to create app_settings', { error: createErr, module: 'accounting' });
          return apiResponse.databaseError(res, createErr, 'Failed to save default accounts');
        }
      }
      log.error('Failed to save default accounts', { error: err, module: 'accounting' });
      return apiResponse.databaseError(res, err, 'Failed to save default accounts');
    }
  }

  return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET', 'POST']);
}

export default withAuth(withErrorHandler(handler));

/**
 * PRD-060: FibreFlow Accounting Module
 * Chart of Accounts Service
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import type { GLAccount, GLAccountType } from '../types/gl.types';

export interface CreateAccountInput {
  accountCode: string;
  accountName: string;
  accountType: GLAccountType;
  accountSubtype?: string;
  parentAccountId?: string;
  description?: string;
  normalBalance: 'debit' | 'credit';
}

export interface UpdateAccountInput {
  accountName?: string;
  description?: string;
  isActive?: boolean;
  displayOrder?: number;
}

interface AccountTreeNode extends GLAccount {
  children: AccountTreeNode[];
}

export async function getChartOfAccounts(): Promise<GLAccount[]> {
  try {
    const rows = await sql`
      SELECT a.*,
        p.account_code AS parent_code,
        p.account_name AS parent_name
      FROM gl_accounts a
      LEFT JOIN gl_accounts p ON p.id = a.parent_account_id
      WHERE a.is_active = true
      ORDER BY a.account_code
    `;
    return (rows as { [key: string]: unknown }[]).map(mapRow);
  } catch (err) {
    log.error('Failed to get chart of accounts', { error: err }, 'accounting');
    throw err;
  }
}

export async function getAccountTree(): Promise<AccountTreeNode[]> {
  const accounts = await getChartOfAccounts();
  const map = new Map<string, AccountTreeNode>();
  const roots: AccountTreeNode[] = [];

  for (const acc of accounts) {
    map.set(acc.id, { ...acc, children: [] });
  }

  for (const acc of accounts) {
    const node = map.get(acc.id)!;
    if (acc.parentAccountId) {
      const parent = map.get(acc.parentAccountId);
      if (parent) {
        parent.children.push(node);
        continue;
      }
    }
    roots.push(node);
  }

  return roots;
}

export async function getAccountById(id: string): Promise<GLAccount | null> {
  try {
    const rows = await sql`SELECT * FROM gl_accounts WHERE id = ${id}`;
    const arr = rows as { [key: string]: unknown }[];
    return arr.length > 0 ? mapRow(arr[0]!) : null;
  } catch (err) {
    log.error('Failed to get account by id', { id, error: err }, 'accounting');
    throw err;
  }
}

export async function getAccountByCode(code: string): Promise<GLAccount | null> {
  try {
    const rows = await sql`SELECT * FROM gl_accounts WHERE account_code = ${code}`;
    const arr = rows as { [key: string]: unknown }[];
    return arr.length > 0 ? mapRow(arr[0]!) : null;
  } catch (err) {
    log.error('Failed to get account by code', { code, error: err }, 'accounting');
    throw err;
  }
}

export async function createAccount(input: CreateAccountInput): Promise<GLAccount> {
  try {
    const existing = await sql`
      SELECT id FROM gl_accounts WHERE account_code = ${input.accountCode}
    `;
    if ((existing as unknown[]).length > 0) {
      throw new Error(`Account code ${input.accountCode} already exists`);
    }

    let level = 1;
    if (input.parentAccountId) {
      const parent = await sql`
        SELECT id, level FROM gl_accounts WHERE id = ${input.parentAccountId}
      ` as { level: number }[];
      if (parent.length === 0) {
        throw new Error(`Parent account ${input.parentAccountId} not found`);
      }
      level = Number(parent[0]!.level) + 1;
    }

    const rows = await sql`
      INSERT INTO gl_accounts (
        account_code, account_name, account_type, account_subtype,
        parent_account_id, description, normal_balance, level
      ) VALUES (
        ${input.accountCode}, ${input.accountName}, ${input.accountType},
        ${input.accountSubtype || null}, ${input.parentAccountId || null},
        ${input.description || null}, ${input.normalBalance}, ${level}
      )
      RETURNING *
    `;
    return mapRow((rows as { [key: string]: unknown }[])[0]);
  } catch (err) {
    log.error('Failed to create account', { error: err }, 'accounting');
    throw err;
  }
}

export async function updateAccount(id: string, input: UpdateAccountInput): Promise<GLAccount> {
  try {
    const account = await sql`SELECT * FROM gl_accounts WHERE id = ${id}` as {
      is_system_account: boolean;
    }[];
    if (account.length === 0) throw new Error(`Account ${id} not found`);

    if (account[0]!.is_system_account && input.isActive === false) {
      throw new Error('Cannot deactivate a system account');
    }

    const rows = await sql`
      UPDATE gl_accounts SET
        account_name = COALESCE(${input.accountName || null}, account_name),
        description = COALESCE(${input.description ?? null}, description),
        is_active = COALESCE(${input.isActive ?? null}, is_active),
        display_order = COALESCE(${input.displayOrder ?? null}, display_order)
      WHERE id = ${id}
      RETURNING *
    `;
    return mapRow((rows as { [key: string]: unknown }[])[0]);
  } catch (err) {
    log.error('Failed to update account', { id, error: err }, 'accounting');
    throw err;
  }
}

export async function deleteAccount(id: string): Promise<void> {
  try {
    const lines = await sql`
      SELECT COUNT(*) AS cnt FROM gl_journal_lines WHERE gl_account_id = ${id}
    ` as { cnt: string }[];
    if (Number(lines[0]!.cnt) > 0) {
      throw new Error('Cannot delete account with existing journal entries');
    }

    const children = await sql`
      SELECT COUNT(*) AS cnt FROM gl_accounts WHERE parent_account_id = ${id} AND is_active = true
    ` as { cnt: string }[];
    if (Number(children[0]!.cnt) > 0) {
      throw new Error('Cannot delete account with active child accounts');
    }

    await sql`UPDATE gl_accounts SET is_active = false WHERE id = ${id}`;
  } catch (err) {
    log.error('Failed to delete account', { id, error: err }, 'accounting');
    throw err;
  }
}

export async function getAccountBalance(
  accountId: string,
  fiscalPeriodId?: string
): Promise<{ debitTotal: number; creditTotal: number; balance: number }> {
  try {
    let rows: { debit_total: string; credit_total: string; balance: string }[];
    if (fiscalPeriodId) {
      rows = await sql`
        SELECT debit_total, credit_total, balance
        FROM gl_account_balances
        WHERE gl_account_id = ${accountId} AND fiscal_period_id = ${fiscalPeriodId}
      ` as typeof rows;
    } else {
      rows = await sql`
        SELECT
          COALESCE(SUM(debit_total), 0) AS debit_total,
          COALESCE(SUM(credit_total), 0) AS credit_total,
          COALESCE(SUM(balance), 0) AS balance
        FROM gl_account_balances
        WHERE gl_account_id = ${accountId}
      ` as typeof rows;
    }

    if (rows.length === 0) {
      return { debitTotal: 0, creditTotal: 0, balance: 0 };
    }

    return {
      debitTotal: Number(rows[0]!.debit_total),
      creditTotal: Number(rows[0]!.credit_total),
      balance: Number(rows[0]!.balance),
    };
  } catch (err) {
    log.error('Failed to get account balance', { accountId, error: err }, 'accounting');
    throw err;
  }
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
function mapRow(row: any): GLAccount {
  return {
    id: String(row.id),
    accountCode: String(row.account_code),
    accountName: String(row.account_name),
    accountType: String(row.account_type) as GLAccountType,
    accountSubtype: row.account_subtype ? String(row.account_subtype) : undefined,
    parentAccountId: row.parent_account_id ? String(row.parent_account_id) : undefined,
    isActive: Boolean(row.is_active),
    isSystemAccount: Boolean(row.is_system_account),
    description: row.description ? String(row.description) : undefined,
    normalBalance: String(row.normal_balance) as 'debit' | 'credit',
    level: Number(row.level),
    displayOrder: Number(row.display_order),
    bankAccountNumber: row.bank_account_number ? String(row.bank_account_number) : undefined,
    createdAt: String(row.created_at),
    updatedAt: String(row.updated_at),
  };
}

/**
 * PRD-060: FibreFlow Accounting Module
 * Journal Entry Service
