/**
 * Chart of Accounts API
 * GET  /api/accounting/chart-of-accounts - List all accounts (flat or tree)
 * POST /api/accounting/chart-of-accounts - Create new account
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth } from '@/lib/auth';
import { log } from '@/lib/logger';
import {
  getChartOfAccounts,
  getAccountTree,
  createAccount,
  updateAccount,
} from '@/modules/accounting/services/chartOfAccountsService';

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method === 'GET') {
    try {
      const { view, subtype } = req.query;
      let data;
      if (view === 'tree') {
        data = await getAccountTree();
      } else {
        const accounts = await getChartOfAccounts();
        data = subtype
          ? accounts.filter(a => a.accountSubtype === String(subtype))
          : accounts;
      }
      return apiResponse.success(res, data);
    } catch (err) {
      log.error('Failed to get chart of accounts', { error: err }, 'accounting-api');
      return apiResponse.badRequest(res, 'Failed to get chart of accounts');
    }
  }

  if (req.method === 'POST') {
    try {
      const { accountCode, accountName, accountType, accountSubtype, parentAccountId, description, normalBalance } = req.body;

      if (!accountCode || !accountName || !accountType || !normalBalance) {
        return apiResponse.badRequest(res, 'accountCode, accountName, accountType, and normalBalance are required');
      }

      const account = await createAccount({
        accountCode,
        accountName,
        accountType,
        accountSubtype,
        parentAccountId,
        description,
        normalBalance,
      });

      return apiResponse.success(res, account);
    } catch (err) {
      const message = err instanceof Error ? err.message : 'Failed to create account';
      log.error('Failed to create account', { error: err }, 'accounting-api');
      return apiResponse.badRequest(res, message);
    }
  }

  if (req.method === 'PUT') {
    try {
      const { id, accountName, description, isActive, displayOrder } = req.body;
      if (!id) return apiResponse.badRequest(res, 'id is required');
      const updated = await updateAccount(id, { accountName, description, isActive, displayOrder });
      return apiResponse.success(res, updated);
    } catch (err) {
      const message = err instanceof Error ? err.message : 'Failed to update account';
      log.error('Failed to update account', { error: err }, 'accounting-api');
      return apiResponse.badRequest(res, message);
    }
  }

  res.setHeader('Allow', ['GET', 'POST', 'PUT']);
  return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET', 'POST', 'PUT']);
}

export default withAuth(withErrorHandler(handler));

/**
 * Chart of Accounts Detail API
 * GET    /api/accounting/chart-of-accounts-detail?id=... - Get single account
 * PUT    /api/accounting/chart-of-accounts-detail - Update account
 * DELETE /api/accounting/chart-of-accounts-detail - Delete (deactivate) account
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth } from '@/lib/auth';
import { log } from '@/lib/logger';
import {
  getAccountById,
  updateAccount,
  deleteAccount,
} from '@/modules/accounting/services/chartOfAccountsService';

async function handler(req: NextApiRequest, res: NextApiResponse) {
  const id = (req.query.id || req.body?.id) as string;

  if (req.method === 'GET') {
    if (!id) return apiResponse.badRequest(res, 'id is required');
    try {
      const account = await getAccountById(id);
      if (!account) return apiResponse.notFound(res, 'Account', id);
      return apiResponse.success(res, account);
    } catch (err) {
      log.error('Failed to get account', { id, error: err }, 'accounting-api');
      return apiResponse.badRequest(res, 'Failed to get account');
    }
  }

  if (req.method === 'PUT') {
    if (!id) return apiResponse.badRequest(res, 'id is required');
    try {
      const { accountName, description, isActive, displayOrder } = req.body;
      const account = await updateAccount(id, { accountName, description, isActive, displayOrder });
      return apiResponse.success(res, account);
    } catch (err) {
      const message = err instanceof Error ? err.message : 'Failed to update account';
      log.error('Failed to update account', { id, error: err }, 'accounting-api');
      return apiResponse.badRequest(res, message);
    }
  }

  if (req.method === 'DELETE') {
    if (!id) return apiResponse.badRequest(res, 'id is required');
    try {
      await deleteAccount(id);
      return apiResponse.success(res, { deleted: true });
    } catch (err) {
      const message = err instanceof Error ? err.message : 'Failed to delete account';
      log.error('Failed to delete account', { id, error: err }, 'accounting-api');
      return apiResponse.badRequest(res, message);
    }
  }

  res.setHeader('Allow', ['GET', 'PUT', 'DELETE']);
  return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET', 'PUT', 'DELETE']);
}

export default withAuth(withErrorHandler(handler));

