                      {entry.lines ? `R ${entry.lines.reduce((s, l) => s + Number(l.debit), 0).toLocaleString('en-ZA', { minimumFractionDigits: 2 })}` : '-'}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </div>
    </div>
  );
}

