// =====================================================
// Chart of Accounts Tab
// =====================================================

const SUBTYPES_BY_TYPE: Record<string, { value: string; label: string }[]> = {
  asset: [
    { value: 'bank', label: 'Bank' },
    { value: 'receivable', label: 'Receivable' },
    { value: 'inventory', label: 'Inventory' },
