                        </button>
                        <button onClick={() => doAction('delete', rule.id)} disabled={busy === rule.id} className="p-1 text-red-400 hover:text-red-300" title="Delete">
                          {busy === rule.id ? <Loader2 className="h-4 w-4 animate-spin" /> : <Trash2 className="h-4 w-4" />}
                        </button>
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      </div>
    </AppLayout>
  );
}

