                  {clients.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
                </select>
                {/* Quick Win 3: VAT Code select */}
                <select value={form.vatCode} onChange={e => setForm(f => ({ ...f, vatCode: e.target.value }))} className="ff-select">
