    // Check table headers — use columnheader role to avoid strict-mode conflicts
    await expect(page.getByRole('columnheader', { name: 'Rule' })).toBeVisible();
    await expect(page.getByRole('columnheader', { name: 'Pattern' })).toBeVisible();
    await expect(page.getByRole('columnheader', { name: 'GL Account' })).toBeVisible();

    console.log('✅ Page loaded OK');
