          {/* Step 3: Dashboard Photo */}
          <div className="space-y-2">
            <div className="flex items-center gap-2">
              <div className={`p-1.5 rounded-full ${
                hasPhoto
                  ? 'bg-green-100 dark:bg-green-900'
