import React, { useState, useRef, useCallback } from 'react';
import {
  X,
  Camera,
  AlertTriangle,
  Gauge,
  CheckCircle2,
  ImageIcon,
  RefreshCw,
} from 'lucide-react';
import { log } from '@/lib/logger';

