const handleAccept = async (txId: string) => {
  const sel = rowSelections[txId];
  if (!sel?.entityId) { toast.error('Select an account/supplier/customer first'); return; }
  const tx = transactions.find(t => t.id === txId);
  try {
    const body: Record<string, string> = {
      action: 'allocate', bankTransactionId: txId, allocationType: sel.type,
      vatCode: sel.vatCode || 'none',
    };
    if (sel.type === 'account') body.contraAccountId = sel.entityId;
    else body.entityId = sel.entityId;
    await callAction(body);
    toast.success('Transaction allocated');
    loadTransactions();
    // After allocation, check if there are other similar unprocessed transactions
    // to suggest creating a categorisation rule
    if (tx?.description && selectedBank) {
      const pattern = extractPattern(tx.description);
      if (pattern.trim().length >= 3) {
        try {
          const params = new URLSearchParams({ pattern, matchType: 'contains', bankAccountId: selectedBank });
          const res = await fetch(`/api/accounting/bank-rules-preview?${params}`);
          const json = await res.json();
          const matchCount = json.data?.matchCount ?? 0;
          if (matchCount > 0) setRulePrompt({ tx, matchCount });
        } catch { /* non-critical — ignore preview errors */ }
      }
    }
  } catch (e) { toast.error(e instanceof Error ? e.message : 'Failed'); }
};

/** Opens the ExcludeReasonModal — actual API call happens in handleExcludeConfirm */
const handleExclude = (txId: string) => {
  setExcludingTxId(txId);
};

/** Called by ExcludeReasonModal on confirm — posts to API with reason then reloads */
const handleExcludeConfirm = async (reason: string) => {
  if (!excludingTxId) return;
  const txId = excludingTxId;
  setExcludingTxId(null);
  try {
    await callAction({ action: 'exclude', bankTransactionId: txId, excludeReason: reason });
    toast.success('Transaction excluded');
    loadTransactions();
  } catch (e) { toast.error(e instanceof Error ? e.message : 'Failed to exclude'); }
};

const handleUnmatch = async (txId: string) => {
  try {
    await callAction({ action: 'unmatch', bankTransactionId: txId });
    toast.success('Allocation undone');
    loadTransactions();
  } catch (e) { toast.error(e instanceof Error ? e.message : 'Failed'); }

/**
 * Bank Accounts API
 * GET /api/accounting/bank-accounts - List bank GL accounts with transaction summaries
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth } from '@/lib/auth';
import { log } from '@/lib/logger';
import { sql } from '@/lib/neon';

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method === 'PUT') {
    try {
      const { id, bankAccountNumber } = req.body;
      if (!id) return apiResponse.badRequest(res, 'id is required');
      await sql`
        UPDATE gl_accounts
        SET bank_account_number = ${bankAccountNumber || null},
            updated_at = NOW()
        WHERE id = ${id} AND account_subtype = 'bank'
      `;
      return apiResponse.success(res, { updated: true });
    } catch (err) {
      log.error('Failed to update bank account', { error: err }, 'accounting-api');
      return apiResponse.badRequest(res, 'Failed to update bank account');
    }
  }

  if (req.method !== 'GET') {
    return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET', 'PUT']);
  }

  try {
    const rows = await sql`
      SELECT
        ga.id,
        ga.account_code,
        ga.account_name,
        ga.description,
        ga.is_active,
        ga.bank_account_number,
        COALESCE(s.txn_count, 0) AS txn_count,
        COALESCE(s.total_debits, 0) AS total_debits,
        COALESCE(s.total_credits, 0) AS total_credits,
        COALESCE(s.total_credits, 0) - COALESCE(s.total_debits, 0) AS balance,
        s.first_date,
        s.last_date
      FROM gl_accounts ga
      LEFT JOIN LATERAL (
        SELECT
          COUNT(*)::INT AS txn_count,
          SUM(CASE WHEN bt.amount < 0 THEN ABS(bt.amount) ELSE 0 END) AS total_debits,
          SUM(CASE WHEN bt.amount > 0 THEN bt.amount ELSE 0 END) AS total_credits,
          MIN(bt.transaction_date) AS first_date,
          MAX(bt.transaction_date) AS last_date
        FROM bank_transactions bt
        WHERE bt.bank_account_id = ga.id
      ) s ON TRUE
      WHERE ga.account_subtype = 'bank'
        AND ga.is_active = TRUE
      ORDER BY ga.account_code
    `;

    const accounts = rows.map(r => ({
      id: r.id,
      accountCode: r.account_code,
      accountName: r.account_name,
      description: r.description,
      bankAccountNumber: r.bank_account_number || null,
      isActive: r.is_active,
      txnCount: Number(r.txn_count),
      totalDebits: Number(r.total_debits),
      totalCredits: Number(r.total_credits),
      balance: Number(r.balance),
      firstDate: r.first_date instanceof Date
        ? r.first_date.toISOString().split('T')[0]
        : r.first_date ? String(r.first_date).split('T')[0] : null,
      lastDate: r.last_date instanceof Date
        ? r.last_date.toISOString().split('T')[0]
        : r.last_date ? String(r.last_date).split('T')[0] : null,
    }));

    return apiResponse.success(res, accounts);
  } catch (err) {
    log.error('Failed to get bank accounts', { error: err }, 'accounting-api');
    return apiResponse.badRequest(res, 'Failed to get bank accounts');
  }
}

export default withAuth(withErrorHandler(handler));

/**
 * Statement Balance Widget
 * Displays the latest bank statement import batch balances alongside the
 * current GL balance, highlighting any discrepancy between them.
 */

'use client';

import { useEffect, useState } from 'react';
import { Loader2, AlertCircle, CheckCircle2, CalendarDays, Hash } from 'lucide-react';

// 🟢 WORKING: ZAR currency formatter (2 decimal places for reconciliation context)
const fmt = (amount: number): string =>
  new Intl.NumberFormat('en-ZA', {
    style: 'currency',
    currency: 'ZAR',
    minimumFractionDigits: 2,
    maximumFractionDigits: 2,
  }).format(amount);

interface ImportBatch {
  id: string;
  statementDate: string;
  bankFormat: string | null;
  openingBalance: number | null;
  closingBalance: number | null;
  transactionCount: number;
  createdAt: string;
}

interface Props {
  /** UUID of the bank account (gl_accounts.id with account_subtype = 'bank') */
  bankAccountId: string;
  /** Current GL balance to compare against the statement closing balance */
  glBalance?: number;
}

// 🟢 WORKING: Statement Balance Widget
export function StatementBalanceWidget({ bankAccountId, glBalance }: Props) {
  const [batch, setBatch] = useState<ImportBatch | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');

  useEffect(() => {
    if (!bankAccountId) return;

    let cancelled = false;
    setLoading(true);
    setError('');

    fetch(
      `/api/accounting/bank-import-batches?bankAccountId=${encodeURIComponent(bankAccountId)}`,
      { credentials: 'include' }
    )
      .then(r => r.json())
      .then(json => {
        if (cancelled) return;
        const batches: ImportBatch[] = json?.data?.batches ?? [];
        setBatch(batches[0] ?? null);
      })
      .catch(() => {
        if (!cancelled) setError('Failed to load statement data');
      })
      .finally(() => {
        if (!cancelled) setLoading(false);
      });

    return () => { cancelled = true; };
  }, [bankAccountId]);

  if (loading) {
    return (
      <div
        className="rounded-lg border border-[var(--ff-border-light)] bg-[var(--ff-bg-secondary)] p-4"
        style={{ minHeight: 100 }}
      >
        <div className="flex items-center gap-2 text-xs text-[var(--ff-text-tertiary)]">
          <Loader2 className="h-3.5 w-3.5 animate-spin" />
          Loading statement balances…
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="rounded-lg border border-[var(--ff-border-light)] bg-[var(--ff-bg-secondary)] p-4">
        <div className="flex items-center gap-2 text-xs text-red-400">
          <AlertCircle className="h-3.5 w-3.5" />
          {error}
        </div>
      </div>
    );
  }

  if (!batch) {
    return (
      <div className="rounded-lg border border-[var(--ff-border-light)] bg-[var(--ff-bg-secondary)] p-4">
        <p className="text-xs text-[var(--ff-text-tertiary)]">No statement imports found.</p>
      </div>
    );
  }

  const difference =
    batch.closingBalance !== null && glBalance !== undefined
      ? batch.closingBalance - glBalance
      : null;

  const isReconciled = difference !== null && Math.abs(difference) < 0.01;

  // Format the import date for display
  const importedOn = new Date(batch.createdAt).toLocaleDateString('en-ZA', {
    day: '2-digit',
    month: 'short',
    year: 'numeric',
  });

  return (
    <div className="rounded-lg border border-[var(--ff-border-light)] bg-[var(--ff-bg-secondary)]">
      {/* Header */}
      <div className="flex items-center justify-between border-b border-[var(--ff-border-light)] px-4 py-2.5">
        <h3 className="text-xs font-semibold uppercase tracking-wider text-[var(--ff-text-secondary)]">
          Statement Balance
        </h3>
        {batch.bankFormat && (
          <span className="rounded-full bg-[var(--ff-bg-tertiary)] px-2 py-0.5 text-[10px] font-medium text-[var(--ff-text-tertiary)]">
            {batch.bankFormat.toUpperCase()}
          </span>
        )}
      </div>

      {/* Balance rows */}
      <div className="divide-y divide-[var(--ff-border-light)]">
        {/* Opening Balance */}
        <div className="flex items-center justify-between px-4 py-2.5">
          <span className="text-xs text-[var(--ff-text-tertiary)]">Opening Balance</span>
          <span className="font-mono text-sm text-[var(--ff-text-primary)]">
            {batch.openingBalance !== null ? fmt(batch.openingBalance) : '—'}
          </span>
        </div>

        {/* Closing Balance */}
        <div className="flex items-center justify-between px-4 py-2.5">
          <span className="text-xs text-[var(--ff-text-tertiary)]">Closing Balance</span>
          <span className="font-mono text-sm font-medium text-[var(--ff-text-primary)]">
            {batch.closingBalance !== null ? fmt(batch.closingBalance) : '—'}
          </span>
        </div>

        {/* GL Balance */}
        {glBalance !== undefined && (
          <div className="flex items-center justify-between px-4 py-2.5">
            <span className="text-xs text-[var(--ff-text-tertiary)]">GL Balance</span>
            <span className="font-mono text-sm text-[var(--ff-text-primary)]">
              {fmt(glBalance)}
            </span>
          </div>
        )}

        {/* Difference */}
        {difference !== null && (
          <div className="flex items-center justify-between px-4 py-2.5">
            <span className="flex items-center gap-1.5 text-xs text-[var(--ff-text-tertiary)]">
              {isReconciled
                ? <CheckCircle2 className="h-3.5 w-3.5 text-emerald-500" />
                : <AlertCircle className="h-3.5 w-3.5 text-amber-400" />}
              Difference
            </span>
            <span
              className={`font-mono text-sm font-semibold ${
                isReconciled ? 'text-emerald-500' : 'text-amber-400'
              }`}
            >
              {isReconciled ? fmt(0) : fmt(difference)}
            </span>
          </div>
        )}
      </div>

      {/* Footer: import metadata */}
      <div className="flex items-center gap-4 border-t border-[var(--ff-border-light)] px-4 py-2 text-[10px] text-[var(--ff-text-tertiary)]">
        <span className="flex items-center gap-1">
          <CalendarDays className="h-3 w-3" />
          {batch.statementDate}
        </span>
        <span className="flex items-center gap-1">
          <Hash className="h-3 w-3" />
          {batch.transactionCount} transactions
        </span>
        <span className="ml-auto">Imported {importedOn}</span>
      </div>
    </div>
  );
}

export default StatementBalanceWidget;

