/**
 * Inbox Panel — unified feed + messaging views
 * Views: Feed (default) | Messages | Sent | Archived with compose modal and thread view
 */

import { useState } from 'react';
import {
  Inbox,
  Send,
  Archive,
  PenLine,
  CheckCheck,
  RefreshCw,
  Mail,
  Rss,
} from 'lucide-react';
import { cn } from '@/lib/utils';
import { useInternalMessages } from '../hooks/useInternalMessages';
import { MessageListItem } from './MessageListItem';
import { MessageThread } from './MessageThread';
import { ComposeMessageModal } from './ComposeMessageModal';
import { UnifiedFeedList } from './UnifiedFeedList';
import type { MessageView } from '../types/messaging.types';

type PanelView = 'feed' | MessageView;

const VIEWS: { key: PanelView; label: string; icon: React.ElementType }[] = [
  { key: 'feed', label: 'Feed', icon: Rss },
  { key: 'inbox', label: 'Messages', icon: Inbox },
  { key: 'sent', label: 'Sent', icon: Send },
  { key: 'archived', label: 'Archived', icon: Archive },
];

export function InboxPanel() {
  const [view, setView] = useState<PanelView>('feed');
  const [activeThread, setActiveThread] = useState<string | null>(null);
  const [showCompose, setShowCompose] = useState(false);

  // Messages hook — only needed for messaging views, pass 'inbox' when on feed
  const messageView: MessageView = view === 'feed' ? 'inbox' : view;
  const {
    messages,
    isLoading,
    hasMore,
    total,
    unreadCount,
    refetch,
    loadMore,
    markRead,
    markAllRead,
  } = useInternalMessages(messageView);

  const handleOpenThread = (messageId: string) => {
    // If opening from feed, switch to messages view context
    if (view === 'feed') {
      setView('inbox');
    }
    const msg = messages.find(m => m.id === messageId);
    if (msg && !msg.is_read) {
      markRead([messageId]);
    }
    setActiveThread(messageId);
  };

  const handleBackFromThread = () => {
    setActiveThread(null);
    refetch();
  };

  const handleMessageSent = () => {
    refetch();
  };

  // Thread view (shared between feed and messages)
  if (activeThread) {
    return (
      <MessageThread threadId={activeThread} onBack={handleBackFromThread} />
    );
  }

  const isFeed = view === 'feed';

  return (
    <div className="space-y-4">
      {/* Top bar: view toggle + actions */}
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-1">
          {VIEWS.map(v => {
            const Icon = v.icon;
            const isActive = view === v.key;
            return (
              <button
                key={v.key}
                type="button"
                onClick={() => setView(v.key)}
                className={cn(
                  'flex items-center gap-1.5 px-3 py-1.5 text-xs font-medium rounded-lg transition-colors',
                  isActive
                    ? 'bg-[var(--ff-primary)]/10 text-[var(--ff-primary)]'
                    : 'text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)] hover:bg-[var(--ff-bg-tertiary)]'
                )}
              >
                <Icon className="w-3.5 h-3.5" />
                {v.label}
                {v.key === 'inbox' && unreadCount > 0 && (
                  <span className="px-1.5 py-0.5 text-[10px] font-semibold bg-blue-500 text-white rounded-full">
                    {unreadCount}
                  </span>
                )}
              </button>
            );
          })}
        </div>

        <div className="flex items-center gap-2">
          {view === 'inbox' && unreadCount > 0 && (
            <button
              type="button"
              onClick={markAllRead}
              className="flex items-center gap-1.5 px-3 py-1.5 text-xs font-medium text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)] border border-[var(--ff-border-light)] rounded-lg hover:bg-[var(--ff-bg-tertiary)] transition-colors"
            >
              <CheckCheck className="w-3.5 h-3.5" />
              Mark all read
            </button>
          )}

          {!isFeed && (
            <button
              type="button"
              onClick={() => refetch()}
              disabled={isLoading}
              className="flex items-center gap-1.5 px-3 py-1.5 text-xs font-medium text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)] border border-[var(--ff-border-light)] rounded-lg hover:bg-[var(--ff-bg-tertiary)] transition-colors disabled:opacity-50"
            >
              <RefreshCw className={cn('w-3.5 h-3.5', isLoading && 'animate-spin')} />
            </button>
          )}

          <button
            type="button"
            onClick={() => setShowCompose(true)}
            className="flex items-center gap-1.5 px-4 py-1.5 text-sm font-medium bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors"
          >
            <PenLine className="w-3.5 h-3.5" />
            Compose
          </button>
        </div>
      </div>

      {/* Feed view */}
      {isFeed ? (
        <UnifiedFeedList onOpenThread={handleOpenThread} />
      ) : (
        <>
          {/* Message count */}
          <p className="text-xs text-[var(--ff-text-tertiary)]">
            {total > 0
              ? `${total} message${total !== 1 ? 's' : ''}${view === 'inbox' && unreadCount > 0 ? ` (${unreadCount} unread)` : ''}`
              : ''}
          </p>

          {/* Message list */}
          {isLoading && messages.length === 0 ? (
            <div className="flex items-center justify-center py-12">
              <RefreshCw className="w-5 h-5 animate-spin text-[var(--ff-text-tertiary)]" />
              <span className="ml-2 text-sm text-[var(--ff-text-secondary)]">Loading messages...</span>
            </div>
          ) : messages.length === 0 ? (
            <div className="text-center py-12">
              <Mail className="w-10 h-10 mx-auto text-[var(--ff-text-tertiary)] mb-3" />
              <p className="text-sm text-[var(--ff-text-secondary)]">
                {view === 'inbox' ? 'Your inbox is empty' :
                 view === 'sent' ? 'No sent messages' :
                 'No archived messages'}
              </p>
              {view === 'inbox' && (
                <button
                  type="button"
                  onClick={() => setShowCompose(true)}
                  className="mt-3 text-sm text-blue-500 hover:text-blue-400"
                >
                  Send your first message
                </button>
              )}
            </div>
          ) : (
            <div className="border border-[var(--ff-border-light)] rounded-lg overflow-hidden">
              {messages.map(msg => (
                <MessageListItem
                  key={msg.id}
                  message={msg}
                  onClick={handleOpenThread}
                  showSender={view !== 'sent'}
                />
              ))}

              {hasMore && (
                <div className="flex justify-center py-3 border-t border-[var(--ff-border-light)]">
                  <button
                    type="button"
                    onClick={loadMore}
                    disabled={isLoading}
                    className="px-4 py-1.5 text-sm font-medium text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)] border border-[var(--ff-border-light)] rounded-lg hover:bg-[var(--ff-bg-tertiary)] transition-colors disabled:opacity-50"
                  >
                    {isLoading ? 'Loading...' : 'Load more'}
                  </button>
                </div>
              )}
            </div>
          )}
        </>
      )}

      {/* Compose modal */}
      <ComposeMessageModal
        isOpen={showCompose}
        onClose={() => setShowCompose(false)}
        onSent={handleMessageSent}
      />
    </div>
  );
}

/**
 * Single message row in the inbox/sent list
 */

import { MessageCircle, AlertTriangle, Clock } from 'lucide-react';
import { cn } from '@/lib/utils';
import type { MessageListItem as MessageListItemType } from '../types/messaging.types';

interface MessageListItemProps {
  message: MessageListItemType;
  onClick: (id: string) => void;
  showSender?: boolean;
}

function formatRelative(iso: string): string {
  const now = Date.now();
  const then = new Date(iso).getTime();
  const diffMs = now - then;
  const diffMin = Math.floor(diffMs / 60_000);
  if (diffMin < 1) return 'just now';
  if (diffMin < 60) return `${diffMin}m ago`;
  const diffHrs = Math.floor(diffMin / 60);
  if (diffHrs < 24) return `${diffHrs}h ago`;
  const diffDays = Math.floor(diffHrs / 24);
  if (diffDays < 7) return `${diffDays}d ago`;
  return new Date(iso).toLocaleDateString('en-ZA', { day: '2-digit', month: 'short' });
}

export function MessageListItem({ message, onClick, showSender = true }: MessageListItemProps) {
  const isUnread = !message.is_read;
  const isUrgent = message.priority === 'urgent';
  const isHigh = message.priority === 'high';

  return (
    <button
      type="button"
      onClick={() => onClick(message.id)}
      className={cn(
        'w-full text-left px-4 py-3 border-b border-[var(--ff-border-light)] hover:bg-[var(--ff-bg-tertiary)] transition-colors',
        isUnread && 'bg-blue-500/5'
      )}
    >
      <div className="flex items-start gap-3">
        {/* Unread dot */}
        <div className="pt-1.5 w-2 flex-shrink-0">
          {isUnread && (
            <div className="w-2 h-2 rounded-full bg-blue-500" />
          )}
        </div>

        {/* Sender initial */}
        <div className="w-8 h-8 rounded-full bg-[var(--ff-bg-tertiary)] flex items-center justify-center flex-shrink-0">
          <span className="text-xs font-semibold text-[var(--ff-text-secondary)]">
            {message.sender_name?.charAt(0)?.toUpperCase() || '?'}
          </span>
        </div>

        {/* Content */}
        <div className="flex-1 min-w-0">
          <div className="flex items-center gap-2">
            {showSender && (
              <span className={cn(
                'text-sm truncate',
                isUnread
                  ? 'font-semibold text-[var(--ff-text-primary)]'
                  : 'font-medium text-[var(--ff-text-secondary)]'
              )}>
                {message.sender_name}
              </span>
            )}

            {/* Priority badge */}
            {isUrgent && (
              <span className="inline-flex items-center gap-0.5 px-1.5 py-0.5 text-[10px] font-semibold bg-red-500/15 text-red-400 rounded">
                <AlertTriangle className="w-2.5 h-2.5" />
                Urgent
              </span>
            )}
            {isHigh && (
              <span className="px-1.5 py-0.5 text-[10px] font-semibold bg-orange-500/15 text-orange-400 rounded">
                High
              </span>
            )}

            <span className="ml-auto text-xs text-[var(--ff-text-tertiary)] whitespace-nowrap flex-shrink-0">
              {formatRelative(message.latest_reply_at || message.created_at)}
            </span>
          </div>

          {/* Subject */}
          {message.subject && (
            <p className={cn(
              'text-sm truncate mt-0.5',
              isUnread ? 'text-[var(--ff-text-primary)]' : 'text-[var(--ff-text-secondary)]'
            )}>
              {message.subject}
            </p>
          )}

          {/* Body preview */}
          <p className="text-xs text-[var(--ff-text-tertiary)] truncate mt-0.5">
            {message.body}
          </p>

          {/* Meta row */}
          <div className="flex items-center gap-3 mt-1">
            {message.reply_count > 0 && (
              <span className="inline-flex items-center gap-1 text-[10px] text-[var(--ff-text-tertiary)]">
                <MessageCircle className="w-3 h-3" />
                {message.reply_count} {message.reply_count === 1 ? 'reply' : 'replies'}
              </span>
            )}
            {message.recipient_count > 1 && (
              <span className="text-[10px] text-[var(--ff-text-tertiary)]">
                {message.recipient_count} recipients
              </span>
            )}
            {message.context_module && (
              <span className="px-1.5 py-0.5 text-[10px] font-medium bg-[var(--ff-bg-tertiary)] text-[var(--ff-text-tertiary)] rounded capitalize">
                {message.context_module}
              </span>
            )}
          </div>
        </div>
      </div>
    </button>
  );
}

/**
 * Thread view - shows root message + replies with inline reply form
 */

import { useState, useEffect, useCallback } from 'react';
import { ArrowLeft, Send, Loader2, RefreshCw, Link as LinkIcon } from 'lucide-react';
import { cn } from '@/lib/utils';
import { log } from '@/lib/logger';
import type { ThreadMessage, MessageRecipient } from '../types/messaging.types';

interface MessageThreadProps {
  threadId: string;
  onBack: () => void;
}

interface ThreadData {
  root: ThreadMessage & {
    subject: string | null;
    priority: string;
    context_module: string | null;
    context_url: string | null;
  };
  replies: ThreadMessage[];
  recipients: MessageRecipient[];
}

function formatTimestamp(iso: string): string {
  const d = new Date(iso);
  return d.toLocaleDateString('en-ZA', { day: '2-digit', month: 'short' })
    + ' ' + d.toLocaleTimeString('en-ZA', { hour: '2-digit', minute: '2-digit' });
}

export function MessageThread({ threadId, onBack }: MessageThreadProps) {
  const [data, setData] = useState<ThreadData | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [replyBody, setReplyBody] = useState('');
  const [isSending, setIsSending] = useState(false);

  const fetchThread = useCallback(async () => {
    setIsLoading(true);
    try {
      const res = await fetch(
        `/api/communications/messages-thread?threadId=${threadId}`,
        { credentials: 'include' }
      );
      const json = await res.json();
      if (json.success) {
        setData(json.data);
      }
    } catch (err) {
      log.error('Failed to fetch thread:', err);
    } finally {
      setIsLoading(false);
    }
  }, [threadId]);

  useEffect(() => {
    fetchThread();
  }, [fetchThread]);

  const handleReply = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!replyBody.trim() || !data) return;

    setIsSending(true);
    try {
      const recipientIds = data.recipients.map(r => r.id);
      // Also include the original sender if not already a recipient
      if (!recipientIds.includes(data.root.sender_id)) {
        recipientIds.push(data.root.sender_id);
      }

      const res = await fetch('/api/communications/messages', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        credentials: 'include',
        body: JSON.stringify({
          recipients: recipientIds,
          body: replyBody.trim(),
          threadId,
        }),
      });

      const json = await res.json();
      if (json.success) {
        setReplyBody('');
        await fetchThread();
      }
    } catch (err) {
      log.error('Failed to send reply:', err);
    } finally {
      setIsSending(false);
    }
  };

  if (isLoading) {
    return (
      <div className="flex items-center justify-center py-12">
        <RefreshCw className="w-5 h-5 animate-spin text-[var(--ff-text-tertiary)]" />
        <span className="ml-2 text-sm text-[var(--ff-text-secondary)]">Loading thread...</span>
      </div>
    );
  }

  if (!data) {
    return (
      <div className="text-center py-12">
        <p className="text-sm text-[var(--ff-text-secondary)]">Message not found</p>
        <button
          type="button"
          onClick={onBack}
          className="mt-2 text-sm text-blue-500 hover:text-blue-400"
        >
          Back to inbox
        </button>
      </div>
    );
  }

  const { root, replies, recipients } = data;

  return (
    <div className="flex flex-col h-full">
      {/* Header */}
      <div className="flex items-center gap-3 pb-4 border-b border-[var(--ff-border-light)]">
        <button
          type="button"
          onClick={onBack}
          className="p-1.5 rounded-lg hover:bg-[var(--ff-bg-tertiary)] transition-colors"
        >
          <ArrowLeft className="w-4 h-4 text-[var(--ff-text-secondary)]" />
        </button>
        <div className="flex-1 min-w-0">
          <h3 className="text-sm font-semibold text-[var(--ff-text-primary)] truncate">
            {root.subject || '(No subject)'}
          </h3>
          <p className="text-xs text-[var(--ff-text-tertiary)]">
            {recipients.length} participant{recipients.length !== 1 ? 's' : ''}
            {root.context_module && (
              <span className="ml-2 capitalize">
                <LinkIcon className="w-3 h-3 inline mr-0.5" />
                {root.context_module}
              </span>
            )}
          </p>
        </div>
        {root.context_url && (
          <a
            href={root.context_url}
            className="px-3 py-1.5 text-xs font-medium text-blue-400 hover:text-blue-300 border border-[var(--ff-border-light)] rounded-lg hover:bg-[var(--ff-bg-tertiary)] transition-colors"
          >
            View Context
          </a>
        )}
      </div>

      {/* Messages */}
      <div className="flex-1 overflow-y-auto py-4 space-y-4">
        {/* Root message */}
        <MessageBubble
          senderName={root.sender_name}
          body={root.body}
          timestamp={root.created_at}
        />

        {/* Replies */}
        {replies.map(reply => (
          <MessageBubble
            key={reply.id}
            senderName={reply.sender_name}
            body={reply.body}
            timestamp={reply.created_at}
          />
        ))}
      </div>

      {/* Reply form */}
      <form
        onSubmit={handleReply}
        className="flex items-end gap-2 pt-4 border-t border-[var(--ff-border-light)]"
      >
        <textarea
          value={replyBody}
          onChange={e => setReplyBody(e.target.value)}
          placeholder="Type a reply..."
          rows={2}
          className="flex-1 px-3 py-2 text-sm rounded-lg border border-[var(--ff-border-light)] bg-[var(--ff-bg-primary)] text-[var(--ff-text-primary)] placeholder:text-[var(--ff-text-tertiary)] focus:outline-none focus:ring-2 focus:ring-[var(--ff-primary)]/50 resize-none"
        />
        <button
          type="submit"
          disabled={isSending || !replyBody.trim()}
          className={cn(
            'flex items-center gap-1.5 px-4 py-2 text-sm font-medium rounded-lg transition-colors',
            isSending || !replyBody.trim()
              ? 'bg-[var(--ff-bg-tertiary)] text-[var(--ff-text-tertiary)] cursor-not-allowed'
              : 'bg-blue-600 text-white hover:bg-blue-700'
          )}
        >
          {isSending ? (
            <Loader2 className="w-4 h-4 animate-spin" />
          ) : (
            <Send className="w-4 h-4" />
          )}
        </button>
      </form>
    </div>
  );
}

function MessageBubble({
  senderName,
  body,
  timestamp,
}: {
  senderName: string;
  body: string;
  timestamp: string;
}) {
  return (
    <div className="flex gap-3">
      <div className="w-8 h-8 rounded-full bg-[var(--ff-bg-tertiary)] flex items-center justify-center flex-shrink-0">
        <span className="text-xs font-semibold text-[var(--ff-text-secondary)]">
          {senderName?.charAt(0)?.toUpperCase() || '?'}
        </span>
