}

/**
 * Compose Message Modal
 * Send a new internal message to one or more recipients
 */

import { useState } from 'react';
import { X, Send, Loader2 } from 'lucide-react';
import { cn } from '@/lib/utils';
import { log } from '@/lib/logger';
import { RecipientPicker } from './RecipientPicker';
import type { UserOption, MessagePriority } from '../types/messaging.types';

interface ComposeMessageModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSent: () => void;
  threadId?: string;
  defaultSubject?: string;
}

const PRIORITY_OPTIONS: { value: MessagePriority; label: string; color: string }[] = [
  { value: 'low', label: 'Low', color: 'text-gray-400' },
  { value: 'normal', label: 'Normal', color: 'text-blue-400' },
  { value: 'high', label: 'High', color: 'text-orange-400' },
  { value: 'urgent', label: 'Urgent', color: 'text-red-400' },
];

export function ComposeMessageModal({
  isOpen,
  onClose,
  onSent,
  threadId,
  defaultSubject,
}: ComposeMessageModalProps) {
  const [recipients, setRecipients] = useState<UserOption[]>([]);
  const [subject, setSubject] = useState(defaultSubject || '');
  const [body, setBody] = useState('');
  const [priority, setPriority] = useState<MessagePriority>('normal');
  const [isSending, setIsSending] = useState(false);
  const [error, setError] = useState<string | null>(null);

  if (!isOpen) return null;

  const canSend = recipients.length > 0 && body.trim().length > 0;

  const handleSend = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!canSend) return;

    setIsSending(true);
    setError(null);

    try {
      const res = await fetch('/api/communications/messages', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        credentials: 'include',
        body: JSON.stringify({
          recipients: recipients.map(r => r.id),
          subject: subject.trim() || undefined,
          body: body.trim(),
          priority,
          threadId: threadId || undefined,
        }),
      });

      const json = await res.json();

      if (json.success) {
        setRecipients([]);
        setSubject('');
        setBody('');
        setPriority('normal');
        onSent();
        onClose();
      } else {
        setError(json.error?.message || 'Failed to send message');
      }
    } catch (err) {
      const msg = err instanceof Error ? err.message : 'Unknown error';
      log.error('Compose message failed:', err);
      setError(msg);
    } finally {
      setIsSending(false);
    }
  };

  const inputClasses =
    'w-full px-3 py-2 text-sm rounded-lg border border-[var(--ff-border-light)] bg-[var(--ff-bg-primary)] text-[var(--ff-text-primary)] placeholder:text-[var(--ff-text-tertiary)] focus:outline-none focus:ring-2 focus:ring-[var(--ff-primary)]/50 focus:border-[var(--ff-primary)]';

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 p-4">
      <div className="w-full max-w-lg max-h-[90vh] overflow-y-auto rounded-xl bg-[var(--ff-bg-secondary)] border border-[var(--ff-border-light)] shadow-xl">
        {/* Header */}
        <div className="flex items-center justify-between border-b border-[var(--ff-border-light)] p-4">
          <h2 className="text-lg font-semibold text-[var(--ff-text-primary)]">
            {threadId ? 'Reply' : 'New Message'}
          </h2>
          <button
            type="button"
            onClick={onClose}
            className="p-1 rounded hover:bg-[var(--ff-bg-tertiary)] transition-colors"
          >
            <X className="w-5 h-5 text-[var(--ff-text-secondary)]" />
          </button>
        </div>

        <form onSubmit={handleSend} className="p-4 space-y-4">
          {/* Recipients */}
          {!threadId && (
            <div>
              <label className="block text-xs font-medium text-[var(--ff-text-secondary)] mb-1">
                To *
              </label>
              <RecipientPicker selected={recipients} onChange={setRecipients} />
            </div>
          )}

          {/* Subject */}
          {!threadId && (
            <div>
              <label className="block text-xs font-medium text-[var(--ff-text-secondary)] mb-1">
                Subject
              </label>
              <input
                type="text"
                value={subject}
                onChange={e => setSubject(e.target.value)}
                placeholder="Message subject (optional)"
                className={inputClasses}
              />
            </div>
          )}

          {/* Priority */}
          {!threadId && (
            <div>
              <label className="block text-xs font-medium text-[var(--ff-text-secondary)] mb-1">
                Priority
              </label>
              <div className="flex gap-2">
                {PRIORITY_OPTIONS.map(opt => (
                  <button
                    key={opt.value}
                    type="button"
                    onClick={() => setPriority(opt.value)}
                    className={cn(
                      'px-3 py-1.5 text-xs font-medium rounded-lg border transition-colors',
                      priority === opt.value
                        ? 'border-[var(--ff-primary)] bg-[var(--ff-primary)]/10 text-[var(--ff-primary)]'
                        : 'border-[var(--ff-border-light)] text-[var(--ff-text-secondary)] hover:bg-[var(--ff-bg-tertiary)]'
                    )}
                  >
                    {opt.label}
                  </button>
                ))}
              </div>
            </div>
          )}

          {/* Body */}
          <div>
            <label className="block text-xs font-medium text-[var(--ff-text-secondary)] mb-1">
              Message *
            </label>
            <textarea
              value={body}
              onChange={e => setBody(e.target.value)}
              placeholder="Type your message..."
              required
              rows={6}
              className={cn(inputClasses, 'resize-y min-h-[100px]')}
            />
          </div>

          {/* Error */}
          {error && (
            <p className="text-sm text-red-500">{error}</p>
          )}

          {/* Actions */}
          <div className="flex justify-end gap-3 pt-2 border-t border-[var(--ff-border-light)]">
            <button
              type="button"
              onClick={onClose}
              className="px-4 py-2 text-sm font-medium text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)] border border-[var(--ff-border-light)] rounded-lg hover:bg-[var(--ff-bg-tertiary)] transition-colors"
            >
              Cancel
            </button>
            <button
              type="submit"
              disabled={isSending || !canSend}
              className={cn(
                'flex items-center gap-2 px-5 py-2 text-sm font-medium rounded-lg transition-colors',
                isSending || !canSend
                  ? 'bg-[var(--ff-bg-tertiary)] text-[var(--ff-text-tertiary)] cursor-not-allowed'
                  : 'bg-blue-600 text-white hover:bg-blue-700'
              )}
            >
              {isSending ? (
                <Loader2 className="w-4 h-4 animate-spin" />
              ) : (
                <Send className="w-4 h-4" />
              )}
              {isSending ? 'Sending...' : 'Send'}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
}

/**
 * Searchable multi-select recipient picker
 * Fetches users from /api/admin/users?search=
 */

import { useState, useEffect, useRef, useCallback } from 'react';
import { X, Search, Loader2 } from 'lucide-react';
import { cn } from '@/lib/utils';
import type { UserOption } from '../types/messaging.types';

interface RecipientPickerProps {
  selected: UserOption[];
  onChange: (users: UserOption[]) => void;
}

export function RecipientPicker({ selected, onChange }: RecipientPickerProps) {
  const [query, setQuery] = useState('');
  const [results, setResults] = useState<UserOption[]>([]);
  const [isSearching, setIsSearching] = useState(false);
  const [isOpen, setIsOpen] = useState(false);
  const debounceRef = useRef<ReturnType<typeof setTimeout>>();
  const containerRef = useRef<HTMLDivElement>(null);

  const search = useCallback(async (searchQuery: string) => {
    if (!searchQuery.trim()) {
      setResults([]);
      return;
    }

    setIsSearching(true);
    try {
      const res = await fetch(
        `/api/admin/users?search=${encodeURIComponent(searchQuery)}&status=active`,
        { credentials: 'include' }
      );
      const json = await res.json();
      if (json.success) {
        const users: UserOption[] = (json.data.users || []).map(
          (u: { id: string; firstName: string; lastName: string; email: string; department: string }) => ({
            id: u.id,
            name: `${u.firstName || ''} ${u.lastName || ''}`.trim() || u.email,
            email: u.email,
            department: u.department || null,
          })
        );
        // Filter out already-selected users
        const selectedIds = new Set(selected.map(s => s.id));
        setResults(users.filter(u => !selectedIds.has(u.id)));
      }
    } catch {
      setResults([]);
    } finally {
      setIsSearching(false);
    }
  }, [selected]);

  useEffect(() => {
    if (debounceRef.current) clearTimeout(debounceRef.current);
    if (!query.trim()) {
      setResults([]);
      return;
    }
    debounceRef.current = setTimeout(() => search(query), 300);
    return () => {
      if (debounceRef.current) clearTimeout(debounceRef.current);
    };
  }, [query, search]);

  // Close dropdown on outside click
  useEffect(() => {
    function handleClick(e: MouseEvent) {
      if (containerRef.current && !containerRef.current.contains(e.target as Node)) {
        setIsOpen(false);
      }
    }
    document.addEventListener('mousedown', handleClick);
    return () => document.removeEventListener('mousedown', handleClick);
  }, []);

  const addRecipient = (user: UserOption) => {
    onChange([...selected, user]);
    setQuery('');
    setResults([]);
  };

  const removeRecipient = (userId: string) => {
    onChange(selected.filter(u => u.id !== userId));
  };

  return (
    <div ref={containerRef} className="relative">
      {/* Selected chips */}
      {selected.length > 0 && (
        <div className="flex flex-wrap gap-1.5 mb-2">
          {selected.map(user => (
            <span
              key={user.id}
              className="inline-flex items-center gap-1 px-2.5 py-1 text-xs font-medium bg-blue-500/15 text-blue-400 rounded-full"
            >
              {user.name}
              <button
                type="button"
                onClick={() => removeRecipient(user.id)}
                className="hover:text-blue-200 transition-colors"
              >
                <X className="w-3 h-3" />
              </button>
            </span>
          ))}
        </div>
      )}

      {/* Search input */}
      <div className="relative">
        <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-[var(--ff-text-tertiary)]" />
        <input
          type="text"
          value={query}
          onChange={e => {
            setQuery(e.target.value);
            setIsOpen(true);
          }}
          onFocus={() => setIsOpen(true)}
          placeholder="Search users by name or email..."
          className="w-full pl-9 pr-8 py-2 text-sm rounded-lg border border-[var(--ff-border-light)] bg-[var(--ff-bg-primary)] text-[var(--ff-text-primary)] placeholder:text-[var(--ff-text-tertiary)] focus:outline-none focus:ring-2 focus:ring-[var(--ff-primary)]/50 focus:border-[var(--ff-primary)]"
        />
        {isSearching && (
          <Loader2 className="absolute right-3 top-1/2 -translate-y-1/2 w-4 h-4 animate-spin text-[var(--ff-text-tertiary)]" />
        )}
      </div>

      {/* Dropdown results */}
      {isOpen && results.length > 0 && (
        <div className="absolute z-50 mt-1 w-full max-h-48 overflow-y-auto rounded-lg border border-[var(--ff-border-light)] bg-[var(--ff-bg-secondary)] shadow-lg">
          {results.map(user => (
            <button
              key={user.id}
              type="button"
              onClick={() => addRecipient(user)}
              className="w-full text-left px-3 py-2 text-sm hover:bg-[var(--ff-bg-tertiary)] transition-colors"
            >
              <span className="text-[var(--ff-text-primary)]">{user.name}</span>
              <span className="text-xs text-[var(--ff-text-tertiary)] ml-2">{user.email}</span>
              {user.department && (
                <span className={cn(
                  'text-xs text-[var(--ff-text-tertiary)] ml-1',
                  'before:content-["·"] before:mx-1'
                )}>
                  {user.department}
                </span>
              )}
            </button>
          ))}
        </div>
      )}
    </div>
  );
}

/**
 * Single feed item row — channel icon, title, body preview, timestamp, unread dot
 */

import {
  Mail,
  MessageSquare,
  Bell,
  CheckSquare,
  AlertTriangle,
} from 'lucide-react';
import { cn } from '@/lib/utils';
import type { FeedItem } from '../types/hub.types';

interface FeedItemRowProps {
  item: FeedItem;
  onClick: (item: FeedItem) => void;
}

const CHANNEL_CONFIG = {
  message: {
    icon: MessageSquare,
    color: 'text-blue-400',
    bg: 'bg-blue-500/10',
    label: 'Message',
  },
  email: {
    icon: Mail,
    color: 'text-purple-400',
    bg: 'bg-purple-500/10',
    label: 'Email',
  },
  notification: {
    icon: Bell,
    color: 'text-amber-400',
    bg: 'bg-amber-500/10',
    label: 'Notification',
  },
  meeting: {
    icon: CheckSquare,
    color: 'text-green-400',
    bg: 'bg-green-500/10',
    label: 'Action Item',
  },
  whatsapp: {
    icon: MessageSquare,
    color: 'text-emerald-400',
    bg: 'bg-emerald-500/10',
    label: 'WhatsApp',
  },
} as const;

function formatRelative(iso: string): string {
  const now = Date.now();
  const then = new Date(iso).getTime();
  const diffMs = now - then;
  const diffMin = Math.floor(diffMs / 60_000);
  if (diffMin < 1) return 'just now';
  if (diffMin < 60) return `${diffMin}m ago`;
  const diffHrs = Math.floor(diffMin / 60);
  if (diffHrs < 24) return `${diffHrs}h ago`;
  const diffDays = Math.floor(diffHrs / 24);
  if (diffDays < 7) return `${diffDays}d ago`;
  return new Date(iso).toLocaleDateString('en-ZA', { day: '2-digit', month: 'short' });
}

export function FeedItemRow({ item, onClick }: FeedItemRowProps) {
  const config = CHANNEL_CONFIG[item.channel] || CHANNEL_CONFIG.notification;
  const Icon = config.icon;
  const meta = item.metadata || {};

  const isUrgent = meta.priority === 'urgent' || meta.severity === 'error';
  const isHigh = meta.priority === 'high' || meta.severity === 'warning';

  return (
    <button
      type="button"
      onClick={() => onClick(item)}
      className={cn(
        'w-full text-left px-4 py-3 border-b border-[var(--ff-border-light)] hover:bg-[var(--ff-bg-tertiary)] transition-colors',
        !item.isRead && 'bg-blue-500/5'
      )}
    >
      <div className="flex items-start gap-3">
        {/* Unread dot */}
        <div className="pt-1.5 w-2 flex-shrink-0">
          {!item.isRead && (
            <div className="w-2 h-2 rounded-full bg-blue-500" />
          )}
        </div>

        {/* Channel icon */}
        <div className={cn(
          'w-8 h-8 rounded-full flex items-center justify-center flex-shrink-0',
          config.bg
        )}>
          <Icon className={cn('w-4 h-4', config.color)} />
        </div>

        {/* Content */}
        <div className="flex-1 min-w-0">
          <div className="flex items-center gap-2">
            <span className={cn(
              'text-sm truncate',
              !item.isRead
                ? 'font-semibold text-[var(--ff-text-primary)]'
                : 'font-medium text-[var(--ff-text-secondary)]'
            )}>
              {item.title}
            </span>

            {/* Priority / severity badge */}
            {isUrgent && (
              <span className="inline-flex items-center gap-0.5 px-1.5 py-0.5 text-[10px] font-semibold bg-red-500/15 text-red-400 rounded">
                <AlertTriangle className="w-2.5 h-2.5" />
                Urgent
              </span>
            )}
            {isHigh && !isUrgent && (
              <span className="px-1.5 py-0.5 text-[10px] font-semibold bg-orange-500/15 text-orange-400 rounded">
                High
              </span>
            )}

            <span className="ml-auto text-xs text-[var(--ff-text-tertiary)] whitespace-nowrap flex-shrink-0">
              {formatRelative(item.timestamp)}
            </span>
          </div>

          {/* Body preview */}
          {item.body && (
            <p className="text-xs text-[var(--ff-text-tertiary)] truncate mt-0.5">
              {item.body}
            </p>
          )}

          {/* Meta row */}
          <div className="flex items-center gap-3 mt-1">
            <span className={cn(
              'px-1.5 py-0.5 text-[10px] font-medium rounded',
              config.bg, config.color
            )}>
              {config.label}
            </span>

            {/* Reply count for messages */}
            {item.channel === 'message' && Number(meta.reply_count) > 0 && (
              <span className="text-[10px] text-[var(--ff-text-tertiary)]">
                {meta.reply_count} {Number(meta.reply_count) === 1 ? 'reply' : 'replies'}
              </span>
            )}

            {/* Email status */}
            {item.channel === 'email' && meta.status && (
              <span className="text-[10px] text-[var(--ff-text-tertiary)] capitalize">
                {String(meta.status)}
              </span>
            )}

            {/* Action item due date */}
            {item.channel === 'meeting' && meta.due_date && (
              <span className="text-[10px] text-[var(--ff-text-tertiary)]">
                Due: {new Date(String(meta.due_date)).toLocaleDateString('en-ZA', { day: '2-digit', month: 'short' })}
              </span>
            )}

            {/* Source module badge */}
            {item.sourceModule && item.sourceModule !== config.label.toLowerCase() && (
              <span className="px-1.5 py-0.5 text-[10px] font-medium bg-[var(--ff-bg-tertiary)] text-[var(--ff-text-tertiary)] rounded capitalize">
                {item.sourceModule}
              </span>
            )}
          </div>
        </div>
      </div>
    </button>
  );
}

/**
 * Unified Feed List — channel filter chips + chronological feed items + pagination
 */

import { useState, useCallback } from 'react';
import { useRouter } from 'next/router';
import {
  RefreshCw,
  Rss,
  MessageSquare,
  Mail,
  Bell,
  CheckSquare,
} from 'lucide-react';
import { cn } from '@/lib/utils';
import { useUnifiedFeed } from '../hooks/useUnifiedFeed';
import { FeedItemRow } from './FeedItemRow';
import type { FeedItem } from '../types/hub.types';

type Channel = 'message' | 'email' | 'notification' | 'meeting';

const CHANNEL_FILTERS: {
  key: Channel | 'all';
  label: string;
  icon: React.ElementType;
}[] = [
  { key: 'all', label: 'All', icon: Rss },
  { key: 'message', label: 'Messages', icon: MessageSquare },
  { key: 'email', label: 'Email', icon: Mail },
  { key: 'notification', label: 'Notifications', icon: Bell },
  { key: 'meeting', label: 'Action Items', icon: CheckSquare },
];

interface UnifiedFeedListProps {
  onOpenThread: (messageId: string) => void;
}

export function UnifiedFeedList({ onOpenThread }: UnifiedFeedListProps) {
  const router = useRouter();
  const [activeFilter, setActiveFilter] = useState<Channel | 'all'>('all');

  const channels = activeFilter === 'all' ? undefined : [activeFilter];
  const { items, isLoading, hasMore, total, counts, refetch, loadMore } =
    useUnifiedFeed(channels);

  const handleItemClick = useCallback(
    (item: FeedItem) => {
      switch (item.channel) {
        case 'message':
          // Open thread within InboxPanel
          if (item.sourceId) {
            onOpenThread(item.sourceId);
          }
          break;
        case 'notification':
          if (item.actionUrl) {
            router.push(item.actionUrl);
          }
          break;
        case 'meeting':
          if (item.actionUrl) {
            router.push(item.actionUrl);
          }
          break;
        case 'email':
          // Switch to email tab
          router.push('/communications?tab=email', undefined, { shallow: true });
          break;
        default:
          break;
      }
    },
    [onOpenThread, router]
  );

  const getCount = (key: Channel | 'all'): number => {
    if (key === 'all') {
      return counts.message + counts.email + counts.notification + counts.meeting;
    }
    return counts[key] || 0;
  };

  return (
    <div className="space-y-4">
      {/* Filter chips + refresh */}
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-1 flex-wrap">
          {CHANNEL_FILTERS.map(f => {
            const Icon = f.icon;
            const isActive = activeFilter === f.key;
            const count = getCount(f.key);
            return (
              <button
                key={f.key}
                type="button"
                onClick={() => setActiveFilter(f.key)}
                className={cn(
                  'flex items-center gap-1.5 px-3 py-1.5 text-xs font-medium rounded-lg transition-colors',
                  isActive
                    ? 'bg-[var(--ff-primary)]/10 text-[var(--ff-primary)]'
                    : 'text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)] hover:bg-[var(--ff-bg-tertiary)]'
                )}
              >
                <Icon className="w-3.5 h-3.5" />
                {f.label}
                {count > 0 && (
                  <span className={cn(
                    'px-1.5 py-0.5 text-[10px] font-semibold rounded-full',
                    isActive
                      ? 'bg-[var(--ff-primary)]/20 text-[var(--ff-primary)]'
                      : 'bg-[var(--ff-bg-tertiary)] text-[var(--ff-text-tertiary)]'
                  )}>
                    {count}
                  </span>
                )}
              </button>
            );
          })}
        </div>

        <button
          type="button"
          onClick={() => refetch()}
          disabled={isLoading}
          className="flex items-center gap-1.5 px-3 py-1.5 text-xs font-medium text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)] border border-[var(--ff-border-light)] rounded-lg hover:bg-[var(--ff-bg-tertiary)] transition-colors disabled:opacity-50"
        >
          <RefreshCw className={cn('w-3.5 h-3.5', isLoading && 'animate-spin')} />
        </button>
      </div>

      {/* Count summary */}
      <p className="text-xs text-[var(--ff-text-tertiary)]">
        {total > 0 ? `${total} item${total !== 1 ? 's' : ''}` : ''}
      </p>

      {/* Feed items */}
      {isLoading && items.length === 0 ? (
        <div className="flex items-center justify-center py-12">
          <RefreshCw className="w-5 h-5 animate-spin text-[var(--ff-text-tertiary)]" />
          <span className="ml-2 text-sm text-[var(--ff-text-secondary)]">
            Loading feed...
          </span>
        </div>
      ) : items.length === 0 ? (
        <div className="text-center py-12">
          <Rss className="w-10 h-10 mx-auto text-[var(--ff-text-tertiary)] mb-3" />
          <p className="text-sm text-[var(--ff-text-secondary)]">
            {activeFilter === 'all'
              ? 'No activity yet'
              : `No ${CHANNEL_FILTERS.find(f => f.key === activeFilter)?.label.toLowerCase() || 'items'} found`}
          </p>
        </div>
      ) : (
        <div className="border border-[var(--ff-border-light)] rounded-lg overflow-hidden">
          {items.map(item => (
