                      : meeting.participants.map(name => ({ name, email: '', displayName: '' }))
                    ).map((attendee, index) => (
                      <div key={index} className="flex items-center gap-2 px-3 py-2 bg-[var(--ff-bg-tertiary)] rounded">
                        <div className="w-7 h-7 rounded-full bg-blue-500/20 flex items-center justify-center text-xs font-medium text-blue-400">
                          {(attendee.displayName || attendee.name || attendee.email || '?').charAt(0).toUpperCase()}
                        </div>
                        <div className="min-w-0 flex-1">
                          <p className="text-sm font-medium text-[var(--ff-text-primary)] truncate">
                            {attendee.displayName || attendee.name || attendee.email || 'Unknown'}
                          </p>
                          {attendee.email && (
                            <p className="text-xs text-[var(--ff-text-tertiary)] truncate">{attendee.email}</p>
                          )}
                        </div>
                      </div>
                    ))}
                  </div>
                </div>
              </div>

              {/* Summary Content */}
              {meeting.summary && (
                <div className="space-y-6">
                  {meeting.summary.overview && (
                    <div>
                      <h3 className="font-medium text-[var(--ff-text-primary)] mb-3">Meeting Summary</h3>
                      {meeting.summary.overview.toLowerCase().includes('no transcript available') ? (
                        <p className="text-sm text-[var(--ff-text-tertiary)] italic">
                          No AI summary — transcription was not enabled for this meeting.
                        </p>
                      ) : (
                        <p className="text-sm text-[var(--ff-text-secondary)] whitespace-pre-wrap">{meeting.summary.overview}</p>
                      )}
                    </div>
                  )}

                  {meeting.summary.decisions && Array.isArray(meeting.summary.decisions) && meeting.summary.decisions.length > 0 && (
                    <div>
                      <h3 className="font-medium text-[var(--ff-text-primary)] mb-3">Decisions</h3>
                      <ul className="space-y-2">
                        {meeting.summary.decisions.map((decision: string, index: number) => (
                          <li key={index} className="flex gap-2 text-sm text-[var(--ff-text-secondary)]">
                            <span className="text-green-400 flex-shrink-0">-</span>
                            <span>{decision}</span>
                          </li>
                        ))}
                      </ul>
                    </div>
                  )}

                  {meeting.summary.keywords && Array.isArray(meeting.summary.keywords) && meeting.summary.keywords.length > 0 && (
                    <div>
                      <h3 className="font-medium text-[var(--ff-text-primary)] mb-3">Keywords</h3>
                      <div className="flex flex-wrap gap-2">
                        {meeting.summary.keywords.map((keyword: string, index: number) => (
                          <span key={index} className="px-3 py-1 bg-blue-500/20 text-blue-400 rounded-full text-sm">
                            {keyword}
                          </span>
                        ))}
                      </div>
                    </div>
                  )}

                  {meeting.summary.outline && Array.isArray(meeting.summary.outline) && meeting.summary.outline.length > 0 && (
                    <div>
                      <h3 className="font-medium text-[var(--ff-text-primary)] mb-3">Detailed Outline</h3>
                      <ol className="space-y-2">
                        {meeting.summary.outline.map((item: string, index: number) => (
                          <li key={index} className="flex gap-2 text-sm text-[var(--ff-text-secondary)]">
                            <span className="font-medium text-[var(--ff-text-tertiary)]">{index + 1}.</span>
                            <span>{item}</span>
                          </li>
                        ))}
                      </ol>
                    </div>
                  )}

                  {meeting.summary.action_items && (Array.isArray(meeting.summary.action_items) ? meeting.summary.action_items.length > 0 : String(meeting.summary.action_items).trim().length > 0) && (
                    <div>
                      <h3 className="font-medium text-[var(--ff-text-primary)] mb-3">AI-Detected Action Items</h3>
                      <div className="p-4 bg-[var(--ff-bg-tertiary)] rounded-lg border-l-4 border-blue-500">
                        <div className="text-sm text-[var(--ff-text-secondary)] leading-relaxed space-y-2">
                          {(() => {
                            const rawText = Array.isArray(meeting.summary.action_items)
                              ? meeting.summary.action_items.join(' ')
                              : String(meeting.summary.action_items);

                            const formatted = rawText
                              .replace(/\*\*([^*]+)\*\*/g, '\n\n**$1**\n')
                              .replace(/(\([0-9:]+\))\s+([A-Z])/g, '$1\n- $2')
                              .trim();

                            return formatted.split('\n').map((line, idx) => {
                              const trimmed = line.trim();
                              if (!trimmed) return null;

                              if (trimmed.startsWith('**') && trimmed.endsWith('**')) {
                                return (
                                  <div key={idx} className="font-semibold text-blue-400 mt-3 first:mt-0">
                                    {trimmed.replace(/\*\*/g, '')}
                                  </div>
                                );
                              }

                              return <div key={idx}>{trimmed}</div>;
                            });
                          })()}
                        </div>
                      </div>
                    </div>
                  )}

                  {meeting.source === 'fireflies' && meeting.meetingLink && (
                    <div className="p-4 bg-[var(--ff-bg-tertiary)] rounded border border-[var(--ff-border-light)]">
                      <a
                        href={meeting.meetingLink}
                        target="_blank"
                        rel="noopener noreferrer"
                        className="text-blue-400 hover:text-blue-300 font-medium flex items-center gap-2"
                      >
                        <Video className="w-4 h-4" />
                        View Full Transcript on Fireflies
                      </a>
                    </div>
                  )}
                </div>
              )}

              {!meeting.summary && meeting.notes && (
                <div className="mt-6">
                  <h3 className="font-medium text-[var(--ff-text-primary)] mb-3">Meeting Notes</h3>
                  <p className="text-sm text-[var(--ff-text-secondary)]">{meeting.notes}</p>
                </div>
              )}
            </>
          )}

          {activeTab === 'transcript' && (
            <TranscriptView meetingId={meeting.id} transcriptUrl={meeting.transcriptUrl} />
          )}

          {activeTab === 'recording' && (
            <RecordingPlayer meetingId={meeting.id} hasRecording={meeting.hasRecording} />
          )}
        </div>

        <div className="p-6 border-t border-[var(--ff-border-light)] flex gap-3 justify-end">
          <button
            className="ff-button ff-button-secondary"
            onClick={onClose}
          >
            Close
          </button>
        </div>
      </div>
    </div>
  );
}

/**
 * Hook for internal messages data fetching
 */

import { useState, useEffect, useCallback, useRef } from 'react';
import { log } from '@/lib/logger';
import type { MessageListItem, MessageView } from '../types/messaging.types';

const PAGE_SIZE = 20;
const UNREAD_POLL_MS = 30_000;

interface UseInternalMessagesReturn {
  messages: MessageListItem[];
  isLoading: boolean;
  hasMore: boolean;
  total: number;
  unreadCount: number;
  refetch: () => Promise<void>;
  loadMore: () => Promise<void>;
  markRead: (messageIds: string[]) => Promise<void>;
  markAllRead: () => Promise<void>;
  archiveMessages: (messageIds: string[]) => Promise<void>;
}

export function useInternalMessages(view: MessageView): UseInternalMessagesReturn {
  const [messages, setMessages] = useState<MessageListItem[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [hasMore, setHasMore] = useState(false);
  const [total, setTotal] = useState(0);
  const [offset, setOffset] = useState(0);
  const [unreadCount, setUnreadCount] = useState(0);
  const pollRef = useRef<ReturnType<typeof setInterval>>();

  const fetchMessages = useCallback(async (reset = false) => {
    setIsLoading(true);
    const currentOffset = reset ? 0 : offset;
    try {
      const params = new URLSearchParams({
        view,
        limit: String(PAGE_SIZE),
        offset: String(currentOffset),
      });

      const res = await fetch(`/api/communications/messages?${params}`, {
        credentials: 'include',
      });
      const json = await res.json();

      if (json.success) {
        const items: MessageListItem[] = json.data.messages;
        if (reset) {
          setMessages(items);
          setOffset(items.length);
        } else {
          setMessages(prev => [...prev, ...items]);
          setOffset(currentOffset + items.length);
        }
        setTotal(json.data.total);
        setHasMore(items.length === PAGE_SIZE);
      }
    } catch (err) {
      log.error('Failed to fetch messages:', err);
    } finally {
      setIsLoading(false);
    }
  }, [offset, view]);

  const fetchUnreadCount = useCallback(async () => {
    try {
      const res = await fetch('/api/communications/messages-unread-count', {
        credentials: 'include',
      });
      const json = await res.json();
      if (json.success) {
        setUnreadCount(json.data.count);
      }
    } catch {
      // Silently ignore polling errors
    }
  }, []);

  const markRead = useCallback(async (messageIds: string[]) => {
    try {
      await fetch('/api/communications/messages-read', {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        credentials: 'include',
        body: JSON.stringify({ messageIds }),
      });
      // Optimistic update
      setMessages(prev =>
        prev.map(m =>
          messageIds.includes(m.id) ? { ...m, is_read: true } : m
        )
      );
      setUnreadCount(prev => Math.max(0, prev - messageIds.length));
    } catch (err) {
      log.error('Failed to mark messages as read:', err);
    }
  }, []);

  const markAllRead = useCallback(async () => {
    const unreadIds = messages.filter(m => !m.is_read).map(m => m.id);
    if (unreadIds.length === 0) return;
    await markRead(unreadIds);
  }, [messages, markRead]);

  const archiveMessages = useCallback(async (messageIds: string[]) => {
    try {
      await fetch('/api/communications/messages-archive', {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        credentials: 'include',
        body: JSON.stringify({ messageIds }),
      });
      // Remove from current list
      setMessages(prev => prev.filter(m => !messageIds.includes(m.id)));
      setTotal(prev => prev - messageIds.length);
    } catch (err) {
      log.error('Failed to archive messages:', err);
    }
  }, []);

  // Fetch messages on mount and when view changes
  useEffect(() => {
    fetchMessages(true);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [view]);

  // Poll unread count
  useEffect(() => {
    fetchUnreadCount();
    pollRef.current = setInterval(fetchUnreadCount, UNREAD_POLL_MS);
    return () => {
      if (pollRef.current) clearInterval(pollRef.current);
    };
  }, [fetchUnreadCount]);

  return {
    messages,
    isLoading,
    hasMore,
    total,
    unreadCount,
    refetch: () => fetchMessages(true),
    loadMore: () => fetchMessages(false),
    markRead,
    markAllRead,
    archiveMessages,
  };
}

/**
 * POST /api/communications/email-send
 * Compose and send an email via Resend, record in email_outbox
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { neon } from '@neondatabase/serverless';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth, type AuthenticatedNextApiRequest } from '@/lib/auth/middleware';
import { log } from '@/lib/logger';

const sql = neon(process.env.DATABASE_URL!);
const FROM_ADDRESS = 'FibreFlow <notifications@fibreflow.app>';

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'POST') {
    return apiResponse.methodNotAllowed(res, req.method!, ['POST']);
  }

  const authReq = req as AuthenticatedNextApiRequest;
  const { to, toName, subject, bodyHtml, bodyText } = req.body;

  if (!to || !subject || !bodyHtml) {
    return apiResponse.badRequest(res, 'to, subject, and bodyHtml are required');
  }

  // Basic email validation
  if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(to)) {
    return apiResponse.badRequest(res, 'Invalid email address');
  }

  let outboxId: string | null = null;

  try {
    // Insert into outbox as 'sending'
    const insertResult = await sql`
      INSERT INTO email_outbox (
        sender_id, recipient_email, recipient_name, subject,
        body_html, body_text, source_module, status
      ) VALUES (
        ${authReq.user.id}::uuid, ${to}, ${toName || null}, ${subject},
        ${bodyHtml}, ${bodyText || null}, 'manual', 'sending'
      )
      RETURNING id
    `;
    outboxId = insertResult[0].id;

    // Send via Resend
    const { resend } = await import('@/lib/email/resendClient');
    const sendResult = await resend.emails.send({
      from: FROM_ADDRESS,
      to,
      subject,
      html: bodyHtml,
      ...(bodyText ? { text: bodyText } : {}),
    });

    const resendId = sendResult.data?.id || null;

    // Update outbox with success
    await sql`
      UPDATE email_outbox
      SET status = 'sent', resend_id = ${resendId}, sent_at = NOW()
      WHERE id = ${outboxId}::uuid
    `;

    log.info('Email sent via compose', {
      to, subject, outboxId, resendId,
    }, 'EmailCompose');

    return apiResponse.success(res, { id: outboxId, status: 'sent', resendId });
  } catch (error) {
    const errorMsg = error instanceof Error ? error.message : String(error);
    log.error('Email compose send failed', { to, subject, error: errorMsg }, 'EmailCompose');

    // Update outbox with failure if we have an ID
    if (outboxId) {
      await sql`
        UPDATE email_outbox
        SET status = 'failed', error_message = ${errorMsg}
        WHERE id = ${outboxId}::uuid
      `.catch(() => {});
    }

    return apiResponse.internalError(res, error);
  }
}

export default withAuth(handler);

/**
 * Hook for unified feed data fetching
 * Fetches from /api/communications/feed with channel filtering and pagination
 */

import { useState, useEffect, useCallback } from 'react';
import { log } from '@/lib/logger';
import type { FeedItem } from '../types/hub.types';

const PAGE_SIZE = 30;

type Channel = 'message' | 'email' | 'notification' | 'meeting';

interface FeedCounts {
  message: number;
  email: number;
  notification: number;
  meeting: number;
}

interface UseUnifiedFeedReturn {
  items: FeedItem[];
  isLoading: boolean;
  hasMore: boolean;
  total: number;
  counts: FeedCounts;
  refetch: () => Promise<void>;
  loadMore: () => Promise<void>;
}

export function useUnifiedFeed(channels?: Channel[]): UseUnifiedFeedReturn {
  const [items, setItems] = useState<FeedItem[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [hasMore, setHasMore] = useState(false);
  const [total, setTotal] = useState(0);
  const [offset, setOffset] = useState(0);
  const [counts, setCounts] = useState<FeedCounts>({
    message: 0,
    email: 0,
    notification: 0,
    meeting: 0,
  });

  const channelsKey = channels ? channels.sort().join(',') : 'all';

  const fetchFeed = useCallback(async (reset = false) => {
    setIsLoading(true);
    const currentOffset = reset ? 0 : offset;

    try {
      const params = new URLSearchParams({
        limit: String(PAGE_SIZE),
        offset: String(currentOffset),
      });

      if (channels && channels.length > 0) {
        params.set('channels', channels.join(','));
      }

      const res = await fetch(`/api/communications/feed?${params}`, {
        credentials: 'include',
      });
      const json = await res.json();

      if (json.success) {
        const newItems: FeedItem[] = json.data.items;
        if (reset) {
          setItems(newItems);
          setOffset(newItems.length);
        } else {
          setItems(prev => [...prev, ...newItems]);
          setOffset(currentOffset + newItems.length);
        }
        setTotal(json.data.total);
        setCounts(json.data.counts);
        setHasMore(newItems.length === PAGE_SIZE);
      }
    } catch (err) {
      log.error('Failed to fetch unified feed:', err);
    } finally {
      setIsLoading(false);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [offset, channelsKey]);

  // Refetch on channel filter change
  useEffect(() => {
    fetchFeed(true);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [channelsKey]);

  return {
    items,
    isLoading,
    hasMore,
    total,
    counts,
    refetch: () => fetchFeed(true),
    loadMore: () => fetchFeed(false),
  };
}

