import { useState, useEffect, useMemo } from 'react';
import { Search, MessageSquare, Loader2, ExternalLink } from 'lucide-react';
import { log } from '@/lib/logger';

interface TranscriptUtterance {
  startMs: number;
  speaker: string;
  text: string;
}

interface TranscriptViewProps {
  meetingId: string;
  transcriptUrl?: string;
}

const SPEAKER_COLORS = [
  'text-blue-400', 'text-green-400', 'text-purple-400',
  'text-yellow-400', 'text-pink-400', 'text-cyan-400',
  'text-orange-400', 'text-red-400',
];

function formatTimestamp(ms: number): string {
  const totalSeconds = Math.floor(ms / 1000);
  const hours = Math.floor(totalSeconds / 3600);
  const minutes = Math.floor((totalSeconds % 3600) / 60);
  const seconds = totalSeconds % 60;
  if (hours > 0) {
    return `${hours}:${String(minutes).padStart(2, '0')}:${String(seconds).padStart(2, '0')}`;
  }
  return `${minutes}:${String(seconds).padStart(2, '0')}`;
}

export function TranscriptView({ meetingId, transcriptUrl }: TranscriptViewProps) {
  const [utterances, setUtterances] = useState<TranscriptUtterance[]>([]);
  const [rawText, setRawText] = useState<string>('');
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [searchQuery, setSearchQuery] = useState('');

  useEffect(() => {
    loadTranscript();
  }, [meetingId]);

  const loadTranscript = async () => {
    setIsLoading(true);
    setError(null);
    try {
      const response = await fetch(`/api/meetings/${meetingId}/transcript`);
      const data = await response.json();

      if (!response.ok) {
        setError(transcriptUrl
          ? 'Transcript is available on Fireflies — click below to view.'
          : (data.error?.message || 'Transcript not available'));
        return;
      }

      const payload = data.data || data;
      if (payload.structured && payload.structured.length > 0) {
        setUtterances(payload.structured);
      }
      setRawText(payload.transcript || '');
    } catch (err) {
      log.error('Failed to load transcript', { meetingId }, 'TranscriptView');
      setError('Failed to load transcript');
    } finally {
      setIsLoading(false);
    }
  };

  const speakerColorMap = useMemo(() => {
    const map = new Map<string, string>();
    const speakers = [...new Set(utterances.map(u => u.speaker))];
    speakers.forEach((s, i) => map.set(s, SPEAKER_COLORS[i % SPEAKER_COLORS.length] || 'text-gray-400'));
    return map;
  }, [utterances]);

  const filteredUtterances = useMemo(() => {
    if (!searchQuery.trim()) return utterances;
    const q = searchQuery.toLowerCase();
    return utterances.filter(u =>
      u.text.toLowerCase().includes(q) || u.speaker.toLowerCase().includes(q)
    );
  }, [utterances, searchQuery]);

  const highlightText = (text: string): React.ReactNode => {
    if (!searchQuery.trim()) return text;
    const regex = new RegExp(`(${searchQuery.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')})`, 'gi');
    const parts = text.split(regex);
    return parts.map((part, i) =>
      regex.test(part) ? <mark key={i} className="bg-yellow-500/30 text-yellow-200 rounded px-0.5">{part}</mark> : part
    );
  };

  if (isLoading) {
    return (
      <div className="flex items-center justify-center py-12">
        <Loader2 className="w-6 h-6 animate-spin text-blue-400" />
        <span className="ml-2 text-[var(--ff-text-secondary)]">Loading transcript...</span>
      </div>
    );
  }

  if (error) {
    return (
      <div className="text-center py-8">
        <MessageSquare className="w-10 h-10 mx-auto mb-3 text-[var(--ff-text-tertiary)]" />
        <p className="text-[var(--ff-text-secondary)] mb-4">{error}</p>
        {transcriptUrl && (
          <a
            href={transcriptUrl}
            target="_blank"
            rel="noopener noreferrer"
            className="inline-flex items-center gap-2 px-4 py-2 bg-blue-600 hover:bg-blue-700 text-white rounded-lg text-sm font-medium transition-colors"
          >
            <ExternalLink className="w-4 h-4" />
            View Full Transcript on Fireflies
          </a>
        )}
      </div>
    );
  }

  return (
    <div className="space-y-4">
      <div className="relative">
        <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-[var(--ff-text-tertiary)]" />
        <input
          type="text"
          placeholder="Search transcript..."
          value={searchQuery}
          onChange={(e) => setSearchQuery(e.target.value)}
          className="w-full pl-10 pr-4 py-2 bg-[var(--ff-bg-tertiary)] border border-[var(--ff-border-light)] rounded-lg text-sm text-[var(--ff-text-primary)] placeholder:text-[var(--ff-text-tertiary)]"
        />
      </div>

      <div className="max-h-[60vh] overflow-y-auto space-y-3 pr-2">
        {filteredUtterances.length > 0 ? (
          filteredUtterances.map((u, i) => (
            <div key={i} className="flex gap-3">
              <span className="text-xs text-[var(--ff-text-tertiary)] whitespace-nowrap pt-1 w-14 text-right flex-shrink-0">
                {formatTimestamp(u.startMs)}
              </span>
              <div className="flex-1 min-w-0">
                <span className={`text-sm font-medium ${speakerColorMap.get(u.speaker) || 'text-gray-400'}`}>
                  {u.speaker}
                </span>
                <p className="text-sm text-[var(--ff-text-secondary)] mt-0.5">{highlightText(u.text)}</p>
              </div>
            </div>
          ))
        ) : rawText ? (
          <pre className="text-sm text-[var(--ff-text-secondary)] whitespace-pre-wrap font-mono">{rawText}</pre>
        ) : (
          <p className="text-center text-[var(--ff-text-tertiary)]">No transcript content</p>
        )}
      </div>
    </div>
  );
}

import type { NextApiRequest, NextApiResponse } from 'next';
import { withAuth, type AuthenticatedNextApiRequest } from '@/lib/auth';
import { neon } from '@neondatabase/serverless';
import { syncFirefliesToNeon } from '@/services/fireflies/firefliesService';
import { log } from '@/lib/logger';

const sql = neon(process.env.DATABASE_URL!);

async function handler(
  req: NextApiRequest,
  res: NextApiResponse
) {
  // Get user info for access control
  const authReq = req as AuthenticatedNextApiRequest;
  const userEmail = authReq.user?.email?.toLowerCase();
  const userName = authReq.user?.name?.toLowerCase() || '';
  const isOwner = userEmail === 'hein@velocityfibre.co.za';

  if (!userEmail) {
    return res.status(403).json({ error: 'User email required for meeting access' });
  }

  if (req.method === 'GET') {
    try {
      // Check if requesting a specific meeting by ID
      const { id, source } = req.query;

      if (id) {
        // Super admin can access any meeting, others need to be participants
        const [meeting] = isOwner
          ? await sql`
              SELECT
                id, fireflies_id, title, meeting_date as date, duration,
                transcript_url, summary, participants, created_at, updated_at,
                source, processing_status, organizer_name, organizer_email, join_url,
                (raw_transcript IS NOT NULL OR transcript_url IS NOT NULL OR EXISTS (SELECT 1 FROM meeting_transcripts mt WHERE mt.meeting_id = meetings.id)) as has_transcript,
                (recording_path IS NOT NULL) as has_recording
              FROM meetings
              WHERE id = ${id}
            `
          : await sql`
              SELECT
                id, fireflies_id, title, meeting_date as date, duration,
                transcript_url, summary, participants, created_at, updated_at,
                source, processing_status, organizer_name, organizer_email, join_url,
                (raw_transcript IS NOT NULL OR transcript_url IS NOT NULL OR EXISTS (SELECT 1 FROM meeting_transcripts mt WHERE mt.meeting_id = meetings.id)) as has_transcript,
                (recording_path IS NOT NULL) as has_recording
              FROM meetings
              WHERE id = ${id}
              AND EXISTS (
                SELECT 1 FROM jsonb_array_elements(participants) AS p
                WHERE LOWER(p->>'email') = ${userEmail}
                   OR LOWER(p->>'name') = ${userName}
                   OR LOWER(p->>'displayName') = ${userName}
              )
            `;

        if (!meeting) {
          return res.status(403).json({ error: 'Not authorized to view this meeting' });
        }

        return res.status(200).json({ meeting });
      }

      // Source filter: ?source=teams|fireflies|all (default: all)
      const sourceFilter = typeof source === 'string' && source !== 'all' ? source : null;

      // Super admin sees all meetings, others only see meetings they participated in
      if (sourceFilter) {
        const meetings = isOwner
          ? await sql`
              SELECT
                id, fireflies_id, title, meeting_date as date, duration,
                transcript_url, summary, participants, created_at, updated_at,
                source, processing_status, organizer_name, organizer_email,
                (raw_transcript IS NOT NULL OR transcript_url IS NOT NULL OR EXISTS (SELECT 1 FROM meeting_transcripts mt WHERE mt.meeting_id = meetings.id)) as has_transcript,
                (recording_path IS NOT NULL) as has_recording
              FROM meetings
              WHERE source = ${sourceFilter}
              ORDER BY meeting_date DESC
              LIMIT 50
            `
          : await sql`
              SELECT
                id, fireflies_id, title, meeting_date as date, duration,
                transcript_url, summary, participants, created_at, updated_at,
                source, processing_status, organizer_name, organizer_email,
                (raw_transcript IS NOT NULL OR transcript_url IS NOT NULL OR EXISTS (SELECT 1 FROM meeting_transcripts mt WHERE mt.meeting_id = meetings.id)) as has_transcript,
                (recording_path IS NOT NULL) as has_recording
              FROM meetings
              WHERE source = ${sourceFilter}
              AND EXISTS (
                SELECT 1 FROM jsonb_array_elements(participants) AS p
                WHERE LOWER(p->>'email') = ${userEmail}
                   OR LOWER(p->>'name') = ${userName}
                   OR LOWER(p->>'displayName') = ${userName}
              )
              ORDER BY meeting_date DESC
              LIMIT 50
            `;

        return res.status(200).json({ meetings });
      }

      const meetings = isOwner
        ? await sql`
            SELECT
              id, fireflies_id, title, meeting_date as date, duration,
              transcript_url, summary, participants, created_at, updated_at,
              source, processing_status, organizer_name, organizer_email,
              (raw_transcript IS NOT NULL OR transcript_url IS NOT NULL OR EXISTS (SELECT 1 FROM meeting_transcripts mt WHERE mt.meeting_id = meetings.id)) as has_transcript,
              (recording_path IS NOT NULL) as has_recording
            FROM meetings
            ORDER BY meeting_date DESC
            LIMIT 50
          `
        : await sql`
            SELECT
              id, fireflies_id, title, meeting_date as date, duration,
              transcript_url, summary, participants, created_at, updated_at,
              source, processing_status, organizer_name, organizer_email,
              (raw_transcript IS NOT NULL OR transcript_url IS NOT NULL OR EXISTS (SELECT 1 FROM meeting_transcripts mt WHERE mt.meeting_id = meetings.id)) as has_transcript,
              (recording_path IS NOT NULL) as has_recording
            FROM meetings
            WHERE EXISTS (
              SELECT 1 FROM jsonb_array_elements(participants) AS p
              WHERE LOWER(p->>'email') = ${userEmail}
                 OR LOWER(p->>'name') = ${userName}
                 OR LOWER(p->>'displayName') = ${userName}
            )
            ORDER BY meeting_date DESC
            LIMIT 50
          `;

      return res.status(200).json({ meetings });
    } catch (error: unknown) {
      const errorMessage = error instanceof Error ? error.message : 'Unknown error';
      log.error('Error fetching meetings:', { error: errorMessage, userEmail });
      return res.status(500).json({ error: errorMessage });
    }
  }

  if (req.method === 'POST' && req.query.action === 'sync') {
    try {
      const apiKey = process.env.FIREFLIES_API_KEY;

      if (!apiKey) {
        return res.status(500).json({ error: 'FIREFLIES_API_KEY not configured' });
      }

      const count = await syncFirefliesToNeon(apiKey, sql);

      return res.status(200).json({
        success: true,
        synced: count,
        message: `Synced ${count} meetings from Fireflies`
      });
    } catch (error: unknown) {
      const errorMessage = error instanceof Error ? error.message : 'Unknown error';
      log.error('Error syncing from Fireflies:', { error: errorMessage });
      return res.status(500).json({ error: errorMessage });
    }
  }

  return res.status(405).json({ error: 'Method not allowed' });
}

