                          </p>
                          {attendee.email && (
                            <p className="text-xs text-[var(--ff-text-tertiary)] truncate">{attendee.email}</p>
                          )}
                        </div>
                      </div>
                    ))}
                  </div>
                </div>
              </div>

              {/* Summary Content */}
              {meeting.summary && (
                <div className="space-y-6">
                  {meeting.summary.overview && (
                    <div>
                      <h3 className="font-medium text-[var(--ff-text-primary)] mb-3">Meeting Summary</h3>
                      {meeting.summary.overview.toLowerCase().includes('no transcript available') ? (
                        <p className="text-sm text-[var(--ff-text-tertiary)] italic">
                          No AI summary — transcription was not enabled for this meeting.
                        </p>
                      ) : (
                        <p className="text-sm text-[var(--ff-text-secondary)] whitespace-pre-wrap">{meeting.summary.overview}</p>
                      )}
                    </div>
                  )}

                  {meeting.summary.decisions && Array.isArray(meeting.summary.decisions) && meeting.summary.decisions.length > 0 && (
                    <div>
                      <h3 className="font-medium text-[var(--ff-text-primary)] mb-3">Decisions</h3>
                      <ul className="space-y-2">
                        {meeting.summary.decisions.map((decision: string, index: number) => (
                          <li key={index} className="flex gap-2 text-sm text-[var(--ff-text-secondary)]">
                            <span className="text-green-400 flex-shrink-0">-</span>
                            <span>{decision}</span>
                          </li>
                        ))}
                      </ul>
                    </div>
                  )}

                  {meeting.summary.keywords && Array.isArray(meeting.summary.keywords) && meeting.summary.keywords.length > 0 && (
                    <div>
                      <h3 className="font-medium text-[var(--ff-text-primary)] mb-3">Keywords</h3>
                      <div className="flex flex-wrap gap-2">
                        {meeting.summary.keywords.map((keyword: string, index: number) => (
                          <span key={index} className="px-3 py-1 bg-blue-500/20 text-blue-400 rounded-full text-sm">
                            {keyword}
                          </span>
                        ))}
                      </div>
                    </div>
                  )}

                  {meeting.summary.outline && Array.isArray(meeting.summary.outline) && meeting.summary.outline.length > 0 && (
                    <div>
                      <h3 className="font-medium text-[var(--ff-text-primary)] mb-3">Detailed Outline</h3>
                      <ol className="space-y-2">
                        {meeting.summary.outline.map((item: string, index: number) => (
                          <li key={index} className="flex gap-2 text-sm text-[var(--ff-text-secondary)]">
                            <span className="font-medium text-[var(--ff-text-tertiary)]">{index + 1}.</span>
                            <span>{item}</span>
                          </li>
                        ))}
                      </ol>
                    </div>
                  )}

                  {meeting.summary.action_items && (Array.isArray(meeting.summary.action_items) ? meeting.summary.action_items.length > 0 : String(meeting.summary.action_items).trim().length > 0) && (
                    <div>
                      <h3 className="font-medium text-[var(--ff-text-primary)] mb-3">AI-Detected Action Items</h3>
                      <div className="p-4 bg-[var(--ff-bg-tertiary)] rounded-lg border-l-4 border-blue-500">
                        <div className="text-sm text-[var(--ff-text-secondary)] leading-relaxed space-y-2">
                          {(() => {
                            const rawText = Array.isArray(meeting.summary.action_items)
                              ? meeting.summary.action_items.join(' ')
                              : String(meeting.summary.action_items);

                            const formatted = rawText
                              .replace(/\*\*([^*]+)\*\*/g, '\n\n**$1**\n')
                              .replace(/(\([0-9:]+\))\s+([A-Z])/g, '$1\n- $2')
                              .trim();

                            return formatted.split('\n').map((line, idx) => {
                              const trimmed = line.trim();
                              if (!trimmed) return null;

                              if (trimmed.startsWith('**') && trimmed.endsWith('**')) {
                                return (
                                  <div key={idx} className="font-semibold text-blue-400 mt-3 first:mt-0">
                                    {trimmed.replace(/\*\*/g, '')}
                                  </div>
                                );
                              }

                              return <div key={idx}>{trimmed}</div>;
                            });
                          })()}
                        </div>
                      </div>
                    </div>
                  )}

                  {meeting.source === 'fireflies' && meeting.meetingLink && (
                    <div className="p-4 bg-[var(--ff-bg-tertiary)] rounded border border-[var(--ff-border-light)]">
                      <a
                        href={meeting.meetingLink}
                        target="_blank"
                        rel="noopener noreferrer"
                        className="text-blue-400 hover:text-blue-300 font-medium flex items-center gap-2"
                      >
                        <Video className="w-4 h-4" />
                        View Full Transcript on Fireflies
                      </a>
                    </div>
                  )}
                </div>
              )}

              {!meeting.summary && meeting.notes && (
                <div className="mt-6">
                  <h3 className="font-medium text-[var(--ff-text-primary)] mb-3">Meeting Notes</h3>
                  <p className="text-sm text-[var(--ff-text-secondary)]">{meeting.notes}</p>
                </div>
              )}
            </>
          )}

          {activeTab === 'transcript' && (
            <TranscriptView meetingId={meeting.id} transcriptUrl={meeting.transcriptUrl} />
          )}

          {activeTab === 'recording' && (
            <RecordingPlayer meetingId={meeting.id} hasRecording={meeting.hasRecording} />
          )}
        </div>

        <div className="p-6 border-t border-[var(--ff-border-light)] flex gap-3 justify-end">
          <button
            className="ff-button ff-button-secondary"
            onClick={onClose}
          >
            Close
          </button>
        </div>
      </div>
    </div>
  );
}

'use client';

/**
 * Communications Hub - Unified communications center
 * 6 tabs: Inbox, Email, WhatsApp, Meetings, Notifications, Settings
 * Replaces the old CommunicationsDashboard with a consolidated hub
 */

import React, { useState, useEffect } from 'react';
import { useRouter } from 'next/router';
import {
  Inbox,
  Mail,
  MessageCircle,
  Users,
  Bell,
  Settings,
  RefreshCw,
  Film,
  Plus,
  Construction,
} from 'lucide-react';
import Link from 'next/link';
import { cn } from '@/lib/utils';
import { log } from '@/lib/logger';
import { useCommunications } from '@/hooks/useCommunications';
import type { CommsTab } from './types/hub.types';
import { CommunicationsStatsCards, CommunicationsMeetingsTab } from './components';
import { NotificationsTab } from './notifications/NotificationsTab';
import { EmailTab } from './email/EmailTab';
import { InboxPanel } from './messaging/InboxPanel';

const TABS: { key: CommsTab; label: string; icon: React.ElementType }[] = [
  { key: 'inbox', label: 'Inbox', icon: Inbox },
  { key: 'email', label: 'Email', icon: Mail },
  { key: 'whatsapp', label: 'WhatsApp', icon: MessageCircle },
  { key: 'meetings', label: 'Meetings', icon: Users },
  { key: 'notifications', label: 'Notifications', icon: Bell },
  { key: 'settings', label: 'Settings', icon: Settings },
];

function ComingSoonCard({ title, description }: { title: string; description: string }) {
  return (
    <div className="text-center py-16">
      <Construction className="w-12 h-12 mx-auto text-[var(--ff-text-tertiary)] mb-4" />
      <h3 className="text-lg font-medium text-[var(--ff-text-primary)] mb-2">{title}</h3>
      <p className="text-sm text-[var(--ff-text-secondary)] max-w-md mx-auto">{description}</p>
      <span className="inline-block mt-4 px-3 py-1 text-xs font-medium bg-amber-500/10 text-amber-400 rounded-full">
        Coming Soon
      </span>
    </div>
  );
}

export default function CommunicationsHub() {
  const router = useRouter();
  const [activeTab, setActiveTab] = useState<CommsTab>('meetings');
  const [isRefreshing, setIsRefreshing] = useState(false);
  const [isSyncing, setIsSyncing] = useState(false);
  const [isSyncingTeams, setIsSyncingTeams] = useState(false);
  const [syncMessage, setSyncMessage] = useState<string | null>(null);
  const [lastRefresh, setLastRefresh] = useState<Date | null>(null);
  const { data, stats, isLoading, getStatusColor, refetch } = useCommunications();

  // Sync active tab with URL param
  useEffect(() => {
    const tabParam = router.query.tab as string | undefined;
    if (tabParam) {
      const valid = TABS.find(t => t.key === tabParam);
      if (valid) setActiveTab(valid.key);
    }
  }, [router.query.tab]);

  const handleTabChange = (tab: CommsTab) => {
    setActiveTab(tab);
    router.push(`/communications?tab=${tab}`, undefined, { shallow: true });
  };

  const handleRefresh = async () => {
    setIsRefreshing(true);
    try {
      if (refetch) await refetch();
      setLastRefresh(new Date());
    } finally {
      setIsRefreshing(false);
    }
  };

  const handleFirefliesSync = async () => {
    setIsSyncing(true);
    setSyncMessage(null);
    try {
      const response = await fetch('/api/meetings?action=sync', { method: 'POST' });
      const result = await response.json();
      if (result.success) {
        setSyncMessage(`Synced ${result.synced} meetings from Fireflies`);
        await handleRefresh();
      } else {
        setSyncMessage(`Sync failed: ${result.error}`);
      }
    } catch (error) {
      const message = error instanceof Error ? error.message : 'Unknown error';
      setSyncMessage(`Sync failed: ${message}`);
      log.error('Fireflies sync failed:', error);
    } finally {
      setIsSyncing(false);
      setTimeout(() => setSyncMessage(null), 5000);
    }
  };

  const handleTeamsSync = async () => {
    setIsSyncingTeams(true);
    setSyncMessage(null);
    try {
      const response = await fetch('/api/meetings/sync-teams', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ hours: 48 }),
      });
      if (response.ok) {
        setSyncMessage('Teams sync started (processing in background)');
        setTimeout(() => handleRefresh(), 5000);
      } else {
        const result = await response.json();
        setSyncMessage(`Teams sync failed: ${result.error?.message || 'Unknown error'}`);
      }
    } catch (error) {
      const message = error instanceof Error ? error.message : 'Unknown error';
      setSyncMessage(`Teams sync failed: ${message}`);
      log.error('Teams sync failed:', error);
    } finally {
      setIsSyncingTeams(false);
      setTimeout(() => setSyncMessage(null), 8000);
    }
  };

  const showMeetingActions = activeTab === 'meetings';

  return (
    <div className="p-6 space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold text-[var(--ff-text-primary)]">Communications Hub</h1>
          <p className="text-sm text-[var(--ff-text-secondary)] mt-1">
            {lastRefresh
              ? `Last updated ${lastRefresh.toLocaleTimeString()}`
              : 'Unified messaging, meetings, and notifications'}
          </p>
        </div>

        <div className="flex flex-col items-end gap-2">
          <div className="flex items-center gap-2">
            {/* Meetings-specific actions */}
            {showMeetingActions && (
              <>
                <Link
                  href="/recordings"
                  className="flex items-center gap-2 px-4 py-2 text-sm font-medium text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)] bg-[var(--ff-bg-secondary)] hover:bg-[var(--ff-bg-tertiary)] border border-[var(--ff-border-light)] rounded-lg transition-colors"
                >
                  <Film className="w-4 h-4" />
                  Recordings
                </Link>

                <button
                  type="button"
                  onClick={handleTeamsSync}
                  disabled={isSyncingTeams}
                  className={cn(
                    'flex items-center gap-2 px-4 py-2 text-sm font-medium rounded-lg transition-colors',
                    isSyncingTeams
                      ? 'bg-[var(--ff-bg-tertiary)] text-[var(--ff-text-tertiary)] cursor-not-allowed'
                      : 'bg-purple-600 text-white hover:bg-purple-700'
                  )}
                >
                  <RefreshCw className={cn('w-4 h-4', isSyncingTeams && 'animate-spin')} />
                  {isSyncingTeams ? 'Syncing...' : 'Sync Teams'}
                </button>

                <button
                  type="button"
                  onClick={handleFirefliesSync}
                  disabled={isSyncing}
                  className={cn(
                    'flex items-center gap-2 px-4 py-2 text-sm font-medium rounded-lg transition-colors',
                    isSyncing
                      ? 'bg-[var(--ff-bg-tertiary)] text-[var(--ff-text-tertiary)] cursor-not-allowed'
                      : 'bg-blue-600 text-white hover:bg-blue-700'
                  )}
                >
                  <RefreshCw className={cn('w-4 h-4', isSyncing && 'animate-spin')} />
                  {isSyncing ? 'Syncing...' : 'Sync Fireflies'}
                </button>

                <button
                  type="button"
                  onClick={() => {}}
                  className="flex items-center gap-2 px-4 py-2 text-sm font-medium text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)] bg-[var(--ff-bg-secondary)] hover:bg-[var(--ff-bg-tertiary)] border border-[var(--ff-border-light)] rounded-lg transition-colors"
                >
                  <Plus className="w-4 h-4" />
                  Add Action Item
                </button>
              </>
            )}

            {/* Refresh button (always visible) */}
            <button
              type="button"
              onClick={handleRefresh}
              disabled={isRefreshing}
              className="flex items-center gap-2 px-4 py-2 text-sm font-medium text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)] bg-[var(--ff-bg-secondary)] hover:bg-[var(--ff-bg-tertiary)] border border-[var(--ff-border-light)] rounded-lg transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
              aria-label="Refresh"
            >
              <RefreshCw className={cn('w-4 h-4', isRefreshing && 'animate-spin')} />
            </button>
          </div>

          {syncMessage && (
            <p className={cn(
              'text-sm',
              syncMessage.includes('failed') ? 'text-red-600' : 'text-green-600'
            )}>
              {syncMessage}
            </p>
          )}
        </div>
      </div>

      {/* Stats Cards (meetings data) */}
      {showMeetingActions && <CommunicationsStatsCards stats={stats} />}

      {/* Tab Navigation */}
      <div className="bg-[var(--ff-bg-secondary)] border border-[var(--ff-border-light)] rounded-lg">
        <div className="border-b border-[var(--ff-border-light)]">
          <nav role="tablist" className="flex gap-1 px-4 -mb-px overflow-x-auto" aria-label="Communications tabs">
            {TABS.map(tab => {
              const Icon = tab.icon;
              const isActive = activeTab === tab.key;
              return (
                <button
                  key={tab.key}
                  role="tab"
                  aria-selected={isActive}
                  aria-controls={`comms-panel-${tab.key}`}
                  onClick={() => handleTabChange(tab.key)}
                  className={cn(
                    'flex items-center gap-2 py-3 px-4 border-b-2 font-medium text-sm transition-colors whitespace-nowrap',
                    'focus:outline-none focus:ring-2 focus:ring-inset focus:ring-[var(--ff-accent)]',
                    isActive
                      ? 'border-[var(--ff-primary)] text-[var(--ff-primary)]'
                      : 'border-transparent text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)] hover:border-[var(--ff-border-light)]'
                  )}
                >
                  <Icon className="w-4 h-4" />
                  {tab.label}
                  {tab.key === 'meetings' && data.meetings.length > 0 && (
                    <span className="px-2 py-0.5 text-xs bg-blue-500/20 text-blue-400 rounded-full">
                      {data.meetings.length}
                    </span>
                  )}
                </button>
              );
            })}
          </nav>
        </div>

        {/* Tab Panels */}
        <div className="p-6">
          {/* Inbox */}
          <div
            id="comms-panel-inbox"
            role="tabpanel"
            hidden={activeTab !== 'inbox'}
          >
            {activeTab === 'inbox' && <InboxPanel />}
          </div>

          {/* Email */}
          <div
            id="comms-panel-email"
            role="tabpanel"
            hidden={activeTab !== 'email'}
          >
            {activeTab === 'email' && <EmailTab />}
          </div>

          {/* WhatsApp */}
          <div
            id="comms-panel-whatsapp"
            role="tabpanel"
            hidden={activeTab !== 'whatsapp'}
          >
            {activeTab === 'whatsapp' && (
              <div className="text-center py-8">
                <MessageCircle className="w-12 h-12 mx-auto text-green-500 mb-4" />
                <h3 className="text-lg font-medium text-[var(--ff-text-primary)] mb-2">WhatsApp Portal</h3>
                <p className="text-sm text-[var(--ff-text-secondary)] max-w-md mx-auto mb-4">
                  Manage WhatsApp groups, view messages, and monitor service status.
                </p>
                <Link
                  href="/communications/whatsapp"
                  className="inline-flex items-center gap-2 px-4 py-2 bg-green-500 text-white rounded-lg hover:bg-green-600 transition-colors"
                >
                  <MessageCircle className="w-4 h-4" />
                  Open WhatsApp Portal
                </Link>
              </div>
            )}
          </div>

          {/* Meetings - Working */}
          <div
            id="comms-panel-meetings"
            role="tabpanel"
            hidden={activeTab !== 'meetings'}
          >
            {activeTab === 'meetings' && (
              isLoading ? (
                <div className="flex items-center justify-center py-12">
                  <RefreshCw className="w-6 h-6 animate-spin text-[var(--ff-text-tertiary)]" />
                  <span className="ml-2 text-[var(--ff-text-secondary)]">Loading meetings...</span>
                </div>
              ) : (
                <CommunicationsMeetingsTab
                  meetings={data.meetings}
                  getStatusColor={getStatusColor}
                  onRefresh={handleRefresh}
                />
              )
            )}
          </div>

          {/* Notifications - Working */}
          <div
            id="comms-panel-notifications"
            role="tabpanel"
            hidden={activeTab !== 'notifications'}
          >
            {activeTab === 'notifications' && <NotificationsTab />}
          </div>

          {/* Settings */}
          <div
            id="comms-panel-settings"
            role="tabpanel"
            hidden={activeTab !== 'settings'}
          >
            {activeTab === 'settings' && (
              <ComingSoonCard
                title="Communication Preferences"
                description="Configure notification preferences per event type — choose between in-app, email, and WhatsApp delivery for each module."
              />
            )}
          </div>
        </div>
      </div>
    </div>
  );
}

import { Calendar, Clock, Video, MapPin, Users, ChevronRight, CheckCircle, Link, Edit, Trash2, Loader2, AlertCircle } from 'lucide-react';
import type { Meeting } from '../types/meeting.types';
import { getMeetingTypeColor, getStatusColor, getSourceColor, getSourceLabel } from '../utils/meetingUtils';

interface MeetingsListProps {
  meetings: Meeting[];
  onEditMeeting: (meeting: Meeting) => void;
  onDeleteMeeting: (meetingId: string) => void;
}

export function MeetingsList({ meetings, onEditMeeting, onDeleteMeeting }: MeetingsListProps) {
  if (meetings.length === 0) {
    return (
      <div className="ff-card">
        <div className="p-8 text-center text-[var(--ff-text-secondary)]">
          <Calendar className="w-12 h-12 mx-auto mb-4 text-[var(--ff-text-tertiary)]" />
          <p>No meetings found</p>
        </div>
      </div>
    );
  }

  return (
    <div className="divide-y divide-[var(--ff-border-light)]">
      {meetings.map((meeting) => (
        <div
          key={meeting.id}
          className="hover:bg-[var(--ff-bg-hover)] transition-colors cursor-pointer"
          onClick={() => onEditMeeting(meeting)}
        >
          <div className="p-6">
            <div className="flex items-start justify-between">
              <div className="flex-1">
                <div className="flex items-center gap-3 mb-2">
                  <h3 className="text-lg font-semibold">{meeting.title}</h3>
                  <span className={`px-2 py-1 text-xs rounded-full ${getSourceColor(meeting.source)}`}>
                    {getSourceLabel(meeting.source)}
                  </span>
                  <span className={`px-2 py-1 text-xs rounded-full ${getMeetingTypeColor(meeting.type)}`}>
                    {meeting.type}
                  </span>
                  <span className={`px-2 py-1 text-xs rounded-full ${getStatusColor(meeting.status)}`}>
                    {meeting.status}
                  </span>
                  {meeting.processingStatus && meeting.processingStatus !== 'completed' && (
                    <span className="flex items-center gap-1 px-2 py-1 text-xs rounded-full bg-yellow-500/20 text-yellow-400">
                      {meeting.processingStatus === 'failed' ? (
                        <AlertCircle className="w-3 h-3" />
                      ) : (
                        <Loader2 className="w-3 h-3 animate-spin" />
                      )}
                      {meeting.processingStatus}
                    </span>
                  )}
                </div>

                <div className="grid grid-cols-1 sm:grid-cols-2 gap-4 text-sm text-[var(--ff-text-secondary)] mb-3">
                  <div className="flex items-center gap-2">
                    <Calendar className="w-4 h-4" />
                    <span>{meeting.date.toISOString().split('T')[0]}</span>
                  </div>
                  <div className="flex items-center gap-2">
                    <Clock className="w-4 h-4" />
                    <span>{meeting.time} ({meeting.duration})</span>
                  </div>
                  <div className="flex items-center gap-2">
                    {meeting.isVirtual ? (
                      <>
                        <Video className="w-4 h-4" />
                        <span>Virtual Meeting</span>
                      </>
                    ) : (
                      <>
                        <MapPin className="w-4 h-4" />
                        <span>{meeting.location}</span>
                      </>
                    )}
                  </div>
                  <div className="flex items-center gap-2">
                    <Users className="w-4 h-4 flex-shrink-0" />
                    <span>
                      {meeting.participants.length} attendee{meeting.participants.length !== 1 ? 's' : ''}
                      {meeting.participants.length > 0 && (
                        <span className="text-[var(--ff-text-tertiary)]">
                          {' '}&middot; {meeting.participants.slice(0, 3).join(', ')}
                          {meeting.participants.length > 3 && ` +${meeting.participants.length - 3}`}
                        </span>
                      )}
                    </span>
                  </div>
                </div>

                <div className="mb-3">
                  <p className="text-sm font-medium text-[var(--ff-text-primary)] mb-1">Agenda:</p>
                  <ul className="text-sm text-[var(--ff-text-secondary)] space-y-1">
                    {meeting.agenda.slice(0, 2).map((item, index) => (
                      <li key={index} className="flex items-start gap-2">
                        <ChevronRight className="w-3 h-3 mt-0.5" />
                        <span>{item}</span>
                      </li>
                    ))}
                    {meeting.agenda.length > 2 && (
                      <li className="text-[var(--ff-text-tertiary)] italic">+{meeting.agenda.length - 2} more items</li>
                    )}
                  </ul>
                </div>

                {meeting.actionItems.length > 0 && (
                  <div className="flex items-center gap-2 text-sm">
                    <CheckCircle className="w-4 h-4 text-green-500" />
                    <span className="text-[var(--ff-text-secondary)]">
                      {meeting.actionItems.filter(a => a.completed).length}/{meeting.actionItems.length} action items completed
                    </span>
                  </div>
                )}
              </div>

              <div className="flex gap-2">
                {meeting.isVirtual && meeting.meetingLink && (
                  <button
                    className="p-2 hover:bg-[var(--ff-bg-hover)] rounded"
                    onClick={(e) => {
                      e.stopPropagation();
                      window.open(meeting.meetingLink, '_blank');
                    }}
                  >
                    <Link className="w-4 h-4 text-blue-500" />
                  </button>
                )}
                <button
                  className="p-2 hover:bg-[var(--ff-bg-hover)] rounded"
                  onClick={(e) => {
                    e.stopPropagation();
                    onEditMeeting(meeting);
                  }}
                >
                  <Edit className="w-4 h-4 text-[var(--ff-text-secondary)]" />
                </button>
                <button
                  className="p-2 hover:bg-[var(--ff-bg-hover)] rounded"
                  onClick={(e) => {
                    e.stopPropagation();
                    onDeleteMeeting(meeting.id);
                  }}
                >
                  <Trash2 className="w-4 h-4 text-red-500" />
                </button>
              </div>
            </div>
          </div>
        </div>
      ))}
    </div>
  );
}

/**
 * Inbox Panel — unified feed + messaging views
 * Views: Feed (default) | Messages | Sent | Archived with compose modal and thread view
 */

import { useState } from 'react';
import {
  Inbox,
  Send,
  Archive,
  PenLine,
  CheckCheck,
  RefreshCw,
  Mail,
  Rss,
} from 'lucide-react';
import { cn } from '@/lib/utils';
import { useInternalMessages } from '../hooks/useInternalMessages';
import { MessageListItem } from './MessageListItem';
import { MessageThread } from './MessageThread';
import { ComposeMessageModal } from './ComposeMessageModal';
import { UnifiedFeedList } from './UnifiedFeedList';
import type { MessageView } from '../types/messaging.types';

type PanelView = 'feed' | MessageView;

const VIEWS: { key: PanelView; label: string; icon: React.ElementType }[] = [
  { key: 'feed', label: 'Feed', icon: Rss },
  { key: 'inbox', label: 'Messages', icon: Inbox },
  { key: 'sent', label: 'Sent', icon: Send },
  { key: 'archived', label: 'Archived', icon: Archive },
];

export function InboxPanel() {
  const [view, setView] = useState<PanelView>('feed');
  const [activeThread, setActiveThread] = useState<string | null>(null);
  const [showCompose, setShowCompose] = useState(false);

  // Messages hook — only needed for messaging views, pass 'inbox' when on feed
  const messageView: MessageView = view === 'feed' ? 'inbox' : view;
  const {
    messages,
    isLoading,
    hasMore,
    total,
    unreadCount,
    refetch,
    loadMore,
    markRead,
    markAllRead,
  } = useInternalMessages(messageView);

  const handleOpenThread = (messageId: string) => {
    // If opening from feed, switch to messages view context
    if (view === 'feed') {
      setView('inbox');
    }
    const msg = messages.find(m => m.id === messageId);
    if (msg && !msg.is_read) {
      markRead([messageId]);
    }
    setActiveThread(messageId);
  };

  const handleBackFromThread = () => {
    setActiveThread(null);
    refetch();
  };

  const handleMessageSent = () => {
    refetch();
  };

  // Thread view (shared between feed and messages)
  if (activeThread) {
    return (
      <MessageThread threadId={activeThread} onBack={handleBackFromThread} />
    );
  }

  const isFeed = view === 'feed';

  return (
    <div className="space-y-4">
      {/* Top bar: view toggle + actions */}
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-1">
          {VIEWS.map(v => {
            const Icon = v.icon;
            const isActive = view === v.key;
            return (
              <button
                key={v.key}
                type="button"
                onClick={() => setView(v.key)}
                className={cn(
                  'flex items-center gap-1.5 px-3 py-1.5 text-xs font-medium rounded-lg transition-colors',
                  isActive
                    ? 'bg-[var(--ff-primary)]/10 text-[var(--ff-primary)]'
                    : 'text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)] hover:bg-[var(--ff-bg-tertiary)]'
                )}
              >
                <Icon className="w-3.5 h-3.5" />
                {v.label}
                {v.key === 'inbox' && unreadCount > 0 && (
                  <span className="px-1.5 py-0.5 text-[10px] font-semibold bg-blue-500 text-white rounded-full">
                    {unreadCount}
                  </span>
                )}
              </button>
            );
          })}
        </div>

        <div className="flex items-center gap-2">
          {view === 'inbox' && unreadCount > 0 && (
            <button
              type="button"
              onClick={markAllRead}
              className="flex items-center gap-1.5 px-3 py-1.5 text-xs font-medium text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)] border border-[var(--ff-border-light)] rounded-lg hover:bg-[var(--ff-bg-tertiary)] transition-colors"
            >
              <CheckCheck className="w-3.5 h-3.5" />
              Mark all read
            </button>
          )}

          {!isFeed && (
            <button
              type="button"
              onClick={() => refetch()}
              disabled={isLoading}
              className="flex items-center gap-1.5 px-3 py-1.5 text-xs font-medium text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)] border border-[var(--ff-border-light)] rounded-lg hover:bg-[var(--ff-bg-tertiary)] transition-colors disabled:opacity-50"
            >
              <RefreshCw className={cn('w-3.5 h-3.5', isLoading && 'animate-spin')} />
            </button>
          )}

          <button
            type="button"
            onClick={() => setShowCompose(true)}
            className="flex items-center gap-1.5 px-4 py-1.5 text-sm font-medium bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors"
          >
            <PenLine className="w-3.5 h-3.5" />
            Compose
          </button>
        </div>
      </div>

      {/* Feed view */}
      {isFeed ? (
        <UnifiedFeedList onOpenThread={handleOpenThread} />
      ) : (
        <>
          {/* Message count */}
          <p className="text-xs text-[var(--ff-text-tertiary)]">
            {total > 0
              ? `${total} message${total !== 1 ? 's' : ''}${view === 'inbox' && unreadCount > 0 ? ` (${unreadCount} unread)` : ''}`
              : ''}
          </p>

          {/* Message list */}
          {isLoading && messages.length === 0 ? (
            <div className="flex items-center justify-center py-12">
              <RefreshCw className="w-5 h-5 animate-spin text-[var(--ff-text-tertiary)]" />
              <span className="ml-2 text-sm text-[var(--ff-text-secondary)]">Loading messages...</span>
            </div>
          ) : messages.length === 0 ? (
            <div className="text-center py-12">
              <Mail className="w-10 h-10 mx-auto text-[var(--ff-text-tertiary)] mb-3" />
              <p className="text-sm text-[var(--ff-text-secondary)]">
                {view === 'inbox' ? 'Your inbox is empty' :
                 view === 'sent' ? 'No sent messages' :
                 'No archived messages'}
              </p>
              {view === 'inbox' && (
                <button
                  type="button"
                  onClick={() => setShowCompose(true)}
                  className="mt-3 text-sm text-blue-500 hover:text-blue-400"
                >
                  Send your first message
                </button>
              )}
            </div>
          ) : (
            <div className="border border-[var(--ff-border-light)] rounded-lg overflow-hidden">
              {messages.map(msg => (
                <MessageListItem
                  key={msg.id}
                  message={msg}
                  onClick={handleOpenThread}
                  showSender={view !== 'sent'}
                />
              ))}

              {hasMore && (
                <div className="flex justify-center py-3 border-t border-[var(--ff-border-light)]">
                  <button
                    type="button"
                    onClick={loadMore}
                    disabled={isLoading}
                    className="px-4 py-1.5 text-sm font-medium text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)] border border-[var(--ff-border-light)] rounded-lg hover:bg-[var(--ff-bg-tertiary)] transition-colors disabled:opacity-50"
                  >
                    {isLoading ? 'Loading...' : 'Load more'}
                  </button>
                </div>
              )}
            </div>
          )}
        </>
      )}

      {/* Compose modal */}
      <ComposeMessageModal
        isOpen={showCompose}
        onClose={() => setShowCompose(false)}
        onSent={handleMessageSent}
      />
    </div>
  );
}

/**
 * Fireflies.ai API Service
 * Fetches meeting transcripts and summaries
 */

const FIREFLIES_API_URL = 'https://api.fireflies.ai/graphql';

interface FirefliesSpeaker {
  id: number;
  name: string;
}

interface FirefliesAttendee {
  name: string | null;
  email: string | null;
  displayName: string | null;
}

interface FirefliesTranscript {
  id: string;
  title: string;
  date: string;
  duration: number;
  transcript_url: string;
  summary: {
    keywords: string[];
    action_items: string[];
    outline: string[];
  };
  speakers: FirefliesSpeaker[];
  participants: string[];
  meeting_attendees: FirefliesAttendee[];
}

export interface MergedParticipant {
  name: string;
  email: string;
  displayName: string;
}

/**
 * Merge speakers, meeting_attendees, and participants into a single deduplicated list.
 * Priority: speakers (have names from voice recognition) > meeting_attendees > participants (emails only)
 */
function mergeParticipants(transcript: FirefliesTranscript): MergedParticipant[] {
  const seen = new Set<string>();
  const result: MergedParticipant[] = [];

  // 1. Add unique speakers (deduplicated by name)
  if (transcript.speakers?.length) {
    for (const speaker of transcript.speakers) {
      const name = speaker.name?.trim();
      if (!name) continue;
      const key = name.toLowerCase();
      if (seen.has(key)) continue;
      seen.add(key);
      result.push({ name, email: '', displayName: name });
    }
  }

  // 2. Add meeting_attendees not already covered by speakers
  if (transcript.meeting_attendees?.length) {
    for (const attendee of transcript.meeting_attendees) {
      const email = attendee.email?.trim() || '';
      const name = attendee.name?.trim() || '';
      const displayName = attendee.displayName?.trim() || '';
      const key = (name || email || displayName).toLowerCase();
      if (!key || seen.has(key)) continue;
      // Also check if email matches a known key
      if (email && seen.has(email.toLowerCase())) continue;
      seen.add(key);
      if (email) seen.add(email.toLowerCase());
      result.push({ name, email, displayName });
    }
  }

  // 3. Add participant emails not already covered
  if (transcript.participants?.length) {
    for (const email of transcript.participants) {
      const trimmed = email?.trim();
      if (!trimmed) continue;
      const key = trimmed.toLowerCase();
      if (seen.has(key)) continue;
      seen.add(key);
      result.push({ name: '', email: trimmed, displayName: '' });
    }
  }

  return result;
}

export async function fetchFirefliesTranscripts(apiKey: string) {
  const query = `
    query {
      transcripts {
        id
        title
        date
        duration
        transcript_url
        summary {
          keywords
          action_items
          outline
        }
        speakers {
          id
          name
        }
        participants
        meeting_attendees {
          name
          email
          displayName
        }
      }
    }
  `;

  const response = await fetch(FIREFLIES_API_URL, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'Authorization': `Bearer ${apiKey}`,
    },
    body: JSON.stringify({ query }),
  });

  if (!response.ok) {
    throw new Error(`Fireflies API error: ${response.statusText}`);
  }

  const data = await response.json();
  return data.data.transcripts as FirefliesTranscript[];
}

export async function syncFirefliesToNeon(apiKey: string, sql: any) {
  const transcripts = await fetchFirefliesTranscripts(apiKey);

  for (const transcript of transcripts) {
    const merged = mergeParticipants(transcript);

    await sql`
      INSERT INTO meetings (
        fireflies_id,
        title,
        meeting_date,
        duration,
        transcript_url,
        summary,
        participants,
        created_at,
        updated_at
      ) VALUES (
        ${transcript.id},
        ${transcript.title},
        TO_TIMESTAMP(${transcript.date} / 1000.0),
        ${Math.floor(transcript.duration || 0)},
        ${transcript.transcript_url},
        ${JSON.stringify(transcript.summary)},
        ${JSON.stringify(merged)},
        NOW(),
        NOW()
      )
      ON CONFLICT (fireflies_id)
      DO UPDATE SET
        title = ${transcript.title},
        meeting_date = TO_TIMESTAMP(${transcript.date} / 1000.0),
        duration = ${Math.floor(transcript.duration || 0)},
        transcript_url = ${transcript.transcript_url},
        summary = ${JSON.stringify(transcript.summary)},
        participants = ${JSON.stringify(merged)},
        updated_at = NOW()
    `;
  }

  return transcripts.length;
}

/**
 * Internal Messages API
 * GET  - List inbox/sent/archived messages (paginated)
 * POST - Send a new message
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { neon } from '@neondatabase/serverless';
import { withAuth, type AuthenticatedNextApiRequest } from '@/lib/auth';
import { apiResponse } from '@/lib/apiResponse';
import { log } from '@/lib/logger';
import { notify } from '@/modules/notifications/services/notificationBus';

const sql = neon(process.env.DATABASE_URL!);

async function handler(req: NextApiRequest, res: NextApiResponse) {
  const authUser = (req as AuthenticatedNextApiRequest).user;
  const userId = authUser.id;

  if (req.method === 'GET') {
    return handleGet(req, res, userId);
  }

  if (req.method === 'POST') {
    return handlePost(req, res, userId, authUser.name || authUser.email);
  }

  return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET', 'POST']);
}

async function handleGet(req: NextApiRequest, res: NextApiResponse, userId: string) {
  try {
    const view = (req.query.view as string) || 'inbox';
    const limit = Math.min(parseInt(req.query.limit as string || '20', 10) || 20, 100);
    const offset = parseInt(req.query.offset as string || '0', 10) || 0;
    const unreadOnly = req.query.unread_only === 'true';

    if (view === 'sent') {
      return fetchSent(res, userId, limit, offset);
    }

    if (view === 'archived') {
      return fetchRecipientView(res, userId, limit, offset, false, true);
    }

    // Default: inbox (not archived)
    return fetchRecipientView(res, userId, limit, offset, unreadOnly, false);
  } catch (error) {
    log.error('Failed to fetch messages', { error }, 'Messages');
    return apiResponse.internalError(res, error);
  }
}

async function fetchRecipientView(
  res: NextApiResponse,
  userId: string,
  limit: number,
  offset: number,
  unreadOnly: boolean,
  archived: boolean
) {
  // Root messages only (thread_id IS NULL) where user is a recipient
  if (unreadOnly) {
    const messages = await sql`
      SELECT
        m.id, m.sender_id, m.subject, m.body, m.priority,
        m.thread_id, m.context_module, m.context_url, m.created_at,
        COALESCE(u.first_name || ' ' || u.last_name, u.email) AS sender_name,
        u.email AS sender_email,
        r.is_read,
        (SELECT COUNT(*)::int FROM internal_messages WHERE thread_id = m.id) AS reply_count,
        (SELECT COUNT(*)::int FROM internal_message_recipients WHERE message_id = m.id) AS recipient_count,
        (SELECT MAX(created_at) FROM internal_messages WHERE thread_id = m.id) AS latest_reply_at
      FROM internal_messages m
      INNER JOIN internal_message_recipients r ON r.message_id = m.id AND r.recipient_id = ${userId}::uuid
      INNER JOIN users u ON u.id = m.sender_id
      WHERE m.thread_id IS NULL
        AND r.is_archived = ${archived}
        AND r.is_read = FALSE
      ORDER BY COALESCE(
        (SELECT MAX(created_at) FROM internal_messages WHERE thread_id = m.id),
        m.created_at
      ) DESC
      LIMIT ${limit} OFFSET ${offset}
    `;

    const countResult = await sql`
      SELECT COUNT(*)::int AS total
      FROM internal_messages m
      INNER JOIN internal_message_recipients r ON r.message_id = m.id AND r.recipient_id = ${userId}::uuid
      WHERE m.thread_id IS NULL
        AND r.is_archived = ${archived}
        AND r.is_read = FALSE
    `;

    return apiResponse.success(res, {
      messages,
      total: Number(countResult[0]?.total || 0),
    });
  }

  // All messages (read + unread)
  const messages = await sql`
    SELECT
      m.id, m.sender_id, m.subject, m.body, m.priority,
      m.thread_id, m.context_module, m.context_url, m.created_at,
      COALESCE(u.first_name || ' ' || u.last_name, u.email) AS sender_name,
      u.email AS sender_email,
      r.is_read,
      (SELECT COUNT(*)::int FROM internal_messages WHERE thread_id = m.id) AS reply_count,
      (SELECT COUNT(*)::int FROM internal_message_recipients WHERE message_id = m.id) AS recipient_count,
      (SELECT MAX(created_at) FROM internal_messages WHERE thread_id = m.id) AS latest_reply_at
    FROM internal_messages m
    INNER JOIN internal_message_recipients r ON r.message_id = m.id AND r.recipient_id = ${userId}::uuid
    INNER JOIN users u ON u.id = m.sender_id
    WHERE m.thread_id IS NULL
      AND r.is_archived = ${archived}
    ORDER BY COALESCE(
      (SELECT MAX(created_at) FROM internal_messages WHERE thread_id = m.id),
      m.created_at
    ) DESC
    LIMIT ${limit} OFFSET ${offset}
  `;

  const countResult = await sql`
    SELECT COUNT(*)::int AS total
    FROM internal_messages m
    INNER JOIN internal_message_recipients r ON r.message_id = m.id AND r.recipient_id = ${userId}::uuid
    WHERE m.thread_id IS NULL
      AND r.is_archived = ${archived}
  `;

  return apiResponse.success(res, {
    messages,
    total: Number(countResult[0]?.total || 0),
  });
}

async function fetchSent(
  res: NextApiResponse,
  userId: string,
  limit: number,
  offset: number
) {
  const messages = await sql`
    SELECT
      m.id, m.sender_id, m.subject, m.body, m.priority,
      m.thread_id, m.context_module, m.context_url, m.created_at,
      COALESCE(u.first_name || ' ' || u.last_name, u.email) AS sender_name,
      u.email AS sender_email,
      TRUE AS is_read,
      (SELECT COUNT(*)::int FROM internal_messages WHERE thread_id = m.id) AS reply_count,
      (SELECT COUNT(*)::int FROM internal_message_recipients WHERE message_id = m.id) AS recipient_count,
      (SELECT MAX(created_at) FROM internal_messages WHERE thread_id = m.id) AS latest_reply_at
    FROM internal_messages m
    INNER JOIN users u ON u.id = m.sender_id
    WHERE m.sender_id = ${userId}::uuid
      AND m.thread_id IS NULL
    ORDER BY m.created_at DESC
    LIMIT ${limit} OFFSET ${offset}
  `;

  const countResult = await sql`
    SELECT COUNT(*)::int AS total
    FROM internal_messages m
    WHERE m.sender_id = ${userId}::uuid
      AND m.thread_id IS NULL
  `;

  return apiResponse.success(res, {
    messages,
    total: Number(countResult[0]?.total || 0),
  });
}

async function handlePost(
  req: NextApiRequest,
  res: NextApiResponse,
  userId: string,
  senderName: string
) {
  try {
    const { recipients, subject, body, priority, threadId, contextModule, contextId, contextUrl } = req.body;

    if (!body || typeof body !== 'string' || !body.trim()) {
      return apiResponse.badRequest(res, 'Message body is required');
    }

    if (!recipients || !Array.isArray(recipients) || recipients.length === 0) {
      return apiResponse.badRequest(res, 'At least one recipient is required');
    }

    // Insert message
    const messageRows = await sql`
      INSERT INTO internal_messages (
        sender_id, subject, body, priority,
        thread_id, context_module, context_id, context_url
      ) VALUES (
        ${userId}::uuid,
        ${subject?.trim() || null},
        ${body.trim()},
        ${priority || 'normal'},
        ${threadId || null},
        ${contextModule || null},
        ${contextId || null},
        ${contextUrl || null}
      )
      RETURNING *
    `;

    const message = messageRows[0];

    // Insert recipients
    for (const recipientId of recipients) {
      await sql`
        INSERT INTO internal_message_recipients (message_id, recipient_id)
        VALUES (${message.id}, ${recipientId}::uuid)
        ON CONFLICT (message_id, recipient_id) DO NOTHING
      `;
    }

    // Trigger notifications (fire-and-forget)
    const notifSubject = subject?.trim() || body.trim().substring(0, 100);
    notify({
      event_type: 'messaging.new_message',
      title: `${senderName} sent you a message`,
      body: notifSubject,
      icon: 'mail',
      severity: priority === 'urgent' ? 'warning' : 'info',
      action_url: '/communications?tab=inbox',
      source_module: 'messaging',
      source_id: message.id,
      recipient_user_ids: recipients,
    }).catch(err => {
      log.error('Failed to send message notification', { error: err }, 'Messages');
    });

    log.info('Internal message sent', {
      messageId: message.id,
      sender: userId,
      recipientCount: recipients.length,
      isReply: !!threadId,
    }, 'Messages');

    return apiResponse.created(res, message, 'Message sent');
  } catch (error) {
    log.error('Failed to send message', { error }, 'Messages');
    return apiResponse.internalError(res, error);
  }
}

export default withAuth(handler);

/**
 * GET /api/communications/feed
 * Unified feed API — queries messages, email outbox, notifications, and
 * meeting action items in parallel, normalizes to FeedItem[], merges
 * chronologically, and paginates.
 *
 * Query params:
 *   limit    — 1..50 (default 30)
 *   offset   — number (default 0)
 *   channels — comma-separated: message,email,notification,meeting (default: all)
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { neon } from '@neondatabase/serverless';
import { withAuth, type AuthenticatedNextApiRequest } from '@/lib/auth';
import { apiResponse } from '@/lib/apiResponse';
import { log } from '@/lib/logger';
import type { FeedItem } from '@/modules/communications/types/hub.types';

const sql = neon(process.env.DATABASE_URL!);

type Channel = 'message' | 'email' | 'notification' | 'meeting';
const ALL_CHANNELS: Channel[] = ['message', 'email', 'notification', 'meeting'];

// ---------------------------------------------------------------------------
// Channel query helpers
// ---------------------------------------------------------------------------

async function fetchMessages(userId: string): Promise<FeedItem[]> {
  const rows = await sql`
    SELECT
      m.id,
      m.subject,
      m.body,
      m.priority,
      m.context_module,
      m.created_at,
      u.first_name || ' ' || u.last_name AS sender_name,
      r.is_read,
      (
        SELECT COUNT(*)::int FROM internal_messages sub
        WHERE sub.thread_id = m.id
      ) AS reply_count,
      (
        SELECT MAX(sub.created_at) FROM internal_messages sub
        WHERE sub.thread_id = m.id
      ) AS latest_reply_at
    FROM internal_messages m
    JOIN internal_message_recipients r
      ON r.message_id = m.id AND r.recipient_id = ${userId}::uuid
    JOIN users u ON u.id = m.sender_id
    WHERE m.thread_id IS NULL
      AND r.is_archived = FALSE
    ORDER BY COALESCE(
      (SELECT MAX(sub.created_at) FROM internal_messages sub WHERE sub.thread_id = m.id),
      m.created_at
    ) DESC
    LIMIT 50
  `;

  return rows.map((r): FeedItem => ({
    id: r.id,
    channel: 'message',
    title: r.subject || r.sender_name,
    body: r.body ? String(r.body).slice(0, 200) : null,
    timestamp: r.latest_reply_at || r.created_at,
    isRead: !!r.is_read,
    actionUrl: '/communications?tab=inbox',
    sourceModule: r.context_module || 'messaging',
    sourceId: r.id,
    metadata: {
      priority: r.priority,
      reply_count: Number(r.reply_count),
      sender_name: r.sender_name,
    },
  }));
}

async function fetchEmails(userId: string): Promise<FeedItem[]> {
  const rows = await sql`
    SELECT
      e.id,
      e.subject,
      e.recipient_email,
      e.recipient_name,
      e.source_module,
      e.status,
      e.sent_at,
      e.created_at
    FROM email_outbox e
    WHERE e.sender_id = ${userId}::uuid
    ORDER BY e.created_at DESC
    LIMIT 50
  `;

  return rows.map((r): FeedItem => ({
    id: r.id,
    channel: 'email',
    title: r.subject,
    body: r.recipient_name
      ? `To: ${r.recipient_name} <${r.recipient_email}>`
      : `To: ${r.recipient_email}`,
    timestamp: r.sent_at || r.created_at,
    isRead: true, // Sent by user
    actionUrl: null,
    sourceModule: r.source_module || 'email',
    sourceId: r.id,
    metadata: {
      status: r.status,
      recipient_name: r.recipient_name,
      recipient_email: r.recipient_email,
    },
  }));
}

async function fetchNotifications(userId: string): Promise<FeedItem[]> {
  const rows = await sql`
    SELECT
      n.id,
      n.title,
      n.body,
      n.icon,
      n.severity,
      n.event_type,
      n.action_url,
      n.source_module,
      n.source_id,
      n.is_read,
      n.created_at
    FROM user_notifications n
    WHERE n.user_id = ${userId}::uuid
      AND n.event_type != 'messaging.new_message'
    ORDER BY n.created_at DESC
    LIMIT 50
  `;

  return rows.map((r): FeedItem => ({
    id: r.id,
    channel: 'notification',
    title: r.title,
    body: r.body ? String(r.body).slice(0, 200) : null,
    timestamp: r.created_at,
    isRead: !!r.is_read,
    actionUrl: r.action_url || null,
    sourceModule: r.source_module || null,
    sourceId: r.source_id || null,
    metadata: {
      severity: r.severity,
      event_type: r.event_type,
      icon: r.icon,
    },
  }));
}

async function fetchMeetingActions(
  userId: string,
  userEmail: string
): Promise<FeedItem[]> {
  const rows = await sql`
    SELECT
      ai.id,
      ai.description,
      ai.assignee_name,
      ai.status::text AS status,
      ai.priority::text AS priority,
      ai.due_date,
      ai.created_at,
      m.title AS meeting_title
    FROM meeting_action_items ai
    LEFT JOIN meetings m ON ai.meeting_id = m.id
    WHERE (ai.assignee_email = ${userEmail} OR ai.created_by = ${userId}::uuid)
      AND ai.status::text IN ('pending', 'in_progress')
    ORDER BY ai.created_at DESC
    LIMIT 50
  `;

  return rows.map((r): FeedItem => ({
    id: r.id,
    channel: 'meeting',
    title: r.description ? String(r.description).slice(0, 120) : 'Action item',
    body: r.meeting_title
      ? `${r.meeting_title}${r.due_date ? ` — Due: ${new Date(r.due_date).toLocaleDateString('en-ZA')}` : ''}`
      : null,
    timestamp: r.created_at,
    isRead: r.status !== 'pending',
    actionUrl: '/action-items',
    sourceModule: 'meetings',
    sourceId: r.id,
    metadata: {
      priority: r.priority,
      status: r.status,
      due_date: r.due_date,
      assignee: r.assignee_name,
    },
  }));
}

// ---------------------------------------------------------------------------
// Handler
// ---------------------------------------------------------------------------

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'GET') {
    return apiResponse.methodNotAllowed(res, req.method!, ['GET']);
  }

  const authUser = (req as AuthenticatedNextApiRequest).user;
  const userId = authUser.id;
  const userEmail = authUser.email;

  try {
    // Parse params
    const limit = Math.min(
      Math.max(parseInt(String(req.query.limit || '30'), 10) || 30, 1),
      50
    );
    const offset = Math.max(
      parseInt(String(req.query.offset || '0'), 10) || 0,
      0
    );

    const channelsParam = String(req.query.channels || '').trim();
    const requestedChannels: Channel[] = channelsParam
      ? (channelsParam.split(',').filter(c => ALL_CHANNELS.includes(c as Channel)) as Channel[])
      : ALL_CHANNELS;

    if (requestedChannels.length === 0) {
      return apiResponse.success(res, {
        items: [],
        total: 0,
        counts: { message: 0, email: 0, notification: 0, meeting: 0 },
      });
    }

    // Fetch all active channels in parallel
    const fetchers: Record<Channel, () => Promise<FeedItem[]>> = {
      message: () => fetchMessages(userId),
      email: () => fetchEmails(userId),
      notification: () => fetchNotifications(userId),
      meeting: () => fetchMeetingActions(userId, userEmail),
    };

    const results = await Promise.all(
      requestedChannels.map(async (ch) => ({
        channel: ch,
        items: await fetchers[ch](),
      }))
    );

    // Build per-channel counts
    const counts = { message: 0, email: 0, notification: 0, meeting: 0 };
    const allItems: FeedItem[] = [];

    for (const { channel, items } of results) {
      counts[channel] = items.length;
      allItems.push(...items);
    }

    // Sort by timestamp DESC
    allItems.sort(
      (a, b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime()
    );

    const total = allItems.length;
    const paginated = allItems.slice(offset, offset + limit);

    return apiResponse.success(res, {
      items: paginated,
      total,
      counts,
    });
  } catch (error) {
    log.error('Failed to fetch unified feed', { error }, 'CommunicationsFeed');
    return apiResponse.internalError(res, error);
  }
}

export default withAuth(handler);

