import type { NextApiRequest, NextApiResponse } from 'next';
import { neon } from '@neondatabase/serverless';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth } from '@/lib/auth';
import {
  ActionItem,
  ActionItemCreateInput,
  ActionItemFilters,
  ActionItemStats,
} from '@/types/action-items.types';
import { log } from '@/lib/logger';

const sql = neon(process.env.DATABASE_URL!);

async function handler(
  req: NextApiRequest,
  res: NextApiResponse
) {
  // GET - List action items with filters
  if (req.method === 'GET') {
    try {
      const {
        status,
        assignee_name,
        meeting_id,
        priority,
        search,
        overdue,
      } = req.query as Partial<Record<keyof ActionItemFilters, string>>;

      // Simple approach: Fetch all and filter in code
      // This is acceptable for moderate datasets (<10k items)
      let items = await sql`
        SELECT
          ai.id,
          ai.meeting_id,
          ai.description,
          ai.assignee_name,
          ai.assignee_email,
          ai.status::text,
          ai.priority::text,
          ai.due_date,
          ai.completed_date,
          ai.mentioned_at,
          ai.created_at,
          ai.updated_at,
          ai.tags,
          ai.notes,
          m.title as meeting_title,
          m.meeting_date,
          m.transcript_url
        FROM meeting_action_items ai
        LEFT JOIN meetings m ON ai.meeting_id = m.id
        ORDER BY
          CASE
            WHEN ai.status::text = 'pending' THEN 1
            WHEN ai.status::text = 'in_progress' THEN 2
            WHEN ai.status::text = 'completed' THEN 3
            WHEN ai.status::text = 'cancelled' THEN 4
          END,
          ai.created_at DESC
        LIMIT 500
      `;

      // Apply filters in JavaScript
      if (status) {
        const statuses = status.split(',');
        items = items.filter(item => statuses.includes(item.status));
      }

      if (assignee_name) {
        const search = assignee_name.toLowerCase();
        items = items.filter(item => item.assignee_name?.toLowerCase().includes(search));
      }

      if (meeting_id) {
        const id = parseInt(meeting_id);
        items = items.filter(item => item.meeting_id === id);
      }

      if (priority) {
        items = items.filter(item => item.priority === priority);
      }

      if (search) {
        const searchLower = search.toLowerCase();
        items = items.filter(item => item.description?.toLowerCase().includes(searchLower));
      }

      if (overdue === 'true') {
        const now = new Date();
        items = items.filter(item =>
          item.due_date &&
          new Date(item.due_date) < now &&
          item.status !== 'completed'
        );
      }

      // Limit results
      items = items.slice(0, 100);

      return apiResponse.success(res, items as ActionItem[]);
    } catch (error: any) {
      log.error('Error fetching action items', { error });
      return apiResponse.internalError(res, error);
    }
  }

  // POST - Create new action item
  if (req.method === 'POST') {
    try {
      const input: ActionItemCreateInput = req.body;

      if (!input.meeting_id || !input.description) {
        return apiResponse.validationError(res, {
          meeting_id: !input.meeting_id ? 'Meeting ID is required' : undefined,
          description: !input.description ? 'Description is required' : undefined,
        });
      }

      const [item] = await sql`
        INSERT INTO meeting_action_items (
          meeting_id,
          description,
          assignee_name,
          assignee_email,
          status,
          priority,
          due_date,
          mentioned_at,
          tags,
          notes
        ) VALUES (
          ${input.meeting_id},
          ${input.description},
          ${input.assignee_name || null},
          ${input.assignee_email || null},
          ${input.status || 'pending'},
          ${input.priority || 'medium'},
          ${input.due_date || null},
          ${input.mentioned_at || null},
          ${input.tags || null},
          ${input.notes || null}
        )
        RETURNING *
      `;

      return apiResponse.created(res, item, 'Action item created successfully');
    } catch (error: any) {
      log.error('Error creating action item', { error });
      return apiResponse.internalError(res, error);
    }
  }

  return res.status(405).json({ error: 'Method not allowed' });
}

export default withAuth(handler);

import type { NextApiRequest, NextApiResponse } from 'next';
import { neon } from '@neondatabase/serverless';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth } from '@/lib/auth';
import { ActionItemUpdateInput } from '@/types/action-items.types';
import { log } from '@/lib/logger';

const sql = neon(process.env.DATABASE_URL!);

async function handler(
  req: NextApiRequest,
  res: NextApiResponse
) {
  const { id } = req.query;

  if (!id || typeof id !== 'string') {
    return apiResponse.validationError(res, { id: 'Invalid action item ID' });
  }

  // GET - Fetch single action item
  if (req.method === 'GET') {
    try {
      const item = await sql`
        SELECT
          ai.*,
          m.title as meeting_title,
          m.meeting_date,
          m.transcript_url
        FROM meeting_action_items ai
        LEFT JOIN meetings m ON ai.meeting_id = m.id
        WHERE ai.id = ${id}
      `;

      if (!item || item.length === 0) {
        return apiResponse.notFound(res, 'Action item', id);
      }

      return apiResponse.success(res, item[0]);
    } catch (error: any) {
      log.error('Error fetching action item', { error });
      return apiResponse.internalError(res, error);
    }
  }

  // PATCH - Update action item
  if (req.method === 'PATCH') {
    try {
      const updates: ActionItemUpdateInput = req.body;

      // Build dynamic SET clause
      const setClauses: string[] = ['updated_at = NOW()'];
      const fields: Record<string, any> = {};

      if (updates.description !== undefined) {
        fields.description = updates.description;
      }
      if (updates.assignee_name !== undefined) {
        fields.assignee_name = updates.assignee_name;
      }
      if (updates.assignee_email !== undefined) {
        fields.assignee_email = updates.assignee_email;
      }
      if (updates.status !== undefined) {
        fields.status = updates.status;
        // Auto-set completed_date when status changes to completed
        if (updates.status === 'completed' && !updates.completed_date) {
          fields.completed_date = new Date().toISOString();
        }
      }
      if (updates.priority !== undefined) {
        fields.priority = updates.priority;
      }
      if (updates.due_date !== undefined) {
        fields.due_date = updates.due_date;
      }
      if (updates.completed_date !== undefined) {
        fields.completed_date = updates.completed_date;
      }
      if (updates.tags !== undefined) {
        fields.tags = updates.tags;
      }
      if (updates.notes !== undefined) {
        fields.notes = updates.notes;
      }

      if (Object.keys(fields).length === 0) {
        return apiResponse.validationError(res, { updates: 'No fields to update' });
      }

      // Neon serverless ONLY accepts tagged templates
      // Build conditional update based on what fields are provided
      let result;

      if (fields.status !== undefined) {
        // Most common case - status update
        result = await sql`
          UPDATE meeting_action_items
          SET
            status = ${fields.status},
            completed_date = ${fields.completed_date || null},
            updated_at = NOW()
          WHERE id = ${id}
          RETURNING *
        `;
      } else if (fields.description !== undefined) {
        result = await sql`
          UPDATE meeting_action_items
          SET
            description = ${fields.description},
            updated_at = NOW()
          WHERE id = ${id}
          RETURNING *
        `;
      } else if (fields.assignee_name !== undefined || fields.assignee_email !== undefined) {
        result = await sql`
          UPDATE meeting_action_items
          SET
            assignee_name = ${fields.assignee_name || null},
            assignee_email = ${fields.assignee_email || null},
            updated_at = NOW()
          WHERE id = ${id}
          RETURNING *
        `;
      } else if (fields.priority !== undefined) {
        result = await sql`
          UPDATE meeting_action_items
          SET
            priority = ${fields.priority},
            updated_at = NOW()
          WHERE id = ${id}
          RETURNING *
        `;
      } else if (fields.due_date !== undefined) {
        result = await sql`
          UPDATE meeting_action_items
          SET
            due_date = ${fields.due_date},
            updated_at = NOW()
          WHERE id = ${id}
          RETURNING *
        `;
      } else if (fields.tags !== undefined) {
        result = await sql`
          UPDATE meeting_action_items
          SET
            tags = ${fields.tags},
            updated_at = NOW()
          WHERE id = ${id}
          RETURNING *
        `;
      } else if (fields.notes !== undefined) {
        result = await sql`
          UPDATE meeting_action_items
          SET
            notes = ${fields.notes},
            updated_at = NOW()
          WHERE id = ${id}
          RETURNING *
        `;
      } else {
        // Fallback - just update timestamp
        result = await sql`
          UPDATE meeting_action_items
          SET updated_at = NOW()
          WHERE id = ${id}
          RETURNING *
        `;
      }

      if (!result || result.length === 0) {
        return apiResponse.notFound(res, 'Action item', id);
      }

      return apiResponse.success(res, result[0], 'Action item updated successfully');
    } catch (error: any) {
      log.error('Error updating action item', { error });
      return apiResponse.internalError(res, error);
    }
  }

  // DELETE - Delete action item
  if (req.method === 'DELETE') {
    try {
      const [deleted] = await sql`
        DELETE FROM meeting_action_items
        WHERE id = ${id}
        RETURNING id
      `;

      if (!deleted) {
        return apiResponse.notFound(res, 'Action item', id);
      }

      return apiResponse.success(res, { id: deleted.id }, 'Action item deleted successfully');
    } catch (error: any) {
      log.error('Error deleting action item', { error });
      return apiResponse.internalError(res, error);
    }
  }

  return res.status(405).json({ error: 'Method not allowed' });
}

export default withAuth(handler);

-- Create meeting_action_items table
-- Normalized action items extracted from Fireflies meeting summaries
-- Allows tracking, assignment, status management, and completion

-- Create status enum
CREATE TYPE meeting_action_item_status AS ENUM ('pending', 'in_progress', 'completed', 'cancelled');

-- Create priority enum
CREATE TYPE meeting_action_item_priority AS ENUM ('low', 'medium', 'high', 'urgent');

-- Create meeting_action_items table
CREATE TABLE IF NOT EXISTS meeting_action_items (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  meeting_id INTEGER REFERENCES meetings(id) ON DELETE CASCADE,

  -- Core fields
  description TEXT NOT NULL,
  assignee_name VARCHAR(255), -- Parsed from Fireflies text
  assignee_email VARCHAR(255), -- If available from meeting participants
  status meeting_action_item_status DEFAULT 'pending',
  priority meeting_action_item_priority DEFAULT 'medium',

  -- Timestamps
  due_date TIMESTAMP,
  completed_date TIMESTAMP,
  mentioned_at VARCHAR(10), -- Timestamp from meeting (e.g., "16:17")

  -- Tracking
  created_at TIMESTAMP DEFAULT NOW(),
  updated_at TIMESTAMP DEFAULT NOW(),
  created_by UUID, -- Staff member who created/extracted it
  completed_by UUID, -- Staff member who marked it complete

  -- Metadata
  tags TEXT[], -- Searchable tags
  notes TEXT -- Additional context or updates
);

-- Indexes for performance
CREATE INDEX IF NOT EXISTS idx_meeting_action_items_meeting_id ON meeting_action_items(meeting_id);
CREATE INDEX IF NOT EXISTS idx_meeting_action_items_status ON meeting_action_items(status);
CREATE INDEX IF NOT EXISTS idx_meeting_action_items_assignee_name ON meeting_action_items(assignee_name);
CREATE INDEX IF NOT EXISTS idx_meeting_action_items_assignee_email ON meeting_action_items(assignee_email);
CREATE INDEX IF NOT EXISTS idx_meeting_action_items_due_date ON meeting_action_items(due_date);
CREATE INDEX IF NOT EXISTS idx_meeting_action_items_priority ON meeting_action_items(priority);
CREATE INDEX IF NOT EXISTS idx_meeting_action_items_created_at ON meeting_action_items(created_at DESC);

-- Full text search index on description
CREATE INDEX IF NOT EXISTS idx_meeting_action_items_description_fts ON meeting_action_items USING gin(to_tsvector('english', description));

