/**
 * GET /api/communications/feed
 * Unified feed API — queries messages, email outbox, notifications, and
 * meeting action items in parallel, normalizes to FeedItem[], merges
 * chronologically, and paginates.
 *
 * Query params:
 *   limit    — 1..50 (default 30)
 *   offset   — number (default 0)
 *   channels — comma-separated: message,email,notification,meeting (default: all)
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { neon } from '@neondatabase/serverless';
import { withAuth, type AuthenticatedNextApiRequest } from '@/lib/auth';
import { apiResponse } from '@/lib/apiResponse';
import { log } from '@/lib/logger';
import type { FeedItem } from '@/modules/communications/types/hub.types';

const sql = neon(process.env.DATABASE_URL!);

type Channel = 'message' | 'email' | 'notification' | 'meeting';
const ALL_CHANNELS: Channel[] = ['message', 'email', 'notification', 'meeting'];

// ---------------------------------------------------------------------------
// Channel query helpers
// ---------------------------------------------------------------------------

async function fetchMessages(userId: string): Promise<FeedItem[]> {
  const rows = await sql`
    SELECT
      m.id,
      m.subject,
      m.body,
      m.priority,
      m.context_module,
      m.created_at,
      u.first_name || ' ' || u.last_name AS sender_name,
      r.is_read,
      (
        SELECT COUNT(*)::int FROM internal_messages sub
        WHERE sub.thread_id = m.id
      ) AS reply_count,
      (
        SELECT MAX(sub.created_at) FROM internal_messages sub
        WHERE sub.thread_id = m.id
      ) AS latest_reply_at
    FROM internal_messages m
    JOIN internal_message_recipients r
      ON r.message_id = m.id AND r.recipient_id = ${userId}::uuid
    JOIN users u ON u.id = m.sender_id
    WHERE m.thread_id IS NULL
      AND r.is_archived = FALSE
    ORDER BY COALESCE(
      (SELECT MAX(sub.created_at) FROM internal_messages sub WHERE sub.thread_id = m.id),
      m.created_at
    ) DESC
    LIMIT 50
  `;

  return rows.map((r): FeedItem => ({
    id: r.id,
    channel: 'message',
    title: r.subject || r.sender_name,
    body: r.body ? String(r.body).slice(0, 200) : null,
    timestamp: r.latest_reply_at || r.created_at,
    isRead: !!r.is_read,
    actionUrl: '/communications?tab=inbox',
    sourceModule: r.context_module || 'messaging',
    sourceId: r.id,
    metadata: {
      priority: r.priority,
      reply_count: Number(r.reply_count),
      sender_name: r.sender_name,
    },
  }));
}

async function fetchEmails(userId: string): Promise<FeedItem[]> {
  const rows = await sql`
    SELECT
      e.id,
      e.subject,
      e.recipient_email,
      e.recipient_name,
      e.source_module,
      e.status,
      e.sent_at,
      e.created_at
    FROM email_outbox e
    WHERE e.sender_id = ${userId}::uuid
    ORDER BY e.created_at DESC
    LIMIT 50
  `;

  return rows.map((r): FeedItem => ({
    id: r.id,
    channel: 'email',
    title: r.subject,
    body: r.recipient_name
      ? `To: ${r.recipient_name} <${r.recipient_email}>`
      : `To: ${r.recipient_email}`,
    timestamp: r.sent_at || r.created_at,
    isRead: true, // Sent by user
    actionUrl: null,
    sourceModule: r.source_module || 'email',
    sourceId: r.id,
    metadata: {
      status: r.status,
      recipient_name: r.recipient_name,
      recipient_email: r.recipient_email,
    },
  }));
}

async function fetchNotifications(userId: string): Promise<FeedItem[]> {
  const rows = await sql`
    SELECT
      n.id,
      n.title,
      n.body,
      n.icon,
      n.severity,
      n.event_type,
      n.action_url,
      n.source_module,
      n.source_id,
      n.is_read,
      n.created_at
    FROM user_notifications n
    WHERE n.user_id = ${userId}::uuid
      AND n.event_type != 'messaging.new_message'
    ORDER BY n.created_at DESC
    LIMIT 50
  `;

  return rows.map((r): FeedItem => ({
    id: r.id,
    channel: 'notification',
    title: r.title,
    body: r.body ? String(r.body).slice(0, 200) : null,
    timestamp: r.created_at,
    isRead: !!r.is_read,
    actionUrl: r.action_url || null,
    sourceModule: r.source_module || null,
    sourceId: r.source_id || null,
    metadata: {
      severity: r.severity,
      event_type: r.event_type,
      icon: r.icon,
    },
  }));
}

async function fetchMeetingActions(
  userId: string,
  userEmail: string
): Promise<FeedItem[]> {
  const rows = await sql`
    SELECT
      ai.id,
      ai.description,
      ai.assignee_name,
      ai.status::text AS status,
      ai.priority::text AS priority,
      ai.due_date,
      ai.created_at,
      m.title AS meeting_title
    FROM meeting_action_items ai
    LEFT JOIN meetings m ON ai.meeting_id = m.id
    WHERE (ai.assignee_email = ${userEmail} OR ai.created_by = ${userId}::uuid)
      AND ai.status::text IN ('pending', 'in_progress')
    ORDER BY ai.created_at DESC
    LIMIT 50
  `;

  return rows.map((r): FeedItem => ({
    id: r.id,
    channel: 'meeting',
    title: r.description ? String(r.description).slice(0, 120) : 'Action item',
    body: r.meeting_title
      ? `${r.meeting_title}${r.due_date ? ` — Due: ${new Date(r.due_date).toLocaleDateString('en-ZA')}` : ''}`
      : null,
    timestamp: r.created_at,
    isRead: r.status !== 'pending',
    actionUrl: '/action-items',
    sourceModule: 'meetings',
    sourceId: r.id,
    metadata: {
      priority: r.priority,
      status: r.status,
      due_date: r.due_date,
      assignee: r.assignee_name,
    },
  }));
}

// ---------------------------------------------------------------------------
// Handler
// ---------------------------------------------------------------------------

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'GET') {
    return apiResponse.methodNotAllowed(res, req.method!, ['GET']);
  }

  const authUser = (req as AuthenticatedNextApiRequest).user;
  const userId = authUser.id;
  const userEmail = authUser.email;

  try {
    // Parse params
    const limit = Math.min(
      Math.max(parseInt(String(req.query.limit || '30'), 10) || 30, 1),
      50
    );
    const offset = Math.max(
      parseInt(String(req.query.offset || '0'), 10) || 0,
      0
    );

    const channelsParam = String(req.query.channels || '').trim();
    const requestedChannels: Channel[] = channelsParam
      ? (channelsParam.split(',').filter(c => ALL_CHANNELS.includes(c as Channel)) as Channel[])
      : ALL_CHANNELS;

    if (requestedChannels.length === 0) {
      return apiResponse.success(res, {
        items: [],
        total: 0,
        counts: { message: 0, email: 0, notification: 0, meeting: 0 },
      });
    }

    // Fetch all active channels in parallel
    const fetchers: Record<Channel, () => Promise<FeedItem[]>> = {
      message: () => fetchMessages(userId),
      email: () => fetchEmails(userId),
      notification: () => fetchNotifications(userId),
      meeting: () => fetchMeetingActions(userId, userEmail),
    };

    const results = await Promise.all(
      requestedChannels.map(async (ch) => ({
        channel: ch,
        items: await fetchers[ch](),
      }))
    );

    // Build per-channel counts
    const counts = { message: 0, email: 0, notification: 0, meeting: 0 };
    const allItems: FeedItem[] = [];

    for (const { channel, items } of results) {
      counts[channel] = items.length;
      allItems.push(...items);
    }

    // Sort by timestamp DESC
    allItems.sort(
      (a, b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime()
    );

    const total = allItems.length;
    const paginated = allItems.slice(offset, offset + limit);

    return apiResponse.success(res, {
      items: paginated,
      total,
      counts,
    });
  } catch (error) {
    log.error('Failed to fetch unified feed', { error }, 'CommunicationsFeed');
    return apiResponse.internalError(res, error);
  }
}

export default withAuth(handler);

/**
 * Action Items Types
 * Extracted from Fireflies meeting summaries
 */

export type ActionItemStatus = 'pending' | 'in_progress' | 'completed' | 'cancelled';
export type ActionItemPriority = 'low' | 'medium' | 'high' | 'urgent';

export interface ActionItem {
  id: string;
  meeting_id: number;

  // Core fields
  description: string;
  assignee_name?: string;
  assignee_email?: string;
  status: ActionItemStatus;
  priority: ActionItemPriority;

  // Timestamps
  due_date?: string;
  completed_date?: string;
  mentioned_at?: string; // e.g., "16:17" - timestamp in meeting

  // Tracking
  created_at: string;
  updated_at: string;
  created_by?: string;
  completed_by?: string;

  // Metadata
  tags?: string[];
  notes?: string;

  // Joined data (from meetings table)
  meeting_title?: string;
  meeting_date?: string;
  transcript_url?: string;
}

export interface ActionItemCreateInput {
  meeting_id: number;
  description: string;
  assignee_name?: string;
  assignee_email?: string;
  status?: ActionItemStatus;
  priority?: ActionItemPriority;
  due_date?: string;
  mentioned_at?: string;
  tags?: string[];
  notes?: string;
}

export interface ActionItemUpdateInput {
  description?: string;
  assignee_name?: string;
  assignee_email?: string;
  status?: ActionItemStatus;
  priority?: ActionItemPriority;
  due_date?: string;
  completed_date?: string;
  tags?: string[];
  notes?: string;
}

export interface ActionItemFilters {
  status?: ActionItemStatus | ActionItemStatus[];
  assignee_name?: string;
  meeting_id?: number;
  priority?: ActionItemPriority;
  search?: string;
  overdue?: boolean;
}

export interface ActionItemStats {
  total: number;
  pending: number;
  in_progress: number;
  completed: number;
  overdue: number;
}

// For parsing Fireflies action items text
export interface ParsedActionItem {
  assignee: string;
  description: string;
  mentioned_at?: string;
}

// 🟢 WORKING: Retrieve transcript for a specific meeting (VTT or plain text)
// Access is restricted to meeting participants; hein@velocityfibre.co.za bypasses the check
import type { NextApiRequest, NextApiResponse } from 'next';
import { withAuth, type AuthenticatedNextApiRequest } from '@/lib/auth';
import { apiResponse } from '@/lib/apiResponse';
import { neon } from '@neondatabase/serverless';
import { parseVttSpeakers } from '@/lib/graph/transcripts';

const sql = neon(process.env.DATABASE_URL!);

/** Shape of a meetings row as returned by the participant-filtered query */
interface MeetingTranscriptRow {
  id: number;
  raw_transcript: string | null;
  participants: string | null;
}

/** Shape of a meeting_transcripts fallback row */
interface StoredTranscriptRow {
  content: string;
  format: string;
}

/**
 * GET /api/meetings/[id]/transcript
 *
 * Returns the transcript for a meeting in both raw and structured (speaker-parsed) form.
 *
 * Access control:
 *   - hein@velocityfibre.co.za: unrestricted access
 *   - Other roles: must appear in the meeting's participants JSON array by email
 *
 * Response body:
 *   meetingId  — numeric meeting ID
 *   transcript — raw VTT or plain text string
 *   format     — 'vtt' | 'text'
 *   structured — parsed utterances (non-null only for VTT format)
 */
async function handler(req: NextApiRequest, res: NextApiResponse): Promise<void> {
  if (req.method !== 'GET') {
    return apiResponse.methodNotAllowed(res, req.method!, ['GET']);
  }

  const authReq = req as AuthenticatedNextApiRequest;
  const userEmail = authReq.user?.email?.toLowerCase();
  const isOwner = userEmail === 'hein@velocityfibre.co.za';

  if (!userEmail) {
    return apiResponse.forbidden(res, 'User email is required for transcript access');
  }

  const rawId = req.query.id;
  const meetingId = typeof rawId === 'string' ? Number(rawId) : NaN;

  if (isNaN(meetingId) || meetingId <= 0) {
    return apiResponse.badRequest(res, 'Invalid meeting ID');
  }

  try {
    // Fetch meeting row — owner gets unconditional access, others require participant match
    const rows = isOwner
      ? await sql`
          SELECT id, raw_transcript, participants
          FROM meetings
          WHERE id = ${meetingId}
        `
      : await sql`
          SELECT id, raw_transcript, participants
          FROM meetings
          WHERE id = ${meetingId}
            AND EXISTS (
              SELECT 1
              FROM jsonb_array_elements(participants) AS p
              WHERE LOWER(p->>'email') = ${userEmail}
            )
        `;

    const meeting = rows[0] as MeetingTranscriptRow | undefined;

    if (!meeting) {
      // Return 403 rather than 404 to avoid leaking meeting existence to non-participants
      return apiResponse.forbidden(res, 'Meeting not found or you are not a participant');
    }

    // Resolve transcript: inline column first, then meeting_transcripts fallback
    let transcript: string | null = (meeting.raw_transcript as string | null) ?? null;
    let format = 'text';

    if (!transcript) {
      const fallback = await sql`
        SELECT content, format
        FROM meeting_transcripts
        WHERE meeting_id = ${meetingId}
        ORDER BY created_at DESC
        LIMIT 1
      `;

      const fallbackRow = fallback[0] as StoredTranscriptRow | undefined;
      if (fallbackRow) {
        transcript = fallbackRow.content;
        format = fallbackRow.format ?? 'text';
      }
    }

    if (!transcript) {
      return apiResponse.notFound(res, 'Transcript', meetingId);
    }

    // Parse VTT into structured utterances for client convenience
    const structured = format === 'vtt' ? parseVttSpeakers(transcript) : null;

    return apiResponse.success(res, {
      meetingId,
      transcript,
      format,
      structured,
    });
  } catch (error: unknown) {
    return apiResponse.internalError(res, error);
  }
}

export default withAuth(handler);

import type { NextApiRequest, NextApiResponse } from 'next';
import { neon } from '@neondatabase/serverless';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth, type AuthenticatedNextApiRequest } from '@/lib/auth';
import {
  parseFirefliesActionItems,
  findAssigneeEmail,
} from '@/services/action-items/actionItemsParser';
import { log } from '@/lib/logger';

const sql = neon(process.env.DATABASE_URL!);

/**
 * Extract action items from a meeting's summary
 * POST /api/action-items/extract
 * Body: { meeting_id: number }
 *
 * Access Control: User must be a participant of the meeting (or super_admin)
 */
async function handler(
  req: NextApiRequest,
  res: NextApiResponse
) {
  if (req.method !== 'POST') {
    return res.status(405).json({ error: 'Method not allowed' });
  }

  // Get user info for access control
  const authReq = req as AuthenticatedNextApiRequest;
  const userEmail = authReq.user?.email?.toLowerCase();
  const userRole = authReq.user?.role;
  const isSuperAdmin = userRole === 'super_admin';

  if (!userEmail) {
    return res.status(403).json({ error: 'User email required for meeting access' });
  }

  try {
    const { meeting_id } = req.body;

    if (!meeting_id) {
      return apiResponse.validationError(res, {
        meeting_id: 'Meeting ID is required',
      });
    }

    // Fetch meeting with action items - check participant access
    const [meeting] = isSuperAdmin
      ? await sql`
          SELECT id, summary, participants
          FROM meetings
          WHERE id = ${meeting_id}
        `
      : await sql`
          SELECT id, summary, participants
          FROM meetings
          WHERE id = ${meeting_id}
          AND EXISTS (
            SELECT 1 FROM jsonb_array_elements(participants) AS p
            WHERE LOWER(p->>'email') = ${userEmail}
          )
        `;

    if (!meeting) {
      return res.status(403).json({ error: 'Meeting not found or not authorized to access' });
    }

    // Check if action items exist in summary
    const actionItemsText = meeting.summary?.action_items;
    if (!actionItemsText) {
      return apiResponse.success(res, [], 'No action items found in meeting summary');
    }

    // Parse action items
    const parsedItems = parseFirefliesActionItems(actionItemsText);

    // Check for existing action items from this meeting
    const existing = await sql`
      SELECT COUNT(*)::int as count
      FROM meeting_action_items
      WHERE meeting_id = ${meeting_id}
    `;

    if (existing[0]?.count > 0) {
      return apiResponse.validationError(res, {
        meeting_id: `Action items already extracted for meeting ${meeting_id}`,
      });
    }

    // Insert action items
    const inserted = [];
    for (const item of parsedItems) {
      const assignee_email = findAssigneeEmail(item.assignee, meeting.participants);

      const [created] = await sql`
        INSERT INTO meeting_action_items (
          meeting_id,
          description,
          assignee_name,
          assignee_email,
          mentioned_at,
          status,
          priority
        ) VALUES (
          ${meeting_id},
          ${item.description},
          ${item.assignee},
          ${assignee_email || null},
          ${item.mentioned_at || null},
          'pending',
          'medium'
        )
        RETURNING *
      `;

      inserted.push(created);
    }

    return apiResponse.created(
      res,
      inserted,
      `Extracted ${inserted.length} action items from meeting`
    );
  } catch (error: any) {
    log.error('Error extracting action items', { error });
    return apiResponse.internalError(res, error);
  }
}

export default withAuth(handler);

