 * Types for the unified communications hub (Phase 1+)
 */

/** Tab identifiers for the Communications Hub */
export type CommsTab = 'inbox' | 'email' | 'whatsapp' | 'meetings' | 'notifications' | 'settings';

/** Stats displayed in the hub header */
