/**
 * Action Items Service
 * Frontend service for action items API
 */

import {
  ActionItem,
  ActionItemCreateInput,
  ActionItemUpdateInput,
  ActionItemFilters,
  ActionItemStats,
} from '@/types/action-items.types';

const API_BASE = '/api/action-items';

async function handleResponse<T>(response: Response): Promise<T> {
  if (!response.ok) {
    const error = await response.json().catch(() => ({ message: 'Request failed' }));
    throw new Error(error.message || error.error || `HTTP ${response.status}`);
  }

  const data = await response.json();
  return data.data || data;
}

export const actionItemsService = {
  /**
   * Fetch action items with optional filters
   */
  async getActionItems(filters?: ActionItemFilters): Promise<ActionItem[]> {
    const params = new URLSearchParams();

    if (filters?.status) {
      const statuses = Array.isArray(filters.status)
        ? filters.status.join(',')
        : filters.status;
      params.append('status', statuses);
    }
    if (filters?.assignee_name) params.append('assignee_name', filters.assignee_name);
    if (filters?.meeting_id) params.append('meeting_id', filters.meeting_id.toString());
    if (filters?.priority) params.append('priority', filters.priority);
    if (filters?.search) params.append('search', filters.search);
    if (filters?.overdue) params.append('overdue', 'true');

    const url = params.toString() ? `${API_BASE}?${params}` : API_BASE;
    const response = await fetch(url);
    return handleResponse<ActionItem[]>(response);
  },

  /**
   * Get action item by ID
   */
  async getActionItem(id: string): Promise<ActionItem> {
    const response = await fetch(`${API_BASE}/${id}`);
    return handleResponse<ActionItem>(response);
  },

  /**
   * Create new action item
   */
  async createActionItem(input: ActionItemCreateInput): Promise<ActionItem> {
    const response = await fetch(API_BASE, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(input),
    });
    return handleResponse<ActionItem>(response);
  },

  /**
   * Update action item
   */
  async updateActionItem(id: string, updates: ActionItemUpdateInput): Promise<ActionItem> {
    const response = await fetch(`${API_BASE}/${id}`, {
      method: 'PATCH',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(updates),
    });
    return handleResponse<ActionItem>(response);
  },

  /**
   * Delete action item
   */
  async deleteActionItem(id: string): Promise<void> {
    const response = await fetch(`${API_BASE}/${id}`, {
      method: 'DELETE',
    });
    await handleResponse<void>(response);
  },

  /**
   * Get action items statistics
   */
  async getStats(): Promise<ActionItemStats> {
    const response = await fetch(`${API_BASE}/stats`);
    return handleResponse<ActionItemStats>(response);
  },

  /**
   * Extract action items from a meeting
   */
  async extractFromMeeting(meeting_id: number): Promise<ActionItem[]> {
    const response = await fetch(`${API_BASE}/extract`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ meeting_id }),
    });
    return handleResponse<ActionItem[]>(response);
  },

  /**
   * Mark action item as completed
   */
  async markCompleted(id: string): Promise<ActionItem> {
    return this.updateActionItem(id, {
      status: 'completed',
      completed_date: new Date().toISOString(),
    });
  },

  /**
   * Update action item status
   */
  async updateStatus(id: string, status: ActionItem['status']): Promise<ActionItem> {
    return this.updateActionItem(id, { status });
  },
};

/**
 * Action Items Parser
 * Parses Fireflies action items text format into structured data
 */

import { ParsedActionItem } from '@/types/action-items.types';

/**
 * Parse Fireflies action items text into structured data
 *
 * Format example:
 * **Louis**
 * Update and finalize the Request for Proposal documents (16:17)
 * Confirm acquisition rates and finalize negotiations (11:21)
 *
 * **Hein van Vuuren**
 * Provide detailed cost breakdowns (04:21)
 */
export function parseFirefliesActionItems(actionItemsText: string): ParsedActionItem[] {
  if (!actionItemsText || typeof actionItemsText !== 'string') {
    return [];
  }

  const parsed: ParsedActionItem[] = [];
  const lines = actionItemsText.split('\n').filter(line => line.trim());

  let currentAssignee = 'Unassigned';

  for (const line of lines) {
    const trimmed = line.trim();

    // Check if this is an assignee header (e.g., "**Louis**")
    const assigneeMatch = trimmed.match(/^\*\*(.+?)\*\*$/);
    if (assigneeMatch) {
      currentAssignee = assigneeMatch[1].trim();
      continue;
    }

    // Check if this is an action item
    // Extract timestamp if present (e.g., "(16:17)")
    const timestampMatch = trimmed.match(/\((\d{1,2}:\d{2})\)$/);
    const mentioned_at = timestampMatch ? timestampMatch[1] : undefined;

    // Remove timestamp from description
    const description = timestampMatch
      ? trimmed.substring(0, timestampMatch.index).trim()
      : trimmed;

    // Skip empty lines or lines that are too short
    if (description.length < 10) {
      continue;
    }

    parsed.push({
      assignee: currentAssignee,
      description,
      mentioned_at,
    });
  }

  return parsed;
}

/**
 * Extract assignee email from meeting participants
 */
export function findAssigneeEmail(
  assigneeName: string,
  participants: Array<{ name: string; email: string; displayName?: string }>
): string | undefined {
  if (!participants || !Array.isArray(participants)) {
    return undefined;
  }

  const normalizedName = assigneeName.toLowerCase().trim();

  return participants.find(
    (p) =>
      p.name?.toLowerCase().includes(normalizedName) ||
      p.displayName?.toLowerCase().includes(normalizedName) ||
      normalizedName.includes(p.name?.toLowerCase() || '')
  )?.email;
}

