import { useState } from 'react';
import { CheckCircle, Clock, AlertCircle, Calendar, User, ExternalLink } from 'lucide-react';
import { notificationService } from '@/services/core/NotificationService';
import { ActionItem } from '@/types/action-items.types';
import { actionItemsService } from '@/services/action-items/actionItemsService';
import { log } from '@/lib/logger';

interface ActionItemsListProps {
  items: ActionItem[];
  onItemUpdated?: () => void;
}

export function ActionItemsList({ items, onItemUpdated }: ActionItemsListProps) {
  const [updatingId, setUpdatingId] = useState<string | null>(null);

  const handleToggleComplete = async (item: ActionItem) => {
    setUpdatingId(item.id);
    try {
      const newStatus = item.status === 'completed' ? 'pending' : 'completed';
      await actionItemsService.updateStatus(item.id, newStatus);
      onItemUpdated?.();
    } catch (error) {
      log.error('Error updating action item', { error, itemId: item.id }, 'ActionItemsList');
      notificationService.error('Failed to update action item');
    } finally {
      setUpdatingId(null);
    }
  };

  const getStatusIcon = (status: ActionItem['status']) => {
    switch (status) {
      case 'completed':
        return <CheckCircle className="w-5 h-5 text-green-500" />;
      case 'in_progress':
        return <Clock className="w-5 h-5 text-blue-500" />;
      case 'cancelled':
        return <AlertCircle className="w-5 h-5 text-gray-400" />;
      default:
        return <Clock className="w-5 h-5 text-yellow-500" />;
    }
  };

  const getPriorityBadge = (priority: ActionItem['priority']) => {
    const colors = {
      urgent: 'bg-red-500/20 text-red-400',
      high: 'bg-orange-500/20 text-orange-400',
      medium: 'bg-blue-500/20 text-blue-400',
      low: 'bg-gray-500/20 text-gray-400',
    };

    return (
      <span className={`px-2 py-0.5 text-xs font-medium rounded ${colors[priority]}`}>
        {priority}
      </span>
    );
  };

  if (items.length === 0) {
    return (
      <div className="bg-[var(--ff-bg-secondary)] rounded-lg shadow-sm border border-[var(--ff-border-light)] p-12 text-center">
        <AlertCircle className="w-12 h-12 text-[var(--ff-text-tertiary)] mx-auto mb-4" />
        <p className="text-[var(--ff-text-secondary)] text-lg">No action items found</p>
      </div>
    );
  }

  return (
    <div className="space-y-4">
      {items.map((item) => (
        <div
          key={item.id}
          className={`bg-[var(--ff-bg-secondary)] rounded-lg shadow-sm border border-[var(--ff-border-light)] p-4 hover:shadow-md transition-shadow ${
            item.status === 'completed' ? 'opacity-60' : ''
          }`}
        >
          <div className="flex items-start gap-4">
            {/* Status Icon */}
            <button
              onClick={() => handleToggleComplete(item)}
              disabled={updatingId === item.id}
              className="mt-1 hover:scale-110 transition-transform disabled:opacity-50"
            >
              {getStatusIcon(item.status)}
            </button>

            {/* Content */}
            <div className="flex-1 min-w-0">
              {/* Description */}
              <p
                className={`text-[var(--ff-text-primary)] mb-2 ${
                  item.status === 'completed' ? 'line-through text-[var(--ff-text-secondary)]' : ''
                }`}
              >
                {item.description}
              </p>

              {/* Metadata */}
              <div className="flex flex-wrap items-center gap-4 text-sm text-[var(--ff-text-secondary)]">
                {/* Assignee */}
                {item.assignee_name && (
                  <div className="flex items-center gap-1">
                    <User className="w-4 h-4" />
                    <span>{item.assignee_name}</span>
                  </div>
                )}

                {/* Meeting */}
                {item.meeting_title && (
                  <div className="flex items-center gap-1">
                    <Calendar className="w-4 h-4" />
                    <span className="truncate max-w-xs">{item.meeting_title}</span>
                  </div>
                )}

                {/* Meeting timestamp */}
                {item.mentioned_at && (
                  <span className="text-xs text-[var(--ff-text-secondary)]">@ {item.mentioned_at}</span>
                )}

                {/* Priority */}
                {getPriorityBadge(item.priority)}

                {/* Due date */}
                {item.due_date && (
                  <span
                    className={`text-xs ${
                      new Date(item.due_date) < new Date() && item.status !== 'completed'
                        ? 'text-red-400 font-semibold'
                        : 'text-[var(--ff-text-secondary)]'
                    }`}
                  >
                    Due: {new Date(item.due_date).toISOString().split('T')[0]}
                  </span>
                )}
              </div>

              {/* Notes */}
              {item.notes && (
                <p className="mt-2 text-sm text-[var(--ff-text-secondary)] italic">{item.notes}</p>
              )}

              {/* Tags */}
              {item.tags && item.tags.length > 0 && (
                <div className="mt-2 flex flex-wrap gap-1">
                  {item.tags.map((tag, idx) => (
                    <span
                      key={idx}
                      className="px-2 py-0.5 text-xs bg-[var(--ff-bg-tertiary)] text-[var(--ff-text-secondary)] rounded"
                    >
                      {tag}
                    </span>
                  ))}
                </div>
              )}
            </div>

            {/* Meeting transcript link */}
            {item.transcript_url && (
              <a
                href={item.transcript_url}
                target="_blank"
                rel="noopener noreferrer"
                className="text-blue-400 hover:text-blue-300"
                title="View meeting transcript"
              >
                <ExternalLink className="w-4 h-4" />
              </a>
            )}
          </div>
        </div>
      ))}
    </div>
  );
}

/**
 * Hook for internal messages data fetching
 */

import { useState, useEffect, useCallback, useRef } from 'react';
import { log } from '@/lib/logger';
import type { MessageListItem, MessageView } from '../types/messaging.types';

const PAGE_SIZE = 20;
const UNREAD_POLL_MS = 30_000;

interface UseInternalMessagesReturn {
  messages: MessageListItem[];
  isLoading: boolean;
  hasMore: boolean;
  total: number;
  unreadCount: number;
  refetch: () => Promise<void>;
  loadMore: () => Promise<void>;
  markRead: (messageIds: string[]) => Promise<void>;
  markAllRead: () => Promise<void>;
  archiveMessages: (messageIds: string[]) => Promise<void>;
}

export function useInternalMessages(view: MessageView): UseInternalMessagesReturn {
  const [messages, setMessages] = useState<MessageListItem[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [hasMore, setHasMore] = useState(false);
  const [total, setTotal] = useState(0);
  const [offset, setOffset] = useState(0);
  const [unreadCount, setUnreadCount] = useState(0);
  const pollRef = useRef<ReturnType<typeof setInterval>>();

  const fetchMessages = useCallback(async (reset = false) => {
    setIsLoading(true);
    const currentOffset = reset ? 0 : offset;
    try {
      const params = new URLSearchParams({
        view,
        limit: String(PAGE_SIZE),
        offset: String(currentOffset),
      });

      const res = await fetch(`/api/communications/messages?${params}`, {
        credentials: 'include',
      });
      const json = await res.json();

      if (json.success) {
        const items: MessageListItem[] = json.data.messages;
        if (reset) {
          setMessages(items);
          setOffset(items.length);
        } else {
          setMessages(prev => [...prev, ...items]);
          setOffset(currentOffset + items.length);
        }
        setTotal(json.data.total);
        setHasMore(items.length === PAGE_SIZE);
      }
    } catch (err) {
      log.error('Failed to fetch messages:', err);
    } finally {
      setIsLoading(false);
    }
  }, [offset, view]);

  const fetchUnreadCount = useCallback(async () => {
    try {
      const res = await fetch('/api/communications/messages-unread-count', {
        credentials: 'include',
      });
      const json = await res.json();
      if (json.success) {
        setUnreadCount(json.data.count);
      }
    } catch {
      // Silently ignore polling errors
    }
  }, []);

  const markRead = useCallback(async (messageIds: string[]) => {
    try {
      await fetch('/api/communications/messages-read', {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        credentials: 'include',
        body: JSON.stringify({ messageIds }),
      });
      // Optimistic update
      setMessages(prev =>
        prev.map(m =>
          messageIds.includes(m.id) ? { ...m, is_read: true } : m
        )
      );
      setUnreadCount(prev => Math.max(0, prev - messageIds.length));
    } catch (err) {
      log.error('Failed to mark messages as read:', err);
    }
  }, []);

  const markAllRead = useCallback(async () => {
    const unreadIds = messages.filter(m => !m.is_read).map(m => m.id);
    if (unreadIds.length === 0) return;
    await markRead(unreadIds);
  }, [messages, markRead]);

  const archiveMessages = useCallback(async (messageIds: string[]) => {
    try {
      await fetch('/api/communications/messages-archive', {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        credentials: 'include',
        body: JSON.stringify({ messageIds }),
      });
      // Remove from current list
      setMessages(prev => prev.filter(m => !messageIds.includes(m.id)));
      setTotal(prev => prev - messageIds.length);
    } catch (err) {
      log.error('Failed to archive messages:', err);
    }
  }, []);

  // Fetch messages on mount and when view changes
  useEffect(() => {
    fetchMessages(true);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [view]);

  // Poll unread count
  useEffect(() => {
    fetchUnreadCount();
    pollRef.current = setInterval(fetchUnreadCount, UNREAD_POLL_MS);
    return () => {
      if (pollRef.current) clearInterval(pollRef.current);
    };
  }, [fetchUnreadCount]);

  return {
    messages,
    isLoading,
    hasMore,
    total,
    unreadCount,
    refetch: () => fetchMessages(true),
    loadMore: () => fetchMessages(false),
    markRead,
    markAllRead,
    archiveMessages,
  };
}

