/**
 * Notifications Tab for the Communications Hub
 * Fetches from /api/notifications (real UNS data), supports mark read, filter by module
 */

import { useState, useEffect, useCallback } from 'react';
import { Bell, CheckCheck, RefreshCw, Filter } from 'lucide-react';
import { cn } from '@/lib/utils';
import { log } from '@/lib/logger';
import type { UserNotification } from '@/modules/notifications/types';
import { NotificationItem } from './NotificationItem';

const MODULE_FILTERS = [
  { key: 'all', label: 'All' },
  { key: 'maintenance', label: 'Maintenance' },
  { key: 'procurement', label: 'Procurement' },
  { key: 'qfield', label: 'QField' },
  { key: 'activate', label: 'Activate' },
  { key: 'fleet', label: 'Fleet' },
];

const PAGE_SIZE = 20;

export function NotificationsTab() {
  const [notifications, setNotifications] = useState<UserNotification[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [moduleFilter, setModuleFilter] = useState('all');
  const [unreadOnly, setUnreadOnly] = useState(false);
  const [offset, setOffset] = useState(0);
  const [hasMore, setHasMore] = useState(false);

  const fetchNotifications = useCallback(async (reset = false) => {
    const newOffset = reset ? 0 : offset;
    setIsLoading(true);
    try {
      const params = new URLSearchParams({
        limit: String(PAGE_SIZE),
        offset: String(newOffset),
      });
      if (unreadOnly) params.set('unread_only', 'true');

      const res = await fetch(`/api/notifications?${params}`, {
        credentials: 'include',
      });
      const json = await res.json();

      if (json.success && Array.isArray(json.data)) {
        const items: UserNotification[] = json.data;
        if (reset) {
          setNotifications(items);
          setOffset(items.length);
        } else {
          setNotifications(prev => [...prev, ...items]);
          setOffset(newOffset + items.length);
        }
        setHasMore(items.length === PAGE_SIZE);
      }
    } catch (err) {
      log.error('Failed to fetch notifications:', err);
    } finally {
      setIsLoading(false);
    }
  }, [offset, unreadOnly]);

  // Initial load and when filters change
  useEffect(() => {
    setOffset(0);
    fetchNotifications(true);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [unreadOnly]);

  const handleMarkRead = async (id: string) => {
    try {
      await fetch('/api/notifications/mark-read', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        credentials: 'include',
        body: JSON.stringify({ notification_id: id }),
      });
      setNotifications(prev =>
        prev.map(n => (n.id === id ? { ...n, is_read: true, read_at: new Date().toISOString() } : n))
      );
    } catch (err) {
      log.error('Failed to mark notification as read:', err);
    }
  };

  const handleMarkAllRead = async () => {
    try {
      await fetch('/api/notifications/mark-all-read', {
        method: 'POST',
        credentials: 'include',
      });
      setNotifications(prev =>
        prev.map(n => ({ ...n, is_read: true, read_at: new Date().toISOString() }))
      );
    } catch (err) {
      log.error('Failed to mark all notifications as read:', err);
    }
  };

  // Client-side module filter (API doesn't support module param)
  const filteredNotifications =
    moduleFilter === 'all'
      ? notifications
      : notifications.filter(n => n.source_module === moduleFilter);

  const unreadCount = notifications.filter(n => !n.is_read).length;

  return (
    <div className="space-y-4">
      {/* Toolbar */}
      <div className="flex items-center justify-between flex-wrap gap-3">
        <div className="flex items-center gap-2">
          <Bell className="w-5 h-5 text-[var(--ff-text-secondary)]" />
          <h3 className="text-sm font-medium text-[var(--ff-text-primary)]">
            Notifications
            {unreadCount > 0 && (
              <span className="ml-2 px-2 py-0.5 text-xs bg-blue-500/20 text-blue-400 rounded-full">
                {unreadCount} unread
              </span>
            )}
          </h3>
        </div>

        <div className="flex items-center gap-2">
          {/* Unread toggle */}
          <button
            type="button"
            onClick={() => setUnreadOnly(!unreadOnly)}
            className={cn(
              'flex items-center gap-1.5 px-3 py-1.5 text-xs font-medium rounded-lg border transition-colors',
              unreadOnly
                ? 'bg-blue-500/10 text-blue-400 border-blue-500/30'
                : 'text-[var(--ff-text-secondary)] border-[var(--ff-border-light)] hover:bg-[var(--ff-bg-tertiary)]'
            )}
          >
            <Filter className="w-3.5 h-3.5" />
            Unread only
          </button>

          {/* Mark all read */}
          {unreadCount > 0 && (
            <button
              type="button"
              onClick={handleMarkAllRead}
              className="flex items-center gap-1.5 px-3 py-1.5 text-xs font-medium text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)] border border-[var(--ff-border-light)] rounded-lg hover:bg-[var(--ff-bg-tertiary)] transition-colors"
            >
              <CheckCheck className="w-3.5 h-3.5" />
              Mark all read
            </button>
          )}

          {/* Refresh */}
          <button
            type="button"
            onClick={() => fetchNotifications(true)}
            disabled={isLoading}
            className="flex items-center gap-1.5 px-3 py-1.5 text-xs font-medium text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)] border border-[var(--ff-border-light)] rounded-lg hover:bg-[var(--ff-bg-tertiary)] transition-colors disabled:opacity-50"
          >
            <RefreshCw className={cn('w-3.5 h-3.5', isLoading && 'animate-spin')} />
          </button>
        </div>
      </div>

      {/* Module filter chips */}
      <div className="flex items-center gap-1.5 flex-wrap">
        {MODULE_FILTERS.map(f => (
          <button
            key={f.key}
            type="button"
            onClick={() => setModuleFilter(f.key)}
            className={cn(
              'px-3 py-1 text-xs font-medium rounded-full border transition-colors',
              moduleFilter === f.key
                ? 'bg-[var(--ff-primary)] text-white border-[var(--ff-primary)]'
                : 'text-[var(--ff-text-secondary)] border-[var(--ff-border-light)] hover:bg-[var(--ff-bg-tertiary)]'
            )}
          >
            {f.label}
          </button>
        ))}
      </div>

      {/* Notification list */}
      {isLoading && notifications.length === 0 ? (
        <div className="flex items-center justify-center py-12">
          <RefreshCw className="w-5 h-5 animate-spin text-[var(--ff-text-tertiary)]" />
          <span className="ml-2 text-sm text-[var(--ff-text-secondary)]">Loading notifications...</span>
        </div>
      ) : filteredNotifications.length === 0 ? (
        <div className="text-center py-12">
          <Bell className="w-10 h-10 mx-auto text-[var(--ff-text-tertiary)] mb-3" />
          <p className="text-sm text-[var(--ff-text-secondary)]">
            {unreadOnly && moduleFilter !== 'all'
              ? `No unread ${moduleFilter} notifications`
              : unreadOnly
                ? 'No unread notifications'
                : moduleFilter !== 'all'
                  ? `No ${moduleFilter} notifications`
                  : 'No notifications yet'}
          </p>
          <p className="text-xs text-[var(--ff-text-tertiary)] mt-1">
            {moduleFilter !== 'all'
              ? `Notifications from the ${moduleFilter} module will appear here.`
              : 'Notifications from maintenance, procurement, and other modules will appear here.'}
          </p>
        </div>
      ) : (
        <div className="space-y-2">
          {filteredNotifications.map(notification => (
            <NotificationItem
              key={notification.id}
              notification={notification}
              onMarkRead={handleMarkRead}
            />
          ))}

          {/* Load more */}
          {hasMore && (
            <div className="flex justify-center pt-4">
              <button
                type="button"
                onClick={() => fetchNotifications(false)}
                disabled={isLoading}
                className="px-4 py-2 text-sm font-medium text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)] border border-[var(--ff-border-light)] rounded-lg hover:bg-[var(--ff-bg-tertiary)] transition-colors disabled:opacity-50"
              >
                {isLoading ? 'Loading...' : 'Load more'}
              </button>
            </div>
          )}
        </div>
      )}
    </div>
  );
}

/**
 * Unified Feed List — channel filter chips + chronological feed items + pagination
 */

import { useState, useCallback } from 'react';
import { useRouter } from 'next/router';
import {
  RefreshCw,
  Rss,
  MessageSquare,
  Mail,
  Bell,
  CheckSquare,
} from 'lucide-react';
import { cn } from '@/lib/utils';
import { useUnifiedFeed } from '../hooks/useUnifiedFeed';
import { FeedItemRow } from './FeedItemRow';
import type { FeedItem } from '../types/hub.types';

type Channel = 'message' | 'email' | 'notification' | 'meeting';

const CHANNEL_FILTERS: {
  key: Channel | 'all';
  label: string;
  icon: React.ElementType;
}[] = [
  { key: 'all', label: 'All', icon: Rss },
  { key: 'message', label: 'Messages', icon: MessageSquare },
  { key: 'email', label: 'Email', icon: Mail },
  { key: 'notification', label: 'Notifications', icon: Bell },
  { key: 'meeting', label: 'Action Items', icon: CheckSquare },
];

interface UnifiedFeedListProps {
  onOpenThread: (messageId: string) => void;
}

export function UnifiedFeedList({ onOpenThread }: UnifiedFeedListProps) {
  const router = useRouter();
  const [activeFilter, setActiveFilter] = useState<Channel | 'all'>('all');

  const channels = activeFilter === 'all' ? undefined : [activeFilter];
  const { items, isLoading, hasMore, total, counts, refetch, loadMore } =
    useUnifiedFeed(channels);

  const handleItemClick = useCallback(
    (item: FeedItem) => {
      switch (item.channel) {
        case 'message':
          // Open thread within InboxPanel
          if (item.sourceId) {
            onOpenThread(item.sourceId);
          }
          break;
        case 'notification':
          if (item.actionUrl) {
            router.push(item.actionUrl);
          }
          break;
        case 'meeting':
          if (item.actionUrl) {
            router.push(item.actionUrl);
          }
          break;
        case 'email':
          // Switch to email tab
          router.push('/communications?tab=email', undefined, { shallow: true });
          break;
        default:
          break;
      }
    },
    [onOpenThread, router]
  );

  const getCount = (key: Channel | 'all'): number => {
    if (key === 'all') {
      return counts.message + counts.email + counts.notification + counts.meeting;
    }
    return counts[key] || 0;
  };

  return (
    <div className="space-y-4">
      {/* Filter chips + refresh */}
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-1 flex-wrap">
          {CHANNEL_FILTERS.map(f => {
            const Icon = f.icon;
            const isActive = activeFilter === f.key;
            const count = getCount(f.key);
            return (
              <button
                key={f.key}
                type="button"
                onClick={() => setActiveFilter(f.key)}
                className={cn(
                  'flex items-center gap-1.5 px-3 py-1.5 text-xs font-medium rounded-lg transition-colors',
                  isActive
                    ? 'bg-[var(--ff-primary)]/10 text-[var(--ff-primary)]'
                    : 'text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)] hover:bg-[var(--ff-bg-tertiary)]'
                )}
              >
                <Icon className="w-3.5 h-3.5" />
                {f.label}
                {count > 0 && (
                  <span className={cn(
                    'px-1.5 py-0.5 text-[10px] font-semibold rounded-full',
                    isActive
                      ? 'bg-[var(--ff-primary)]/20 text-[var(--ff-primary)]'
                      : 'bg-[var(--ff-bg-tertiary)] text-[var(--ff-text-tertiary)]'
                  )}>
                    {count}
                  </span>
                )}
              </button>
            );
          })}
        </div>

        <button
          type="button"
          onClick={() => refetch()}
          disabled={isLoading}
          className="flex items-center gap-1.5 px-3 py-1.5 text-xs font-medium text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)] border border-[var(--ff-border-light)] rounded-lg hover:bg-[var(--ff-bg-tertiary)] transition-colors disabled:opacity-50"
        >
          <RefreshCw className={cn('w-3.5 h-3.5', isLoading && 'animate-spin')} />
        </button>
      </div>

      {/* Count summary */}
      <p className="text-xs text-[var(--ff-text-tertiary)]">
        {total > 0 ? `${total} item${total !== 1 ? 's' : ''}` : ''}
      </p>

      {/* Feed items */}
      {isLoading && items.length === 0 ? (
        <div className="flex items-center justify-center py-12">
          <RefreshCw className="w-5 h-5 animate-spin text-[var(--ff-text-tertiary)]" />
          <span className="ml-2 text-sm text-[var(--ff-text-secondary)]">
            Loading feed...
          </span>
        </div>
      ) : items.length === 0 ? (
        <div className="text-center py-12">
          <Rss className="w-10 h-10 mx-auto text-[var(--ff-text-tertiary)] mb-3" />
          <p className="text-sm text-[var(--ff-text-secondary)]">
            {activeFilter === 'all'
              ? 'No activity yet'
              : `No ${CHANNEL_FILTERS.find(f => f.key === activeFilter)?.label.toLowerCase() || 'items'} found`}
          </p>
        </div>
      ) : (
        <div className="border border-[var(--ff-border-light)] rounded-lg overflow-hidden">
          {items.map(item => (
            <FeedItemRow key={`${item.channel}-${item.id}`} item={item} onClick={handleItemClick} />
          ))}

          {hasMore && (
            <div className="flex justify-center py-3 border-t border-[var(--ff-border-light)]">
              <button
                type="button"
                onClick={loadMore}
                disabled={isLoading}
                className="px-4 py-1.5 text-sm font-medium text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)] border border-[var(--ff-border-light)] rounded-lg hover:bg-[var(--ff-bg-tertiary)] transition-colors disabled:opacity-50"
              >
                {isLoading ? 'Loading...' : 'Load more'}
              </button>
            </div>
          )}
        </div>
      )}
    </div>
  );
}

/**
 * Meeting Transcript Processor
 *
 * Orchestrates the full LLM-powered meeting analysis pipeline:
 *   1. Load raw transcript from `meetings.raw_transcript` (or `meeting_transcripts` fallback).
 *   2. Chunk the transcript to respect Claude's context window.
 *   3. Call Claude Sonnet for each chunk and merge the structured results.
 *   4. Persist the summary back to `meetings.summary` and upsert action items.
 *
