function FiscalPeriodsTab() {
  const [periods, setPeriods] = useState<FiscalPeriod[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [actionLoading, setActionLoading] = useState<string | null>(null);

  useEffect(() => {
    loadPeriods();
  }, []);

  const loadPeriods = async () => {
    setIsLoading(true);
    try {
      const res = await fetch('/api/accounting/fiscal-periods');
      const data = await res.json();
      setPeriods(data.data || data || []);
    } catch (err) {
      log.error('Failed to load fiscal periods', { error: err }, 'accounting-ui');
    } finally {
      setIsLoading(false);
    }
  };

  const handlePeriodAction = async (periodId: string, action: 'close' | 'lock' | 'reopen') => {
    setActionLoading(periodId);
    try {
      const res = await fetch('/api/accounting/fiscal-periods-action', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        credentials: 'include',
        body: JSON.stringify({ id: periodId, action }),
      });
      if (!res.ok) {
        const err = await res.json();
        throw new Error(err.message || 'Action failed');
      }
      await loadPeriods();
    } catch (err) {
      log.error('Fiscal period action failed', { error: err, periodId, action }, 'accounting-ui');
    } finally {
      setActionLoading(null);
    }
  };

  const statusIcon = (status: string) => {
    switch (status) {
      case 'open': return <CheckCircle2 className="h-4 w-4 text-emerald-500" />;
      case 'closing': return <Clock className="h-4 w-4 text-amber-500" />;
      case 'closed': return <Lock className="h-4 w-4 text-blue-500" />;
      case 'locked': return <Lock className="h-4 w-4 text-red-500" />;
      default: return null;
    }
  };

  const statusColor = (status: string) => {
    switch (status) {
      case 'open': return 'bg-emerald-500/20 text-emerald-400';
      case 'closing': return 'bg-amber-500/20 text-amber-400';
      case 'closed': return 'bg-blue-500/20 text-blue-400';
      case 'locked': return 'bg-red-500/20 text-red-400';
      default: return 'bg-gray-500/20 text-gray-400';
    }
  };

  return (
    <div className="space-y-4">
      <div className="bg-[var(--ff-bg-secondary)] rounded-lg border border-[var(--ff-border-light)] overflow-hidden">
        {isLoading ? (
          <div className="p-8 text-center">
            <Loader2 className="h-6 w-6 animate-spin text-[var(--ff-text-tertiary)] mx-auto" />
          </div>
        ) : (
          <div className="overflow-x-auto">
            <table className="w-full">
              <thead>
                <tr className="bg-[var(--ff-bg-tertiary)] border-b border-[var(--ff-border-light)]">
                  <th className="px-6 py-3 text-left text-xs font-semibold uppercase tracking-wider text-[var(--ff-text-secondary)]">Period</th>
                  <th className="px-6 py-3 text-left text-xs font-semibold uppercase tracking-wider text-[var(--ff-text-secondary)]">Year</th>
                  <th className="px-6 py-3 text-left text-xs font-semibold uppercase tracking-wider text-[var(--ff-text-secondary)]">Start Date</th>
                  <th className="px-6 py-3 text-left text-xs font-semibold uppercase tracking-wider text-[var(--ff-text-secondary)]">End Date</th>
                  <th className="px-6 py-3 text-left text-xs font-semibold uppercase tracking-wider text-[var(--ff-text-secondary)]">Status</th>
                  <th className="px-6 py-3 text-right text-xs font-semibold uppercase tracking-wider text-[var(--ff-text-secondary)]">Actions</th>
                </tr>
              </thead>
              <tbody>
                {periods.map(period => (
                  <tr key={period.id} className="border-b border-[var(--ff-border-light)] hover:bg-[var(--ff-bg-tertiary)] transition-colors">
                    <td className="px-6 py-3 text-sm font-medium text-[var(--ff-text-primary)]">{period.periodName}</td>
                    <td className="px-6 py-3 text-sm text-[var(--ff-text-secondary)]">{period.fiscalYear}</td>
                    <td className="px-6 py-3 text-sm text-[var(--ff-text-primary)]">{new Date(period.startDate).toLocaleDateString()}</td>
                    <td className="px-6 py-3 text-sm text-[var(--ff-text-primary)]">{new Date(period.endDate).toLocaleDateString()}</td>
                    <td className="px-6 py-3">
                      <span className={`inline-flex items-center gap-1.5 px-2 py-0.5 rounded text-xs font-medium uppercase ${statusColor(period.status)}`}>
                        {statusIcon(period.status)}
                        {period.status}
                      </span>
                    </td>
                    <td className="px-6 py-3 text-right">
                      <div className="flex items-center justify-end gap-2">
                        {period.status === 'open' && (
                          <button
                            onClick={() => handlePeriodAction(period.id, 'close')}
                            disabled={actionLoading === period.id}
                            className="px-3 py-1 text-xs font-medium rounded bg-blue-500/20 text-blue-400 hover:bg-blue-500/30 transition-colors disabled:opacity-50"
                          >
                            {actionLoading === period.id ? 'Closing...' : 'Close'}
                          </button>
                        )}
                        {period.status === 'closed' && (
                          <>
                            <button
                              onClick={() => handlePeriodAction(period.id, 'lock')}
                              disabled={actionLoading === period.id}
                              className="px-3 py-1 text-xs font-medium rounded bg-red-500/20 text-red-400 hover:bg-red-500/30 transition-colors disabled:opacity-50"
                            >
                              Lock
                            </button>
                            <button
                              onClick={() => handlePeriodAction(period.id, 'reopen')}
                              disabled={actionLoading === period.id}
                              className="px-3 py-1 text-xs font-medium rounded bg-emerald-500/20 text-emerald-400 hover:bg-emerald-500/30 transition-colors disabled:opacity-50"
                            >
                              Reopen
                            </button>
                          </>
                        )}
                        {period.status === 'locked' && (
                          <span className="text-xs text-[var(--ff-text-tertiary)]">Locked</span>
                        )}
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </div>
    </div>
  );
}

// =====================================================
// Reports Tab
// =====================================================

function ReportsTab() {
  const [periods, setPeriods] = useState<FiscalPeriod[]>([]);
  const [selectedPeriod, setSelectedPeriod] = useState<string>('');
  const [trialBalance, setTrialBalance] = useState<TrialBalanceRow[]>([]);
  const [totals, setTotals] = useState({ debit: 0, credit: 0 });
  const [isLoading, setIsLoading] = useState(false);

  useEffect(() => {
    loadPeriods();
  }, []);

  const loadPeriods = async () => {
    try {
      const res = await fetch('/api/accounting/fiscal-periods');
      const data = await res.json();
      const list = data.data || data || [];
      setPeriods(list);
      const current = list.find((p: FiscalPeriod) => p.status === 'open');
      if (current) setSelectedPeriod(current.id);
    } catch (err) {
      log.error('Failed to load periods for reports', { error: err }, 'accounting-ui');
    }
  };

  const loadTrialBalance = async () => {
    if (!selectedPeriod) return;
    setIsLoading(true);
    try {
      const res = await fetch(`/api/accounting/reports-trial-balance?fiscal_period_id=${selectedPeriod}`);
      const data = await res.json();
      const payload = data.data || data;
      setTrialBalance(payload.rows || []);
      setTotals({ debit: payload.totalDebit || 0, credit: payload.totalCredit || 0 });
    } catch (err) {
      log.error('Failed to load trial balance', { error: err }, 'accounting-ui');
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    if (selectedPeriod) loadTrialBalance();
  }, [selectedPeriod]);

  const formatCurrency = (amount: number) =>
    amount === 0 ? '-' : `R ${Number(amount).toLocaleString('en-ZA', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;

  return (
    <div className="space-y-6">
      {/* Report Navigation */}
      <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
        <Link href="/accounting/reports/income-statement" className="p-4 rounded-lg bg-[var(--ff-bg-secondary)] border border-[var(--ff-border-light)] hover:border-emerald-500/50 transition-all no-underline">
          <p className="font-medium text-sm text-[var(--ff-text-primary)]">Income Statement</p>
          <p className="text-xs text-[var(--ff-text-tertiary)]">Profit & Loss</p>
        </Link>
        <Link href="/accounting/reports/balance-sheet" className="p-4 rounded-lg bg-[var(--ff-bg-secondary)] border border-[var(--ff-border-light)] hover:border-blue-500/50 transition-all no-underline">
          <p className="font-medium text-sm text-[var(--ff-text-primary)]">Balance Sheet</p>
          <p className="text-xs text-[var(--ff-text-tertiary)]">Assets = L + E</p>
        </Link>
        <Link href="/accounting/reports/vat-return" className="p-4 rounded-lg bg-[var(--ff-bg-secondary)] border border-[var(--ff-border-light)] hover:border-amber-500/50 transition-all no-underline">
          <p className="font-medium text-sm text-[var(--ff-text-primary)]">VAT Return</p>
          <p className="text-xs text-[var(--ff-text-tertiary)]">Input / Output VAT</p>
        </Link>
        <Link href="/accounting/reports/project-profitability" className="p-4 rounded-lg bg-[var(--ff-bg-secondary)] border border-[var(--ff-border-light)] hover:border-purple-500/50 transition-all no-underline">
          <p className="font-medium text-sm text-[var(--ff-text-primary)]">Project Profitability</p>
          <p className="text-xs text-[var(--ff-text-tertiary)]">Revenue vs costs</p>
        </Link>
      </div>

      {/* Period Selector */}
      <div className="flex items-center gap-4">
        <label className="text-sm font-medium text-[var(--ff-text-primary)]">Fiscal Period:</label>
        <select
          value={selectedPeriod}
          onChange={e => setSelectedPeriod(e.target.value)}
          className="ff-select text-sm py-2 px-3 min-w-[200px]"
        >
          <option value="">Select period...</option>
          {periods.map(p => (
            <option key={p.id} value={p.id}>{p.periodName} ({p.fiscalYear})</option>
          ))}
        </select>
      </div>

      {/* Trial Balance */}
      <div className="bg-[var(--ff-bg-secondary)] rounded-lg border border-[var(--ff-border-light)] overflow-hidden">
        <div className="px-6 py-4 border-b border-[var(--ff-border-light)]">
          <h3 className="text-lg font-semibold text-[var(--ff-text-primary)]">Trial Balance</h3>
        </div>

        {!selectedPeriod ? (
          <div className="p-8 text-center">
            <BarChart3 className="h-8 w-8 text-[var(--ff-text-tertiary)] mx-auto mb-2" />
            <p className="text-[var(--ff-text-secondary)]">Select a fiscal period to view the trial balance</p>
          </div>
        ) : isLoading ? (
          <div className="p-8 text-center">
            <Loader2 className="h-6 w-6 animate-spin text-[var(--ff-text-tertiary)] mx-auto" />
          </div>
        ) : trialBalance.length === 0 ? (
          <div className="p-8 text-center">
            <BarChart3 className="h-8 w-8 text-[var(--ff-text-tertiary)] mx-auto mb-2" />
            <p className="text-[var(--ff-text-secondary)]">No balances found for this period</p>
          </div>
        ) : (
          <div className="overflow-x-auto">
            <table className="w-full">
              <thead>
                <tr className="bg-[var(--ff-bg-tertiary)] border-b border-[var(--ff-border-light)]">
                  <th className="px-6 py-3 text-left text-xs font-semibold uppercase tracking-wider text-[var(--ff-text-secondary)]">Code</th>
                  <th className="px-6 py-3 text-left text-xs font-semibold uppercase tracking-wider text-[var(--ff-text-secondary)]">Account</th>
                  <th className="px-6 py-3 text-left text-xs font-semibold uppercase tracking-wider text-[var(--ff-text-secondary)]">Type</th>
                  <th className="px-6 py-3 text-right text-xs font-semibold uppercase tracking-wider text-[var(--ff-text-secondary)]">Debit</th>
                  <th className="px-6 py-3 text-right text-xs font-semibold uppercase tracking-wider text-[var(--ff-text-secondary)]">Credit</th>
                </tr>
              </thead>
              <tbody>
                {trialBalance.map(row => (
                  <tr key={row.accountCode} className="border-b border-[var(--ff-border-light)] hover:bg-[var(--ff-bg-tertiary)] transition-colors">
                    <td className="px-6 py-3 text-sm font-mono text-[var(--ff-text-primary)]">{row.accountCode}</td>
                    <td className="px-6 py-3 text-sm text-[var(--ff-text-primary)]">{row.accountName}</td>
                    <td className="px-6 py-3 text-sm text-[var(--ff-text-secondary)] capitalize">{row.accountType}</td>
                    <td className="px-6 py-3 text-sm text-right font-medium text-[var(--ff-text-primary)]">
                      {formatCurrency(row.debitBalance)}
                    </td>
                    <td className="px-6 py-3 text-sm text-right font-medium text-[var(--ff-text-primary)]">
                      {formatCurrency(row.creditBalance)}
                    </td>
                  </tr>
                ))}
              </tbody>
              <tfoot>
                <tr className="bg-[var(--ff-bg-tertiary)] border-t-2 border-[var(--ff-border-medium)]">
                  <td colSpan={3} className="px-6 py-3 text-sm font-semibold text-[var(--ff-text-primary)]">Total</td>
                  <td className="px-6 py-3 text-sm text-right font-bold text-[var(--ff-text-primary)]">{formatCurrency(totals.debit)}</td>
                  <td className="px-6 py-3 text-sm text-right font-bold text-[var(--ff-text-primary)]">{formatCurrency(totals.credit)}</td>
                </tr>
                {totals.debit !== totals.credit && (
                  <tr className="bg-red-500/10">
                    <td colSpan={3} className="px-6 py-2 text-xs font-medium text-red-400 flex items-center gap-1">
                      <AlertCircle className="h-3 w-3" />
                      Out of balance
                    </td>
                    <td colSpan={2} className="px-6 py-2 text-xs text-right text-red-400">
                      Difference: {formatCurrency(Math.abs(totals.debit - totals.credit))}
                    </td>
                  </tr>
                )}
              </tfoot>
            </table>
          </div>
        )}
      </div>
    </div>
  );
}

// =====================================================
// Shared Components
// =====================================================

function StatusBadge({ status }: { status: string }) {
  const colors: Record<string, string> = {
    draft: 'bg-amber-500/20 text-amber-400',
    posted: 'bg-emerald-500/20 text-emerald-400',
    reversed: 'bg-red-500/20 text-red-400',
    voided: 'bg-gray-500/20 text-gray-400',
  };

  return (
    <span className={`inline-flex items-center px-2 py-0.5 rounded text-xs font-medium uppercase ${colors[status] || colors.draft}`}>
      {status}
    </span>
  );
}

file.content:
'use client';

/**
 * Communications Hub - Unified communications center
 * 6 tabs: Inbox, Email, WhatsApp, Meetings, Notifications, Settings
 * Replaces the old CommunicationsDashboard with a consolidated hub
 */

import React, { useState, useEffect } from 'react';
import { useRouter } from 'next/router';
import {
  Inbox,
  Mail,
  MessageCircle,
  Users,
  Bell,
  Settings,
  RefreshCw,
  Film,
  Plus,
  Construction,
} from 'lucide-react';
import Link from 'next/link';
import { cn } from '@/lib/utils';
import { log } from '@/lib/logger';
import { useCommunications } from '@/hooks/useCommunications';
import type { CommsTab } from './types/hub.types';
import { CommunicationsStatsCards, CommunicationsMeetingsTab } from './components';
import { NotificationsTab } from './notifications/NotificationsTab';
import { EmailTab } from './email/EmailTab';
import { InboxPanel } from './messaging/InboxPanel';

const TABS: { key: CommsTab; label: string; icon: React.ElementType }[] = [
  { key: 'inbox', label: 'Inbox', icon: Inbox },
  { key: 'email', label: 'Email', icon: Mail },
  { key: 'whatsapp', label: 'WhatsApp', icon: MessageCircle },
  { key: 'meetings', label: 'Meetings', icon: Users },
  { key: 'notifications', label: 'Notifications', icon: Bell },
  { key: 'settings', label: 'Settings', icon: Settings },
];

function ComingSoonCard({ title, description }: { title: string; description: string }) {
  return (
    <div className="text-center py-16">
      <Construction className="w-12 h-12 mx-auto text-[var(--ff-text-tertiary)] mb-4" />
      <h3 className="text-lg font-medium text-[var(--ff-text-primary)] mb-2">{title}</h3>
      <p className="text-sm text-[var(--ff-text-secondary)] max-w-md mx-auto">{description}</p>
      <span className="inline-block mt-4 px-3 py-1 text-xs font-medium bg-amber-500/10 text-amber-400 rounded-full">
        Coming Soon
      </span>
    </div>
  );
}

export default function CommunicationsHub() {
  const router = useRouter();
  const [activeTab, setActiveTab] = useState<CommsTab>('meetings');
  const [isRefreshing, setIsRefreshing] = useState(false);
  const [isSyncing, setIsSyncing] = useState(false);
  const [isSyncingTeams, setIsSyncingTeams] = useState(false);
  const [syncMessage, setSyncMessage] = useState<string | null>(null);
  const [lastRefresh, setLastRefresh] = useState<Date | null>(null);
  const { data, stats, isLoading, getStatusColor, refetch } = useCommunications();

  // Sync active tab with URL param
  useEffect(() => {
    const tabParam = router.query.tab as string | undefined;
    if (tabParam) {
      const valid = TABS.find(t => t.key === tabParam);
      if (valid) setActiveTab(valid.key);
    }
  }, [router.query.tab]);

  const handleTabChange = (tab: CommsTab) => {
    setActiveTab(tab);
    router.push(`/communications?tab=${tab}`, undefined, { shallow: true });
  };

  const handleRefresh = async () => {
    setIsRefreshing(true);
    try {
      if (refetch) await refetch();
      setLastRefresh(new Date());
    } finally {
      setIsRefreshing(false);
    }
  };

  const handleFirefliesSync = async () => {
    setIsSyncing(true);
    setSyncMessage(null);
    try {
      const response = await fetch('/api/meetings?action=sync', { method: 'POST' });
      const result = await response.json();
      if (result.success) {
        setSyncMessage(`Synced ${result.synced} meetings from Fireflies`);
        await handleRefresh();
      } else {
        setSyncMessage(`Sync failed: ${result.error}`);
      }
    } catch (error) {
      const message = error instanceof Error ? error.message : 'Unknown error';
      setSyncMessage(`Sync failed: ${message}`);
      log.error('Fireflies sync failed:', error);
    } finally {
      setIsSyncing(false);
      setTimeout(() => setSyncMessage(null), 5000);
    }
  };

  const handleTeamsSync = async () => {
    setIsSyncingTeams(true);
    setSyncMessage(null);
    try {
      const response = await fetch('/api/meetings/sync-teams', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ hours: 48 }),
      });
      if (response.ok) {
        setSyncMessage('Teams sync started (processing in background)');
        setTimeout(() => handleRefresh(), 5000);
      } else {
        const result = await response.json();
        setSyncMessage(`Teams sync failed: ${result.error?.message || 'Unknown error'}`);
      }
    } catch (error) {
      const message = error instanceof Error ? error.message : 'Unknown error';
      setSyncMessage(`Teams sync failed: ${message}`);
      log.error('Teams sync failed:', error);
    } finally {
      setIsSyncingTeams(false);
      setTimeout(() => setSyncMessage(null), 8000);
    }
  };

  const showMeetingActions = activeTab === 'meetings';

  return (
    <div className="p-6 space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold text-[var(--ff-text-primary)]">Communications Hub</h1>
          <p className="text-sm text-[var(--ff-text-secondary)] mt-1">
            {lastRefresh
              ? `Last updated ${lastRefresh.toLocaleTimeString()}`
              : 'Unified messaging, meetings, and notifications'}
          </p>
        </div>

        <div className="flex flex-col items-end gap-2">
          <div className="flex items-center gap-2">
            {/* Meetings-specific actions */}
            {showMeetingActions && (
              <>
                <Link
                  href="/recordings"
                  className="flex items-center gap-2 px-4 py-2 text-sm font-medium text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)] bg-[var(--ff-bg-secondary)] hover:bg-[var(--ff-bg-tertiary)] border border-[var(--ff-border-light)] rounded-lg transition-colors"
                >
                  <Film className="w-4 h-4" />
                  Recordings
                </Link>

                <button
                  type="button"
                  onClick={handleTeamsSync}
                  disabled={isSyncingTeams}
                  className={cn(
                    'flex items-center gap-2 px-4 py-2 text-sm font-medium rounded-lg transition-colors',
                    isSyncingTeams
                      ? 'bg-[var(--ff-bg-tertiary)] text-[var(--ff-text-tertiary)] cursor-not-allowed'
                      : 'bg-purple-600 text-white hover:bg-purple-700'
                  )}
                >
                  <RefreshCw className={cn('w-4 h-4', isSyncingTeams && 'animate-spin')} />
                  {isSyncingTeams ? 'Syncing...' : 'Sync Teams'}
                </button>

                <button
                  type="button"
                  onClick={handleFirefliesSync}
                  disabled={isSyncing}
                  className={cn(
                    'flex items-center gap-2 px-4 py-2 text-sm font-medium rounded-lg transition-colors',
                    isSyncing
                      ? 'bg-[var(--ff-bg-tertiary)] text-[var(--ff-text-tertiary)] cursor-not-allowed'
                      : 'bg-blue-600 text-white hover:bg-blue-700'
                  )}
                >
                  <RefreshCw className={cn('w-4 h-4', isSyncing && 'animate-spin')} />
                  {isSyncing ? 'Syncing...' : 'Sync Fireflies'}
                </button>

                <button
                  type="button"
                  onClick={() => {}}
                  className="flex items-center gap-2 px-4 py-2 text-sm font-medium text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)] bg-[var(--ff-bg-secondary)] hover:bg-[var(--ff-bg-tertiary)] border border-[var(--ff-border-light)] rounded-lg transition-colors"
                >
                  <Plus className="w-4 h-4" />
                  Add Action Item
                </button>
              </>
            )}

            {/* Refresh button (always visible) */}
            <button
              type="button"
              onClick={handleRefresh}
              disabled={isRefreshing}
              className="flex items-center gap-2 px-4 py-2 text-sm font-medium text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)] bg-[var(--ff-bg-secondary)] hover:bg-[var(--ff-bg-tertiary)] border border-[var(--ff-border-light)] rounded-lg transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
              aria-label="Refresh"
            >
              <RefreshCw className={cn('w-4 h-4', isRefreshing && 'animate-spin')} />
            </button>
          </div>

          {syncMessage && (
            <p className={cn(
              'text-sm',
              syncMessage.includes('failed') ? 'text-red-600' : 'text-green-600'
            )}>
              {syncMessage}
            </p>
          )}
        </div>
      </div>

      {/* Stats Cards (meetings data) */}
      {showMeetingActions && <CommunicationsStatsCards stats={stats} />}

      {/* Tab Navigation */}
      <div className="bg-[var(--ff-bg-secondary)] border border-[var(--ff-border-light)] rounded-lg">
        <div className="border-b border-[var(--ff-border-light)]">
          <nav role="tablist" className="flex gap-1 px-4 -mb-px overflow-x-auto" aria-label="Communications tabs">
            {TABS.map(tab => {
              const Icon = tab.icon;
              const isActive = activeTab === tab.key;
              return (
                <button
                  key={tab.key}
                  role="tab"
                  aria-selected={isActive}
                  aria-controls={`comms-panel-${tab.key}`}
                  onClick={() => handleTabChange(tab.key)}
                  className={cn(
                    'flex items-center gap-2 py-3 px-4 border-b-2 font-medium text-sm transition-colors whitespace-nowrap',
                    'focus:outline-none focus:ring-2 focus:ring-inset focus:ring-[var(--ff-accent)]',
                    isActive
                      ? 'border-[var(--ff-primary)] text-[var(--ff-primary)]'
                      : 'border-transparent text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)] hover:border-[var(--ff-border-light)]'
                  )}
                >
                  <Icon className="w-4 h-4" />
                  {tab.label}
                  {tab.key === 'meetings' && data.meetings.length > 0 && (
                    <span className="px-2 py-0.5 text-xs bg-blue-500/20 text-blue-400 rounded-full">
                      {data.meetings.length}
                    </span>
                  )}
                </button>
              );
            })}
          </nav>
        </div>

        {/* Tab Panels */}
        <div className="p-6">
          {/* Inbox */}
          <div
            id="comms-panel-inbox"
            role="tabpanel"
            hidden={activeTab !== 'inbox'}
          >
            {activeTab === 'inbox' && <InboxPanel />}
          </div>

          {/* Email */}
          <div
            id="comms-panel-email"
            role="tabpanel"
            hidden={activeTab !== 'email'}
          >
            {activeTab === 'email' && <EmailTab />}
          </div>

          {/* WhatsApp */}
          <div
            id="comms-panel-whatsapp"
            role="tabpanel"
            hidden={activeTab !== 'whatsapp'}
          >
            {activeTab === 'whatsapp' && (
              <div className="text-center py-8">
                <MessageCircle className="w-12 h-12 mx-auto text-green-500 mb-4" />
                <h3 className="text-lg font-medium text-[var(--ff-text-primary)] mb-2">WhatsApp Portal</h3>
                <p className="text-sm text-[var(--ff-text-secondary)] max-w-md mx-auto mb-4">
                  Manage WhatsApp groups, view messages, and monitor service status.
                </p>
                <Link
                  href="/communications/whatsapp"
                  className="inline-flex items-center gap-2 px-4 py-2 bg-green-500 text-white rounded-lg hover:bg-green-600 transition-colors"
                >
                  <MessageCircle className="w-4 h-4" />
                  Open WhatsApp Portal
                </Link>
              </div>
            )}
          </div>

          {/* Meetings - Working */}
          <div
            id="comms-panel-meetings"
            role="tabpanel"
            hidden={activeTab !== 'meetings'}
          >
            {activeTab === 'meetings' && (
              isLoading ? (
                <div className="flex items-center justify-center py-12">
                  <RefreshCw className="w-6 h-6 animate-spin text-[var(--ff-text-tertiary)]" />
                  <span className="ml-2 text-[var(--ff-text-secondary)]">Loading meetings...</span>
                </div>
              ) : (
                <CommunicationsMeetingsTab
                  meetings={data.meetings}
                  getStatusColor={getStatusColor}
                  onRefresh={handleRefresh}
                />
              )
            )}
          </div>

          {/* Notifications - Working */}
          <div
            id="comms-panel-notifications"
            role="tabpanel"
            hidden={activeTab !== 'notifications'}
          >
            {activeTab === 'notifications' && <NotificationsTab />}
          </div>

          {/* Settings */}
          <div
            id="comms-panel-settings"
            role="tabpanel"
            hidden={activeTab !== 'settings'}
          >
            {activeTab === 'settings' && (
              <ComingSoonCard
                title="Communication Preferences"
                description="Configure notification preferences per event type — choose between in-app, email, and WhatsApp delivery for each module."
              />
            )}
          </div>
        </div>
      </div>
    </div>
  );
}

'use client';

/**
 * Communications Meetings Tab
 *
 * Integrates the full Meetings module functionality:
 * - MeetingsList component (card-based with agenda/keywords)
 * - MeetingDetailModal for viewing details
 * - Sub-tab filters (all/upcoming/past/cancelled)
 */

import { useState } from 'react';
import { Calendar } from 'lucide-react';
import type { Meeting } from '@/modules/meetings/types/meeting.types';
import { MeetingsList } from '@/modules/meetings/components/MeetingsList';
import { MeetingDetailModal } from '@/modules/meetings/components/MeetingDetailModal';

interface CommunicationsMeetingsTabProps {
  meetings: Meeting[];
  getStatusColor: (status: string) => string;
  onRefresh?: () => Promise<void>;
}

type MeetingFilter = 'all' | 'upcoming' | 'past' | 'cancelled';
type SourceFilter = 'all' | 'teams' | 'fireflies';

export function CommunicationsMeetingsTab({
  meetings,
  getStatusColor,
  onRefresh
}: CommunicationsMeetingsTabProps) {
  const [activeFilter, setActiveFilter] = useState<MeetingFilter>('all');
  const [sourceFilter, setSourceFilter] = useState<SourceFilter>('all');
  const [selectedMeeting, setSelectedMeeting] = useState<Meeting | null>(null);
  const [showDetailModal, setShowDetailModal] = useState(false);

  // Filter meetings based on source + status filters
  const filteredMeetings = meetings.filter(meeting => {
    // Source filter
    if (sourceFilter !== 'all' && meeting.source !== sourceFilter) return false;

    // Status filter
    switch (activeFilter) {
      case 'upcoming':
        return meeting.status === 'scheduled';
      case 'past':
        return meeting.status === 'completed';
      case 'cancelled':
        return meeting.status === 'cancelled';
      default:
        return true;
    }
  });

  // Handle meeting click to show detail modal
  const handleEditMeeting = (meeting: Meeting) => {
    setSelectedMeeting(meeting);
    setShowDetailModal(true);
  };

  // Handle delete (no-op for now since Fireflies meetings are read-only)
  const handleDeleteMeeting = (meetingId: string) => {
    // Future: implement delete functionality
  };

  // Source-filtered meetings for accurate counts
  const sourceMeetings = sourceFilter === 'all'
    ? meetings
    : meetings.filter(m => m.source === sourceFilter);

  const filters: { key: MeetingFilter; label: string; count: number }[] = [
    { key: 'all', label: 'All', count: sourceMeetings.length },
    { key: 'upcoming', label: 'Upcoming', count: sourceMeetings.filter(m => m.status === 'scheduled').length },
    { key: 'past', label: 'Past', count: sourceMeetings.filter(m => m.status === 'completed').length },
    { key: 'cancelled', label: 'Cancelled', count: sourceMeetings.filter(m => m.status === 'cancelled').length },
  ];

  const sourceFilters: { key: SourceFilter; label: string; color: string }[] = [
    { key: 'all', label: 'All Sources', color: 'bg-blue-600 text-white' },
    { key: 'teams', label: 'Teams', color: 'bg-purple-600 text-white' },
    { key: 'fireflies', label: 'Fireflies', color: 'bg-orange-600 text-white' },
  ];

  if (meetings.length === 0) {
    return (
      <div className="text-center py-12">
        <Calendar className="w-12 h-12 mx-auto mb-4 text-[var(--ff-text-tertiary)]" />
        <h3 className="text-lg font-medium text-[var(--ff-text-primary)] mb-2">No meetings yet</h3>
        <p className="text-[var(--ff-text-secondary)]">
          Click &quot;Sync Fireflies&quot; to import your recorded meetings, or schedule a new meeting.
        </p>
      </div>
    );
  }

  return (
    <div className="space-y-4">
      {/* Source filter */}
      <div className="flex items-center gap-2">
        {sourceFilters.map(sf => (
          <button
            key={sf.key}
            onClick={() => setSourceFilter(sf.key)}
            className={`px-3 py-1.5 text-sm font-medium rounded-lg transition-colors ${
              sourceFilter === sf.key
                ? sf.color
                : 'bg-[var(--ff-bg-tertiary)] text-[var(--ff-text-secondary)] hover:bg-[var(--ff-bg-hover)]'
            }`}
          >
            {sf.label}
          </button>
        ))}
      </div>

      {/* Status filters */}
      <div className="flex items-center gap-2">
        {filters.map(filter => (
          <button
            key={filter.key}
            onClick={() => setActiveFilter(filter.key)}
            className={`px-3 py-1.5 text-sm font-medium rounded-lg transition-colors ${
              activeFilter === filter.key
                ? 'bg-[var(--ff-primary)] text-white'
                : 'bg-[var(--ff-bg-tertiary)] text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)] hover:bg-[var(--ff-bg-hover)]'
            }`}
          >
            {filter.label}
            {filter.count > 0 && (
              <span className={`ml-1.5 px-1.5 py-0.5 text-xs rounded-full ${
                activeFilter === filter.key
                  ? 'bg-card/20 text-white'
                  : 'bg-[var(--ff-bg-secondary)] text-[var(--ff-text-tertiary)]'
              }`}>
                {filter.count}
              </span>
            )}
          </button>
        ))}
      </div>

      {/* Meeting List */}
      {filteredMeetings.length === 0 ? (
        <div className="text-center py-8">
          <p className="text-[var(--ff-text-secondary)]">
            No {activeFilter === 'all' ? '' : activeFilter} meetings found.
          </p>
        </div>
      ) : (
        <MeetingsList
          meetings={filteredMeetings}
          onEditMeeting={handleEditMeeting}
          onDeleteMeeting={handleDeleteMeeting}
        />
      )}

      {/* Meeting Detail Modal */}
      <MeetingDetailModal
        meeting={selectedMeeting}
        isOpen={showDetailModal}
        onClose={() => {
          setShowDetailModal(false);
          setSelectedMeeting(null);
        }}
      />
    </div>
  );
}

