                <span className={`text-xs font-medium ${matchCount > 0 ? 'text-emerald-400' : 'text-[var(--ff-text-tertiary)]'}`}>
                  Would match <strong>{matchCount}</strong> transaction{matchCount !== 1 ? 's' : ''}
                </span>
