import { MessageCircle, AlertTriangle, Clock } from 'lucide-react';
import { cn } from '@/lib/utils';
import type { MessageListItem as MessageListItemType } from '../types/messaging.types';

interface MessageListItemProps {
  message: MessageListItemType;
  onClick: (id: string) => void;
  showSender?: boolean;
}

function formatRelative(iso: string): string {
  const now = Date.now();
  const then = new Date(iso).getTime();
  const diffMs = now - then;
  const diffMin = Math.floor(diffMs / 60_000);
  if (diffMin < 1) return 'just now';
  if (diffMin < 60) return `${diffMin}m ago`;
  const diffHrs = Math.floor(diffMin / 60);
  if (diffHrs < 24) return `${diffHrs}h ago`;
  const diffDays = Math.floor(diffHrs / 24);
  if (diffDays < 7) return `${diffDays}d ago`;
  return new Date(iso).toLocaleDateString('en-ZA', { day: '2-digit', month: 'short' });
}

export function MessageListItem({ message, onClick, showSender = true }: MessageListItemProps) {
  const isUnread = !message.is_read;
  const isUrgent = message.priority === 'urgent';
  const isHigh = message.priority === 'high';

  return (
    <button
      type="button"
      onClick={() => onClick(message.id)}
      className={cn(
        'w-full text-left px-4 py-3 border-b border-[var(--ff-border-light)] hover:bg-[var(--ff-bg-tertiary)] transition-colors',
        isUnread && 'bg-blue-500/5'
      )}
    >
      <div className="flex items-start gap-3">
        {/* Unread dot */}
        <div className="pt-1.5 w-2 flex-shrink-0">
          {isUnread && (
            <div className="w-2 h-2 rounded-full bg-blue-500" />
          )}
        </div>

        {/* Sender initial */}
        <div className="w-8 h-8 rounded-full bg-[var(--ff-bg-tertiary)] flex items-center justify-center flex-shrink-0">
          <span className="text-xs font-semibold text-[var(--ff-text-secondary)]">
            {message.sender_name?.charAt(0)?.toUpperCase() || '?'}
          </span>
        </div>

        {/* Content */}
        <div className="flex-1 min-w-0">
          <div className="flex items-center gap-2">
            {showSender && (
              <span className={cn(
                'text-sm truncate',
                isUnread
                  ? 'font-semibold text-[var(--ff-text-primary)]'
                  : 'font-medium text-[var(--ff-text-secondary)]'
              )}>
                {message.sender_name}
              </span>
            )}

            {/* Priority badge */}
            {isUrgent && (
              <span className="inline-flex items-center gap-0.5 px-1.5 py-0.5 text-[10px] font-semibold bg-red-500/15 text-red-400 rounded">
                <AlertTriangle className="w-2.5 h-2.5" />
                Urgent
              </span>
            )}
            {isHigh && (
              <span className="px-1.5 py-0.5 text-[10px] font-semibold bg-orange-500/15 text-orange-400 rounded">
                High
              </span>
            )}

            <span className="ml-auto text-xs text-[var(--ff-text-tertiary)] whitespace-nowrap flex-shrink-0">
              {formatRelative(message.latest_reply_at || message.created_at)}
            </span>
          </div>

          {/* Subject */}
          {message.subject && (
            <p className={cn(
              'text-sm truncate mt-0.5',
              isUnread ? 'text-[var(--ff-text-primary)]' : 'text-[var(--ff-text-secondary)]'
            )}>
              {message.subject}
            </p>
          )}

          {/* Body preview */}
          <p className="text-xs text-[var(--ff-text-tertiary)] truncate mt-0.5">
            {message.body}
          </p>

          {/* Meta row */}
          <div className="flex items-center gap-3 mt-1">
            {message.reply_count > 0 && (
              <span className="inline-flex items-center gap-1 text-[10px] text-[var(--ff-text-tertiary)]">
                <MessageCircle className="w-3 h-3" />
                {message.reply_count} {message.reply_count === 1 ? 'reply' : 'replies'}
              </span>
            )}
            {message.recipient_count > 1 && (
              <span className="text-[10px] text-[var(--ff-text-tertiary)]">
                {message.recipient_count} recipients
              </span>
            )}
            {message.context_module && (
              <span className="px-1.5 py-0.5 text-[10px] font-medium bg-[var(--ff-bg-tertiary)] text-[var(--ff-text-tertiary)] rounded capitalize">
                {message.context_module}
              </span>
            )}
          </div>
        </div>
      </div>
    </button>
  );
}

/**
 * Hook for internal messages data fetching
 */

import { useState, useEffect, useCallback, useRef } from 'react';
import { log } from '@/lib/logger';
import type { MessageListItem, MessageView } from '../types/messaging.types';

const PAGE_SIZE = 20;
const UNREAD_POLL_MS = 30_000;

interface UseInternalMessagesReturn {
  messages: MessageListItem[];
  isLoading: boolean;
  hasMore: boolean;
  total: number;
  unreadCount: number;
  refetch: () => Promise<void>;
  loadMore: () => Promise<void>;
  markRead: (messageIds: string[]) => Promise<void>;
  markAllRead: () => Promise<void>;
  archiveMessages: (messageIds: string[]) => Promise<void>;
}

export function useInternalMessages(view: MessageView): UseInternalMessagesReturn {
  const [messages, setMessages] = useState<MessageListItem[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [hasMore, setHasMore] = useState(false);
  const [total, setTotal] = useState(0);
  const [offset, setOffset] = useState(0);
  const [unreadCount, setUnreadCount] = useState(0);
  const pollRef = useRef<ReturnType<typeof setInterval>>();

  const fetchMessages = useCallback(async (reset = false) => {
    setIsLoading(true);
    const currentOffset = reset ? 0 : offset;
    try {
      const params = new URLSearchParams({
        view,
        limit: String(PAGE_SIZE),
        offset: String(currentOffset),
      });

      const res = await fetch(`/api/communications/messages?${params}`, {
        credentials: 'include',
      });
      const json = await res.json();

      if (json.success) {
        const items: MessageListItem[] = json.data.messages;
        if (reset) {
          setMessages(items);
          setOffset(items.length);
        } else {
          setMessages(prev => [...prev, ...items]);
          setOffset(currentOffset + items.length);
        }
        setTotal(json.data.total);
        setHasMore(items.length === PAGE_SIZE);
      }
    } catch (err) {
      log.error('Failed to fetch messages:', err);
    } finally {
      setIsLoading(false);
    }
  }, [offset, view]);

  const fetchUnreadCount = useCallback(async () => {
    try {
      const res = await fetch('/api/communications/messages-unread-count', {
        credentials: 'include',
      });
      const json = await res.json();
      if (json.success) {
        setUnreadCount(json.data.count);
      }
    } catch {
      // Silently ignore polling errors
    }
  }, []);

  const markRead = useCallback(async (messageIds: string[]) => {
    try {
      await fetch('/api/communications/messages-read', {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        credentials: 'include',
        body: JSON.stringify({ messageIds }),
      });
      // Optimistic update
      setMessages(prev =>
        prev.map(m =>
          messageIds.includes(m.id) ? { ...m, is_read: true } : m
        )
      );
      setUnreadCount(prev => Math.max(0, prev - messageIds.length));
    } catch (err) {
      log.error('Failed to mark messages as read:', err);
    }
  }, []);

  const markAllRead = useCallback(async () => {
    const unreadIds = messages.filter(m => !m.is_read).map(m => m.id);
    if (unreadIds.length === 0) return;
    await markRead(unreadIds);
  }, [messages, markRead]);

  const archiveMessages = useCallback(async (messageIds: string[]) => {
    try {
      await fetch('/api/communications/messages-archive', {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        credentials: 'include',
        body: JSON.stringify({ messageIds }),
      });
      // Remove from current list
      setMessages(prev => prev.filter(m => !messageIds.includes(m.id)));
      setTotal(prev => prev - messageIds.length);
    } catch (err) {
      log.error('Failed to archive messages:', err);
    }
  }, []);

  // Fetch messages on mount and when view changes
  useEffect(() => {
    fetchMessages(true);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [view]);

  // Poll unread count
  useEffect(() => {
    fetchUnreadCount();
    pollRef.current = setInterval(fetchUnreadCount, UNREAD_POLL_MS);
    return () => {
      if (pollRef.current) clearInterval(pollRef.current);
    };
  }, [fetchUnreadCount]);

  return {
    messages,
    isLoading,
    hasMore,
    total,
    unreadCount,
    refetch: () => fetchMessages(true),
    loadMore: () => fetchMessages(false),
    markRead,
    markAllRead,
    archiveMessages,
  };
}

'use client';

/**
 * Communications Meetings Tab
 *
 * Integrates the full Meetings module functionality:
 * - MeetingsList component (card-based with agenda/keywords)
 * - MeetingDetailModal for viewing details
 * - Sub-tab filters (all/upcoming/past/cancelled)
 */

import { useState } from 'react';
import { Calendar } from 'lucide-react';
import type { Meeting } from '@/modules/meetings/types/meeting.types';
import { MeetingsList } from '@/modules/meetings/components/MeetingsList';
import { MeetingDetailModal } from '@/modules/meetings/components/MeetingDetailModal';

interface CommunicationsMeetingsTabProps {
  meetings: Meeting[];
  getStatusColor: (status: string) => string;
  onRefresh?: () => Promise<void>;
}

type MeetingFilter = 'all' | 'upcoming' | 'past' | 'cancelled';
type SourceFilter = 'all' | 'teams' | 'fireflies';

export function CommunicationsMeetingsTab({
  meetings,
  getStatusColor,
  onRefresh
}: CommunicationsMeetingsTabProps) {
  const [activeFilter, setActiveFilter] = useState<MeetingFilter>('all');
  const [sourceFilter, setSourceFilter] = useState<SourceFilter>('all');
  const [selectedMeeting, setSelectedMeeting] = useState<Meeting | null>(null);
  const [showDetailModal, setShowDetailModal] = useState(false);

  // Filter meetings based on source + status filters
  const filteredMeetings = meetings.filter(meeting => {
    // Source filter
    if (sourceFilter !== 'all' && meeting.source !== sourceFilter) return false;

    // Status filter
    switch (activeFilter) {
      case 'upcoming':
        return meeting.status === 'scheduled';
      case 'past':
        return meeting.status === 'completed';
      case 'cancelled':
        return meeting.status === 'cancelled';
      default:
        return true;
    }
  });

  // Handle meeting click to show detail modal
  const handleEditMeeting = (meeting: Meeting) => {
    setSelectedMeeting(meeting);
    setShowDetailModal(true);
  };

  // Handle delete (no-op for now since Fireflies meetings are read-only)
  const handleDeleteMeeting = (meetingId: string) => {
    // Future: implement delete functionality
  };

  // Source-filtered meetings for accurate counts
  const sourceMeetings = sourceFilter === 'all'
    ? meetings
    : meetings.filter(m => m.source === sourceFilter);

  const filters: { key: MeetingFilter; label: string; count: number }[] = [
    { key: 'all', label: 'All', count: sourceMeetings.length },
    { key: 'upcoming', label: 'Upcoming', count: sourceMeetings.filter(m => m.status === 'scheduled').length },
    { key: 'past', label: 'Past', count: sourceMeetings.filter(m => m.status === 'completed').length },
    { key: 'cancelled', label: 'Cancelled', count: sourceMeetings.filter(m => m.status === 'cancelled').length },
  ];

  const sourceFilters: { key: SourceFilter; label: string; color: string }[] = [
    { key: 'all', label: 'All Sources', color: 'bg-blue-600 text-white' },
    { key: 'teams', label: 'Teams', color: 'bg-purple-600 text-white' },
    { key: 'fireflies', label: 'Fireflies', color: 'bg-orange-600 text-white' },
  ];

  if (meetings.length === 0) {
    return (
      <div className="text-center py-12">
        <Calendar className="w-12 h-12 mx-auto mb-4 text-[var(--ff-text-tertiary)]" />
        <h3 className="text-lg font-medium text-[var(--ff-text-primary)] mb-2">No meetings yet</h3>
        <p className="text-[var(--ff-text-secondary)]">
          Click &quot;Sync Fireflies&quot; to import your recorded meetings, or schedule a new meeting.
        </p>
      </div>
    );
  }

  return (
    <div className="space-y-4">
      {/* Source filter */}
      <div className="flex items-center gap-2">
        {sourceFilters.map(sf => (
          <button
            key={sf.key}
            onClick={() => setSourceFilter(sf.key)}
            className={`px-3 py-1.5 text-sm font-medium rounded-lg transition-colors ${
              sourceFilter === sf.key
                ? sf.color
                : 'bg-[var(--ff-bg-tertiary)] text-[var(--ff-text-secondary)] hover:bg-[var(--ff-bg-hover)]'
            }`}
          >
            {sf.label}
          </button>
        ))}
      </div>

      {/* Status filters */}
      <div className="flex items-center gap-2">
        {filters.map(filter => (
          <button
            key={filter.key}
            onClick={() => setActiveFilter(filter.key)}
            className={`px-3 py-1.5 text-sm font-medium rounded-lg transition-colors ${
              activeFilter === filter.key
                ? 'bg-[var(--ff-primary)] text-white'
                : 'bg-[var(--ff-bg-tertiary)] text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)] hover:bg-[var(--ff-bg-hover)]'
            }`}
          >
            {filter.label}
            {filter.count > 0 && (
              <span className={`ml-1.5 px-1.5 py-0.5 text-xs rounded-full ${
                activeFilter === filter.key
                  ? 'bg-card/20 text-white'
                  : 'bg-[var(--ff-bg-secondary)] text-[var(--ff-text-tertiary)]'
              }`}>
                {filter.count}
              </span>
            )}
          </button>
        ))}
      </div>

      {/* Meeting List */}
      {filteredMeetings.length === 0 ? (
        <div className="text-center py-8">
          <p className="text-[var(--ff-text-secondary)]">
            No {activeFilter === 'all' ? '' : activeFilter} meetings found.
          </p>
        </div>
      ) : (
        <MeetingsList
          meetings={filteredMeetings}
          onEditMeeting={handleEditMeeting}
          onDeleteMeeting={handleDeleteMeeting}
        />
      )}

      {/* Meeting Detail Modal */}
      <MeetingDetailModal
        meeting={selectedMeeting}
        isOpen={showDetailModal}
        onClose={() => {
          setShowDetailModal(false);
          setSelectedMeeting(null);
        }}
      />
    </div>
  );
}

import type { NextApiRequest, NextApiResponse } from 'next';
import { withAuth, type AuthenticatedNextApiRequest } from '@/lib/auth';
import { neon } from '@neondatabase/serverless';
import { syncFirefliesToNeon } from '@/services/fireflies/firefliesService';
import { log } from '@/lib/logger';

const sql = neon(process.env.DATABASE_URL!);

async function handler(
  req: NextApiRequest,
  res: NextApiResponse
) {
  // Get user info for access control
  const authReq = req as AuthenticatedNextApiRequest;
  const userEmail = authReq.user?.email?.toLowerCase();
  const userName = authReq.user?.name?.toLowerCase() || '';
  const isOwner = userEmail === 'hein@velocityfibre.co.za';

  if (!userEmail) {
    return res.status(403).json({ error: 'User email required for meeting access' });
  }

  if (req.method === 'GET') {
    try {
      // Check if requesting a specific meeting by ID
      const { id, source } = req.query;

      if (id) {
        // Super admin can access any meeting, others need to be participants
        const [meeting] = isOwner
          ? await sql`
              SELECT
                id, fireflies_id, title, meeting_date as date, duration,
                transcript_url, summary, participants, created_at, updated_at,
                source, processing_status, organizer_name, organizer_email, join_url,
                (raw_transcript IS NOT NULL OR transcript_url IS NOT NULL OR EXISTS (SELECT 1 FROM meeting_transcripts mt WHERE mt.meeting_id = meetings.id)) as has_transcript,
                (recording_path IS NOT NULL) as has_recording
              FROM meetings
              WHERE id = ${id}
            `
          : await sql`
              SELECT
                id, fireflies_id, title, meeting_date as date, duration,
                transcript_url, summary, participants, created_at, updated_at,
                source, processing_status, organizer_name, organizer_email, join_url,
                (raw_transcript IS NOT NULL OR transcript_url IS NOT NULL OR EXISTS (SELECT 1 FROM meeting_transcripts mt WHERE mt.meeting_id = meetings.id)) as has_transcript,
                (recording_path IS NOT NULL) as has_recording
              FROM meetings
              WHERE id = ${id}
              AND EXISTS (
                SELECT 1 FROM jsonb_array_elements(participants) AS p
                WHERE LOWER(p->>'email') = ${userEmail}
                   OR LOWER(p->>'name') = ${userName}
                   OR LOWER(p->>'displayName') = ${userName}
              )
            `;

        if (!meeting) {
          return res.status(403).json({ error: 'Not authorized to view this meeting' });
        }

        return res.status(200).json({ meeting });
      }

      // Source filter: ?source=teams|fireflies|all (default: all)
      const sourceFilter = typeof source === 'string' && source !== 'all' ? source : null;

      // Super admin sees all meetings, others only see meetings they participated in
      if (sourceFilter) {
        const meetings = isOwner
          ? await sql`
              SELECT
                id, fireflies_id, title, meeting_date as date, duration,
                transcript_url, summary, participants, created_at, updated_at,
                source, processing_status, organizer_name, organizer_email,
                (raw_transcript IS NOT NULL OR transcript_url IS NOT NULL OR EXISTS (SELECT 1 FROM meeting_transcripts mt WHERE mt.meeting_id = meetings.id)) as has_transcript,
                (recording_path IS NOT NULL) as has_recording
              FROM meetings
              WHERE source = ${sourceFilter}
              ORDER BY meeting_date DESC
              LIMIT 50
            `
          : await sql`
              SELECT
                id, fireflies_id, title, meeting_date as date, duration,
                transcript_url, summary, participants, created_at, updated_at,
                source, processing_status, organizer_name, organizer_email,
                (raw_transcript IS NOT NULL OR transcript_url IS NOT NULL OR EXISTS (SELECT 1 FROM meeting_transcripts mt WHERE mt.meeting_id = meetings.id)) as has_transcript,
                (recording_path IS NOT NULL) as has_recording
              FROM meetings
              WHERE source = ${sourceFilter}
              AND EXISTS (
                SELECT 1 FROM jsonb_array_elements(participants) AS p
                WHERE LOWER(p->>'email') = ${userEmail}
                   OR LOWER(p->>'name') = ${userName}
                   OR LOWER(p->>'displayName') = ${userName}
              )
              ORDER BY meeting_date DESC
              LIMIT 50
            `;

        return res.status(200).json({ meetings });
      }

      const meetings = isOwner
        ? await sql`
            SELECT
              id, fireflies_id, title, meeting_date as date, duration,
              transcript_url, summary, participants, created_at, updated_at,
              source, processing_status, organizer_name, organizer_email,
              (raw_transcript IS NOT NULL OR transcript_url IS NOT NULL OR EXISTS (SELECT 1 FROM meeting_transcripts mt WHERE mt.meeting_id = meetings.id)) as has_transcript,
              (recording_path IS NOT NULL) as has_recording
            FROM meetings
            ORDER BY meeting_date DESC
            LIMIT 50
          `
        : await sql`
            SELECT
              id, fireflies_id, title, meeting_date as date, duration,
              transcript_url, summary, participants, created_at, updated_at,
              source, processing_status, organizer_name, organizer_email,
              (raw_transcript IS NOT NULL OR transcript_url IS NOT NULL OR EXISTS (SELECT 1 FROM meeting_transcripts mt WHERE mt.meeting_id = meetings.id)) as has_transcript,
              (recording_path IS NOT NULL) as has_recording
            FROM meetings
            WHERE EXISTS (
              SELECT 1 FROM jsonb_array_elements(participants) AS p
              WHERE LOWER(p->>'email') = ${userEmail}
                 OR LOWER(p->>'name') = ${userName}
                 OR LOWER(p->>'displayName') = ${userName}
            )
            ORDER BY meeting_date DESC
            LIMIT 50
          `;

      return res.status(200).json({ meetings });
    } catch (error: unknown) {
      const errorMessage = error instanceof Error ? error.message : 'Unknown error';
      log.error('Error fetching meetings:', { error: errorMessage, userEmail });
      return res.status(500).json({ error: errorMessage });
    }
  }

  if (req.method === 'POST' && req.query.action === 'sync') {
    try {
      const apiKey = process.env.FIREFLIES_API_KEY;

      if (!apiKey) {
        return res.status(500).json({ error: 'FIREFLIES_API_KEY not configured' });
      }

      const count = await syncFirefliesToNeon(apiKey, sql);

      return res.status(200).json({
        success: true,
        synced: count,
        message: `Synced ${count} meetings from Fireflies`
      });
    } catch (error: unknown) {
      const errorMessage = error instanceof Error ? error.message : 'Unknown error';
      log.error('Error syncing from Fireflies:', { error: errorMessage });
      return res.status(500).json({ error: errorMessage });
    }
  }

  return res.status(405).json({ error: 'Method not allowed' });
}

export default withAuth(handler);

/**
 * Internal Messages API
 * GET  - List inbox/sent/archived messages (paginated)
 * POST - Send a new message
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { neon } from '@neondatabase/serverless';
import { withAuth, type AuthenticatedNextApiRequest } from '@/lib/auth';
import { apiResponse } from '@/lib/apiResponse';
import { log } from '@/lib/logger';
import { notify } from '@/modules/notifications/services/notificationBus';

const sql = neon(process.env.DATABASE_URL!);

async function handler(req: NextApiRequest, res: NextApiResponse) {
  const authUser = (req as AuthenticatedNextApiRequest).user;
  const userId = authUser.id;

  if (req.method === 'GET') {
    return handleGet(req, res, userId);
  }

  if (req.method === 'POST') {
    return handlePost(req, res, userId, authUser.name || authUser.email);
  }

  return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET', 'POST']);
}

async function handleGet(req: NextApiRequest, res: NextApiResponse, userId: string) {
  try {
    const view = (req.query.view as string) || 'inbox';
    const limit = Math.min(parseInt(req.query.limit as string || '20', 10) || 20, 100);
    const offset = parseInt(req.query.offset as string || '0', 10) || 0;
    const unreadOnly = req.query.unread_only === 'true';

    if (view === 'sent') {
      return fetchSent(res, userId, limit, offset);
    }

    if (view === 'archived') {
      return fetchRecipientView(res, userId, limit, offset, false, true);
    }

    // Default: inbox (not archived)
    return fetchRecipientView(res, userId, limit, offset, unreadOnly, false);
  } catch (error) {
    log.error('Failed to fetch messages', { error }, 'Messages');
    return apiResponse.internalError(res, error);
  }
}

async function fetchRecipientView(
  res: NextApiResponse,
  userId: string,
  limit: number,
  offset: number,
  unreadOnly: boolean,
  archived: boolean
) {
  // Root messages only (thread_id IS NULL) where user is a recipient
  if (unreadOnly) {
    const messages = await sql`
      SELECT
        m.id, m.sender_id, m.subject, m.body, m.priority,
        m.thread_id, m.context_module, m.context_url, m.created_at,
        COALESCE(u.first_name || ' ' || u.last_name, u.email) AS sender_name,
        u.email AS sender_email,
        r.is_read,
        (SELECT COUNT(*)::int FROM internal_messages WHERE thread_id = m.id) AS reply_count,
        (SELECT COUNT(*)::int FROM internal_message_recipients WHERE message_id = m.id) AS recipient_count,
        (SELECT MAX(created_at) FROM internal_messages WHERE thread_id = m.id) AS latest_reply_at
      FROM internal_messages m
      INNER JOIN internal_message_recipients r ON r.message_id = m.id AND r.recipient_id = ${userId}::uuid
      INNER JOIN users u ON u.id = m.sender_id
      WHERE m.thread_id IS NULL
        AND r.is_archived = ${archived}
        AND r.is_read = FALSE
      ORDER BY COALESCE(
        (SELECT MAX(created_at) FROM internal_messages WHERE thread_id = m.id),
        m.created_at
      ) DESC
      LIMIT ${limit} OFFSET ${offset}
    `;

    const countResult = await sql`
      SELECT COUNT(*)::int AS total
      FROM internal_messages m
      INNER JOIN internal_message_recipients r ON r.message_id = m.id AND r.recipient_id = ${userId}::uuid
      WHERE m.thread_id IS NULL
        AND r.is_archived = ${archived}
        AND r.is_read = FALSE
    `;

    return apiResponse.success(res, {
      messages,
      total: Number(countResult[0]?.total || 0),
    });
  }

  // All messages (read + unread)
  const messages = await sql`
    SELECT
      m.id, m.sender_id, m.subject, m.body, m.priority,
      m.thread_id, m.context_module, m.context_url, m.created_at,
      COALESCE(u.first_name || ' ' || u.last_name, u.email) AS sender_name,
      u.email AS sender_email,
      r.is_read,
      (SELECT COUNT(*)::int FROM internal_messages WHERE thread_id = m.id) AS reply_count,
      (SELECT COUNT(*)::int FROM internal_message_recipients WHERE message_id = m.id) AS recipient_count,
      (SELECT MAX(created_at) FROM internal_messages WHERE thread_id = m.id) AS latest_reply_at
    FROM internal_messages m
    INNER JOIN internal_message_recipients r ON r.message_id = m.id AND r.recipient_id = ${userId}::uuid
    INNER JOIN users u ON u.id = m.sender_id
    WHERE m.thread_id IS NULL
      AND r.is_archived = ${archived}
    ORDER BY COALESCE(
      (SELECT MAX(created_at) FROM internal_messages WHERE thread_id = m.id),
      m.created_at
    ) DESC
    LIMIT ${limit} OFFSET ${offset}
  `;

  const countResult = await sql`
    SELECT COUNT(*)::int AS total
    FROM internal_messages m
    INNER JOIN internal_message_recipients r ON r.message_id = m.id AND r.recipient_id = ${userId}::uuid
    WHERE m.thread_id IS NULL
      AND r.is_archived = ${archived}
  `;

  return apiResponse.success(res, {
    messages,
    total: Number(countResult[0]?.total || 0),
  });
}

async function fetchSent(
  res: NextApiResponse,
  userId: string,
  limit: number,
  offset: number
) {
  const messages = await sql`
    SELECT
      m.id, m.sender_id, m.subject, m.body, m.priority,
      m.thread_id, m.context_module, m.context_url, m.created_at,
      COALESCE(u.first_name || ' ' || u.last_name, u.email) AS sender_name,
      u.email AS sender_email,
      TRUE AS is_read,
      (SELECT COUNT(*)::int FROM internal_messages WHERE thread_id = m.id) AS reply_count,
      (SELECT COUNT(*)::int FROM internal_message_recipients WHERE message_id = m.id) AS recipient_count,
      (SELECT MAX(created_at) FROM internal_messages WHERE thread_id = m.id) AS latest_reply_at
    FROM internal_messages m
    INNER JOIN users u ON u.id = m.sender_id
    WHERE m.sender_id = ${userId}::uuid
      AND m.thread_id IS NULL
    ORDER BY m.created_at DESC
    LIMIT ${limit} OFFSET ${offset}
  `;

  const countResult = await sql`
    SELECT COUNT(*)::int AS total
    FROM internal_messages m
    WHERE m.sender_id = ${userId}::uuid
      AND m.thread_id IS NULL
  `;

  return apiResponse.success(res, {
    messages,
    total: Number(countResult[0]?.total || 0),
  });
}

async function handlePost(
  req: NextApiRequest,
  res: NextApiResponse,
  userId: string,
  senderName: string
) {
  try {
    const { recipients, subject, body, priority, threadId, contextModule, contextId, contextUrl } = req.body;

    if (!body || typeof body !== 'string' || !body.trim()) {
      return apiResponse.badRequest(res, 'Message body is required');
    }

    if (!recipients || !Array.isArray(recipients) || recipients.length === 0) {
      return apiResponse.badRequest(res, 'At least one recipient is required');
    }

    // Insert message
    const messageRows = await sql`
      INSERT INTO internal_messages (
        sender_id, subject, body, priority,
        thread_id, context_module, context_id, context_url
      ) VALUES (
        ${userId}::uuid,
        ${subject?.trim() || null},
        ${body.trim()},
        ${priority || 'normal'},
        ${threadId || null},
        ${contextModule || null},
        ${contextId || null},
        ${contextUrl || null}
      )
      RETURNING *
    `;

    const message = messageRows[0];

    // Insert recipients
    for (const recipientId of recipients) {
      await sql`
        INSERT INTO internal_message_recipients (message_id, recipient_id)
        VALUES (${message.id}, ${recipientId}::uuid)
        ON CONFLICT (message_id, recipient_id) DO NOTHING
      `;
    }

    // Trigger notifications (fire-and-forget)
    const notifSubject = subject?.trim() || body.trim().substring(0, 100);
    notify({
      event_type: 'messaging.new_message',
      title: `${senderName} sent you a message`,
      body: notifSubject,
      icon: 'mail',
      severity: priority === 'urgent' ? 'warning' : 'info',
      action_url: '/communications?tab=inbox',
      source_module: 'messaging',
      source_id: message.id,
      recipient_user_ids: recipients,
    }).catch(err => {
      log.error('Failed to send message notification', { error: err }, 'Messages');
    });

    log.info('Internal message sent', {
      messageId: message.id,
      sender: userId,
      recipientCount: recipients.length,
      isReply: !!threadId,
    }, 'Messages');

    return apiResponse.created(res, message, 'Message sent');
  } catch (error) {
    log.error('Failed to send message', { error }, 'Messages');
    return apiResponse.internalError(res, error);
  }
}

