            >
              <option value="">Select a meeting...</option>
              {meetings.map(m => (
                <option key={m.id} value={m.id}>{m.title}</option>
              ))}
            </select>
          </div>

          {/* Description */}
          <div>
            <label className="text-sm font-medium text-[var(--ff-text-primary)] mb-1 block">Description</label>
            <textarea
              value={description}
