import React, { useState, useEffect } from 'react';
import { useRouter } from 'next/router';
import {
  Inbox,
  Mail,
  MessageCircle,
  Users,
  Bell,
  Settings,
  RefreshCw,
  Film,
  Plus,
} from 'lucide-react';
