/**
 * GET/PUT /api/notifications/preferences
 * GET: Returns user preferences merged with system defaults.
 * PUT: Upserts user notification preferences.
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { neon } from '@neondatabase/serverless';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth, type AuthenticatedNextApiRequest } from '@/lib/auth/middleware';
import {
  DEFAULT_CHANNEL_PREFERENCES,
  EVENT_LABELS,
  EVENT_GROUPS,
  getRegisteredEventTypes,
} from '@/modules/notifications/constants';
import type { MergedPreference } from '@/modules/notifications/types';

const sql = neon(process.env.DATABASE_URL!);

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method === 'GET') {
    return handleGet(req, res);
  }
  if (req.method === 'PUT') {
    return handlePut(req, res);
  }
  return apiResponse.methodNotAllowed(res, req.method!, ['GET', 'PUT']);
}

/** GET: Return all event types with user overrides merged in */
async function handleGet(req: NextApiRequest, res: NextApiResponse) {
  const authReq = req as AuthenticatedNextApiRequest;

  try {
    const userId = authReq.user.id;

    // Fetch user overrides
    const overrides = await sql`
      SELECT event_type, channel_in_app, channel_email, channel_whatsapp
      FROM notification_preferences
      WHERE user_id = ${userId}::uuid
    `;

    const overrideMap = new Map(
      overrides.map(r => [r.event_type, r])
    );

    // Merge with system defaults
    const eventTypes = getRegisteredEventTypes();
    const fallback = DEFAULT_CHANNEL_PREFERENCES._fallback || { in_app: true, email: false, whatsapp: false };

    const merged: MergedPreference[] = eventTypes.map(eventType => {
      const defaults = DEFAULT_CHANNEL_PREFERENCES[eventType] || fallback;
      const userOverride = overrideMap.get(eventType);

      return {
        event_type: eventType,
        label: EVENT_LABELS[eventType] || eventType,
        group: EVENT_GROUPS[eventType] || 'Other',
        channel_in_app: userOverride ? userOverride.channel_in_app : defaults.in_app,
        channel_email: userOverride ? userOverride.channel_email : defaults.email,
        channel_whatsapp: userOverride ? userOverride.channel_whatsapp : defaults.whatsapp,
        is_user_override: !!userOverride,
      };
    });

    return apiResponse.success(res, merged);
  } catch (error) {
    return apiResponse.internalError(res, error);
  }
}

/** PUT: Upsert user preferences */
async function handlePut(req: NextApiRequest, res: NextApiResponse) {
  const authReq = req as AuthenticatedNextApiRequest;

  try {
    const userId = authReq.user.id;
    const { preferences } = req.body || {};

    if (!Array.isArray(preferences)) {
      return apiResponse.badRequest(res, 'preferences must be an array of { event_type, channel_in_app, channel_email, channel_whatsapp }');
    }

    for (const pref of preferences) {
      if (!pref.event_type || typeof pref.event_type !== 'string') {
        continue;
      }

      await sql`
        INSERT INTO notification_preferences (
          user_id, event_type, channel_in_app, channel_email, channel_whatsapp, updated_at
        ) VALUES (
          ${userId}::uuid, ${pref.event_type},
          ${!!pref.channel_in_app}, ${!!pref.channel_email}, ${!!pref.channel_whatsapp},
          NOW()
        )
        ON CONFLICT (user_id, event_type)
        DO UPDATE SET
          channel_in_app = ${!!pref.channel_in_app},
          channel_email = ${!!pref.channel_email},
          channel_whatsapp = ${!!pref.channel_whatsapp},
          updated_at = NOW()
      `;
    }

    return apiResponse.success(res, { updated: preferences.length });
  } catch (error) {
    return apiResponse.internalError(res, error);
  }
}

export default withAuth(handler);

/**
 * Unified Notification Service - Type Definitions
 * @module notifications/types
 */

/** Severity levels for notifications */
export type NotificationSeverity = 'info' | 'warning' | 'error' | 'success';

/** Delivery channels */
export type NotificationChannel = 'in_app' | 'email' | 'whatsapp';

/** Channel preference flags */
export interface ChannelPreferences {
  in_app: boolean;
  email: boolean;
  whatsapp: boolean;
}

/** Stored in-app notification (from user_notifications table) */
export interface UserNotification {
  id: string;
  user_id: string;
  event_type: string;
  title: string;
  body: string | null;
  icon: string;
  severity: NotificationSeverity;
  action_url: string | null;
  source_module: string | null;
  source_id: string | null;
  metadata: Record<string, unknown>;
  is_read: boolean;
  read_at: string | null;
  created_at: string;
  updated_at: string;
}

/** Payload passed to notify() by calling modules */
export interface NotifyPayload {
  /** Event type key, e.g. 'maintenance.ticket_assigned' */
  event_type: string;
  /** Title shown in bell dropdown */
  title: string;
  /** Optional body text for detail */
  body?: string;
  /** Lucide icon name override (defaults from EVENT_ICONS) */
  icon?: string;
  /** Severity override (defaults from EVENT_SEVERITY) */
  severity?: NotificationSeverity;
  /** In-app link when notification is clicked */
  action_url?: string;
  /** Source module name for grouping */
  source_module?: string;
  /** Source entity ID (ticket, project, etc.) */
  source_id?: string;
  /** Additional metadata stored as JSONB */
  metadata?: Record<string, unknown>;
  /** User IDs to notify — caller resolves recipients */
  recipient_user_ids: string[];
  /** Custom HTML for email (optional, else default template used) */
  email_html?: string;
  /** Custom email subject (defaults to title) */
  email_subject?: string;
  /** WA group JID for group messages (optional) */
  wa_group_jid?: string;
  /** Custom WA message text (optional, else title+body used) */
  wa_message?: string;
}

/** Notification preference row from DB */
export interface NotificationPreference {
  user_id: string;
  event_type: string;
  channel_in_app: boolean;
  channel_email: boolean;
  channel_whatsapp: boolean;
}

/** Delivery log entry */
export interface DeliveryLogEntry {
  id: string;
  notification_id: string | null;
  user_id: string;
  channel: NotificationChannel;
  status: 'sent' | 'delivered' | 'failed' | 'skipped';
  recipient_address: string | null;
  error_message: string | null;
  sent_at: string;
}

/** Merged preference (system default + user override) for API response */
export interface MergedPreference {
  event_type: string;
  label: string;
  group: string;
  channel_in_app: boolean;
  channel_email: boolean;
  channel_whatsapp: boolean;
  is_user_override: boolean;
}

'use client';

/**
 * Communications Hub - Unified communications center
 * 6 tabs: Inbox, Email, WhatsApp, Meetings, Notifications, Settings
 * Replaces the old CommunicationsDashboard with a consolidated hub
 */

import React, { useState, useEffect } from 'react';
import { useRouter } from 'next/router';
import {
  Inbox,
  Mail,
  MessageCircle,
  Users,
  Bell,
  Settings,
  RefreshCw,
  Film,
  Plus,
} from 'lucide-react';
import Link from 'next/link';
import { cn } from '@/lib/utils';
import { log } from '@/lib/logger';
import { useCommunications } from '@/hooks/useCommunications';
import type { CommsTab } from './types/hub.types';
import { CommunicationsStatsCards, CommunicationsMeetingsTab } from './components';
import { NotificationsTab } from './notifications/NotificationsTab';
import { EmailTab } from './email/EmailTab';
import { InboxPanel } from './messaging/InboxPanel';
import { CreateActionItemModal } from '@/modules/meetings/components/CreateActionItemModal';
import { SettingsTab } from './settings/SettingsTab';

const TABS: { key: CommsTab; label: string; icon: React.ElementType }[] = [
  { key: 'inbox', label: 'Inbox', icon: Inbox },
  { key: 'email', label: 'Email', icon: Mail },
  { key: 'whatsapp', label: 'WhatsApp', icon: MessageCircle },
  { key: 'meetings', label: 'Meetings', icon: Users },
  { key: 'notifications', label: 'Notifications', icon: Bell },
  { key: 'settings', label: 'Settings', icon: Settings },
];

export default function CommunicationsHub() {
  const router = useRouter();
  const [activeTab, setActiveTab] = useState<CommsTab>('meetings');
  const [isRefreshing, setIsRefreshing] = useState(false);
  const [isSyncing, setIsSyncing] = useState(false);
  const [isSyncingTeams, setIsSyncingTeams] = useState(false);
  const [syncMessage, setSyncMessage] = useState<string | null>(null);
  const [lastRefresh, setLastRefresh] = useState<Date | null>(null);
  const [showCreateActionItem, setShowCreateActionItem] = useState(false);
  const { data, stats, isLoading, getStatusColor, refetch } = useCommunications();

  // Sync active tab with URL param
  useEffect(() => {
    const tabParam = router.query.tab as string | undefined;
    if (tabParam) {
      const valid = TABS.find(t => t.key === tabParam);
      if (valid) setActiveTab(valid.key);
    }
  }, [router.query.tab]);

  const handleTabChange = (tab: CommsTab) => {
    setActiveTab(tab);
    router.push(`/communications?tab=${tab}`, undefined, { shallow: true });
  };

  const handleRefresh = async () => {
    setIsRefreshing(true);
    try {
      if (refetch) await refetch();
      setLastRefresh(new Date());
    } finally {
      setIsRefreshing(false);
    }
  };

  const handleFirefliesSync = async () => {
    setIsSyncing(true);
    setSyncMessage(null);
    try {
      const response = await fetch('/api/meetings?action=sync', { method: 'POST' });
      const result = await response.json();
      if (result.success) {
        setSyncMessage(`Synced ${result.synced} meetings from Fireflies`);
        await handleRefresh();
      } else {
        setSyncMessage(`Sync failed: ${result.error}`);
      }
    } catch (error) {
      const message = error instanceof Error ? error.message : 'Unknown error';
      setSyncMessage(`Sync failed: ${message}`);
      log.error('Fireflies sync failed:', error);
    } finally {
      setIsSyncing(false);
      setTimeout(() => setSyncMessage(null), 5000);
    }
  };

  const handleTeamsSync = async () => {
    setIsSyncingTeams(true);
    setSyncMessage(null);
    try {
      const response = await fetch('/api/meetings/sync-teams', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ hours: 48 }),
      });
      if (response.ok) {
        setSyncMessage('Teams sync started (processing in background)');
        setTimeout(() => handleRefresh(), 5000);
      } else {
        const result = await response.json();
        setSyncMessage(`Teams sync failed: ${result.error?.message || 'Unknown error'}`);
      }
    } catch (error) {
      const message = error instanceof Error ? error.message : 'Unknown error';
      setSyncMessage(`Teams sync failed: ${message}`);
      log.error('Teams sync failed:', error);
    } finally {
      setIsSyncingTeams(false);
      setTimeout(() => setSyncMessage(null), 8000);
    }
  };

  const showMeetingActions = activeTab === 'meetings';

  return (
    <div className="p-6 space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold text-[var(--ff-text-primary)]">Communications Hub</h1>
          <p className="text-sm text-[var(--ff-text-secondary)] mt-1">
            {lastRefresh
              ? `Last updated ${lastRefresh.toLocaleTimeString()}`
              : 'Unified messaging, meetings, and notifications'}
          </p>
        </div>

        <div className="flex flex-col items-end gap-2">
          <div className="flex items-center gap-2">
            {/* Meetings-specific actions */}
            {showMeetingActions && (
              <>
                <Link
                  href="/recordings"
                  className="flex items-center gap-2 px-4 py-2 text-sm font-medium text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)] bg-[var(--ff-bg-secondary)] hover:bg-[var(--ff-bg-tertiary)] border border-[var(--ff-border-light)] rounded-lg transition-colors"
                >
                  <Film className="w-4 h-4" />
                  Recordings
                </Link>

                <button
                  type="button"
                  onClick={handleTeamsSync}
                  disabled={isSyncingTeams}
                  className={cn(
                    'flex items-center gap-2 px-4 py-2 text-sm font-medium rounded-lg transition-colors',
                    isSyncingTeams
                      ? 'bg-[var(--ff-bg-tertiary)] text-[var(--ff-text-tertiary)] cursor-not-allowed'
                      : 'bg-purple-600 text-white hover:bg-purple-700'
                  )}
                >
                  <RefreshCw className={cn('w-4 h-4', isSyncingTeams && 'animate-spin')} />
                  {isSyncingTeams ? 'Syncing...' : 'Sync Teams'}
                </button>

                <button
                  type="button"
                  onClick={handleFirefliesSync}
                  disabled={isSyncing}
                  className={cn(
                    'flex items-center gap-2 px-4 py-2 text-sm font-medium rounded-lg transition-colors',
                    isSyncing
                      ? 'bg-[var(--ff-bg-tertiary)] text-[var(--ff-text-tertiary)] cursor-not-allowed'
                      : 'bg-blue-600 text-white hover:bg-blue-700'
                  )}
                >
                  <RefreshCw className={cn('w-4 h-4', isSyncing && 'animate-spin')} />
                  {isSyncing ? 'Syncing...' : 'Sync Fireflies'}
                </button>

                <button
                  type="button"
                  onClick={() => setShowCreateActionItem(true)}
                  className="flex items-center gap-2 px-4 py-2 text-sm font-medium text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)] bg-[var(--ff-bg-secondary)] hover:bg-[var(--ff-bg-tertiary)] border border-[var(--ff-border-light)] rounded-lg transition-colors"
                >
                  <Plus className="w-4 h-4" />
                  Add Action Item
                </button>
              </>
            )}

            {/* Refresh button (always visible) */}
            <button
              type="button"
              onClick={handleRefresh}
              disabled={isRefreshing}
              className="flex items-center gap-2 px-4 py-2 text-sm font-medium text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)] bg-[var(--ff-bg-secondary)] hover:bg-[var(--ff-bg-tertiary)] border border-[var(--ff-border-light)] rounded-lg transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
              aria-label="Refresh"
            >
              <RefreshCw className={cn('w-4 h-4', isRefreshing && 'animate-spin')} />
            </button>
          </div>

          {syncMessage && (
            <p className={cn(
              'text-sm',
              syncMessage.includes('failed') ? 'text-red-600' : 'text-green-600'
            )}>
              {syncMessage}
            </p>
          )}
        </div>
      </div>

      {/* Stats Cards (meetings data) */}
      {showMeetingActions && <CommunicationsStatsCards stats={stats} />}

      {/* Tab Navigation */}
      <div className="bg-[var(--ff-bg-secondary)] border border-[var(--ff-border-light)] rounded-lg">
        <div className="border-b border-[var(--ff-border-light)]">
          <nav role="tablist" className="flex gap-1 px-4 -mb-px overflow-x-auto" aria-label="Communications tabs">
            {TABS.map(tab => {
              const Icon = tab.icon;
              const isActive = activeTab === tab.key;
              return (
                <button
                  key={tab.key}
                  role="tab"
                  aria-selected={isActive}
                  aria-controls={`comms-panel-${tab.key}`}
                  onClick={() => handleTabChange(tab.key)}
                  className={cn(
                    'flex items-center gap-2 py-3 px-4 border-b-2 font-medium text-sm transition-colors whitespace-nowrap',
                    'focus:outline-none focus:ring-2 focus:ring-inset focus:ring-[var(--ff-accent)]',
                    isActive
                      ? 'border-[var(--ff-primary)] text-[var(--ff-primary)]'
                      : 'border-transparent text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)] hover:border-[var(--ff-border-light)]'
                  )}
                >
                  <Icon className="w-4 h-4" />
                  {tab.label}
                  {tab.key === 'meetings' && data.meetings.length > 0 && (
                    <span className="px-2 py-0.5 text-xs bg-blue-500/20 text-blue-400 rounded-full">
                      {data.meetings.length}
                    </span>
                  )}
                </button>
              );
            })}
          </nav>
        </div>

        {/* Tab Panels */}
        <div className="p-6">
          {/* Inbox */}
          <div
            id="comms-panel-inbox"
            role="tabpanel"
            hidden={activeTab !== 'inbox'}
          >
            {activeTab === 'inbox' && <InboxPanel />}
          </div>

          {/* Email */}
          <div
            id="comms-panel-email"
            role="tabpanel"
            hidden={activeTab !== 'email'}
          >
            {activeTab === 'email' && <EmailTab />}
          </div>

          {/* WhatsApp */}
          <div
            id="comms-panel-whatsapp"
            role="tabpanel"
            hidden={activeTab !== 'whatsapp'}
          >
            {activeTab === 'whatsapp' && (
              <div className="text-center py-8">
                <MessageCircle className="w-12 h-12 mx-auto text-green-500 mb-4" />
                <h3 className="text-lg font-medium text-[var(--ff-text-primary)] mb-2">WhatsApp Portal</h3>
                <p className="text-sm text-[var(--ff-text-secondary)] max-w-md mx-auto mb-4">
                  Manage WhatsApp groups, view messages, and monitor service status.
                </p>
                <Link
                  href="/communications/whatsapp"
                  className="inline-flex items-center gap-2 px-4 py-2 bg-green-500 text-white rounded-lg hover:bg-green-600 transition-colors"
                >
                  <MessageCircle className="w-4 h-4" />
                  Open WhatsApp Portal
                </Link>
              </div>
            )}
          </div>

          {/* Meetings - Working */}
          <div
            id="comms-panel-meetings"
            role="tabpanel"
            hidden={activeTab !== 'meetings'}
          >
            {activeTab === 'meetings' && (
              isLoading ? (
                <div className="flex items-center justify-center py-12">
                  <RefreshCw className="w-6 h-6 animate-spin text-[var(--ff-text-tertiary)]" />
                  <span className="ml-2 text-[var(--ff-text-secondary)]">Loading meetings...</span>
                </div>
              ) : (
                <CommunicationsMeetingsTab
                  meetings={data.meetings}
                  getStatusColor={getStatusColor}
                  onRefresh={handleRefresh}
                />
              )
            )}
          </div>

          {/* Notifications - Working */}
          <div
            id="comms-panel-notifications"
            role="tabpanel"
            hidden={activeTab !== 'notifications'}
          >
            {activeTab === 'notifications' && <NotificationsTab />}
          </div>

          {/* Settings */}
          <div
            id="comms-panel-settings"
            role="tabpanel"
            hidden={activeTab !== 'settings'}
          >
            {activeTab === 'settings' && <SettingsTab />}
          </div>
        </div>
      </div>
      {/* Create Action Item Modal */}
      <CreateActionItemModal
        isOpen={showCreateActionItem}
        onClose={() => setShowCreateActionItem(false)}
      />
    </div>
  );
}

/**
 * Hook for email outbox data fetching
 */

import { useState, useEffect, useCallback } from 'react';
import { log } from '@/lib/logger';
import type { EmailOutboxItem, EmailOutboxFilters } from '../types/email.types';

const PAGE_SIZE = 20;

interface UseEmailOutboxReturn {
  emails: EmailOutboxItem[];
  isLoading: boolean;
  hasMore: boolean;
  total: number;
  refetch: () => Promise<void>;
  loadMore: () => Promise<void>;
}

export function useEmailOutbox(filters?: EmailOutboxFilters): UseEmailOutboxReturn {
  const [emails, setEmails] = useState<EmailOutboxItem[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [hasMore, setHasMore] = useState(false);
  const [total, setTotal] = useState(0);
  const [offset, setOffset] = useState(0);

  const fetchEmails = useCallback(async (reset = false) => {
    setIsLoading(true);
    const currentOffset = reset ? 0 : offset;
    try {
      const params = new URLSearchParams({
        limit: String(filters?.limit || PAGE_SIZE),
        offset: String(currentOffset),
      });
      if (filters?.status) params.set('status', filters.status);
      if (filters?.sourceModule) params.set('source_module', filters.sourceModule);

      const res = await fetch(`/api/communications/email-outbox?${params}`, {
        credentials: 'include',
      });
      const json = await res.json();

      if (json.success) {
        const items: EmailOutboxItem[] = json.data.emails;
        if (reset) {
          setEmails(items);
          setOffset(items.length);
        } else {
          setEmails(prev => [...prev, ...items]);
          setOffset(currentOffset + items.length);
        }
        setTotal(json.data.total);
        setHasMore(items.length === (filters?.limit || PAGE_SIZE));
      }
    } catch (err) {
      log.error('Failed to fetch email outbox:', err);
    } finally {
      setIsLoading(false);
    }
  }, [offset, filters?.status, filters?.sourceModule, filters?.limit]);

  useEffect(() => {
    fetchEmails(true);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [filters?.status, filters?.sourceModule]);

  return {
    emails,
    isLoading,
    hasMore,
    total,
    refetch: () => fetchEmails(true),
    loadMore: () => fetchEmails(false),
  };
}

/**
 * Logger Service
 * Proper logging replacement for console.* statements
 * Zero Tolerance Enforcement: No console.* statements allowed
 */

// Global type declarations for log storage
declare global {
  interface Window {
    __appLogs?: LogEntry[];
  }

  // Modern approach: extend NodeJS namespace
  namespace NodeJS {
    interface Process {
      __appLogs?: LogEntry[];
    }
  }
}

export interface LogData {
  [key: string]: any;
}

export interface LogEntry {
  timestamp: string;
  level: 'debug' | 'info' | 'warn' | 'error';
  component: string | undefined;
  message: string;
  data: LogData | undefined;
  formattedMessage: string;
}

export interface LoggerOptions {
  enableConsole?: boolean;
  enableFile?: boolean;
  level?: 'debug' | 'info' | 'warn' | 'error';
}

/**
 * Logger class for structured logging
 * Replaces all console.* statements in the application
 */
class Logger {
  private options: LoggerOptions = {
    enableConsole: process.env.NODE_ENV === 'development',
    enableFile: false,
    level: 'info',
  };

  constructor(options?: Partial<LoggerOptions>) {
    this.options = { ...this.options, ...options };
  }

  /**
   * Log debug messages
   * @param message - Log message
   * @param data - Additional data to log
   * @param component - Component name for context
   */
  debug(message: string, data?: LogData, component?: string): void {
    this.log('debug', message, data, component);
  }

  /**
   * Log info messages
   * @param message - Log message
   * @param data - Additional data to log
   * @param component - Component name for context
   */
  info(message: string, data?: LogData, component?: string): void {
    this.log('info', message, data, component);
  }

  /**
   * Log warning messages
   * @param message - Log message
   * @param data - Additional data to log
   * @param component - Component name for context
   */
  warn(message: string, data?: LogData, component?: string): void {
    this.log('warn', message, data, component);
  }

  /**
   * Log error messages
   * @param message - Log message
   * @param data - Additional data to log
   * @param component - Component name for context
   */
  error(message: string, data?: LogData, component?: string): void {
    this.log('error', message, data, component);
  }

  /**
   * Internal logging method
   * @param level - Log level
   * @param message - Log message
   * @param data - Additional data
   * @param component - Component name
   */
  private log(
    level: 'debug' | 'info' | 'warn' | 'error',
    message: string,
    data?: LogData,
    component?: string
  ): void {
    if (!this.shouldLog(level)) return;

    const timestamp = new Date().toISOString();
    const prefix = component ? `[${component}]` : '';
    const logMessage = `${timestamp} [${level.toUpperCase()}] ${prefix} ${message}`;

    // Store logs in memory for development (could be sent to external service in production)
    const logEntry = {
      timestamp,
      level,
      component,
      message,
      data,
      formattedMessage: logMessage
    };

    // Store in global log collection (browser or Node.js)
    if (typeof window !== 'undefined') {
      // Browser environment
      if (!window.__appLogs) window.__appLogs = [];
      window.__appLogs.push(logEntry);

      // Limit log storage to prevent memory issues
      if (window.__appLogs.length > 1000) {
        window.__appLogs.shift();
      }
    } else {
      // Node.js environment - could write to file or send to logging service
      // For now, just store in process (could be extended)
      if (!process.__appLogs) process.__appLogs = [];
      process.__appLogs.push(logEntry);

      // Limit log storage
      if (process.__appLogs.length > 1000) {
        process.__appLogs.shift();
      }
    }

    // In development, could optionally write to stderr/stdout
    // But we avoid console.* statements entirely for zero-tolerance compliance
    if (this.options.enableFile && process.env.NODE_ENV === 'development') {
      // Could implement file logging here if needed
      // fs.appendFile('app.log', logMessage + '\n', () => {})
    }
  }

  /**
   * Check if we should log at this level
   * @param level - Log level to check
   * @returns Boolean indicating if logging should occur
   */
  private shouldLog(level: 'debug' | 'info' | 'warn' | 'error'): boolean {
    const levels = ['debug', 'info', 'warn', 'error'];
    const currentLevelIndex = levels.indexOf(this.options.level || 'info');
    const messageLevelIndex = levels.indexOf(level);
    return messageLevelIndex >= currentLevelIndex;
  }

  /**
   * Get all stored logs (for debugging in development)
   * @returns Array of log entries
   */
  getLogs(): LogEntry[] {
    if (typeof window !== 'undefined') {
      return window.__appLogs || [];
    } else {
      return (process as any).__appLogs || [];
    }
  }

  /**
   * Clear all stored logs
   */
  clearLogs(): void {
    if (typeof window !== 'undefined') {
      window.__appLogs = [];
    } else {
      (process as any).__appLogs = [];
    }
  }

  /**
   * Get logs for development debugging (replaces console access)
   * This method can be used in development to inspect logs without console
   */
  getRecentLogs(count: number = 50): LogEntry[] {
    const logs = this.getLogs();
    return logs.slice(-count);
  }

  /**
   * Export logs as string (for debugging or external service)
   */
  exportLogs(): string {
    const logs = this.getLogs();
    return logs.map(log => log.formattedMessage + (log.data ? ` ${JSON.stringify(log.data)}` : '')).join('\n');
  }
}

// Export singleton logger instance
export const log = new Logger();

// Export Logger class for custom instances
export { Logger };

// Default export for convenience
export default log;

/**
 * Create a logger instance with a component name
 * @param component - Component name for logging context
 * @returns Logger instance with component context
 */
export function createLogger(component: string) {
  return {
    debug: (message: string, data?: LogData) => log.debug(message, data, component),
    info: (message: string, data?: LogData) => log.info(message, data, component),
    warn: (message: string, data?: LogData) => log.warn(message, data, component),
    error: (message: string, data?: LogData) => log.error(message, data, component),
  };
}

/**
 * Pino-style API logger for use in API routes
 * Accepts (data, message?) format used by api-error-handler and API routes
 */
export const apiLogger = {
  debug: (data: LogData, message?: string) => log.debug(message || 'debug', data, 'API'),
  info: (data: LogData, message?: string) => log.info(message || 'info', data, 'API'),
  warn: (data: LogData, message?: string) => log.warn(message || 'warning', data, 'API'),
  error: (data: LogData, message?: string) => log.error(message || 'error', data, 'API'),
};

import { NextApiRequest, NextApiResponse } from 'next';
import { log } from '@/lib/logger';

/**
 * Standard API Response Types
 */
export interface ApiSuccessResponse<T = any> {
  success: true;
  data: T;
  message?: string;
  meta?: {
    timestamp?: string;
    requestId?: string;
    [key: string]: any;
  };
}

export interface ApiErrorResponse {
  success: false;
  error: {
    code: string;
    message: string;
    details?: any;
  };
  meta?: {
    timestamp?: string;
    requestId?: string;
    [key: string]: any;
  };
}

export interface ApiPaginatedResponse<T = any> extends ApiSuccessResponse<T[]> {
  pagination: {
    page: number;
    pageSize: number;
    total: number;
    totalPages: number;
  };
}

export type ApiResponse<T = any> = ApiSuccessResponse<T> | ApiErrorResponse;

/**
 * Standard error codes
 */
export enum ErrorCode {
  // Client errors (400-499)
  BAD_REQUEST = 'BAD_REQUEST',
  UNAUTHORIZED = 'UNAUTHORIZED',
  FORBIDDEN = 'FORBIDDEN',
  NOT_FOUND = 'NOT_FOUND',
  METHOD_NOT_ALLOWED = 'METHOD_NOT_ALLOWED',
  CONFLICT = 'CONFLICT',
  VALIDATION_ERROR = 'VALIDATION_ERROR',
  RATE_LIMIT = 'RATE_LIMIT',
  PAYLOAD_TOO_LARGE = 'PAYLOAD_TOO_LARGE',

  // Server errors (500-599)
  INTERNAL_ERROR = 'INTERNAL_ERROR',
  DATABASE_ERROR = 'DATABASE_ERROR',
  SERVICE_UNAVAILABLE = 'SERVICE_UNAVAILABLE',
  GATEWAY_TIMEOUT = 'GATEWAY_TIMEOUT',

  // Business logic errors
  BUSINESS_RULE_VIOLATION = 'BUSINESS_RULE_VIOLATION',
  INSUFFICIENT_PERMISSIONS = 'INSUFFICIENT_PERMISSIONS',
  RESOURCE_LOCKED = 'RESOURCE_LOCKED',
  DEPENDENCY_ERROR = 'DEPENDENCY_ERROR',
}

/**
 * HTTP status code mapping
 */
const STATUS_CODE_MAP: Record<ErrorCode, number> = {
  // Client errors
  [ErrorCode.BAD_REQUEST]: 400,
  [ErrorCode.UNAUTHORIZED]: 401,
  [ErrorCode.FORBIDDEN]: 403,
  [ErrorCode.NOT_FOUND]: 404,
  [ErrorCode.METHOD_NOT_ALLOWED]: 405,
  [ErrorCode.CONFLICT]: 409,
  [ErrorCode.VALIDATION_ERROR]: 422,
  [ErrorCode.RATE_LIMIT]: 429,
  [ErrorCode.PAYLOAD_TOO_LARGE]: 413,

  // Server errors
  [ErrorCode.INTERNAL_ERROR]: 500,
  [ErrorCode.DATABASE_ERROR]: 500,
  [ErrorCode.SERVICE_UNAVAILABLE]: 503,
  [ErrorCode.GATEWAY_TIMEOUT]: 504,

  // Business logic errors (usually 400 or 422)
  [ErrorCode.BUSINESS_RULE_VIOLATION]: 422,
  [ErrorCode.INSUFFICIENT_PERMISSIONS]: 403,
  [ErrorCode.RESOURCE_LOCKED]: 423,
  [ErrorCode.DEPENDENCY_ERROR]: 424,
};

/**
 * API Response Helper Class
 */
export class ApiResponseHelper {
  private static generateMeta(additionalMeta?: Record<string, any>) {
    return {
      timestamp: new Date().toISOString(),
      ...additionalMeta,
    };
  }

  /**
   * Send success response
   */
  static success<T>(
    res: NextApiResponse,
    data: T,
    message?: string,
    statusCode = 200,
    meta?: Record<string, any>
  ): void {
    const response: ApiSuccessResponse<T> = {
      success: true,
      data,
      ...(message && { message }),
      meta: this.generateMeta(meta),
    };

    res.status(statusCode).json(response);
  }

  /**
   * Send created response (201)
   */
  static created<T>(
    res: NextApiResponse,
    data: T,
    message = 'Resource created successfully',
    meta?: Record<string, any>
  ): void {
    this.success(res, data, message, 201, meta);
  }

  /**
   * Send no content response (204)
   */
  static noContent(res: NextApiResponse): void {
    res.status(204).end();
  }

  /**
   * Send paginated response
   */
  static paginated<T>(
    res: NextApiResponse,
    data: T[],
    pagination: {
      page: number;
      pageSize: number;
      total: number;
    },
    message?: string,
    meta?: Record<string, any>
  ): void {
    const totalPages = Math.ceil(pagination.total / pagination.pageSize);

    const response: ApiPaginatedResponse<T> = {
      success: true,
      data,
      pagination: {
        ...pagination,
        totalPages,
      },
      ...(message && { message }),
      meta: this.generateMeta(meta),
    };

    res.status(200).json(response);
  }

  /**
   * Send error response
   */
  static error(
    res: NextApiResponse,
    code: ErrorCode,
    message: string,
    details?: any,
    meta?: Record<string, any>
  ): void {
    const statusCode = STATUS_CODE_MAP[code] || 500;

    const response: ApiErrorResponse = {
      success: false,
      error: {
        code,
        message,
        ...(details && { details }),
      },
      meta: this.generateMeta(meta),
    };

    res.status(statusCode).json(response);
  }

  /**
   * Send bad request error response (400)
   */
  static badRequest(
    res: NextApiResponse,
    message: string,
    details?: any
  ): void {
    this.error(res, ErrorCode.BAD_REQUEST, message, details);
  }

  /**
   * Send validation error response
   */
  static validationError(
    res: NextApiResponse,
    errors: Record<string, string | string[]>,
    message = 'Validation failed'
  ): void {
    this.error(res, ErrorCode.VALIDATION_ERROR, message, errors);
  }

  /**
   * Send not found error response
   */
  static notFound(
    res: NextApiResponse,
    resource: string,
    identifier?: string | number
  ): void {
    const message = identifier
      ? `${resource} with identifier '${identifier}' not found`
      : `${resource} not found`;

    this.error(res, ErrorCode.NOT_FOUND, message);
  }

  /**
   * Send unauthorized error response
   */
  static unauthorized(
    res: NextApiResponse,
    message = 'Authentication required'
  ): void {
    this.error(res, ErrorCode.UNAUTHORIZED, message);
  }

  /**
   * Send forbidden error response
   */
  static forbidden(
    res: NextApiResponse,
    message = 'You do not have permission to perform this action'
  ): void {
    this.error(res, ErrorCode.FORBIDDEN, message);
  }

  /**
   * Send method not allowed error response
   */
  static methodNotAllowed(
    res: NextApiResponse,
    method: string,
    allowedMethods: string[]
  ): void {
    res.setHeader('Allow', allowedMethods.join(', '));
    this.error(
      res,
      ErrorCode.METHOD_NOT_ALLOWED,
      `Method ${method} not allowed. Allowed methods: ${allowedMethods.join(', ')}`
    );
  }

  /**
   * Send internal server error response
   */
  static internalError(
    res: NextApiResponse,
    error: Error | unknown,
    message = 'An internal error occurred'
  ): void {
    // Log the actual error for debugging
    log.error('Internal Server Error', error instanceof Error ? { message: error.message, stack: error.stack } : { error }, 'ApiResponse');

    // In production, don't expose internal error details
    const isDevelopment = process.env.NODE_ENV === 'development';
    const errorDetails = isDevelopment && error instanceof Error
      ? { stack: error.stack, originalMessage: error.message }
      : undefined;

    this.error(res, ErrorCode.INTERNAL_ERROR, message, errorDetails);
  }

  /**
   * Send database error response
   */
  static databaseError(
    res: NextApiResponse,
    error: Error | unknown,
    message = 'A database error occurred'
  ): void {
    // Log the actual error for debugging
    log.error('Database Error', error instanceof Error ? { message: error.message } : { error }, 'ApiResponse');

    // In production, don't expose database error details
    const isDevelopment = process.env.NODE_ENV === 'development';
    const errorDetails = isDevelopment && error instanceof Error
      ? { originalMessage: error.message }
      : undefined;

    this.error(res, ErrorCode.DATABASE_ERROR, message, errorDetails);
  }

  /**
   * Handle CORS headers
   */
  static setCorsHeaders(
    res: NextApiResponse,
    origin = '',
    methods = ['GET', 'POST', 'PUT', 'DELETE', 'PATCH', 'OPTIONS'],
    headers = ['Content-Type', 'Authorization']
  ): void {
    const allowedOrigins = [
      'https://app.fibreflow.app',
      'https://vf.fibreflow.app',
      'https://dev.fibreflow.app',
      // Only include localhost origins in development
      ...(process.env.NODE_ENV === 'development' ? [
        'http://localhost:3004',
        'http://localhost:3005',
      ] : []),
    ];
    const safeOrigin = origin && allowedOrigins.includes(origin) ? origin : '';
    if (!safeOrigin) return;
    res.setHeader('Access-Control-Allow-Origin', safeOrigin);
    res.setHeader('Access-Control-Allow-Methods', methods.join(', '));
    res.setHeader('Access-Control-Allow-Headers', headers.join(', '));
  }

  /**
   * Handle OPTIONS request for CORS
   */
  static handleOptions(req: NextApiRequest, res: NextApiResponse): void {
    this.setCorsHeaders(res, req.headers.origin || '');
    res.status(200).end();
  }
}

/**
 * Convenience exports for common responses
 */
export const apiResponse = {
  success: ApiResponseHelper.success.bind(ApiResponseHelper),
  created: ApiResponseHelper.created.bind(ApiResponseHelper),
  noContent: ApiResponseHelper.noContent.bind(ApiResponseHelper),
  paginated: ApiResponseHelper.paginated.bind(ApiResponseHelper),
  error: ApiResponseHelper.error.bind(ApiResponseHelper),
  badRequest: ApiResponseHelper.badRequest.bind(ApiResponseHelper),
  validationError: ApiResponseHelper.validationError.bind(ApiResponseHelper),
  notFound: ApiResponseHelper.notFound.bind(ApiResponseHelper),
  unauthorized: ApiResponseHelper.unauthorized.bind(ApiResponseHelper),
  forbidden: ApiResponseHelper.forbidden.bind(ApiResponseHelper),
  methodNotAllowed: ApiResponseHelper.methodNotAllowed.bind(ApiResponseHelper),
  internalError: ApiResponseHelper.internalError.bind(ApiResponseHelper),
  databaseError: ApiResponseHelper.databaseError.bind(ApiResponseHelper),
  setCorsHeaders: ApiResponseHelper.setCorsHeaders.bind(ApiResponseHelper),
  handleOptions: ApiResponseHelper.handleOptions.bind(ApiResponseHelper),
};

export default apiResponse;

/**
 * Hook for internal messages data fetching
 */

import { useState, useEffect, useCallback, useRef } from 'react';
import { log } from '@/lib/logger';
import type { MessageListItem, MessageView } from '../types/messaging.types';

const PAGE_SIZE = 20;
const UNREAD_POLL_MS = 30_000;

interface UseInternalMessagesReturn {
  messages: MessageListItem[];
  isLoading: boolean;
  hasMore: boolean;
  total: number;
  unreadCount: number;
  refetch: () => Promise<void>;
  loadMore: () => Promise<void>;
  markRead: (messageIds: string[]) => Promise<void>;
  markAllRead: () => Promise<void>;
  archiveMessages: (messageIds: string[]) => Promise<void>;
}

export function useInternalMessages(view: MessageView): UseInternalMessagesReturn {
  const [messages, setMessages] = useState<MessageListItem[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [hasMore, setHasMore] = useState(false);
  const [total, setTotal] = useState(0);
  const [offset, setOffset] = useState(0);
  const [unreadCount, setUnreadCount] = useState(0);
  const pollRef = useRef<ReturnType<typeof setInterval>>();

  const fetchMessages = useCallback(async (reset = false) => {
    setIsLoading(true);
    const currentOffset = reset ? 0 : offset;
    try {
      const params = new URLSearchParams({
        view,
        limit: String(PAGE_SIZE),
        offset: String(currentOffset),
      });

      const res = await fetch(`/api/communications/messages?${params}`, {
        credentials: 'include',
      });
      const json = await res.json();

      if (json.success) {
        const items: MessageListItem[] = json.data.messages;
        if (reset) {
          setMessages(items);
          setOffset(items.length);
        } else {
          setMessages(prev => [...prev, ...items]);
          setOffset(currentOffset + items.length);
        }
        setTotal(json.data.total);
        setHasMore(items.length === PAGE_SIZE);
      }
    } catch (err) {
      log.error('Failed to fetch messages:', err);
    } finally {
      setIsLoading(false);
    }
  }, [offset, view]);

  const fetchUnreadCount = useCallback(async () => {
    try {
      const res = await fetch('/api/communications/messages-unread-count', {
        credentials: 'include',
      });
      const json = await res.json();
      if (json.success) {
        setUnreadCount(json.data.count);
      }
    } catch {
      // Silently ignore polling errors
    }
  }, []);

  const markRead = useCallback(async (messageIds: string[]) => {
    try {
      await fetch('/api/communications/messages-read', {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        credentials: 'include',
        body: JSON.stringify({ messageIds }),
      });
      // Optimistic update
      setMessages(prev =>
        prev.map(m =>
          messageIds.includes(m.id) ? { ...m, is_read: true } : m
        )
      );
      setUnreadCount(prev => Math.max(0, prev - messageIds.length));
    } catch (err) {
      log.error('Failed to mark messages as read:', err);
    }
  }, []);

  const markAllRead = useCallback(async () => {
    const unreadIds = messages.filter(m => !m.is_read).map(m => m.id);
    if (unreadIds.length === 0) return;
    await markRead(unreadIds);
  }, [messages, markRead]);

  const archiveMessages = useCallback(async (messageIds: string[]) => {
    try {
      await fetch('/api/communications/messages-archive', {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        credentials: 'include',
        body: JSON.stringify({ messageIds }),
      });
      // Remove from current list
      setMessages(prev => prev.filter(m => !messageIds.includes(m.id)));
      setTotal(prev => prev - messageIds.length);
    } catch (err) {
      log.error('Failed to archive messages:', err);
    }
  }, []);

  // Fetch messages on mount and when view changes
  useEffect(() => {
    fetchMessages(true);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [view]);

  // Poll unread count
  useEffect(() => {
    fetchUnreadCount();
    pollRef.current = setInterval(fetchUnreadCount, UNREAD_POLL_MS);
    return () => {
      if (pollRef.current) clearInterval(pollRef.current);
    };
  }, [fetchUnreadCount]);

  return {
    messages,
    isLoading,
    hasMore,
    total,
    unreadCount,
    refetch: () => fetchMessages(true),
    loadMore: () => fetchMessages(false),
    markRead,
    markAllRead,
    archiveMessages,
  };
}

