  const fetchNotifications = useCallback(async (reset = false) => {
    const newOffset = reset ? 0 : offset;
    setIsLoading(true);
    try {
      const params = new URLSearchParams({
        limit: String(PAGE_SIZE),
        offset: String(newOffset),
      });
      if (unreadOnly) params.set('unread_only', 'true');

      const res = await fetch(`/api/notifications?${params}`, {
        credentials: 'include',
      });
      const json = await res.json();

      if (json.success && Array.isArray(json.data)) {
        const items: UserNotification[] = json.data;
        if (reset) {
          setNotifications(items);
          setOffset(items.length);
        } else {
          setNotifications(prev => [...prev, ...items]);
          setOffset(newOffset + items.length);
        }
        setHasMore(items.length === PAGE_SIZE);
      }
    } catch (err) {
      log.error('Failed to fetch notifications:', err);
    } finally {
      setIsLoading(false);
    }
  }, [offset, unreadOnly]);

  // Initial load and when filters change
  useEffect(() => {
    setOffset(0);
    fetchNotifications(true);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [unreadOnly]);

  const handleMarkRead = async (id: string) => {
    try {
      await fetch('/api/notifications/mark-read', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        credentials: 'include',
        body: JSON.stringify({ notification_id: id }),
      });
      setNotifications(prev =>
        prev.map(n => (n.id === id ? { ...n, is_read: true, read_at: new Date().toISOString() } : n))
      );
    } catch (err) {
      log.error('Failed to mark notification as read:', err);
    }
  };

  const handleMarkAllRead = async () => {
    try {
      await fetch('/api/notifications/mark-all-read', {
        method: 'POST',
        credentials: 'include',
      });
      setNotifications(prev =>
        prev.map(n => ({ ...n, is_read: true, read_at: new Date().toISOString() }))
      );
    } catch (err) {
      log.error('Failed to mark all notifications as read:', err);
    }
  };

  // Client-side module filter (API doesn't support module param)
  const filteredNotifications =
    moduleFilter === 'all'
      ? notifications
      : notifications.filter(n => n.source_module === moduleFilter);

  const unreadCount = notifications.filter(n => !n.is_read).length;

  return (
    <div className="space-y-4">
      {/* Toolbar */}
      <div className="flex items-center justify-between flex-wrap gap-3">
        <div className="flex items-center gap-2">
          <Bell className="w-5 h-5 text-[var(--ff-text-secondary)]" />
          <h3 className="text-sm font-medium text-[var(--ff-text-primary)]">
            Notifications
            {unreadCount > 0 && (
              <span className="ml-2 px-2 py-0.5 text-xs bg-blue-500/20 text-blue-400 rounded-full">
                {unreadCount} unread
              </span>
            )}
          </h3>
        </div>

        <div className="flex items-center gap-2">
          {/* Unread toggle */}
          <button
            type="button"
            onClick={() => setUnreadOnly(!unreadOnly)}
            className={cn(
              'flex items-center gap-1.5 px-3 py-1.5 text-xs font-medium rounded-lg border transition-colors',
              unreadOnly
                ? 'bg-blue-500/10 text-blue-400 border-blue-500/30'
                : 'text-[var(--ff-text-secondary)] border-[var(--ff-border-light)] hover:bg-[var(--ff-bg-tertiary)]'
            )}
          >
            <Filter className="w-3.5 h-3.5" />
            Unread only
          </button>

          {/* Mark all read */}
          {unreadCount > 0 && (
            <button
              type="button"
              onClick={handleMarkAllRead}
              className="flex items-center gap-1.5 px-3 py-1.5 text-xs font-medium text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)] border border-[var(--ff-border-light)] rounded-lg hover:bg-[var(--ff-bg-tertiary)] transition-colors"
            >
              <CheckCheck className="w-3.5 h-3.5" />
              Mark all read
            </button>
          )}

          {/* Refresh */}
          <button
            type="button"
            onClick={() => fetchNotifications(true)}
            disabled={isLoading}
            className="flex items-center gap-1.5 px-3 py-1.5 text-xs font-medium text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)] border border-[var(--ff-border-light)] rounded-lg hover:bg-[var(--ff-bg-tertiary)] transition-colors disabled:opacity-50"
          >
            <RefreshCw className={cn('w-3.5 h-3.5', isLoading && 'animate-spin')} />
          </button>
        </div>
      </div>

      {/* Module filter chips */}
      <div className="flex items-center gap-1.5 flex-wrap">
        {MODULE_FILTERS.map(f => (
          <button
            key={f.key}
            type="button"
            onClick={() => setModuleFilter(f.key)}
            className={cn(
              'px-3 py-1 text-xs font-medium rounded-full border transition-colors',
              moduleFilter === f.key
                ? 'bg-[var(--ff-primary)] text-white border-[var(--ff-primary)]'
                : 'text-[var(--ff-text-secondary)] border-[var(--ff-border-light)] hover:bg-[var(--ff-bg-tertiary)]'
            )}
          >
            {f.label}
          </button>
        ))}
      </div>

      {/* Notification list */}
      {isLoading && notifications.length === 0 ? (
        <div className="flex items-center justify-center py-12">
          <RefreshCw className="w-5 h-5 animate-spin text-[var(--ff-text-tertiary)]" />
          <span className="ml-2 text-sm text-[var(--ff-text-secondary)]">Loading notifications...</span>
        </div>
      ) : filteredNotifications.length === 0 ? (
        <div className="text-center py-12">
          <Bell className="w-10 h-10 mx-auto text-[var(--ff-text-tertiary)] mb-3" />
          <p className="text-sm text-[var(--ff-text-secondary)]">
            {unreadOnly && moduleFilter !== 'all'
              ? `No unread ${moduleFilter} notifications`
              : unreadOnly
                ? 'No unread notifications'
                : moduleFilter !== 'all'
                  ? `No ${moduleFilter} notifications`
                  : 'No notifications yet'}
          </p>
          <p className="text-xs text-[var(--ff-text-tertiary)] mt-1">
            {moduleFilter !== 'all'
              ? `Notifications from the ${moduleFilter} module will appear here.`
              : 'Notifications from maintenance, procurement, and other modules will appear here.'}
          </p>
        </div>
      ) : (
        <div className="space-y-2">
          {filteredNotifications.map(notification => (
            <NotificationItem
              key={notification.id}
              notification={notification}
              onMarkRead={handleMarkRead}
            />
          ))}

          {/* Load more */}
          {hasMore && (
            <div className="flex justify-center pt-4">
              <button
                type="button"
                onClick={() => fetchNotifications(false)}
                disabled={isLoading}
                className="px-4 py-2 text-sm font-medium text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)] border border-[var(--ff-border-light)] rounded-lg hover:bg-[var(--ff-bg-tertiary)] transition-colors disabled:opacity-50"
              >
                {isLoading ? 'Loading...' : 'Load more'}
              </button>
            </div>
          )}
        </div>
      )}
    </div>
  );
}

/**
 * Internal Messages API
 * GET  - List inbox/sent/archived messages (paginated)
 * POST - Send a new message
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { neon } from '@neondatabase/serverless';
import { withAuth, type AuthenticatedNextApiRequest } from '@/lib/auth';
import { apiResponse } from '@/lib/apiResponse';
import { log } from '@/lib/logger';
import { notify } from '@/modules/notifications/services/notificationBus';

const sql = neon(process.env.DATABASE_URL!);

async function handler(req: NextApiRequest, res: NextApiResponse) {
  const authUser = (req as AuthenticatedNextApiRequest).user;
  const userId = authUser.id;

  if (req.method === 'GET') {
    return handleGet(req, res, userId);
  }

  if (req.method === 'POST') {
    return handlePost(req, res, userId, authUser.name || authUser.email);
  }

  return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET', 'POST']);
}

async function handleGet(req: NextApiRequest, res: NextApiResponse, userId: string) {
  try {
    const view = (req.query.view as string) || 'inbox';
    const limit = Math.min(parseInt(req.query.limit as string || '20', 10) || 20, 100);
    const offset = parseInt(req.query.offset as string || '0', 10) || 0;
    const unreadOnly = req.query.unread_only === 'true';

    if (view === 'sent') {
      return fetchSent(res, userId, limit, offset);
    }

    if (view === 'archived') {
      return fetchRecipientView(res, userId, limit, offset, false, true);
    }

    // Default: inbox (not archived)
    return fetchRecipientView(res, userId, limit, offset, unreadOnly, false);
  } catch (error) {
    log.error('Failed to fetch messages', { error }, 'Messages');
    return apiResponse.internalError(res, error);
  }
}

async function fetchRecipientView(
  res: NextApiResponse,
  userId: string,
  limit: number,
  offset: number,
  unreadOnly: boolean,
  archived: boolean
) {
  // Root messages only (thread_id IS NULL) where user is a recipient
  if (unreadOnly) {
    const messages = await sql`
      SELECT
        m.id, m.sender_id, m.subject, m.body, m.priority,
        m.thread_id, m.context_module, m.context_url, m.created_at,
        COALESCE(u.first_name || ' ' || u.last_name, u.email) AS sender_name,
        u.email AS sender_email,
        r.is_read,
        (SELECT COUNT(*)::int FROM internal_messages WHERE thread_id = m.id) AS reply_count,
        (SELECT COUNT(*)::int FROM internal_message_recipients WHERE message_id = m.id) AS recipient_count,
        (SELECT MAX(created_at) FROM internal_messages WHERE thread_id = m.id) AS latest_reply_at
      FROM internal_messages m
      INNER JOIN internal_message_recipients r ON r.message_id = m.id AND r.recipient_id = ${userId}::uuid
      INNER JOIN users u ON u.id = m.sender_id
      WHERE m.thread_id IS NULL
        AND r.is_archived = ${archived}
        AND r.is_read = FALSE
      ORDER BY COALESCE(
        (SELECT MAX(created_at) FROM internal_messages WHERE thread_id = m.id),
        m.created_at
      ) DESC
      LIMIT ${limit} OFFSET ${offset}
    `;

    const countResult = await sql`
      SELECT COUNT(*)::int AS total
      FROM internal_messages m
      INNER JOIN internal_message_recipients r ON r.message_id = m.id AND r.recipient_id = ${userId}::uuid
      WHERE m.thread_id IS NULL
        AND r.is_archived = ${archived}
        AND r.is_read = FALSE
    `;

    return apiResponse.success(res, {
      messages,
      total: Number(countResult[0]?.total || 0),
    });
  }

  // All messages (read + unread)
  const messages = await sql`
    SELECT
      m.id, m.sender_id, m.subject, m.body, m.priority,
      m.thread_id, m.context_module, m.context_url, m.created_at,
      COALESCE(u.first_name || ' ' || u.last_name, u.email) AS sender_name,
      u.email AS sender_email,
      r.is_read,
      (SELECT COUNT(*)::int FROM internal_messages WHERE thread_id = m.id) AS reply_count,
      (SELECT COUNT(*)::int FROM internal_message_recipients WHERE message_id = m.id) AS recipient_count,
      (SELECT MAX(created_at) FROM internal_messages WHERE thread_id = m.id) AS latest_reply_at
    FROM internal_messages m
    INNER JOIN internal_message_recipients r ON r.message_id = m.id AND r.recipient_id = ${userId}::uuid
    INNER JOIN users u ON u.id = m.sender_id
    WHERE m.thread_id IS NULL
      AND r.is_archived = ${archived}
    ORDER BY COALESCE(
      (SELECT MAX(created_at) FROM internal_messages WHERE thread_id = m.id),
      m.created_at
    ) DESC
    LIMIT ${limit} OFFSET ${offset}
  `;

  const countResult = await sql`
    SELECT COUNT(*)::int AS total
    FROM internal_messages m
    INNER JOIN internal_message_recipients r ON r.message_id = m.id AND r.recipient_id = ${userId}::uuid
    WHERE m.thread_id IS NULL
      AND r.is_archived = ${archived}
  `;

  return apiResponse.success(res, {
    messages,
    total: Number(countResult[0]?.total || 0),
  });
}

async function fetchSent(
  res: NextApiResponse,
  userId: string,
  limit: number,
  offset: number
) {
  const messages = await sql`
    SELECT
      m.id, m.sender_id, m.subject, m.body, m.priority,
      m.thread_id, m.context_module, m.context_url, m.created_at,
      COALESCE(u.first_name || ' ' || u.last_name, u.email) AS sender_name,
      u.email AS sender_email,
      TRUE AS is_read,
      (SELECT COUNT(*)::int FROM internal_messages WHERE thread_id = m.id) AS reply_count,
      (SELECT COUNT(*)::int FROM internal_message_recipients WHERE message_id = m.id) AS recipient_count,
      (SELECT MAX(created_at) FROM internal_messages WHERE thread_id = m.id) AS latest_reply_at
    FROM internal_messages m
    INNER JOIN users u ON u.id = m.sender_id
    WHERE m.sender_id = ${userId}::uuid
      AND m.thread_id IS NULL
    ORDER BY m.created_at DESC
    LIMIT ${limit} OFFSET ${offset}
  `;

  const countResult = await sql`
    SELECT COUNT(*)::int AS total
    FROM internal_messages m
    WHERE m.sender_id = ${userId}::uuid
      AND m.thread_id IS NULL
  `;

  return apiResponse.success(res, {
    messages,
    total: Number(countResult[0]?.total || 0),
  });
}

async function handlePost(
  req: NextApiRequest,
  res: NextApiResponse,
  userId: string,
  senderName: string
) {
  try {
    const { recipients, subject, body, priority, threadId, contextModule, contextId, contextUrl } = req.body;

    if (!body || typeof body !== 'string' || !body.trim()) {
      return apiResponse.badRequest(res, 'Message body is required');
    }

    if (!recipients || !Array.isArray(recipients) || recipients.length === 0) {
      return apiResponse.badRequest(res, 'At least one recipient is required');
    }

    // Insert message
    const messageRows = await sql`
      INSERT INTO internal_messages (
        sender_id, subject, body, priority,
        thread_id, context_module, context_id, context_url
      ) VALUES (
        ${userId}::uuid,
        ${subject?.trim() || null},
        ${body.trim()},
        ${priority || 'normal'},
        ${threadId || null},
        ${contextModule || null},
        ${contextId || null},
        ${contextUrl || null}
      )
      RETURNING *
    `;

    const message = messageRows[0];

    // Insert recipients
    for (const recipientId of recipients) {
      await sql`
        INSERT INTO internal_message_recipients (message_id, recipient_id)
        VALUES (${message.id}, ${recipientId}::uuid)
        ON CONFLICT (message_id, recipient_id) DO NOTHING
      `;
    }

    // Trigger notifications (fire-and-forget)
    const notifSubject = subject?.trim() || body.trim().substring(0, 100);
    notify({
      event_type: 'messaging.new_message',
      title: `${senderName} sent you a message`,
      body: notifSubject,
      icon: 'mail',
      severity: priority === 'urgent' ? 'warning' : 'info',
      action_url: '/communications?tab=inbox',
      source_module: 'messaging',
      source_id: message.id,
      recipient_user_ids: recipients,
    }).catch(err => {
      log.error('Failed to send message notification', { error: err }, 'Messages');
    });

    log.info('Internal message sent', {
      messageId: message.id,
      sender: userId,
      recipientCount: recipients.length,
      isReply: !!threadId,
    }, 'Messages');

    return apiResponse.created(res, message, 'Message sent');
  } catch (error) {
    log.error('Failed to send message', { error }, 'Messages');
    return apiResponse.internalError(res, error);
  }
}

export default withAuth(handler);

/**
 * Hook for internal messages data fetching
 */

import { useState, useEffect, useCallback, useRef } from 'react';
import { log } from '@/lib/logger';
import type { MessageListItem, MessageView } from '../types/messaging.types';

const PAGE_SIZE = 20;
const UNREAD_POLL_MS = 30_000;

interface UseInternalMessagesReturn {
  messages: MessageListItem[];
  isLoading: boolean;
  hasMore: boolean;
  total: number;
  unreadCount: number;
  refetch: () => Promise<void>;
  loadMore: () => Promise<void>;
  markRead: (messageIds: string[]) => Promise<void>;
  markAllRead: () => Promise<void>;
  archiveMessages: (messageIds: string[]) => Promise<void>;
}

export function useInternalMessages(view: MessageView): UseInternalMessagesReturn {
  const [messages, setMessages] = useState<MessageListItem[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [hasMore, setHasMore] = useState(false);
  const [total, setTotal] = useState(0);
  const [offset, setOffset] = useState(0);
  const [unreadCount, setUnreadCount] = useState(0);
  const pollRef = useRef<ReturnType<typeof setInterval>>();

  const fetchMessages = useCallback(async (reset = false) => {
    setIsLoading(true);
    const currentOffset = reset ? 0 : offset;
    try {
      const params = new URLSearchParams({
        view,
        limit: String(PAGE_SIZE),
        offset: String(currentOffset),
      });

      const res = await fetch(`/api/communications/messages?${params}`, {
        credentials: 'include',
      });
      const json = await res.json();

      if (json.success) {
        const items: MessageListItem[] = json.data.messages;
        if (reset) {
          setMessages(items);
          setOffset(items.length);
        } else {
          setMessages(prev => [...prev, ...items]);
          setOffset(currentOffset + items.length);
        }
        setTotal(json.data.total);
        setHasMore(items.length === PAGE_SIZE);
      }
    } catch (err) {
      log.error('Failed to fetch messages:', err);
    } finally {
      setIsLoading(false);
    }
  }, [offset, view]);

  const fetchUnreadCount = useCallback(async () => {
    try {
      const res = await fetch('/api/communications/messages-unread-count', {
        credentials: 'include',
      });
      const json = await res.json();
      if (json.success) {
        setUnreadCount(json.data.count);
      }
    } catch {
      // Silently ignore polling errors
    }
  }, []);

  const markRead = useCallback(async (messageIds: string[]) => {
    try {
      await fetch('/api/communications/messages-read', {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        credentials: 'include',
        body: JSON.stringify({ messageIds }),
      });
      // Optimistic update
      setMessages(prev =>
        prev.map(m =>
          messageIds.includes(m.id) ? { ...m, is_read: true } : m
        )
      );
      setUnreadCount(prev => Math.max(0, prev - messageIds.length));
    } catch (err) {
      log.error('Failed to mark messages as read:', err);
    }
  }, []);

  const markAllRead = useCallback(async () => {
    const unreadIds = messages.filter(m => !m.is_read).map(m => m.id);
    if (unreadIds.length === 0) return;
    await markRead(unreadIds);
  }, [messages, markRead]);

  const archiveMessages = useCallback(async (messageIds: string[]) => {
    try {
      await fetch('/api/communications/messages-archive', {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        credentials: 'include',
        body: JSON.stringify({ messageIds }),
      });
      // Remove from current list
      setMessages(prev => prev.filter(m => !messageIds.includes(m.id)));
      setTotal(prev => prev - messageIds.length);
    } catch (err) {
      log.error('Failed to archive messages:', err);
    }
  }, []);

  // Fetch messages on mount and when view changes
  useEffect(() => {
    fetchMessages(true);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [view]);

  // Poll unread count
  useEffect(() => {
    fetchUnreadCount();
    pollRef.current = setInterval(fetchUnreadCount, UNREAD_POLL_MS);
    return () => {
      if (pollRef.current) clearInterval(pollRef.current);
    };
  }, [fetchUnreadCount]);

  return {
    messages,
    isLoading,
    hasMore,
    total,
    unreadCount,
    refetch: () => fetchMessages(true),
    loadMore: () => fetchMessages(false),
    markRead,
    markAllRead,
    archiveMessages,
  };
}

/**
 * Inbox Panel — unified feed + messaging views
 * Views: Feed (default) | Messages | Sent | Archived with compose modal and thread view
 */

import { useState } from 'react';
import {
  Inbox,
  Send,
  Archive,
  PenLine,
  CheckCheck,
  RefreshCw,
  Mail,
  Rss,
} from 'lucide-react';
import { cn } from '@/lib/utils';
import { useInternalMessages } from '../hooks/useInternalMessages';
import { MessageListItem } from './MessageListItem';
import { MessageThread } from './MessageThread';
import { ComposeMessageModal } from './ComposeMessageModal';
import { UnifiedFeedList } from './UnifiedFeedList';
import type { MessageView } from '../types/messaging.types';

type PanelView = 'feed' | MessageView;

const VIEWS: { key: PanelView; label: string; icon: React.ElementType }[] = [
  { key: 'feed', label: 'Feed', icon: Rss },
  { key: 'inbox', label: 'Messages', icon: Inbox },
  { key: 'sent', label: 'Sent', icon: Send },
  { key: 'archived', label: 'Archived', icon: Archive },
];

export function InboxPanel() {
  const [view, setView] = useState<PanelView>('feed');
  const [activeThread, setActiveThread] = useState<string | null>(null);
  const [showCompose, setShowCompose] = useState(false);

  // Messages hook — only needed for messaging views, pass 'inbox' when on feed
  const messageView: MessageView = view === 'feed' ? 'inbox' : view;
  const {
    messages,
    isLoading,
    hasMore,
    total,
    unreadCount,
    refetch,
    loadMore,
    markRead,
    markAllRead,
  } = useInternalMessages(messageView);

  const handleOpenThread = (messageId: string) => {
    // If opening from feed, switch to messages view context
    if (view === 'feed') {
      setView('inbox');
    }
    const msg = messages.find(m => m.id === messageId);
    if (msg && !msg.is_read) {
      markRead([messageId]);
    }
    setActiveThread(messageId);
  };

  const handleBackFromThread = () => {
    setActiveThread(null);
    refetch();
  };

  const handleMessageSent = () => {
    refetch();
  };

  // Thread view (shared between feed and messages)
  if (activeThread) {
    return (
      <MessageThread threadId={activeThread} onBack={handleBackFromThread} />
    );
  }

  const isFeed = view === 'feed';

  return (
    <div className="space-y-4">
      {/* Top bar: view toggle + actions */}
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-1">
          {VIEWS.map(v => {
            const Icon = v.icon;
            const isActive = view === v.key;
            return (
              <button
                key={v.key}
                type="button"
                onClick={() => setView(v.key)}
                className={cn(
                  'flex items-center gap-1.5 px-3 py-1.5 text-xs font-medium rounded-lg transition-colors',
                  isActive
                    ? 'bg-[var(--ff-primary)]/10 text-[var(--ff-primary)]'
                    : 'text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)] hover:bg-[var(--ff-bg-tertiary)]'
                )}
              >
                <Icon className="w-3.5 h-3.5" />
                {v.label}
                {v.key === 'inbox' && unreadCount > 0 && (
                  <span className="px-1.5 py-0.5 text-[10px] font-semibold bg-blue-500 text-white rounded-full">
                    {unreadCount}
                  </span>
                )}
              </button>
            );
          })}
        </div>

        <div className="flex items-center gap-2">
          {view === 'inbox' && unreadCount > 0 && (
            <button
              type="button"
              onClick={markAllRead}
              className="flex items-center gap-1.5 px-3 py-1.5 text-xs font-medium text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)] border border-[var(--ff-border-light)] rounded-lg hover:bg-[var(--ff-bg-tertiary)] transition-colors"
            >
              <CheckCheck className="w-3.5 h-3.5" />
              Mark all read
            </button>
          )}

          {!isFeed && (
            <button
              type="button"
              onClick={() => refetch()}
              disabled={isLoading}
              className="flex items-center gap-1.5 px-3 py-1.5 text-xs font-medium text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)] border border-[var(--ff-border-light)] rounded-lg hover:bg-[var(--ff-bg-tertiary)] transition-colors disabled:opacity-50"
            >
              <RefreshCw className={cn('w-3.5 h-3.5', isLoading && 'animate-spin')} />
            </button>
          )}

          <button
            type="button"
            onClick={() => setShowCompose(true)}
            className="flex items-center gap-1.5 px-4 py-1.5 text-sm font-medium bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors"
          >
            <PenLine className="w-3.5 h-3.5" />
            Compose
          </button>
        </div>
      </div>

      {/* Feed view */}
      {isFeed ? (
        <UnifiedFeedList onOpenThread={handleOpenThread} />
      ) : (
        <>
          {/* Message count */}
          <p className="text-xs text-[var(--ff-text-tertiary)]">
            {total > 0
              ? `${total} message${total !== 1 ? 's' : ''}${view === 'inbox' && unreadCount > 0 ? ` (${unreadCount} unread)` : ''}`
              : ''}
          </p>

          {/* Message list */}
          {isLoading && messages.length === 0 ? (
            <div className="flex items-center justify-center py-12">
              <RefreshCw className="w-5 h-5 animate-spin text-[var(--ff-text-tertiary)]" />
              <span className="ml-2 text-sm text-[var(--ff-text-secondary)]">Loading messages...</span>
            </div>
          ) : messages.length === 0 ? (
            <div className="text-center py-12">
              <Mail className="w-10 h-10 mx-auto text-[var(--ff-text-tertiary)] mb-3" />
              <p className="text-sm text-[var(--ff-text-secondary)]">
                {view === 'inbox' ? 'Your inbox is empty' :
                 view === 'sent' ? 'No sent messages' :
                 'No archived messages'}
              </p>
              {view === 'inbox' && (
                <button
                  type="button"
                  onClick={() => setShowCompose(true)}
                  className="mt-3 text-sm text-blue-500 hover:text-blue-400"
                >
                  Send your first message
                </button>
              )}
            </div>
          ) : (
            <div className="border border-[var(--ff-border-light)] rounded-lg overflow-hidden">
              {messages.map(msg => (
                <MessageListItem
                  key={msg.id}
                  message={msg}
                  onClick={handleOpenThread}
                  showSender={view !== 'sent'}
                />
              ))}

              {hasMore && (
                <div className="flex justify-center py-3 border-t border-[var(--ff-border-light)]">
                  <button
