                  <span className="px-1.5 py-0.5 text-[10px] font-semibold bg-blue-500 text-white rounded-full">
                    {unreadCount}
                  </span>
                )}
              </button>
            );
          })}
        </div>

        <div className="flex items-center gap-2">
          {view === 'inbox' && unreadCount > 0 && !selectionMode && (
            <button
              type="button"
              onClick={markAllRead}
