                  key={msg.id}
                  message={msg}
                  onClick={handleOpenThread}
                  showSender={view !== 'sent'}
                  showCheckbox={selectionMode}
                  isSelected={selectedIds.has(msg.id)}
                  onToggleSelect={handleToggleSelect}
