/**
 * Inbox Panel — unified feed + messaging views
 * Views: Feed (default) | Messages | Sent | Archived with compose modal and thread view
 */

import { useState } from 'react';
import {
  Inbox,
  Send,
  Archive,
  PenLine,
  CheckCheck,
  RefreshCw,
  Mail,
  Rss,
} from 'lucide-react';
import { cn } from '@/lib/utils';
import { useInternalMessages } from '../hooks/useInternalMessages';
import { MessageListItem } from './MessageListItem';
import { MessageThread } from './MessageThread';
import { ComposeMessageModal } from './ComposeMessageModal';
import { UnifiedFeedList } from './UnifiedFeedList';
import type { MessageView } from '../types/messaging.types';

type PanelView = 'feed' | MessageView;

const VIEWS: { key: PanelView; label: string; icon: React.ElementType }[] = [
  { key: 'feed', label: 'Feed', icon: Rss },
  { key: 'inbox', label: 'Messages', icon: Inbox },
  { key: 'sent', label: 'Sent', icon: Send },
  { key: 'archived', label: 'Archived', icon: Archive },
];

export function InboxPanel() {
  const [view, setView] = useState<PanelView>('feed');
  const [activeThread, setActiveThread] = useState<string | null>(null);
  const [showCompose, setShowCompose] = useState(false);

  // Messages hook — only needed for messaging views, pass 'inbox' when on feed
  const messageView: MessageView = view === 'feed' ? 'inbox' : view;
  const {
    messages,
    isLoading,
    hasMore,
    total,
    unreadCount,
    refetch,
    loadMore,
    markRead,
    markAllRead,
  } = useInternalMessages(messageView);

  const handleOpenThread = (messageId: string) => {
    // If opening from feed, switch to messages view context
    if (view === 'feed') {
      setView('inbox');
    }
    const msg = messages.find(m => m.id === messageId);
    if (msg && !msg.is_read) {
      markRead([messageId]);
    }
    setActiveThread(messageId);
  };

  const handleBackFromThread = () => {
    setActiveThread(null);
    refetch();
  };

  const handleMessageSent = () => {
    refetch();
  };

  // Thread view (shared between feed and messages)
  if (activeThread) {
    return (
      <MessageThread threadId={activeThread} onBack={handleBackFromThread} />
    );
  }

  const isFeed = view === 'feed';

  return (
    <div className="space-y-4">
      {/* Top bar: view toggle + actions */}
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-1">
          {VIEWS.map(v => {
            const Icon = v.icon;
            const isActive = view === v.key;
            return (
              <button
                key={v.key}
                type="button"
                onClick={() => setView(v.key)}
                className={cn(
                  'flex items-center gap-1.5 px-3 py-1.5 text-xs font-medium rounded-lg transition-colors',
                  isActive
                    ? 'bg-[var(--ff-primary)]/10 text-[var(--ff-primary)]'
                    : 'text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)] hover:bg-[var(--ff-bg-tertiary)]'
                )}
              >
                <Icon className="w-3.5 h-3.5" />
                {v.label}
                {v.key === 'inbox' && unreadCount > 0 && (
                  <span className="px-1.5 py-0.5 text-[10px] font-semibold bg-blue-500 text-white rounded-full">
                    {unreadCount}
                  </span>
                )}
              </button>
            );
          })}
        </div>

        <div className="flex items-center gap-2">
          {view === 'inbox' && unreadCount > 0 && (
            <button
              type="button"
              onClick={markAllRead}
              className="flex items-center gap-1.5 px-3 py-1.5 text-xs font-medium text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)] border border-[var(--ff-border-light)] rounded-lg hover:bg-[var(--ff-bg-tertiary)] transition-colors"
            >
              <CheckCheck className="w-3.5 h-3.5" />
              Mark all read
            </button>
          )}

          {!isFeed && (
            <button
              type="button"
              onClick={() => refetch()}
              disabled={isLoading}
              className="flex items-center gap-1.5 px-3 py-1.5 text-xs font-medium text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)] border border-[var(--ff-border-light)] rounded-lg hover:bg-[var(--ff-bg-tertiary)] transition-colors disabled:opacity-50"
            >
              <RefreshCw className={cn('w-3.5 h-3.5', isLoading && 'animate-spin')} />
            </button>
          )}

          <button
            type="button"
            onClick={() => setShowCompose(true)}
            className="flex items-center gap-1.5 px-4 py-1.5 text-sm font-medium bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors"
          >
            <PenLine className="w-3.5 h-3.5" />
            Compose
          </button>
        </div>
      </div>

      {/* Feed view */}
      {isFeed ? (
        <UnifiedFeedList onOpenThread={handleOpenThread} />
      ) : (
        <>
          {/* Message count */}
          <p className="text-xs text-[var(--ff-text-tertiary)]">
            {total > 0
              ? `${total} message${total !== 1 ? 's' : ''}${view === 'inbox' && unreadCount > 0 ? ` (${unreadCount} unread)` : ''}`
              : ''}
          </p>

          {/* Message list */}
          {isLoading && messages.length === 0 ? (
            <div className="flex items-center justify-center py-12">
              <RefreshCw className="w-5 h-5 animate-spin text-[var(--ff-text-tertiary)]" />
              <span className="ml-2 text-sm text-[var(--ff-text-secondary)]">Loading messages...</span>
            </div>
          ) : messages.length === 0 ? (
            <div className="text-center py-12">
              <Mail className="w-10 h-10 mx-auto text-[var(--ff-text-tertiary)] mb-3" />
              <p className="text-sm text-[var(--ff-text-secondary)]">
                {view === 'inbox' ? 'Your inbox is empty' :
                 view === 'sent' ? 'No sent messages' :
                 'No archived messages'}
              </p>
              {view === 'inbox' && (
                <button
                  type="button"
                  onClick={() => setShowCompose(true)}
                  className="mt-3 text-sm text-blue-500 hover:text-blue-400"
                >
                  Send your first message
                </button>
              )}
            </div>
          ) : (
            <div className="border border-[var(--ff-border-light)] rounded-lg overflow-hidden">
              {messages.map(msg => (
                <MessageListItem
                  key={msg.id}
                  message={msg}
                  onClick={handleOpenThread}
                  showSender={view !== 'sent'}
                />
              ))}

              {hasMore && (
                <div className="flex justify-center py-3 border-t border-[var(--ff-border-light)]">
                  <button
                    type="button"
                    onClick={loadMore}
                    disabled={isLoading}
                    className="px-4 py-1.5 text-sm font-medium text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)] border border-[var(--ff-border-light)] rounded-lg hover:bg-[var(--ff-bg-tertiary)] transition-colors disabled:opacity-50"
                  >
                    {isLoading ? 'Loading...' : 'Load more'}
                  </button>
                </div>
              )}
            </div>
          )}
        </>
      )}

      {/* Compose modal */}
      <ComposeMessageModal
        isOpen={showCompose}
        onClose={() => setShowCompose(false)}
        onSent={handleMessageSent}
      />
    </div>
  );
}

'use client';

/**
 * NotificationPreferencesGrid
 * Renders a grouped table of notification event types with channel checkboxes.
 * Rows = event types, Columns = in_app, email, whatsapp
 * Events are grouped by their MODULE (e.g. Maintenance, Projects, Procurement).
 */

import React from 'react';
import { cn } from '@/lib/utils';
import type { MergedPreference } from '@/modules/notifications/types';

interface NotificationPreferencesGridProps {
  preferences: MergedPreference[];
  updatePreference: (
    eventType: string,
    channel: 'in_app' | 'email' | 'whatsapp',
    value: boolean
  ) => void;
}

interface GroupedPreferences {
  [group: string]: MergedPreference[];
}

const CHANNEL_COLUMNS: { key: 'in_app' | 'email' | 'whatsapp'; label: string }[] = [
  { key: 'in_app', label: 'In-App' },
  { key: 'email', label: 'Email' },
  { key: 'whatsapp', label: 'WhatsApp' },
];

/** Group preferences by their `group` field, preserving insertion order */
function groupPreferences(preferences: MergedPreference[]): GroupedPreferences {
  return preferences.reduce<GroupedPreferences>((acc, pref) => {
    const key = pref.group || 'Other';
    if (!acc[key]) {
      acc[key] = [];
    }
    acc[key].push(pref);
    return acc;
  }, {});
}

/** Single channel checkbox cell */
function ChannelCheckbox({
  checked,
  onChange,
  label,
}: {
  checked: boolean;
  onChange: (value: boolean) => void;
  label: string;
}) {
  return (
    <td className="px-4 py-2.5 text-center">
      <input
        type="checkbox"
        checked={checked}
        onChange={e => onChange(e.target.checked)}
        aria-label={label}
        className="w-4 h-4 rounded accent-[var(--ff-primary)] cursor-pointer"
      />
    </td>
  );
}

export function NotificationPreferencesGrid({
  preferences,
  updatePreference,
}: NotificationPreferencesGridProps) {
  const grouped = groupPreferences(preferences);
  const groups = Object.keys(grouped);

  if (preferences.length === 0) {
    return (
      <p className="text-sm text-[var(--ff-text-secondary)] text-center py-8">
        No notification preferences available.
      </p>
    );
  }

  return (
    <div className="overflow-x-auto rounded-lg border border-[var(--ff-border-light)]">
      <table className="w-full text-sm">
        <thead>
          <tr className="border-b border-[var(--ff-border-light)] bg-[var(--ff-bg-tertiary)]">
            <th className="px-4 py-3 text-left font-medium text-[var(--ff-text-secondary)]">
              Event
            </th>
            {CHANNEL_COLUMNS.map(col => (
              <th
                key={col.key}
                className="px-4 py-3 text-center font-medium text-[var(--ff-text-secondary)] w-24"
              >
                {col.label}
              </th>
            ))}
          </tr>
        </thead>
        <tbody>
          {groups.map(group => (
            <React.Fragment key={group}>
              {/* Group header row */}
              <tr className="bg-[var(--ff-bg-secondary)]">
                <td
                  colSpan={4}
                  className="px-4 py-2 text-xs font-semibold uppercase tracking-wider text-[var(--ff-text-tertiary)]"
                >
                  {group}
                </td>
              </tr>
              {/* Event rows */}
              {grouped[group].map((pref, idx) => (
                <tr
                  key={pref.event_type}
                  className={cn(
                    'border-t border-[var(--ff-border-light)] transition-colors',
                    'hover:bg-[var(--ff-bg-tertiary)]',
                    idx % 2 === 0
                      ? 'bg-[var(--ff-bg-primary)]'
                      : 'bg-[var(--ff-bg-secondary)]'
                  )}
                >
                  <td className="px-4 py-2.5">
                    <span className="text-[var(--ff-text-primary)]">{pref.label}</span>
                    {pref.is_user_override && (
                      <span className="ml-2 px-1.5 py-0.5 text-[10px] font-medium bg-[var(--ff-primary)]/10 text-[var(--ff-primary)] rounded">
                        custom
                      </span>
                    )}
                  </td>
                  <ChannelCheckbox
                    checked={pref.channel_in_app}
                    onChange={v => updatePreference(pref.event_type, 'in_app', v)}
                    label={`${pref.label} in-app`}
                  />
                  <ChannelCheckbox
                    checked={pref.channel_email}
                    onChange={v => updatePreference(pref.event_type, 'email', v)}
                    label={`${pref.label} email`}
                  />
                  <ChannelCheckbox
                    checked={pref.channel_whatsapp}
                    onChange={v => updatePreference(pref.event_type, 'whatsapp', v)}
                    label={`${pref.label} WhatsApp`}
                  />
                </tr>
              ))}
            </React.Fragment>
          ))}
        </tbody>
      </table>
    </div>
  );
}

