sql\`
  UPDATE gl_accounts SET default_vat_code = CASE
    -- Balance sheet, equity, control accounts → none
    WHEN account_type IN ('asset', 'equity', 'liability') THEN 'none'
    -- Tax/payroll/depreciation expense subtypes → none
    WHEN account_subtype IN ('tax', 'accumulated_depreciation', 'retained_earnings') THEN 'none'
    -- Salary, wages, PAYE, UIF, SDL, depreciation by name → none
    WHEN account_name ILIKE '%salary%' OR account_name ILIKE '%salaries%'
      OR account_name ILIKE '%wages%' OR account_name ILIKE '%wage%'
      OR account_name ILIKE '%paye%' OR account_name ILIKE '%uif%'
      OR account_name ILIKE '%sdl%' OR account_name ILIKE '%depreciation%' THEN 'none'
    -- Interest & bank charges → exempt in SA (financial services)
    WHEN account_name ILIKE '%interest%' OR account_name ILIKE '%bank charge%' THEN 'exempt'
    -- Forex, bad debts, discounts, suspense, income tax → none
    WHEN account_name ILIKE '%forex%' OR account_name ILIKE '%bad debt%'
      OR account_name ILIKE '%discount%' OR account_name ILIKE '%suspense%'
      OR account_name ILIKE '%income tax%' THEN 'none'
    -- All remaining expense & revenue accounts → standard 15%
    WHEN account_type IN ('expense', 'revenue') THEN 'standard'
    ELSE 'none'
  END
  WHERE is_active = true
  RETURNING account_code, account_name, default_vat_code
\`.then(rows => {
  const byVat = rows.reduce((acc, r) => {
    (acc[r.default_vat_code] = acc[r.default_vat_code] || []).push(r);
