/**
 * Unified Notification Bus
 * Central entry point: all modules call notify(payload) to dispatch notifications.
 * Handles in-app storage + channel dispatch (email, WhatsApp).
 *
 * @module notifications/services/notificationBus
 */

import { neon } from '@neondatabase/serverless';
import { log } from '@/lib/logger';
import {
  DEFAULT_CHANNEL_PREFERENCES,
  EVENT_ICONS,
  EVENT_SEVERITY,
} from '../constants';
import type {
  NotifyPayload,
  UserNotification,
  ChannelPreferences,
} from '../types';
import { deliverEmail } from './emailDelivery';
import { deliverWhatsApp } from './whatsappDelivery';

const sql = neon(process.env.DATABASE_URL!);

// =============================================================================
// Core notify() function
// =============================================================================

/**
 * Send a notification to one or more users.
 * Creates in-app records and dispatches to email/WA based on preferences.
 * Non-blocking — errors are logged, never thrown to callers.
 */
export async function notify(payload: NotifyPayload): Promise<void> {
  const {
    event_type,
    title,
    body,
    action_url,
    source_module,
    source_id,
    metadata,
    recipient_user_ids,
  } = payload;

  if (!recipient_user_ids || recipient_user_ids.length === 0) {
    log.warn('notify() called with no recipients', { event_type }, 'NotificationBus');
    return;
  }

  const icon = payload.icon || EVENT_ICONS[event_type] || 'bell';
  const severity = payload.severity || EVENT_SEVERITY[event_type] || 'info';

  for (const userId of recipient_user_ids) {
    try {
      const channels = await getEffectiveChannels(userId, event_type);

      // Always create in-app notification if enabled
      let notificationId: string | null = null;
      if (channels.in_app) {
        const sourceIdValue = source_id || null;
        const result = await sql`
          INSERT INTO user_notifications (
            user_id, event_type, title, body, icon, severity,
            action_url, source_module, source_id, metadata
          ) VALUES (
            ${userId}::uuid, ${event_type}, ${title}, ${body || null},
            ${icon}, ${severity}, ${action_url || null},
            ${source_module || null}, ${sourceIdValue},
            ${JSON.stringify(metadata || {})}::jsonb
          )
          RETURNING id
        `;
        notificationId = result[0]?.id || null;
      }

      // Fire-and-forget email delivery
      if (channels.email) {
        deliverEmail(userId, payload, notificationId).catch(err =>
          log.error('Email delivery failed', {
            userId, event_type, error: err instanceof Error ? err.message : String(err),
          }, 'NotificationBus')
        );
      }

      // Fire-and-forget WhatsApp delivery
      if (channels.whatsapp) {
        deliverWhatsApp(userId, payload, notificationId).catch(err =>
          log.error('WA delivery failed', {
            userId, event_type, error: err instanceof Error ? err.message : String(err),
          }, 'NotificationBus')
        );
      }
    } catch (err) {
      log.error('notify() failed for user', {
        userId, event_type, error: err instanceof Error ? err.message : String(err),
      }, 'NotificationBus');
    }
  }
}

// =============================================================================
// Channel resolution
// =============================================================================

/**
 * Determine which channels a notification should be delivered to.
 * User overrides take priority, then system defaults, then _fallback.
 */
export async function getEffectiveChannels(
  userId: string,
  eventType: string
): Promise<ChannelPreferences> {
  try {
    const rows = await sql`
      SELECT channel_in_app, channel_email, channel_whatsapp
      FROM notification_preferences
      WHERE user_id = ${userId}::uuid AND event_type = ${eventType}
      LIMIT 1
    `;

    if (rows.length > 0 && rows[0]) {
      return {
        in_app: rows[0].channel_in_app,
        email: rows[0].channel_email,
        whatsapp: rows[0].channel_whatsapp,
      };
    }
  } catch (err) {
    log.error('Failed to load notification preferences', {
      userId, eventType, error: err instanceof Error ? err.message : String(err),
    }, 'NotificationBus');
  }

  // Fall back to system defaults
  const prefs = DEFAULT_CHANNEL_PREFERENCES[eventType] || DEFAULT_CHANNEL_PREFERENCES._fallback;
  return prefs || { in_app: true, email: false, whatsapp: false };
}

// =============================================================================
// Read helpers (for API routes)
// =============================================================================

/** Get unread notification count for a user */
export async function getUnreadCount(userId: string): Promise<number> {
  const result = await sql`
    SELECT COUNT(*)::int as count
    FROM user_notifications
    WHERE user_id = ${userId}::uuid AND is_read = FALSE
  `;
  return result[0]?.count || 0;
}

/** Get notification list for a user */
export async function getNotifications(
  userId: string,
  limit = 20,
  offset = 0,
  unreadOnly = false
): Promise<UserNotification[]> {
  if (unreadOnly) {
    const rows = await sql`
      SELECT * FROM user_notifications
      WHERE user_id = ${userId}::uuid AND is_read = FALSE
      ORDER BY created_at DESC
      LIMIT ${limit} OFFSET ${offset}
    `;
    return rows as UserNotification[];
  }

  const rows = await sql`
    SELECT * FROM user_notifications
    WHERE user_id = ${userId}::uuid
    ORDER BY created_at DESC
    LIMIT ${limit} OFFSET ${offset}
  `;
  return rows as UserNotification[];
}

/** Mark specific notifications as read */
export async function markAsRead(
  notificationIds: string[],
  userId: string
): Promise<number> {
  if (notificationIds.length === 0) return 0;

  const result = await sql`
    UPDATE user_notifications
    SET is_read = TRUE, read_at = NOW(), updated_at = NOW()
    WHERE id = ANY(${notificationIds}::uuid[])
      AND user_id = ${userId}::uuid
      AND is_read = FALSE
  `;
  return (result as unknown as { count: number }).count || notificationIds.length;
}

/** Mark all notifications as read for a user */
export async function markAllAsRead(userId: string): Promise<number> {
  const result = await sql`
    UPDATE user_notifications
    SET is_read = TRUE, read_at = NOW(), updated_at = NOW()
    WHERE user_id = ${userId}::uuid AND is_read = FALSE
  `;
  return (result as unknown as { count: number }).count || 0;
}

// WORKING: Convert Purchase Requisition to Purchase Order
// PRD-050 Phase 2: Core Procurement - PR to PO Conversion
import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { neon } from '@neondatabase/serverless';
import { apiResponse } from '@/lib/apiResponse';
import { log } from '@/lib/logger';
import { withAuth, type AuthenticatedNextApiRequest } from '@/lib/auth';

const sql = neon(process.env.DATABASE_URL!);

interface ConvertToPORequest {
  supplierId: number;
  deliveryAddress: string;
  expectedDeliveryDate?: string;
  paymentTerms?: string;
  notes?: string;
  itemIds?: string[]; // Optional: specific items to include, default all
}

export default withAuth(withErrorHandler(async (
  req: NextApiRequest,
  res: NextApiResponse
) => {
  if (req.method !== 'POST') {
    return apiResponse.methodNotAllowed(res, req.method!, ['POST']);
  }

  const { id } = req.query;
  const authReq = req as AuthenticatedNextApiRequest;
  const userId = authReq.user.id;
  const user = authReq.user;
  const body = req.body as ConvertToPORequest;

  if (!id || typeof id !== 'string') {
    return apiResponse.validationError(res, { id: 'Requisition ID is required' });
  }

  try {
    // Fetch the requisition
    const requisitions = await sql`
      SELECT
        pr.*,
        p.project_name as project_name
      FROM purchase_requisitions pr
      LEFT JOIN projects p ON pr.project_id = p.id
      WHERE pr.id = ${id}
    `;

    if (requisitions.length === 0) {
      return apiResponse.notFound(res, 'Purchase Requisition', id);
    }

    const requisition = requisitions[0]!;

    // Validate status - only approved PRs can be converted
    if (requisition.status !== 'approved') {
      return apiResponse.validationError(res, {
        status: `Cannot convert a requisition with status "${requisition.status}". Only approved requisitions can be converted to PO.`,
      });
    }

    // Validate supplier is provided
    if (!body.supplierId) {
      return apiResponse.validationError(res, { supplierId: 'Supplier is required' });
    }

    // Validate delivery address
    if (!body.deliveryAddress || body.deliveryAddress.trim().length < 10) {
      return apiResponse.validationError(res, {
        deliveryAddress: 'Delivery address is required (min 10 characters)',
      });
    }

    // Get supplier info
    const suppliers = await sql`
      SELECT id, company_name, contact_name, email, phone
      FROM suppliers WHERE id = ${body.supplierId}
    `;

    if (suppliers.length === 0) {
      return apiResponse.validationError(res, { supplierId: 'Supplier not found' });
    }

    const supplier = suppliers[0]!;

    // Fetch requisition items
    let itemsQuery;
    if (body.itemIds && body.itemIds.length > 0) {
      // Convert itemIds to proper query
      itemsQuery = await sql`
        SELECT * FROM purchase_requisition_items
        WHERE requisition_id = ${id}
        AND id = ANY(${body.itemIds}::uuid[])
        AND converted_to_po = false
        ORDER BY created_at
      `;
    } else {
      itemsQuery = await sql`
        SELECT * FROM purchase_requisition_items
        WHERE requisition_id = ${id}
        AND converted_to_po = false
        ORDER BY created_at
      `;
    }

    if (itemsQuery.length === 0) {
      return apiResponse.validationError(res, {
        items: 'No unconverted items found in this requisition',
      });
    }

    const items = itemsQuery;

    // Calculate totals
    const taxRate = 15;
    const subtotal = items.reduce((sum: number, item: Record<string, unknown>) => {
      const price = Number(item.estimated_unit_price) || 0;
      const qty = Number(item.quantity) || 0;
      return sum + Math.round(price * qty * 100) / 100;
    }, 0);

    const taxAmount = Math.round(subtotal * (taxRate / 100) * 100) / 100;
    const totalAmount = Math.round((subtotal + taxAmount) * 100) / 100;

    // Generate PO number
    const year = new Date().getFullYear();
    const seqResult = await sql`
      SELECT COUNT(*) + 1 as seq
      FROM purchase_orders
      WHERE po_number LIKE ${`PO-${year}-%`}
    `;
    const sequence = parseInt(String(seqResult[0]?.seq) || '1', 10);
    const poNumber = `PO-${year}-${String(sequence).padStart(4, '0')}`;

    // Create the Purchase Order
    const poResult = await sql`
      INSERT INTO purchase_orders (
        po_number,
        status,
        supplier_id,
        supplier_contact,
        project_id,
        cost_center_id,
        delivery_address,
        expected_delivery_date,
        payment_terms,
        currency,
        tax_rate,
        subtotal,
        tax_amount,
        total_amount,
        internal_notes,
        created_by,
        requisition_id
      ) VALUES (
        ${poNumber},
        'draft',
        ${body.supplierId},
        ${supplier.contact_name || null},
        ${requisition.project_id || null},
        ${requisition.cost_center_id || null},
        ${body.deliveryAddress.trim()},
        ${body.expectedDeliveryDate || null},
        ${body.paymentTerms || 'Net 30'},
        ${requisition.currency || 'ZAR'},
        ${taxRate},
        ${subtotal},
        ${taxAmount},
        ${totalAmount},
        ${body.notes || `Converted from PR ${requisition.requisition_number}`},
        ${user?.name || userId || 'system'},
        ${id}
      )
      RETURNING *
    `;

    const newPO = poResult[0]!;

    // Insert PO items
    for (let i = 0; i < items.length; i++) {
      const item = items[i]!;
      const unitPrice = Number(item.estimated_unit_price) || 0;
      const quantity = Number(item.quantity) || 0;
      const lineTotal = Math.round(unitPrice * quantity * 100) / 100;

      await sql`
        INSERT INTO purchase_order_items (
          purchase_order_id,
          item_code,
          stock_item_id,
          boq_item_id,
          item_description,
          quantity_ordered,
          uom,
          unit_price,
          total_price,
          requisition_item_id
        ) VALUES (
          ${newPO.id},
          ${item.item_code || `ITEM-${i + 1}`},
          ${item.stock_item_id || null},
          ${item.boq_item_id || null},
          ${item.item_description || 'Item'},
          ${quantity},
          ${item.uom || 'EA'},
          ${unitPrice},
          ${lineTotal},
          ${item.id}
        )
      `;

      // Mark requisition item as converted
      await sql`
        UPDATE purchase_requisition_items
        SET
          converted_to_po = true,
          po_id = ${newPO.id}
        WHERE id = ${item.id}
      `;
    }

    // Check if all items are now converted
    const unconvertedCheck = await sql`
      SELECT COUNT(*) as count
      FROM purchase_requisition_items
      WHERE requisition_id = ${id}
      AND converted_to_po = false
    `;

    const allConverted = parseInt(String(unconvertedCheck[0]?.count) || '0', 10) === 0;

    // Update requisition status
    await sql`
      UPDATE purchase_requisitions
      SET
        status = ${allConverted ? 'ordered' : 'partially_ordered'},
        updated_at = NOW()
      WHERE id = ${id}
    `;

    log.info({
      module: 'procurement',
      action: 'requisition_converted_to_po',
      requisitionId: id,
      requisitionNumber: requisition.requisition_number,
      purchaseOrderId: newPO.id,
      poNumber: newPO.po_number,
      itemCount: items.length,
      convertedBy: userId,
    });

    return apiResponse.created(res, {
      purchaseOrder: {
        id: newPO.id,
        poNumber: newPO.po_number,
        status: newPO.status,
        supplierId: newPO.supplier_id,
        supplierName: supplier.company_name,
        subtotal,
        taxAmount,
        total: totalAmount,
        itemCount: items.length,
      },
      requisition: {
        id: requisition.id,
        requisitionNumber: requisition.requisition_number,
        newStatus: allConverted ? 'ordered' : 'partially_ordered',
      },
    }, `Purchase Order ${poNumber} created successfully`);
  } catch (error) {
    log.error('Failed to convert requisition to PO', error);
    return apiResponse.databaseError(res, error, 'Failed to convert requisition to PO');
  }
}));

// WORKING: Purchase Order Detail API - GET detail, PATCH status, DELETE
import type { NextApiRequest, NextApiResponse } from 'next';
import { neon } from '@neondatabase/serverless';
import { apiResponse } from '@/lib/apiResponse';
import { log } from '@/lib/logger';
import { withAuth, AuthenticatedRequest } from '@/lib/auth';
import { poApprovalService } from '@/services/procurement/approval';
import { createAuditLog } from '@/services/procurement/auditService';

const sql = neon(process.env.DATABASE_URL!);

// UUID validation regex
const UUID_REGEX = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

async function handler(req: NextApiRequest, res: NextApiResponse) {
  const { id } = req.query;

  if (!id || typeof id !== 'string') {
    return apiResponse.badRequest(res, 'Purchase order ID is required');
  }

  // Validate UUID format
  if (!UUID_REGEX.test(id)) {
    return apiResponse.notFound(res, 'Purchase order', id);
  }

  if (req.method === 'GET') {
    return handleGet(req, res, id);
  } else if (req.method === 'PATCH') {
    return handlePatch(req, res, id);
  } else if (req.method === 'DELETE') {
    return handleDelete(req, res, id);
  } else {
    return apiResponse.methodNotAllowed(res, req.method!, ['GET', 'PATCH', 'DELETE']);
  }
}

async function handleGet(req: NextApiRequest, res: NextApiResponse, id: string) {
  try {
    // Fetch PO with supplier and project info
    const poResult = await sql`
      SELECT
        po.id,
        po.po_number,
        po.status,
        po.supplier_id,
        COALESCE(s.company_name, s.name) as supplier_name,
        s.contact_email as supplier_email,
        s.contact_phone as supplier_phone,
        po.project_id,
        p.project_name,
        po.delivery_address,
        po.order_date,
        po.expected_delivery_date,
        po.payment_terms,
        po.currency,
        po.tax_rate,
        po.subtotal,
        po.tax_amount,
        po.total_amount,
        po.internal_notes,
        po.supplier_notes,
        po.created_by,
        po.created_at,
        po.updated_at,
        po.version,
        po.current_approval_request_id,
        po.approved_by,
        po.approved_at,
        po.odoo_po_id,
        po.supplier_reference,
        po.quote_number,
        po.quote_attachment_url,
        po.quote_attachment_name,
        po.department
      FROM purchase_orders po
      LEFT JOIN suppliers s ON po.supplier_id = s.id
      LEFT JOIN projects p ON po.project_id = p.id
      WHERE po.id = ${id}
    `;

    if (poResult.length === 0) {
      return apiResponse.notFound(res, 'Purchase order', id);
    }

    const po = poResult[0]!;

    // Fetch line items
    const itemsResult = await sql`
      SELECT
        id,
        item_code,
        item_description,
        quantity_ordered,
        quantity_received,
        uom,
        unit_price,
        total_price,
        notes
      FROM purchase_order_items
      WHERE purchase_order_id = ${id}
      ORDER BY created_at
    `;

    // Map items with calculated pending quantity
    const items = itemsResult.map((item, index) => {
      const qtyOrdered = parseFloat(item.quantity_ordered) || 0;
      const qtyReceived = parseFloat(item.quantity_received) || 0;
      return {
        id: item.id,
        lineNumber: index + 1,
        description: item.item_description,
        itemCode: item.item_code,
        quantityOrdered: qtyOrdered,
        quantityReceived: qtyReceived,
        quantityPending: Math.max(0, qtyOrdered - qtyReceived),
        unitOfMeasure: item.uom,
        unitPrice: parseFloat(item.unit_price) || 0,
        lineTotal: parseFloat(item.total_price) || 0,
        notes: item.notes,
      };
    });

    // Fetch history from purchase_order_history
    const historyResult = await sql`
      SELECT id, action, notes, created_by, created_at
      FROM purchase_order_history
      WHERE purchase_order_id = ${id}
      ORDER BY created_at DESC
    `;

    // Fetch version history if version > 1
    const versionHistory = po.version > 1
      ? await poApprovalService.getVersionHistory(id)
      : [];

    // Fetch GRN receipts linked to this PO
    const receiptsResult = await sql`
      SELECT id, grn_number, delivery_date, received_by_name, total_items, status
      FROM goods_receipt_notes
      WHERE purchase_order_id = ${id}
      ORDER BY delivery_date DESC
    `;

    // Fetch documents: procurement_documents + odoo_documents linked to this PO or its GRNs
    const grnIds = receiptsResult.map(r => r.id);
    const odooDocsResult = grnIds.length > 0
      ? await sql`
          SELECT id, document_name, document_type, odoo_model, file_url, file_name, mime_type, file_size, created_at
          FROM odoo_documents
          WHERE (ff_entity_type = 'purchase_order' AND ff_entity_id = ${id}::uuid)
             OR (ff_entity_type = 'goods_receipt_note' AND ff_entity_id = ANY(${grnIds}::uuid[]))
          ORDER BY created_at DESC
        `
      : await sql`
          SELECT id, document_name, document_type, odoo_model, file_url, file_name, mime_type, file_size, created_at
          FROM odoo_documents
          WHERE ff_entity_type = 'purchase_order' AND ff_entity_id = ${id}::uuid
          ORDER BY created_at DESC
        `;

    // Get quote comparison if RFQ linked
    let quoteComparison = null;
    try {
      quoteComparison = await poApprovalService.getQuoteComparisonForApproval(id);
    } catch {
      // Quote comparison is optional
    }

    const purchaseOrder = {
      id: po.id,
      poNumber: po.po_number,
      status: po.status,
      supplierId: po.supplier_id,
      supplierName: po.supplier_name || 'Unknown Supplier',
      supplierEmail: po.supplier_email,
      supplierPhone: po.supplier_phone,
      projectId: po.project_id,
      projectName: po.project_name,
      deliveryAddress: po.delivery_address,
      orderDate: po.order_date,
      expectedDeliveryDate: po.expected_delivery_date,
      paymentTerms: po.payment_terms,
      currency: po.currency || 'ZAR',
      taxRate: parseFloat(po.tax_rate) || 15,
      subtotal: parseFloat(po.subtotal) || 0,
      taxAmount: parseFloat(po.tax_amount) || 0,
      totalAmount: parseFloat(po.total_amount) || 0,
      notes: po.internal_notes,
      supplierNotes: po.supplier_notes,
      createdBy: po.created_by,
      createdAt: po.created_at,
      updatedAt: po.updated_at,
      // Versioning
      version: po.version || 1,
      versionHistory,
      // Approval info
      currentApprovalRequestId: po.current_approval_request_id,
      approvedBy: po.approved_by,
      approvedAt: po.approved_at,

      approvedAt: po.approved_at,
      // Odoo integration
      odooPoId: po.odoo_po_id || null,
      // Quote / supplier reference
      supplierReference: po.supplier_reference || null,
      quoteNumber: po.quote_number || null,
      quoteAttachmentUrl: po.quote_attachment_url || null,
      quoteAttachmentName: po.quote_attachment_name || null,
      department: po.department || null,
      // Quote comparison for approvers
      quoteComparison,
      items,
      history: historyResult.map(h => ({
        id: h.id,
        action: h.action,
        notes: h.notes,
        createdBy: h.created_by,
        createdAt: h.created_at,
      })),
      receipts: receiptsResult.map(r => ({
        id: r.id,
        grnNumber: r.grn_number,
        receivedDate: r.delivery_date,
        receivedBy: r.received_by_name || 'Unknown',
        totalItems: parseInt(r.total_items) || 0,
      })),
      odooDocuments: odooDocsResult.map(d => ({
        id: d.id,
        name: d.document_name,
        type: d.document_type,
        odooModel: d.odoo_model,
        fileUrl: d.file_url,
        fileName: d.file_name,
        mimeType: d.mime_type,
        fileSize: parseInt(d.file_size) || 0,
        createdAt: d.created_at,
      })),
    };

    return apiResponse.success(res, purchaseOrder);
  } catch (error) {
    log.error('Failed to fetch purchase order detail', error);
    return apiResponse.internalError(res, error);
  }
}

async function handlePatch(req: NextApiRequest, res: NextApiResponse, id: string) {
  try {
    const { action, notes, reason } = req.body;
    const authReq = req as AuthenticatedRequest;
    const userId = authReq.user?.id || 'system';
    const userName = authReq.user?.name || 'System';

    if (!action) {
      return apiResponse.badRequest(res, 'Action is required');
    }

    // Get current PO status
    const currentPO = await sql`
      SELECT status, version FROM purchase_orders WHERE id = ${id}
    `;

    if (currentPO.length === 0) {
      return apiResponse.notFound(res, 'Purchase order', id);
    }

    const currentStatus = currentPO[0]!.status;
    const currentVersion = currentPO[0]!.version || 1;

    // Handle approval workflow actions with the approval service
    switch (action) {
      case 'submit': {
        if (currentStatus !== 'draft') {
          return apiResponse.badRequest(res, 'Only draft POs can be submitted');
        }

        const result = await poApprovalService.submitForApproval(id, userId, userName);

        log.info('PO submitted for approval', { id, autoApproved: result.autoApproved });

        createAuditLog({
          entityType: 'purchase_order',
          entityId: id,
          action: 'update',
          performedBy: userId,
          performedByName: userName,
          oldValues: { status: currentStatus },
          newValues: { status: result.autoApproved ? 'approved' : 'pending_approval' },
        });

        return apiResponse.success(res, {
          id,
          status: result.autoApproved ? 'approved' : 'pending_approval',
          action: 'submitted',
          autoApproved: result.autoApproved,
          approvalRequest: result.approvalRequest,
