/**
 * Field Ops Photo Processing Endpoint
 *
 * POST /api/field-ops/process-photos
 *   - Validates x-cron-secret header
 *   - Runs photo download + staging batch (fieldOpsPhotoService)
 *   - Runs VLM validation + cross-reference batch (fieldOpsVlmService)
 *   - Returns combined results
 *
 * Intended for cron invocation every few minutes.
 *
 * @module api/field-ops/process-photos
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { createLogger } from '@/lib/logger';
import { apiResponse } from '@/lib/apiResponse';
import { processPendingPhotos } from '@/modules/field-ops/services/fieldOpsPhotoService';
import { validatePendingPhotos } from '@/modules/field-ops/services/fieldOpsVlmService';

const logger = createLogger('api:field-ops:process-photos');

export default async function handler(
  req: NextApiRequest,
  res: NextApiResponse
): Promise<void> {
  if (req.method !== 'POST') {
    apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['POST']);
    return;
  }

  // Validate cron secret
  const cronSecret = req.headers['x-cron-secret'];
  if (!process.env.CRON_SECRET || cronSecret !== process.env.CRON_SECRET) {
    apiResponse.unauthorized(res, 'Invalid or missing cron secret');
    return;
  }

  const { photoLimit = 10, vlmLimit = 5 } = req.body || {};

  logger.info('Starting field-ops photo processing', { photoLimit, vlmLimit });

  try {
    // Phase 1: Download + stage photos from WhatsApp bridge
    const photoResults = await processPendingPhotos(Number(photoLimit));

    logger.info('Photo download batch complete', {
      processed: photoResults.processed,
      succeeded: photoResults.succeeded,
      failed: photoResults.failed,
    });

    // Phase 2: VLM validation + project cross-reference
    const vlmResults = await validatePendingPhotos(Number(vlmLimit));

    logger.info('VLM validation batch complete', {
      processed: vlmResults.processed,
      succeeded: vlmResults.succeeded,
      failed: vlmResults.failed,
    });

    apiResponse.success(res, {
      photos: photoResults,
      vlm: vlmResults,
    });
  } catch (error) {
    const errorMessage = error instanceof Error ? error.message : 'Unknown error';
    logger.error('Field-ops photo processing failed', { error: errorMessage });
    apiResponse.internalError(res, error, 'Photo processing pipeline failed');
  }
}

/**
 * EXFO Exchange Sync Service
 *
 * Orchestrates syncing test results from EXFO Exchange into Neon.
 * Handles:
 * - Incremental sync (based on serverUpdatedDate cursor)
 * - Test name parsing (extracts project, pole, cabinet, port, link, fiber)
 * - Equipment matching (serial numbers → FibreFlow assets)
 * - Measurement detail enrichment
 */

import { neon } from '@neondatabase/serverless';
import { createLogger } from '@/lib/logger';
import { fetchAllResults, getMeasurementDetails } from './exfoApiService';
import type {
  ExfoSearchResult,
  ExfoMeasurementDetail,
  ExfoParsedName,
  ExfoSyncResult,
  ExfoSyncConfig,
} from './types';

const logger = createLogger('exfoSync');
const sql = neon(process.env.DATABASE_URL!);

// =============================================================================
// Name Parser
// =============================================================================

/**
 * Parse EXFO test name into structured components.
 * Convention: {PROJECT}.STS.{N}.DIS.DM.P.{POLE}-C{CAB}P{PORT}.L{LINK}-L{FIBER}
 *
 * Examples:
 *   MOA.STS.1.DIS.DM.P.B756-C5P5.L14-L1
 *   MOA.STS.8.DIS.DM.P.C725-C8P6.L3-L1
 */
export function parseTestName(name: string): ExfoParsedName {
  const result: ExfoParsedName = {
    project: null,
    section: null,
    sectionNum: null,
    pole: null,
    cabinet: null,
    port: null,
    link: null,
    fiber: null,
  };

  if (!name) return result;

  // Split on dots first: MOA.STS.1.DIS.DM.P.B756-C5P5.L14-L1
  const parts = name.split('.');

  if (parts.length >= 1) result.project = parts[0] || null;
  if (parts.length >= 2) result.section = parts[1] || null;
  if (parts.length >= 3) {
    const num = parseInt(parts[2] || '', 10);
    result.sectionNum = isNaN(num) ? null : num;
  }

  // Find the pole-cabinet segment (contains hyphen like P.B756-C5P5)
  const fullName = name;

  // Match pole: P.{POLE} or just the pole reference
  const poleMatch = fullName.match(/\.P\.([A-Z]\d+)/i);
  if (poleMatch?.[1]) result.pole = poleMatch[1];

  // Match cabinet and port: -C{N}P{N}
  const cabPortMatch = fullName.match(/-C(\d+)P(\d+)/i);
  if (cabPortMatch?.[1] && cabPortMatch[2]) {
    result.cabinet = `C${cabPortMatch[1]}`;
    result.port = `P${cabPortMatch[2]}`;
  }

  // Match link and fiber: .L{N}-L{N}
  const linkFiberMatch = fullName.match(/\.L(\d+)-L(\d+)/i);
  if (linkFiberMatch?.[1] && linkFiberMatch[2]) {
    result.link = `L${linkFiberMatch[1]}`;
    result.fiber = `L${linkFiberMatch[2]}`;
  }

  return result;
}

// =============================================================================
// Equipment Matching
// =============================================================================

/**
 * Match equipment serial numbers to FibreFlow assets.
 * Returns asset IDs if found.
 */
async function matchAssets(
  serialA: string | null,
  serialB: string | null
): Promise<{ assetIdA: string | null; assetIdB: string | null }> {
  let assetIdA: string | null = null;
  let assetIdB: string | null = null;

  if (serialA) {
    const rows = await sql`
      SELECT id FROM assets
      WHERE serial_number = ${serialA}
      LIMIT 1
    `;
    if (rows.length > 0) assetIdA = rows[0]!.id as string;
  }

  if (serialB) {
    const rows = await sql`
      SELECT id FROM assets
      WHERE serial_number = ${serialB}
      LIMIT 1
    `;
    if (rows.length > 0) assetIdB = rows[0]!.id as string;
  }

  return { assetIdA, assetIdB };
}

/**
 * Known EXFO code → FibreFlow project name mappings.
 * EXFO uses short codes (MOA, GRA) that don't match project_code or substring.
 */
const PROJECT_CODE_MAP: Record<string, string> = {
  'MOA': 'Mohadin',
};

/**
 * Match parsed project code to a FibreFlow project.
 */
async function matchProject(projectCode: string | null): Promise<string | null> {
  if (!projectCode) return null;

  // Try known mapping first
  const mappedName = PROJECT_CODE_MAP[projectCode.toUpperCase()];
  if (mappedName) {
    const mapped = await sql`
      SELECT id FROM projects
      WHERE UPPER(project_name) = UPPER(${mappedName})
      LIMIT 1
    `;
    if (mapped.length > 0) return mapped[0]!.id as string;
  }

  // Try exact match on project_code
  const rows = await sql`
    SELECT id FROM projects
    WHERE UPPER(project_code) = UPPER(${projectCode})
    LIMIT 1
  `;

  if (rows.length > 0) return rows[0]!.id as string;

  // Try partial match on project_name
  const likePattern = `%${projectCode}%`;
  const nameRows = await sql`
    SELECT id FROM projects
    WHERE UPPER(project_name) LIKE UPPER(${likePattern})
    LIMIT 1
  `;

  return nameRows.length > 0 ? (nameRows[0]!.id as string) : null;
}

// =============================================================================
// Detail Extraction
// =============================================================================

/**
 * Extract structured fields from EXFO measurement detail response.
 */
function extractDetailFields(detail: ExfoMeasurementDetail): Record<string, unknown> {
  const brief = detail.brief || {};
  const hardware = brief.Hardware || {};
  const identification = brief.Identification || {};
  const fiberInfo = brief.FiberInformation || {};
  const identifiers = brief.Identifiers || [];
  const metadata = detail.metadata || {};

  // Parse identifiers array
  const getIdentifier = (name: string): string | null => {
    const entry = identifiers.find(
      (i) => i.Name?.toLowerCase() === name.toLowerCase()
    );
    return entry?.Value || null;
  };

  return {
    unit_a_serial: hardware.UnitA?.SerialNumber || null,
    unit_a_model: hardware.UnitA?.ModelName || null,
    unit_a_calibration: hardware.UnitA?.LastCalibrationDate || null,
    unit_b_serial: hardware.UnitB?.SerialNumber || null,
    unit_b_model: hardware.UnitB?.ModelName || null,
    unit_b_calibration: hardware.UnitB?.LastCalibrationDate || null,
    platform_serial: metadata.platformSerialNumber || null,
    platform_model: metadata.platformUsed || null,
    company_name: identification.CompanyName || null,
    customer_name: identification.CustomerName || null,
    operator_a: identification.OperatorA || null,
    operator_b: identification.OperatorB || null,
    fiber_type: fiberInfo.FiberType || null,
    location_direction: fiberInfo.LocationDirection || null,
    cable_id: getIdentifier('Cable ID'),
    fiber_id: getIdentifier('Fiber ID'),
    location_a: getIdentifier('Location A'),
    location_b: getIdentifier('Location B'),
    geolocation: identification.Geolocation || null,
  };
}

// =============================================================================
// Sync Orchestration
// =============================================================================

/**
 * Get all active sync configs from the database.
 */
export async function getSyncConfigs(): Promise<ExfoSyncConfig[]> {
  const rows = await sql`
    SELECT * FROM exfo_sync_config
    WHERE is_active = true
    ORDER BY workspace_name
  `;
  return rows as unknown as ExfoSyncConfig[];
}

/**
 * Run sync for a single workspace.
 * Supports incremental (from cursor) and full sync modes.
 */
export async function syncWorkspace(
  config: ExfoSyncConfig,
  options: { full?: boolean; fetchDetails?: boolean; maxResults?: number } = {}
): Promise<ExfoSyncResult> {
  const { workspace_id, workspace_name } = config;
  const fetchDetails = options.fetchDetails !== false; // default true
  const maxResults = options.maxResults || 5000;

  logger.info('Starting EXFO sync', { workspace_id, workspace_name, full: !!options.full });

  // Create sync history record
  const historyRows = await sql`
    INSERT INTO exfo_sync_history (workspace_id, sync_type, status)
    VALUES (${workspace_id}, ${options.full ? 'full' : 'incremental'}, 'running')
    RETURNING id
  `;
  const syncBatchId = historyRows[0]!.id as string;

  const result: ExfoSyncResult = {
    status: 'completed',
    resultsFetched: 0,
    resultsInserted: 0,
    resultsUpdated: 0,
    detailsFetched: 0,
    assetsMatched: 0,
  };

  try {
    // Determine sync cursor
    const updatedSince = options.full ? undefined : (config.last_sync_cursor || undefined);

    // Fetch all search results
    const searchResults = await fetchAllResults(workspace_id, {
      updatedSince,
      maxResults,
    });
    result.resultsFetched = searchResults.length;

    if (searchResults.length === 0) {
      logger.info('No new results to sync', { workspace_id });
      await completeSyncHistory(syncBatchId, result);
      return result;
    }

    // Determine which results need detail fetching (new or updated)
    const resultIds = searchResults.map(r => r.resultId);
    const existingRows = await sql`
      SELECT exfo_result_id FROM exfo_test_results
      WHERE exfo_result_id = ANY(${resultIds})
    `;
    const existingIds = new Set(existingRows.map(r => r.exfo_result_id as string));

    // Fetch measurement details for new/updated results
    let details = new Map<string, ExfoMeasurementDetail>();
    if (fetchDetails) {
      const idsToFetch = resultIds.filter(id => !existingIds.has(id));
      if (idsToFetch.length > 0) {
        details = await getMeasurementDetails(workspace_id, idsToFetch, {
          delayMs: 150,
          onProgress: (done, total) => {
            if (done % 10 === 0 || done === total) {
              logger.info('Detail fetch progress', { done, total, workspace_id });
            }
          },
        });
        result.detailsFetched = details.size;
      }
    }

    // Upsert results
    for (const searchResult of searchResults) {
      const isNew = !existingIds.has(searchResult.resultId);
      const detail = details.get(searchResult.resultId);
      const parsed = parseTestName(searchResult.name);

      // Extract detail fields
      const detailFields = detail ? extractDetailFields(detail) : {};

      // Match assets by serial number
      const { assetIdA, assetIdB } = await matchAssets(
        detailFields.unit_a_serial as string | null,
        detailFields.unit_b_serial as string | null
      );
      if (assetIdA || assetIdB) result.assetsMatched++;

      // Match project
      const projectId = config.project_id || await matchProject(parsed.project);

      await upsertResult(searchResult, parsed, detailFields, detail, {
        workspaceId: workspace_id,
        syncBatchId,
        projectId,
        assetIdA,
        assetIdB,
      });

      if (isNew) {
        result.resultsInserted++;
      } else {
        result.resultsUpdated++;
      }
    }

    // Update sync cursor to latest serverUpdatedDate
    const latestDate = searchResults
      .map(r => r.serverUpdatedDate)
      .filter(Boolean)
      .sort()
      .pop();

    if (latestDate) {
      await sql`
        UPDATE exfo_sync_config
        SET last_sync_at = NOW(),
            last_sync_cursor = ${latestDate},
            updated_at = NOW()
        WHERE workspace_id = ${workspace_id}
      `;
    }

    await completeSyncHistory(syncBatchId, result);
    logger.info('EXFO sync completed', { workspace_id, ...result });

  } catch (err) {
    const errorMsg = err instanceof Error ? err.message : String(err);
    result.status = 'failed';
    result.error = errorMsg;

    await sql`
      UPDATE exfo_sync_history
      SET status = 'failed', error_message = ${errorMsg}, completed_at = NOW()
      WHERE id = ${syncBatchId}::UUID
    `;

    logger.error('EXFO sync failed', { workspace_id, error: errorMsg });
  }

  return result;
}

/**
 * Sync all active workspaces.
 */
export async function syncAllWorkspaces(
  options: { full?: boolean; fetchDetails?: boolean } = {}
): Promise<Record<string, ExfoSyncResult>> {
  const configs = await getSyncConfigs();
  const results: Record<string, ExfoSyncResult> = {};

  for (const config of configs) {
    results[config.workspace_id] = await syncWorkspace(config, options);
  }

  return results;
}

// =============================================================================
// Database Operations
// =============================================================================

async function upsertResult(
  search: ExfoSearchResult,
  parsed: ExfoParsedName,
  detailFields: Record<string, unknown>,
  rawDetail: ExfoMeasurementDetail | undefined,
  meta: {
    workspaceId: string;
    syncBatchId: string;
    projectId: string | null;
    assetIdA: string | null;
    assetIdB: string | null;
  }
): Promise<void> {
  // Normalize verdict: EXFO returns lowercase "pass"/"fail", we store capitalized
  const verdict = search.globalVerdict
    ? search.globalVerdict.charAt(0).toUpperCase() + search.globalVerdict.slice(1).toLowerCase()
    : null;
  const testDateTime = search.testDateTime ? new Date(search.testDateTime).toISOString() : null;
  const serverUpdated = search.serverUpdatedDate ? new Date(search.serverUpdatedDate).toISOString() : null;
  const unitACal = detailFields.unit_a_calibration ? String(detailFields.unit_a_calibration) : null;
  const unitBCal = detailFields.unit_b_calibration ? String(detailFields.unit_b_calibration) : null;
  const geoJson = detailFields.geolocation ? JSON.stringify(detailFields.geolocation) : null;
  const rawSearchJson = JSON.stringify(search);
  const rawMeasurementJson = rawDetail ? JSON.stringify(rawDetail) : null;

  await sql`
    INSERT INTO exfo_test_results (
      exfo_result_id, exfo_account_id, exfo_workspace_id, exfo_job_id, exfo_brief_job_id,
      test_type, test_name, job_name, config_name, global_verdict,
      test_date_time, server_updated_date,
      parsed_project, parsed_section, parsed_section_num,
      parsed_pole, parsed_cabinet, parsed_port, parsed_link, parsed_fiber,
      unit_a_serial, unit_a_model, unit_a_calibration,
      unit_b_serial, unit_b_model, unit_b_calibration,
      platform_serial, platform_model,
      company_name, customer_name, operator_a, operator_b,
      test_point_name, fiber_type, location_direction,
      cable_id, fiber_id, location_a, location_b,
      geolocation, created_by_uuid, updated_by_uuid,
      attachments_count, project_id, asset_id, asset_id_b,
      sync_batch_id, raw_search_data, raw_measurement_data
    ) VALUES (
      ${search.resultId}, ${search.accountId}, ${meta.workspaceId},
      ${search.jobId}, ${search.briefJobId},
      ${search.type}, ${search.name}, ${search.jobName}, ${search.configName},
      ${verdict},
      ${testDateTime}::TIMESTAMPTZ, ${serverUpdated}::TIMESTAMPTZ,
      ${parsed.project}, ${parsed.section}, ${parsed.sectionNum},
      ${parsed.pole}, ${parsed.cabinet}, ${parsed.port}, ${parsed.link}, ${parsed.fiber},
      ${detailFields.unit_a_serial as string | null}, ${detailFields.unit_a_model as string | null},
      ${unitACal}::DATE,
      ${detailFields.unit_b_serial as string | null}, ${detailFields.unit_b_model as string | null},
      ${unitBCal}::DATE,
      ${detailFields.platform_serial as string | null}, ${detailFields.platform_model as string | null},
      ${detailFields.company_name as string | null}, ${detailFields.customer_name as string | null},
      ${detailFields.operator_a as string | null}, ${detailFields.operator_b as string | null},
      ${search.testPointName}, ${detailFields.fiber_type as string | null},
      ${detailFields.location_direction as string | null},
      ${detailFields.cable_id as string | null}, ${detailFields.fiber_id as string | null},
      ${detailFields.location_a as string | null}, ${detailFields.location_b as string | null},
      ${geoJson}::JSONB, ${search.createdBy}, ${search.updatedBy},
      ${search.attachmentsCount},
      ${meta.projectId}::UUID, ${meta.assetIdA}::UUID, ${meta.assetIdB}::UUID,
      ${meta.syncBatchId}::UUID,
      ${rawSearchJson}::JSONB, ${rawMeasurementJson}::JSONB
    )
    ON CONFLICT (exfo_result_id) DO UPDATE SET
      global_verdict = EXCLUDED.global_verdict,
      server_updated_date = EXCLUDED.server_updated_date,
      updated_by_uuid = EXCLUDED.updated_by_uuid,
      attachments_count = EXCLUDED.attachments_count,
      raw_search_data = EXCLUDED.raw_search_data,
      sync_batch_id = EXCLUDED.sync_batch_id,
      updated_at = NOW()
  `;
}

async function completeSyncHistory(
  syncBatchId: string,
  result: ExfoSyncResult
): Promise<void> {
  await sql`
    UPDATE exfo_sync_history
    SET status = 'completed',
        results_fetched = ${result.resultsFetched},
        results_inserted = ${result.resultsInserted},
        results_updated = ${result.resultsUpdated},
        details_fetched = ${result.detailsFetched},
        assets_matched = ${result.assetsMatched},
        completed_at = NOW()
    WHERE id = ${syncBatchId}::UUID
  `;
}

/**
 * EXFO Exchange Sync API
 *
 * POST /api/exfo/sync — Trigger sync for one or all workspaces
 *   Body: { workspaceId?, full?, fetchDetails? }
 *
 * GET /api/exfo/sync — Get sync history
 *   ?workspaceId=xxx&limit=20
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { neon } from '@neondatabase/serverless';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth } from '@/lib/auth/middleware';
import { syncWorkspace, syncAllWorkspaces, getSyncConfigs } from '@/services/exfo';

const sql = neon(process.env.DATABASE_URL!);

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method === 'POST') {
    return handleSync(req, res);
  }

  if (req.method === 'GET') {
    return handleGetHistory(req, res);
  }

  return apiResponse.methodNotAllowed(res, req.method || 'unknown', ['GET', 'POST']);
}

async function handleSync(req: NextApiRequest, res: NextApiResponse) {
  try {
    const { workspaceId, full, fetchDetails } = req.body || {};

    if (workspaceId) {
      const configs = await getSyncConfigs();
      const config = configs.find(c => c.workspace_id === workspaceId);

      if (!config) {
        return apiResponse.notFound(res, 'EXFO workspace config', workspaceId);
      }

      const result = await syncWorkspace(config, { full, fetchDetails });
      return apiResponse.success(res, result);
    }

    const results = await syncAllWorkspaces({ full, fetchDetails });
    return apiResponse.success(res, results);
  } catch (err) {
    return apiResponse.internalError(res, err);
  }
}

async function handleGetHistory(req: NextApiRequest, res: NextApiResponse) {
  try {
    const workspaceId = req.query.workspaceId as string || '';
    const limit = Math.min(100, Math.max(1, parseInt(req.query.limit as string || '20', 10)));

    let rows;
    if (workspaceId) {
      rows = await sql`
        SELECT * FROM exfo_sync_history
        WHERE workspace_id = ${workspaceId}
        ORDER BY started_at DESC
        LIMIT ${limit}
      `;
    } else {
      rows = await sql`
        SELECT * FROM exfo_sync_history
        ORDER BY started_at DESC
        LIMIT ${limit}
      `;
    }

    return apiResponse.success(res, { history: rows });
  } catch (err) {
    return apiResponse.internalError(res, err);
  }
}

export default withAuth(handler);

/**
 * EXFO Exchange API Service
 *
 * Wraps the reverse-engineered EXFO Exchange REST API.
 * Handles search, measurement detail, and pagination.
 *
 * API microservices:
 * - search.exfoapis.com  — Search/list test results
 * - measurement.exfoapis.com — Full measurement details
 */

import { createLogger } from '@/lib/logger';
import { getExfoToken } from './exfoAuthService';
import type {
  ExfoSearchRequest,
  ExfoSearchResult,
  ExfoSearchResponse,
  ExfoMeasurementDetail,
} from './types';

const logger = createLogger('exfoApi');

const SEARCH_BASE = 'https://search.exfoapis.com';
const MEASUREMENT_BASE = 'https://measurement.exfoapis.com/prod';

// =============================================================================
// HTTP Helper
// =============================================================================

async function exfoFetch<T>(url: string, options: RequestInit = {}): Promise<T> {
  const token = await getExfoToken();

  const response = await fetch(url, {
    ...options,
    headers: {
      'Authorization': `Bearer ${token}`,
      'Content-Type': 'application/json',
      'Accept': 'application/json',
      ...options.headers,
    },
  });

  if (!response.ok) {
    const errorText = await response.text().catch(() => '');
    logger.error('EXFO API error', {
      url,
      status: response.status,
      error: errorText.slice(0, 500),
    });
    throw new Error(`EXFO API error (${response.status}): ${errorText.slice(0, 200)}`);
  }

  return response.json() as Promise<T>;
}

// =============================================================================
// Search API
// =============================================================================

/**
 * Search test results in a workspace.
 * Supports pagination (from/size), filtering, and sorting.
 */
export async function searchResults(
  workspaceId: string,
  options: {
    from?: number;
    size?: number;
    term?: string;
    updatedSince?: string;
    updatedBefore?: string;
    testType?: string;
    verdict?: string;
  } = {}
): Promise<ExfoSearchResponse> {
  const { from = 0, size = 50, term = '' } = options;

  const filters: ExfoSearchRequest['search']['filters']['values'] = {};

  // Date range filter
  if (options.updatedSince || options.updatedBefore) {
    const dateRange: { start?: string; end?: string } = {};
    if (options.updatedSince) dateRange.start = options.updatedSince;
    if (options.updatedBefore) dateRange.end = options.updatedBefore;
    filters.serverUpdatedDate = { values: [dateRange as { start: string; end: string }] };
    filters.hasRadioButton = { values: 'serverUpdatedDate' };
  }

  // Test type filter (olts, iolm)
  if (options.testType) {
    filters.type = { values: [options.testType] };
  }

  // Verdict filter (Pass, Fail)
  if (options.verdict) {
    filters.globalVerdict = { values: [options.verdict] };
  }

  const body: ExfoSearchRequest = {
    from,
    size,
    search: {
      term,
      filters: { values: filters },
    },
    sort: { by: 'updated', order: 'desc' },
  };

  const url = `${SEARCH_BASE}/workspaces/${workspaceId}/search/results`;
  logger.debug('EXFO search', { workspaceId, from, size });

  return exfoFetch<ExfoSearchResponse>(url, {
    method: 'POST',
    body: JSON.stringify(body),
  });
}

/**
 * Fetch ALL results from a workspace using pagination.
 * Yields batches for memory efficiency.
 */
export async function fetchAllResults(
  workspaceId: string,
  options: {
    updatedSince?: string;
    batchSize?: number;
    maxResults?: number;
  } = {}
): Promise<ExfoSearchResult[]> {
  const batchSize = options.batchSize || 100;
  const maxResults = options.maxResults || 10000;
  const allResults: ExfoSearchResult[] = [];
  let from = 0;

  while (from < maxResults) {
    const response = await searchResults(workspaceId, {
      from,
      size: batchSize,
      updatedSince: options.updatedSince,
    });

    if (!response.results || response.results.length === 0) break;
    allResults.push(...response.results);

    logger.info('EXFO search batch', {
      workspaceId,
      fetched: allResults.length,
      batchSize: response.results.length,
    });

    // If we got fewer than requested, we've reached the end
    if (response.results.length < batchSize) break;
    from += batchSize;
  }

  return allResults;
}

// =============================================================================
// Measurement Detail API
// =============================================================================

/**
 * Get full measurement detail for a single test result.
 * Contains hardware info, identification, fiber data, and measurements.
 */
export async function getMeasurementDetail(
  workspaceId: string,
  resultId: string
): Promise<ExfoMeasurementDetail> {
  const url = `${MEASUREMENT_BASE}/workspaces/${workspaceId}/results/${resultId}`;
  logger.debug('EXFO measurement detail', { workspaceId, resultId });

  return exfoFetch<ExfoMeasurementDetail>(url);
}

/**
 * Fetch measurement details for multiple results with rate limiting.
 * Adds a small delay between requests to avoid overwhelming the API.
 */
export async function getMeasurementDetails(
  workspaceId: string,
  resultIds: string[],
  options: { delayMs?: number; onProgress?: (done: number, total: number) => void } = {}
): Promise<Map<string, ExfoMeasurementDetail>> {
  const delayMs = options.delayMs || 200;
  const results = new Map<string, ExfoMeasurementDetail>();

  for (let i = 0; i < resultIds.length; i++) {
    const resultId = resultIds[i]!;
    try {
      const detail = await getMeasurementDetail(workspaceId, resultId);
      results.set(resultId, detail);
    } catch (err) {
      logger.warn('Failed to fetch measurement detail', {
        resultId,
        error: err instanceof Error ? err.message : String(err),
      });
    }

    options.onProgress?.(i + 1, resultIds.length);

    // Rate limit delay (skip on last item)
    if (i < resultIds.length - 1 && delayMs > 0) {
      await new Promise(resolve => setTimeout(resolve, delayMs));
    }
  }

  return results;
}

/**
 * Field Ops Photo Processing Service
 *
 * Handles downloading WhatsApp construction photos from the bridge and staging
 * them for Firebase upload. Processes photos from field_ops_wa_photos table
 * with pending upload_status.
 *
 * Flow:
 * 1. Query pending photos from field_ops_wa_photos
 * 2. Request download from WhatsApp bridge /api/download
 * 3. Stage file locally and record intended Firebase storage path
 * 4. Update status to 'uploaded' with storage_key
 *
 * @module field-ops/services/fieldOpsPhotoService
 */

import { neon } from '@neondatabase/serverless';
import { createLogger } from '@/lib/logger';
import fs from 'fs';

const logger = createLogger('fieldOpsPhotoService');

// ============================================================================
// Configuration
// ============================================================================

const WA_BRIDGE_DOWNLOAD_URL =
  process.env.WA_BRIDGE_URL || 'http://72.61.197.178:8083/api/download';

// ============================================================================
// Database Connection
// ============================================================================

function getDb() {
  const databaseUrl = process.env.DATABASE_URL;
  if (!databaseUrl) {
    throw new Error('DATABASE_URL environment variable is not set');
  }
  return neon(databaseUrl);
}

// ============================================================================
// Types
// ============================================================================

interface PendingPhoto {
  id: string;
  message_id: string;
  wa_media_id: string;
  wa_group_jid: string;
  group_type: string;
  project: string;
  sender_name: string;
  message_timestamp: string;
  mime_type: string;
  wa_message_id: string;
}

interface DownloadResult {
  success: boolean;
  filename?: string;
  path?: string;
  error?: string;
}

interface FirebaseStageResult {
  success: boolean;
  storageKey?: string;
  error?: string;
}

// ============================================================================
// WhatsApp Bridge Media Download
// ============================================================================

/**
 * Download media from WhatsApp bridge
 */
async function downloadFromBridge(
  messageId: string,
  chatJid: string
): Promise<DownloadResult> {
  try {
    const response = await fetch(WA_BRIDGE_DOWNLOAD_URL, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        message_id: messageId,
        chat_jid: chatJid,
      }),
    });

    const result = await response.json();

    if (result.success && result.path) {
      return {
        success: true,
        filename: result.filename,
        path: result.path,
      };
    }

    return {
      success: false,
      error: result.message || 'Unknown download error',
    };
  } catch (error) {
    return {
      success: false,
      error: error instanceof Error ? error.message : 'Download failed',
    };
  }
}

// ============================================================================
// Firebase Storage Staging
// ============================================================================

/**
 * Stage photo for Firebase upload.
 * Records the intended Firebase storage path; the file is already local from the bridge.
 * Actual Firebase upload runs in a background job when credentials are configured.
 */
async function stageForFirebase(
  localPath: string,
  storagePath: string
): Promise<FirebaseStageResult> {
  try {
    if (!fs.existsSync(localPath)) {
      return { success: false, error: `Local file not found: ${localPath}` };
    }

    logger.info('Photo staged for Firebase upload', { localPath, storagePath });
    return { success: true, storageKey: storagePath };
  } catch (error) {
    return {
      success: false,
      error: error instanceof Error ? error.message : 'Staging failed',
    };
  }
}

// ============================================================================
// Photo Processing
// ============================================================================

/**
 * Get pending photos that need downloading and uploading
 */
export async function getPendingPhotos(limit = 10): Promise<PendingPhoto[]> {
  const sql = getDb();

  const result = await sql`
    SELECT
      p.id,
      p.message_id,
      p.wa_media_id,
      p.wa_group_jid,
      p.group_type,
      p.project,
      p.sender_name,
      p.message_timestamp,
      p.mime_type,
      m.wa_message_id
    FROM field_ops_wa_photos p
    JOIN field_ops_wa_messages m ON p.message_id = m.id
    WHERE p.upload_status = 'pending'
    ORDER BY p.created_at ASC
    LIMIT ${limit}
  `;

  return result as unknown as PendingPhoto[];
}

/**
 * Process a single pending photo: download from bridge + stage for Firebase
 */
export async function processPhoto(
  photo: PendingPhoto
): Promise<{ success: boolean; error?: string }> {
  const sql = getDb();

  // Mark as uploading
  await sql`
    UPDATE field_ops_wa_photos
    SET upload_status = 'uploading', updated_at = NOW()
    WHERE id = ${photo.id}
  `;

  // Step 1: Download from WhatsApp bridge
  logger.info('Downloading photo from bridge', {
    photoId: photo.id,
    messageId: photo.wa_message_id,
  });

  const download = await downloadFromBridge(photo.wa_message_id, photo.wa_group_jid);

  if (!download.success || !download.path) {
    await sql`
      UPDATE field_ops_wa_photos
      SET upload_status = 'failed', upload_error = ${download.error || null}, updated_at = NOW()
      WHERE id = ${photo.id}
    `;
    return { success: false, error: download.error };
  }

  // Step 2: Stage for Firebase
  const date = new Date(photo.message_timestamp).toISOString().split('T')[0];
  const filename = download.filename || `photo_${photo.id}.jpg`;
  const storagePath = `construction-qa/${photo.project}/${date}/${filename}`;

  const stage = await stageForFirebase(download.path, storagePath);

  if (!stage.success) {
    await sql`
      UPDATE field_ops_wa_photos
      SET upload_status = 'failed', upload_error = ${stage.error || null}, updated_at = NOW()
      WHERE id = ${photo.id}
    `;
    return { success: false, error: stage.error };
  }

  // Step 3: Update to uploaded with storage key and local path
  await sql`
    UPDATE field_ops_wa_photos
    SET
      upload_status = 'uploaded',
      storage_key = ${stage.storageKey || null},
      local_path = ${download.path},
      uploaded_at = NOW(),
      updated_at = NOW()
    WHERE id = ${photo.id}
  `;

  logger.info('Photo staged successfully', {
    photoId: photo.id,
    storageKey: stage.storageKey,
  });

  return { success: true };
}

/**
 * Batch process pending photos (download + stage)
 */
export async function processPendingPhotos(limit = 10): Promise<{
  processed: number;
  succeeded: number;
  failed: number;
  errors: string[];
}> {
  const pendingPhotos = await getPendingPhotos(limit);

  const results = {
    processed: 0,
    succeeded: 0,
    failed: 0,
    errors: [] as string[],
  };

  for (const photo of pendingPhotos) {
    results.processed++;

    try {
      const result = await processPhoto(photo);

      if (result.success) {
        results.succeeded++;
      } else {
        results.failed++;
        results.errors.push(`Photo ${photo.id}: ${result.error}`);
      }
    } catch (error) {
      results.failed++;
      results.errors.push(
        `Photo ${photo.id}: ${error instanceof Error ? error.message : 'Unknown error'}`
      );
    }
  }

  logger.info('Batch photo processing complete', {
    processed: results.processed,
    succeeded: results.succeeded,
    failed: results.failed,
  });

  return results;
}

/**
 * Field Ops VLM Validation Service
 *
 * Two-stage AI validation for field_ops_wa_photos (upload_status='uploaded', vlm_processed=false):
 * 1. VLM Visual Analysis — Qwen3-VL-8B inspects photos for discipline-specific QA criteria
 *    and extracts the pole number from visible labels.
 * 2. Project Cross-Reference — Validates the extracted pole number against the project SOW
 *    (poles table) and checks PON stage progression.
 *
 * @module field-ops/services/fieldOpsVlmService
 */

import { neon } from '@neondatabase/serverless';
import { createLogger } from '@/lib/logger';

const logger = createLogger('fieldOpsVlmService');
const VLM_URL = process.env.VLM_SERVICE_URL || 'http://100.96.203.105:8100';
const VLM_MODEL = 'Qwen3-VL-8B-Instruct';

function getDb() {
  if (!process.env.DATABASE_URL) throw new Error('DATABASE_URL not set');
  return neon(process.env.DATABASE_URL);
}

// ============================================================================
// Types
// ============================================================================

interface UploadedPhoto {
  id: string;
  group_type: string;
  project: string;
  storage_key: string;
  local_path: string;
  wa_group_jid: string;
  message_timestamp: string;
}

interface VlmResult {
  extracted_pole_number: string | null;
  vlm_valid: boolean;
  confidence: number;
  issues: string[];
  feedback: string;
}

interface CrossRefResult {
  valid: boolean;
  issues: string[];
  pole_number: string | null;
  zone_no: number | null;
  pon_no: number | null;
}

// ============================================================================
// VLM Prompts
// ============================================================================

const CIVIL_PROMPT = `You are a civil construction QA inspector for fiber network pole installations.
Analyze this photo and respond with ONLY a valid JSON object.
Check: 1) Pole verticality, 2) Depth marker visible, 3) Ground compaction, 4) Stay wires installed, 5) Pole label/number.
JSON format:
{"extracted_pole_number":"POL-001 or null","valid":true,"confidence":0.0,"issues":[],"feedback":"one sentence"}`;

const OPTICAL_PROMPT = `You are a fiber optic construction QA inspector for aerial fiber installations.
Analyze this photo and respond with ONLY a valid JSON object.
Check: 1) Cable tension appropriate, 2) Sag within spec, 3) Splice dome sealed, 4) Cable markings.
JSON format:
{"extracted_pole_number":null,"valid":true,"confidence":0.0,"issues":[],"feedback":"one sentence"}`;

// ============================================================================
// Stage 1: VLM Visual Analysis
// ============================================================================

function parseVlmResponse(text: string): VlmResult {
  try {
    const jsonMatch = text.match(/\{[\s\S]*\}/);
    if (jsonMatch) {
      const p = JSON.parse(jsonMatch[0]);
      return {
        extracted_pole_number: p.extracted_pole_number ? String(p.extracted_pole_number) : null,
        vlm_valid: Boolean(p.valid ?? p.pass ?? false),
        confidence: Math.min(1, Math.max(0, Number(p.confidence ?? 0))),
        issues: Array.isArray(p.issues) ? p.issues : [],
        feedback: String(p.feedback || ''),
      };
    }
  } catch { /* fall through */ }

  const lower = text.toLowerCase();
  const valid = lower.includes('pass') || lower.includes('acceptable');
  return {
    extracted_pole_number: null,
    vlm_valid: valid,
    confidence: valid ? 0.5 : 0.2,
    issues: valid ? [] : ['Manual review required — AI could not parse response'],
    feedback: text.slice(0, 300),
  };
}

/**
 * Call Qwen3-VL to analyse a construction photo and extract QA results.
 */
async function runVlmAnalysis(photoPath: string, discipline: string): Promise<VlmResult> {
  const prompt = discipline === 'civil' ? CIVIL_PROMPT : OPTICAL_PROMPT;
  const baseUrl = process.env.NEXT_PUBLIC_BASE_URL || 'http://localhost:3004';
  const imageUrl = photoPath.startsWith('http')
    ? photoPath
    : `${baseUrl}/api/field-ops/photo-proxy?path=${encodeURIComponent(photoPath)}`;

  try {
    const response = await fetch(`${VLM_URL}/v1/chat/completions`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        model: VLM_MODEL,
        messages: [
          {
            role: 'user',
            content: [
              { type: 'image_url', image_url: { url: imageUrl, detail: 'high' } },
              { type: 'text', text: prompt },
            ],
          },
        ],
        max_tokens: 512,
        temperature: 0.1,
      }),
    });

    if (!response.ok) {
      throw new Error(`VLM HTTP ${response.status}: ${await response.text()}`);
    }

    const data = await response.json();
    const text: string = data.choices?.[0]?.message?.content || '';
    return parseVlmResponse(text);
  } catch (error) {
    logger.error('VLM analysis failed', {
      error: error instanceof Error ? error.message : 'Unknown',
      photoPath,
    });
    return {
      extracted_pole_number: null,
      vlm_valid: false,
      confidence: 0,
      issues: [`VLM error: ${error instanceof Error ? error.message : 'Unknown'}`],
      feedback: 'AI validation unavailable — manual review required',
    };
  }
}

// ============================================================================
// Stage 2: Project Cross-Reference
// ============================================================================

/**
 * Validate extracted pole number against the project SOW and PON stage tracking.
 */
async function crossReferenceProject(
  poleNumber: string | null,
  projectName: string
): Promise<CrossRefResult> {
  if (!poleNumber) {
    return { valid: false, issues: ['Could not extract pole number from photo'], pole_number: null, zone_no: null, pon_no: null };
  }

  const sql = getDb();
  const projects = await sql`SELECT id FROM projects WHERE project_name = ${projectName} LIMIT 1`;

  if (projects.length === 0) {
    return { valid: false, issues: [`Project '${projectName}' not found`], pole_number: poleNumber, zone_no: null, pon_no: null };
  }

  const projectRow = projects[0] as Record<string, unknown> | undefined;
  const projectId = projectRow?.id as string | undefined;
  if (!projectId) {
    return { valid: false, issues: [`Project '${projectName}' has no ID`], pole_number: poleNumber, zone_no: null, pon_no: null };
  }

  const poles = await sql`
    SELECT zone_no, pon_no FROM poles
    WHERE project_id = ${projectId}::uuid AND pole_number = ${poleNumber}
    LIMIT 1
  `;

  if (poles.length === 0) {
    return { valid: false, issues: [`Pole ${poleNumber} not in SOW for '${projectName}'`], pole_number: poleNumber, zone_no: null, pon_no: null };
  }

  const poleRow = poles[0] as Record<string, unknown> | undefined;
  const ponNo = poleRow?.pon_no ? Number(poleRow.pon_no) : null;
  const zoneNo = poleRow?.zone_no ? Number(poleRow.zone_no) : null;
  const issues: string[] = [];

  if (ponNo !== null) {
    const stages = await sql`
      SELECT overall_stage FROM pon_stage_tracking
      WHERE project_id = ${projectId}::uuid AND pon_no = ${ponNo}
      LIMIT 1
    `;
    if (stages.length > 0) {
      const stageRow = stages[0] as Record<string, unknown> | undefined;
      const stage = stageRow?.overall_stage as string | undefined;
      if (stage === 'design' || stage === 'planning') {
        issues.push(`PON ${ponNo} is in '${stage}' stage — pole work may be premature`);
      }
    }
  }

  return { valid: issues.length === 0, issues, pole_number: poleNumber, zone_no: zoneNo, pon_no: ponNo };
}

// ============================================================================
// Exports
// ============================================================================

/**
 * Run VLM + cross-reference validation for a single uploaded photo.
 * Updates field_ops_wa_photos with all results.
 */
export async function validatePhoto(photo: UploadedPhoto): Promise<{ success: boolean; error?: string }> {
  const sql = getDb();
  const discipline = photo.group_type;

  try {
    const vlmResult = await runVlmAnalysis(photo.local_path || photo.storage_key, discipline);

    let crossRef: CrossRefResult = { valid: true, issues: [], pole_number: null, zone_no: null, pon_no: null };
    if (discipline === 'civil' && photo.project) {
      crossRef = await crossReferenceProject(vlmResult.extracted_pole_number, photo.project);
    }

    await sql`
      UPDATE field_ops_wa_photos SET
        vlm_processed = true,
        vlm_valid = ${vlmResult.vlm_valid},
        vlm_confidence = ${vlmResult.confidence},
        vlm_issues = ${JSON.stringify(vlmResult.issues)}::jsonb,
        vlm_feedback = ${vlmResult.feedback},
        vlm_processed_at = NOW(),
        cross_ref_valid = ${crossRef.valid},
        cross_ref_issues = ${JSON.stringify(crossRef.issues)}::jsonb,
        matched_pole_number = ${crossRef.pole_number},
        matched_zone_no = ${crossRef.zone_no},
        matched_pon_no = ${crossRef.pon_no},
        updated_at = NOW()
      WHERE id = ${photo.id}
    `;

    logger.info('Photo validation complete', {
      photoId: photo.id,
      discipline,
      vlmValid: vlmResult.vlm_valid,
      crossRefValid: crossRef.valid,
      poleNumber: crossRef.pole_number,
    });

    return { success: true };
  } catch (error) {
    const errorMessage = error instanceof Error ? error.message : 'Unknown error';
    logger.error('Photo validation failed', { photoId: photo.id, error: errorMessage });
    return { success: false, error: errorMessage };
  }
}

/**
 * Batch validate uploaded photos pending VLM processing
 */
export async function validatePendingPhotos(limit = 5): Promise<{
  processed: number;
  succeeded: number;
  failed: number;
}> {
  const sql = getDb();
  const photos = await sql`
    SELECT id, group_type, project, storage_key, local_path, wa_group_jid, message_timestamp
    FROM field_ops_wa_photos
    WHERE upload_status = 'uploaded' AND vlm_processed = false
    ORDER BY created_at ASC
    LIMIT ${limit}
  `;

  const results = { processed: 0, succeeded: 0, failed: 0 };

  for (const photo of photos) {
    results.processed++;
    try {
      const result = await validatePhoto(photo as unknown as UploadedPhoto);
      if (result.success) results.succeeded++;
      else results.failed++;
    } catch {
      results.failed++;
    }
  }

  logger.info('Batch VLM validation complete', results);
  return results;
}

/**
