/**
 * Field Ops WhatsApp Message Endpoint
 *
 * Receives incoming WhatsApp messages from the VPS bridge for civil/optical
 * field operations groups. Stores messages and creates pending photo records.
 *
 * POST /api/field-ops/wa-message
 * Auth: x-bridge-secret header
 *
 * @module api/field-ops/wa-message
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { neon } from '@neondatabase/serverless';
import { createLogger } from '@/lib/logger';
import { apiResponse } from '@/lib/apiResponse';
import {
  processPoleInstallPhoto,
  handlePoleTextMessage,
  type PhotoData,
  type GroupInfo,
} from '@/modules/field-ops/services/poleInstallAckService';

const logger = createLogger('api:field-ops:wa-message');

interface IncomingFieldOpsMessage {
  group_jid: string;
  sender_jid: string;
  sender_name?: string;
  message_text?: string;
  message_id: string;
  timestamp: string;
  has_media?: boolean;
  media_type?: string;
  media_count?: number;
  photo_base64?: string;
  photo_filename?: string;
}

interface GroupLookupResult {
  group_type: string;
  project_name: string | null;
  project_id: string | null;
}

interface MessageInsertResult {
  id: string;
}

// neon() tagged-template returns Record<string,any>[] — these helpers cast safely
function toGroupResult(row: Record<string, unknown>): GroupLookupResult {
  return {
    group_type: String(row['group_type'] ?? ''),
    project_name: row['project_name'] != null ? String(row['project_name']) : null,
    project_id: row['project_id'] != null ? String(row['project_id']) : null,
  };
}

function toMessageResult(row: Record<string, unknown>): MessageInsertResult {
  return { id: String(row['id'] ?? '') };
}

async function handler(req: NextApiRequest, res: NextApiResponse): Promise<void> {
  if (req.method !== 'POST') {
    return apiResponse.methodNotAllowed(res, req.method ?? 'UNKNOWN', ['POST']);
  }

  const bridgeSecret = process.env.WA_BRIDGE_SECRET;
  if (!bridgeSecret) {
    logger.error('WA_BRIDGE_SECRET env var not set');
    return apiResponse.internalError(res, new Error('Server configuration error'));
  }

  const headerSecret = req.headers['x-bridge-secret'];
  if (headerSecret !== bridgeSecret) {
    logger.warn('Invalid or missing x-bridge-secret header');
    return apiResponse.unauthorized(res, 'Invalid bridge secret');
  }

  const body = req.body as IncomingFieldOpsMessage;

  if (!body.message_id) {
    return apiResponse.badRequest(res, 'Missing required field: message_id');
  }
  if (!body.group_jid) {
    return apiResponse.badRequest(res, 'Missing required field: group_jid');
  }
  if (!body.sender_jid) {
    return apiResponse.badRequest(res, 'Missing required field: sender_jid');
  }
  if (!body.timestamp) {
    return apiResponse.badRequest(res, 'Missing required field: timestamp');
  }

  const sql = neon(process.env.DATABASE_URL!);

  try {
    // Look up group in wa_monitored_groups to get group_type and project
    const groupRows = (await sql`
      SELECT group_type, project_name, project_id
      FROM wa_monitored_groups
      WHERE group_jid = ${body.group_jid}
        AND is_active = TRUE
    `).map(toGroupResult);

    if (groupRows.length === 0) {
      logger.warn('Message from unknown or inactive group', { group_jid: body.group_jid });
      return apiResponse.badRequest(res, `Unknown or inactive group: ${body.group_jid}`);
    }

    const { group_type, project_name, project_id } = groupRows[0]!

    // Determine message timestamp from bridge payload
    const messageTimestamp = new Date(
      typeof body.timestamp === 'number' ? body.timestamp * 1000 : body.timestamp
    ).toISOString();

    // Insert the message (idempotent via ON CONFLICT DO NOTHING)
    const insertedRows = (await sql`
      INSERT INTO field_ops_wa_messages (
        wa_message_id,
        wa_group_jid,
        group_type,
        sender_jid,
        sender_name,
        message_text,
        message_timestamp,
        project,
        has_media,
        media_type,
        media_count
      ) VALUES (
        ${body.message_id},
        ${body.group_jid},
        ${group_type},
        ${body.sender_jid},
        ${body.sender_name ?? null},
        ${body.message_text ?? null},
        ${messageTimestamp},
        ${project_name ?? null},
        ${body.has_media ?? false},
        ${body.media_type ?? null},
        ${body.media_count ?? 0}
      )
      ON CONFLICT (wa_message_id) DO NOTHING
      RETURNING id
    `).map(toMessageResult);

    // If message was a duplicate, return early
    if (insertedRows.length === 0) {
      logger.info('Duplicate message ignored', { message_id: body.message_id });
      return apiResponse.success(res, { message_id: body.message_id, duplicate: true });
    }

    const messageDbId = insertedRows[0]!.id;

    // If the message has images, create pending photo records (one per image)
    const photoCount = body.media_count ?? 0;
    if (body.has_media && body.media_type === 'image' && photoCount > 0) {
      const photoInserts = Array.from({ length: photoCount }, () =>
        sql`
          INSERT INTO field_ops_wa_photos (
            message_id,
            wa_group_jid,
            group_type,
            sender_jid,
            sender_name,
            message_timestamp,
            project,
            upload_status,
            vlm_processed
          ) VALUES (
            ${messageDbId},
            ${body.group_jid},
            ${group_type},
            ${body.sender_jid},
            ${body.sender_name ?? null},
            ${messageTimestamp},
            ${project_name ?? null},
            'pending',
            FALSE
          )
        `
      );

      await Promise.all(photoInserts);

      logger.info('Photo records created', {
        message_id: body.message_id,
        photos_created: photoCount,
        project: project_name,
      });

      // Fire-and-forget: real-time pole install ACK pipeline
      if (body.photo_base64 && project_id && group_type === 'civil') {
        const photoData: PhotoData = {
          photoId: messageDbId, // Use message DB ID as photo reference
          senderJid: body.sender_jid,
          senderName: body.sender_name ?? 'Unknown',
          messageTimestamp: messageTimestamp,
        };
        const groupInfo: GroupInfo = {
          groupJid: body.group_jid,
          projectId: project_id,
          projectName: project_name ?? '',
        };
        processPoleInstallPhoto(photoData, body.photo_base64, groupInfo).catch((err) =>
          logger.error('Pole install ACK pipeline failed', {
            error: err instanceof Error ? err.message : String(err),
            message_id: body.message_id,
          })
        );
      }
    }

    // Fire-and-forget: check text messages for pole number declarations
    if (!body.has_media && body.message_text && project_id && group_type === 'civil') {
      handlePoleTextMessage(
        body.message_text, body.sender_jid, body.sender_name ?? 'Unknown',
        body.group_jid, project_id, project_name ?? ''
      ).catch((err) =>
        logger.error('Pole text message handler failed', {
          error: err instanceof Error ? err.message : String(err),
          message_id: body.message_id,
        })
      );
    }

    logger.info('Field ops WA message stored', {
      message_id: body.message_id,
      group_type,
      project: project_name,
      has_media: body.has_media,
    });

    return apiResponse.success(res, {
      message_id: body.message_id,
      db_id: messageDbId,
      group_type,
      project: project_name,
      photos_created: body.has_media && body.media_type === 'image' ? photoCount : 0,
    });
  } catch (error) {
    logger.error('Failed to store field ops WA message', {
      error: error instanceof Error ? error.message : String(error),
      message_id: body.message_id,
    });
    return apiResponse.internalError(res, error);
  }
}

export const config = {
  api: {
    bodyParser: {
      sizeLimit: '50mb',
    },
  },
};

// No withAuth — authenticated via x-bridge-secret header from Go bridge
export default handler;

/**
 * EXFO Exchange Integration
 * Barrel export for all EXFO services.
 */

export { getExfoToken, clearExfoTokenCache } from './exfoAuthService';
export {
  searchResults,
  fetchAllResults,
  getMeasurementDetail,
  getMeasurementDetails,
} from './exfoApiService';
export {
  parseTestName,
  getSyncConfigs,
  syncWorkspace,
  syncAllWorkspaces,
} from './exfoSyncService';
export type {
  ExfoAuthTokens,
  ExfoSearchResult,
  ExfoSearchResponse,
  ExfoMeasurementDetail,
  ExfoParsedName,
  ExfoSyncConfig,
  ExfoSyncResult,
  ExfoTestResultRow,
} from './types';

/**
 * EXFO Exchange Authentication Service
 *
 * Authenticates with EXFO Exchange via Firebase Identity Toolkit.
 * Server-side only — uses email/password to obtain JWT Bearer tokens.
 * Tokens are cached in memory and refreshed before expiry.
 */

import { createLogger } from '@/lib/logger';
import type { ExfoAuthTokens } from './types';

const logger = createLogger('exfoAuth');

// Firebase Identity Toolkit endpoint
const FIREBASE_API_KEY = 'AIzaSyD1OuV9WUd524L9ybECyLwADBjnV8NQr6s';
const FIREBASE_SIGN_IN_URL = `https://identitytoolkit.googleapis.com/v1/accounts:signInWithPassword?key=${FIREBASE_API_KEY}`;
const FIREBASE_REFRESH_URL = `https://securetoken.googleapis.com/v1/token?key=${FIREBASE_API_KEY}`;
const TENANT_ID = 'FIXME-fdjb0';

// Token refresh buffer (5 minutes before expiry)
const REFRESH_BUFFER_MS = 5 * 60 * 1000;

// In-memory token cache
let cachedTokens: ExfoAuthTokens | null = null;

/**
 * Get a valid JWT token for EXFO Exchange API calls.
 * Handles caching and automatic refresh.
 */
export async function getExfoToken(): Promise<string> {
  // Check if cached token is still valid
  if (cachedTokens && Date.now() < cachedTokens.expiresAt - REFRESH_BUFFER_MS) {
    return cachedTokens.idToken;
  }

  // Try refresh if we have a refresh token
  if (cachedTokens?.refreshToken) {
    try {
      const refreshed = await refreshToken(cachedTokens.refreshToken);
      cachedTokens = refreshed;
      logger.info('EXFO token refreshed successfully');
      return refreshed.idToken;
    } catch (err) {
      logger.warn('EXFO token refresh failed, re-authenticating', {
        error: err instanceof Error ? err.message : String(err),
      });
    }
  }

  // Full sign-in
  const tokens = await signIn();
  cachedTokens = tokens;
  return tokens.idToken;
}

/**
 * Sign in with email/password via Firebase Identity Toolkit
 */
async function signIn(): Promise<ExfoAuthTokens> {
  const email = process.env.EXFO_EMAIL;
  const password = process.env.EXFO_PASSWORD;

  if (!email || !password) {
    throw new Error('EXFO_EMAIL and EXFO_PASSWORD environment variables required');
  }

  logger.info('Authenticating with EXFO Exchange');

  const response = await fetch(FIREBASE_SIGN_IN_URL, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      email,
      password,
      returnSecureToken: true,
      tenantId: TENANT_ID,
    }),
  });

  if (!response.ok) {
    const errorData = await response.json().catch(() => ({}));
    const errorMsg = errorData?.error?.message || response.statusText;
    logger.error('EXFO auth failed', { status: response.status, error: errorMsg });
    throw new Error(`EXFO authentication failed: ${errorMsg}`);
  }

  const data = await response.json();
  const expiresIn = parseInt(data.expiresIn, 10) || 3600;

  return {
    idToken: data.idToken,
    refreshToken: data.refreshToken,
    expiresIn: data.expiresIn,
    expiresAt: Date.now() + expiresIn * 1000,
  };
}

/**
 * Refresh an expired token using the refresh token
 */
async function refreshToken(refreshTokenValue: string): Promise<ExfoAuthTokens> {
  const response = await fetch(FIREBASE_REFRESH_URL, {
    method: 'POST',
    headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
    body: new URLSearchParams({
      grant_type: 'refresh_token',
      refresh_token: refreshTokenValue,
    }),
  });

  if (!response.ok) {
    throw new Error(`Token refresh failed: ${response.status}`);
  }

  const data = await response.json();
  const expiresIn = parseInt(data.expires_in, 10) || 3600;

  return {
    idToken: data.id_token,
    refreshToken: data.refresh_token,
    expiresIn: String(expiresIn),
    expiresAt: Date.now() + expiresIn * 1000,
  };
}

/**
 * Clear cached tokens (useful for testing or forced re-auth)
 */
export function clearExfoTokenCache(): void {
  cachedTokens = null;
  logger.info('EXFO token cache cleared');
}

/**
 * EXFO Exchange API Types
 *
 * Types for the reverse-engineered EXFO Exchange REST API.
 * API uses Firebase JWT auth and microservice architecture:
 * - search.exfoapis.com — Search/list results
 * - measurement.exfoapis.com — Full test details
 * - comment.exfoapis.com — Comments
 * - attachment.exfoapis.com — File downloads
 * - admin.exfoapis.com — Org config
 */

// =============================================================================
// Auth
// =============================================================================

export interface ExfoAuthTokens {
  idToken: string;
  refreshToken: string;
  expiresIn: string;
  expiresAt: number; // Unix ms timestamp
}

// =============================================================================
// Search API
// =============================================================================

export interface ExfoSearchRequest {
  from: number;
  size: number;
  search: {
    term: string;
    filters: {
      values: {
        searchParameter?: { values: string[] };
        serverUpdatedDate?: {
          values?: Array<{ start: string; end: string }>;
          datePreset?: string[];
        };
        hasRadioButton?: { values: string };
        type?: { values: string[] };
        globalVerdict?: { values: string[] };
      };
    };
  };
  sort: {
    by: string;
    order: 'asc' | 'desc';
  };
}

export interface ExfoSearchResult {
  accountId: string;
  configName: string;
  createdBy: string;
  name: string;
  globalVerdict: string | null;
  jobId: string;
  briefJobId: string;
  resultId: string;
  serverUpdatedDate: string;
  testDateTime: string;
  testPointName: string;
  testUnitACalibration: string;
  testUnitAModelName: string;
  type: string;
  updatedBy: string;
  properties: Record<string, unknown>;
  attachmentsCount: number;
  jobName: string;
}

export interface ExfoSearchResponse {
  results: ExfoSearchResult[];
  from: number;
  size: number;
}

// =============================================================================
// Measurement Detail API
// =============================================================================

export interface ExfoMeasurementDetail {
  brief: {
    Hardware?: {
      UnitA?: ExfoHardwareUnit;
      UnitB?: ExfoHardwareUnit;
    };
    Identification?: {
      CompanyName?: string;
      CustomerName?: string;
      OperatorA?: string;
      OperatorB?: string;
      JobId?: string;
      Geolocation?: ExfoGeolocation;
    };
    GlobalVerdict?: string;
    FiberInformation?: {
      FiberType?: string;
      LocationDirection?: string;
    };
    Identifiers?: ExfoIdentifier[];
    [key: string]: unknown;
  };
  metadata?: {
    platformSerialNumber?: string;
    platformUsed?: string;
    [key: string]: unknown;
  };
  [key: string]: unknown;
}

export interface ExfoHardwareUnit {
  SerialNumber?: string;
  ModelName?: string;
  LastCalibrationDate?: string;
}

export interface ExfoGeolocation {
  latitude?: number;
  longitude?: number;
  [key: string]: unknown;
}

export interface ExfoIdentifier {
  Name?: string;
  Value?: string;
}

// =============================================================================
// Parsed Name Components
// =============================================================================

export interface ExfoParsedName {
  project: string | null;     // MOA, GRA
  section: string | null;     // STS
  sectionNum: number | null;  // 1, 2
  pole: string | null;        // B756
  cabinet: string | null;     // C5
  port: string | null;        // P5
  link: string | null;        // L14
  fiber: string | null;       // L1
}

// =============================================================================
// Sync Types
// =============================================================================

export interface ExfoSyncConfig {
  id: string;
  workspace_id: string;
  workspace_name: string;
  org_id: string;
  is_active: boolean;
  sync_interval_minutes: number;
  last_sync_at: string | null;
  last_sync_cursor: string | null;
  project_id: string | null;
}

export interface ExfoSyncResult {
  status: 'completed' | 'failed';
  resultsFetched: number;
  resultsInserted: number;
  resultsUpdated: number;
  detailsFetched: number;
  assetsMatched: number;
  error?: string;
}

// =============================================================================
// DB Row Type
// =============================================================================

export interface ExfoTestResultRow {
  id: string;
  exfo_result_id: string;
  exfo_workspace_id: string;
  test_type: string;
  test_name: string;
  job_name: string | null;
  global_verdict: string | null;
  test_date_time: string | null;
  server_updated_date: string | null;
  parsed_project: string | null;
  parsed_pole: string | null;
  parsed_cabinet: string | null;
  parsed_port: string | null;
  parsed_link: string | null;
  parsed_fiber: string | null;
  unit_a_serial: string | null;
  unit_a_model: string | null;
  unit_b_serial: string | null;
  unit_b_model: string | null;
  platform_serial: string | null;
  platform_model: string | null;
  company_name: string | null;
  customer_name: string | null;
  operator_a: string | null;
  cable_id: string | null;
  fiber_id: string | null;
  location_a: string | null;
  location_b: string | null;
  project_id: string | null;
  asset_id: string | null;
  attachments_count: number;
  synced_at: string;
  created_at: string;
  project_name?: string;
  asset_name?: string;
}

