  matchType: RuleMatchType;
  matchPattern: string;
  glAccountId?: string;
  supplierId?: string;
  clientId?: string;
  descriptionTemplate?: string;
  priority: number;
  isActive: boolean;
  autoCreateEntry: boolean;
  vatCode: RuleVatCode;
  createdBy?: string;
  createdAt: string;
  updatedAt: string;
  // Joined
